function setFullPreloadMarker(name = '', value = '1') {
  const key = String(name || '').trim();
  if (!key) return;
  try {
    document.documentElement?.setAttribute(`data-${key}`, String(value || '1'));
  } catch {}
}

function logFullPreloadTrace(eventName = '', payload = {}) {
  if (!PRELOAD_DIAGNOSTICS_ENABLED) return;
  try {
    console.info(`[YU_FULL_PRELOAD] ${String(eventName || '').trim()}`, JSON.stringify(payload || {}));
  } catch {}
}

function sendFullPreloadHeartbeat(stage = '', payload = {}) {
  const safeStage = String(stage || '').trim();
  if (!safeStage || !ipcRenderer || typeof ipcRenderer.send !== 'function') return;
  try {
    ipcRenderer.send('yuchat-preload-heartbeat', {
      stage: safeStage,
      source: 'fullCustomPreload',
      ...(payload && typeof payload === 'object' ? payload : {})
    });
  } catch {}
}

