function remapSearchKeyboardLayout(value = '', fromLayout = '', toLayout = '') {
  const source = String(value || '');
  if (!source || !fromLayout || !toLayout || fromLayout.length !== toLayout.length) {
    return source;
  }
  let output = '';
  for (const char of source) {
    const lowerChar = char.toLowerCase();
    const index = fromLayout.indexOf(lowerChar);
    if (index < 0) {
      output += char;
      continue;
    }
    const replacement = toLayout[index] || char;
    output += char === lowerChar ? replacement : replacement.toUpperCase();
  }
  return output;
}

let getSearchQueryVariants = (value = '') => {
  const source = String(value || '').trim();
  const variants = [
    source,
    remapSearchKeyboardLayout(source, SEARCH_KEYBOARD_LAYOUT_LATIN, SEARCH_KEYBOARD_LAYOUT_CYRILLIC),
    remapSearchKeyboardLayout(source, SEARCH_KEYBOARD_LAYOUT_CYRILLIC, SEARCH_KEYBOARD_LAYOUT_LATIN)
  ];
  const normalized = [];
  variants.forEach((variant) => {
    const next = normalizeSearchText(variant || '');
    if (next && !normalized.includes(next)) {
      normalized.push(next);
    }
  });
  return normalized;
};

let tokenizeSearchQuery = (value = '', maxTokens = 8) => {
  const normalized = normalizeSearchText(value || '');
  if (!normalized) return [];
  return normalized
    .split(' ')
    .map((token) => String(token || '').trim())
    .filter(Boolean)
    .slice(0, Math.max(1, Number(maxTokens) || 8));
};

let buildSearchTokenGroups = (value = '', maxTokens = 8) => {
  const groups = [];
  getSearchQueryVariants(value || '').forEach((variant) => {
    const tokens = tokenizeSearchQuery(variant, maxTokens);
    if (!tokens.length) return;
    const signature = tokens.join('\u0001');
    if (groups.some((group) => group.join('\u0001') === signature)) return;
    groups.push(tokens);
  });
  return groups;
};

let hasSearchTokenMatch = (haystack = '', tokens = []) => {
  if (Array.isArray(tokens?.[0])) {
    return tokens.some((group) => hasSearchTokenMatch(haystack, group));
  }
  const normalizedHaystack = normalizeSearchText(haystack || '');
  if (!normalizedHaystack) return false;
  const safeTokens = Array.isArray(tokens)
    ? tokens.map((token) => String(token || '').trim()).filter(Boolean)
    : [];
  if (!safeTokens.length) return true;
  return safeTokens.every((token) => normalizedHaystack.includes(token));
};

function normalizeReactionShortcode(value = '') {
  const raw = String(value || '').trim().toLowerCase();
  if (!raw) return '';
  const inner = raw
    .replace(/^:+|:+$/g, '')
    .replace(/\s+/g, '_')
    .replace(/-/g, '_')
    .replace(/_{2,}/g, '_');
  if (/^[a-z0-9_+]+$/.test(inner)) return `:${inner}:`;
  if (/^:[a-z0-9_+]+:$/.test(raw)) return raw;
  return raw;
}

function resolveReactionDisplayEmoji(value = '') {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const emojiPresentation = normalizeReactionEmojiPresentation(raw);
  if (/\p{Extended_Pictographic}/u.test(emojiPresentation)) return emojiPresentation;
  const shortcode = normalizeReactionShortcode(raw);
  return REACTION_SHORTCODE_TO_EMOJI[shortcode] || emojiPresentation;
}

function normalizeReactionEmojiPresentation(value = '') {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withoutTextPresentation = raw.replace(/\uFE0E/gu, '');
  if (withoutTextPresentation === '\u2764') return '\u2764\uFE0F';
  return raw;
}

function replaceKnownEmojiShortcodes(value = '') {
  const source = String(value || '');
  if (!source || !source.includes(':')) return source;
  return source.replace(/:[a-z0-9_+-]+:/gi, (match) => {
    const normalized = normalizeReactionShortcode(match);
    return REACTION_SHORTCODE_TO_EMOJI[normalized] || match;
  });
}

function extractReactionDisplayEmoji(value = null) {
  if (!value) return '';
  if (typeof value === 'string') {
    return resolveReactionDisplayEmoji(value);
  }
  return resolveReactionDisplayEmoji(
    value?.emoji
    || value?.emoticon
    || value?.unicode
    || value?.value
    || value?.reactionEmoji
    || value?.reactionValue
    || value?.shortcode
    || value?.imageId
    || ''
  );
}

function resolveReactionApiImageId(value = '') {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (/^:[a-z0-9_+-]+:$/i.test(raw)) return normalizeReactionShortcode(raw);
  return REACTION_EMOJI_TO_SHORTCODE[raw] || '';
}

let tryParseRealtimeJsonObject = (value = null) => {
  if (!value) return null;
  if (typeof value === 'object') return value;
  if (typeof value !== 'string') return null;
  const raw = value.trim();
  if (!raw) return null;
  const normalized = /^\d+(?=[\[{])/.test(raw) ? raw.replace(/^\d+/, '') : raw;
  if (!normalized || !/^[\[{]/.test(normalized)) return null;
  try {
    const parsed = JSON.parse(normalized);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
};

let findNestedRealtimeValue = (source = null, propertyName = '', options = {}) => {
  const targetName = String(propertyName || '').trim();
  if (!source || !targetName) return null;
  const maxDepth = Math.max(1, Number(options.maxDepth) || 6);
  const maxNodes = Math.max(20, Number(options.maxNodes) || 240);
  const queue = [{ value: source, depth: 0 }];
  const seen = new Set();
  let visited = 0;
  while (queue.length && visited < maxNodes) {
    const current = queue.shift();
    const value = current?.value;
    const depth = Number(current?.depth || 0);
    if (!value || typeof value !== 'object') continue;
    if (seen.has(value)) continue;
    seen.add(value);
    visited += 1;
    if (Object.prototype.hasOwnProperty.call(value, targetName)) {
      return value[targetName];
    }
    if (depth >= maxDepth) continue;
    if (Array.isArray(value)) {
      value.forEach((item) => {
        if (item && typeof item === 'object') queue.push({ value: item, depth: depth + 1 });
      });
      continue;
    }
    Object.keys(value).forEach((key) => {
      const next = value[key];
      if (next && typeof next === 'object') queue.push({ value: next, depth: depth + 1 });
    });
  }
  return null;
};

let findNestedRealtimeEventByKeyRegex = (source = null, keyRegex = null, options = {}) => {
  if (!source || !(keyRegex instanceof RegExp)) return null;
  const maxDepth = Math.max(1, Number(options.maxDepth) || 7);
  const maxNodes = Math.max(40, Number(options.maxNodes) || 380);
  const queue = [{ value: source, depth: 0 }];
  const seen = new Set();
  let visited = 0;
  while (queue.length && visited < maxNodes) {
    const current = queue.shift();
    const value = current?.value;
    const depth = Number(current?.depth || 0);
    if (!value || typeof value !== 'object') continue;
    if (seen.has(value)) continue;
    seen.add(value);
    visited += 1;
    if (!Array.isArray(value)) {
      const keys = Object.keys(value);
      for (const key of keys) {
        if (!keyRegex.test(String(key || ''))) continue;
        const match = value[key];
        const parsed = tryParseRealtimeJsonObject(match) || match;
        if (parsed && typeof parsed === 'object') return parsed;
      }
    }
    if (depth >= maxDepth) continue;
    if (Array.isArray(value)) {
      value.forEach((item) => {
        if (item && typeof item === 'object') queue.push({ value: item, depth: depth + 1 });
      });
      continue;
    }
    Object.keys(value).forEach((key) => {
      const next = value[key];
      if (next && typeof next === 'object') queue.push({ value: next, depth: depth + 1 });
    });
  }
  return null;
};

function mapRealtimeTypeHintToCanonical(rawHint = '') {
  const hint = String(rawHint || '').trim().toLowerCase();
  if (!hint) return '';
  if (/(typing|keyboard|activity)/.test(hint) && /(update|updated|change|changed|start|started|stop|stopped|event|state)/.test(hint)) return 'TYPING_UPDATED';
  if (/thread/.test(hint) && /(updated|changed|new|message|event|sync)/.test(hint)) return 'THREAD_UPDATED';
  if (/reaction/.test(hint) && /(toggle|toggled|update|updated|change|changed|add|added|remove|removed|event)/.test(hint)) return 'REACTION_TOGGLED';
  if (/badge/.test(hint) && /(update|updated|change|changed|new|event|unread)/.test(hint)) return 'BADGE_UPDATED';
  if (/message/.test(hint) && /(delete|deleted|remove|removed|erase|erased)/.test(hint)) return 'MESSAGE_DELETED';
  if (/message/.test(hint) && /(update|updated|edit|edited|modify|modified|patch|patched)/.test(hint)) return 'MESSAGE_UPDATED';
  if (/message/.test(hint) && /(new|send|sent|create|created|add|added|post|posted)/.test(hint)) return 'MESSAGE_ADDED';
  return '';
}

function isRealtimeSyncWorthyCanonicalType(type = '') {
  const normalized = String(type || '').trim().toUpperCase();
  return (
    normalized === 'MESSAGE_ADDED'
    || normalized === 'MESSAGE_UPDATED'
    || normalized === 'MESSAGE_DELETED'
    || normalized === 'BADGE_UPDATED'
    || normalized === 'THREAD_UPDATED'
    || normalized === 'REACTION_TOGGLED'
  );
}

let detectRealtimeCanonicalTypeHint = (sources = [], options = {}) => {
  const sourceList = Array.isArray(sources) ? sources : [sources];
  const maxDepth = Math.max(1, Number(options.maxDepth) || 6);
  const maxNodes = Math.max(40, Number(options.maxNodes) || 320);
  const hintKeys = ['eventType', 'type', 'event', 'name', 'action', 'kind'];
  for (const source of sourceList) {
    if (!source || typeof source !== 'object') continue;
    const queue = [{ value: source, depth: 0 }];
    const seen = new Set();
    let visited = 0;
    while (queue.length && visited < maxNodes) {
      const current = queue.shift();
      const value = current?.value;
      const depth = Number(current?.depth || 0);
      if (!value || typeof value !== 'object') continue;
      if (seen.has(value)) continue;
      seen.add(value);
      visited += 1;
      if (!Array.isArray(value)) {
        for (const key of hintKeys) {
          const rawHint = value?.[key];
          if (typeof rawHint !== 'string') continue;
          const canonical = mapRealtimeTypeHintToCanonical(rawHint);
          if (canonical) return canonical;
        }
      }
      if (depth >= maxDepth) continue;
      if (Array.isArray(value)) {
        value.forEach((item) => {
          if (item && typeof item === 'object') queue.push({ value: item, depth: depth + 1 });
        });
        continue;
      }
      Object.keys(value).forEach((key) => {
        const next = value[key];
        if (next && typeof next === 'object') queue.push({ value: next, depth: depth + 1 });
      });
    }
  }
  return '';
};

