  function normalizeText(value = '') {
    return String(value || '').toLowerCase().replace(/\s+/g, ' ').trim();
  }

  function cleanText(value = '', maxLength = 240) {
    return String(value || '').replace(/\s+/g, ' ').trim().slice(0, Math.max(32, Number(maxLength) || 240));
  }

  function cleanSearchInputValue(value = '', maxLength = 240) {
    return String(value || '')
      .replace(/\r?\n/g, ' ')
      .slice(0, Math.max(32, Number(maxLength) || 240));
  }

  function cleanMultiline(value = '', maxLength = 6000) {
    return String(value || '')
      .split(/\r?\n+/)
      .map((line) => String(line || '').replace(/\s+/g, ' ').trim())
      .filter(Boolean)
      .join('\n')
      .trim()
      .slice(0, Math.max(300, Number(maxLength) || 6000));
  }

  function shouldSuppressUserFacingError(text = '') {
    const source = String(text || '').toLowerCase();
    if (!source) return false;
    if (source.includes('api account.list 404') && source.includes('unable to find matching target resource method')) {
      return true;
    }
    if (source.includes('account.list') && source.includes('unable to find matching target resource method')) {
      return true;
    }
    return false;
  }

  function syncPrebootErrorBanner() {
    if (!ENABLE_PREBOOT_ERROR_BANNERS) {
      const existingBanner = document.getElementById(PREBOOT_ERROR_BANNER_ID);
      if (existingBanner instanceof HTMLElement) {
        existingBanner.remove();
      }
      return;
    }
    const body = document.body || document.documentElement;
    if (!(body instanceof HTMLElement)) return;

    let banner = document.getElementById(PREBOOT_ERROR_BANNER_ID);
    const errorText = cleanText(state.errorText || '', 400);
    const hasTopStatusSurface = refs.topStatus instanceof HTMLElement && refs.topStatus.isConnected;
    const shouldShowPrebootBanner = !hasTopStatusSurface;

    if (!shouldShowPrebootBanner || !errorText || shouldSuppressUserFacingError(errorText)) {
      if (banner instanceof HTMLElement) {
        banner.remove();
      }
      return;
    }

    if (!(banner instanceof HTMLElement)) {
      banner = document.createElement('div');
      banner.id = PREBOOT_ERROR_BANNER_ID;
      banner.setAttribute('role', 'alert');
      banner.style.position = 'fixed';
      banner.style.left = '16px';
      banner.style.right = '16px';
      banner.style.top = '16px';
      banner.style.zIndex = '2147483647';
      banner.style.padding = '14px 16px';
      banner.style.borderRadius = '14px';
      banner.style.background = 'rgba(96, 104, 120, 0.96)';
      banner.style.color = '#f5f8fd';
      banner.style.font = '600 13px/1.45 -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif';
      banner.style.boxShadow = '0 18px 48px rgba(15, 23, 42, 0.28)';
      banner.style.whiteSpace = 'pre-wrap';
      banner.style.wordBreak = 'break-word';
      banner.style.pointerEvents = 'auto';
      body.appendChild(banner);
    }
    if (banner.dataset.prebootDismissBound !== '1') {
      banner.dataset.prebootDismissBound = '1';
      banner.addEventListener('click', (event) => {
        const target = event.target instanceof HTMLElement
          ? event.target.closest('[data-preboot-error-close]')
          : null;
        if (!(target instanceof HTMLElement)) return;
        event.preventDefault();
        event.stopPropagation();
        clearError();
      });
    }
    let messageNode = banner.querySelector('[data-preboot-error-message]');
    let closeButton = banner.querySelector('[data-preboot-error-close]');
    if (!(messageNode instanceof HTMLElement) || !(closeButton instanceof HTMLButtonElement)) {
      banner.innerHTML = '';
      const shell = document.createElement('div');
      shell.style.display = 'flex';
      shell.style.alignItems = 'flex-start';
      shell.style.gap = '12px';
      shell.style.minWidth = '0';

      messageNode = document.createElement('div');
      messageNode.dataset.prebootErrorMessage = '1';
      messageNode.style.flex = '1 1 auto';
      messageNode.style.minWidth = '0';
      messageNode.style.whiteSpace = 'pre-wrap';
      messageNode.style.wordBreak = 'break-word';

      closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.dataset.prebootErrorClose = '1';
      closeButton.setAttribute('aria-label', 'Скрыть ошибку');
      closeButton.setAttribute('title', 'Скрыть ошибку');
      closeButton.textContent = '×';
      closeButton.style.width = '26px';
      closeButton.style.height = '26px';
      closeButton.style.border = '0';
      closeButton.style.borderRadius = '999px';
      closeButton.style.background = 'rgba(255, 255, 255, 0.2)';
      closeButton.style.color = '#f8fbff';
      closeButton.style.font = '600 18px/1 -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif';
      closeButton.style.cursor = 'pointer';
      closeButton.style.flex = '0 0 auto';
      closeButton.style.padding = '0';

      shell.appendChild(messageNode);
      shell.appendChild(closeButton);
      banner.appendChild(shell);
    }

    messageNode.textContent = `Ошибка запуска: ${errorText}`;
  }

  function clonePlain(value = null) {
    if (!value || typeof value !== 'object') return {};
    if (typeof globalThis.structuredClone === 'function') {
      try {
        return globalThis.structuredClone(value);
      } catch {
        // fallback below
      }
    }
    try {
      return JSON.parse(JSON.stringify(value));
    } catch {
      return {};
    }
  }

  function getProductivityState() {
    const storeState = runtime.productivityStore?.getState?.();
    if (storeState && typeof storeState === 'object') {
      return storeState;
    }
    if (!runtime.productivityFallbackState || typeof runtime.productivityFallbackState !== 'object') {
      runtime.productivityFallbackState = createEmptyProductivityState();
    }
    return runtime.productivityFallbackState;
  }

  function markProductivityStateChanged(nextState = null, options = {}) {
    const snapshot = nextState || getProductivityState();
    runtime.productivityStateVersion += 1;
    invalidateRecentsDerivedCache();
    runtime.lastDialogListSignature = '';
    runtime.lastDialogViewportKey = '';
    runtime.lastChatMessagesSignature = '';
    runtime.lastChatPanelShellSignature = '';
    scheduleProductivityReminderCheck(snapshot);
    syncProductivityReminderSchedulesFromState(snapshot);
    if (runtime.productivityPersistence && options.skipPersist !== true) {
      runtime.productivityPersistence.schedule(snapshot);
    }
  }

  function findMessageForReminderAnnotation(annotation = null) {
    const workspaceId = String(annotation?.workspaceId || '').trim();
    const chatId = normalizeChatId(annotation?.chatId || '');
    const messageId = String(annotation?.messageId || '').trim();
    if (!workspaceId || !chatId || !messageId) return null;
    const chatKey = getChatStateKey(workspaceId, chatId);
    if (!chatKey) return null;
    const items = Array.isArray(state.messagesByChatKey?.[chatKey]?.items)
      ? state.messagesByChatKey[chatKey].items
      : [];
    return items.find((message) => String(message?.id || '').trim() === messageId) || null;
  }

  function buildReminderNotificationPayload(annotation = null) {
    const workspaceId = String(annotation?.workspaceId || '').trim();
    const chatId = normalizeChatId(annotation?.chatId || '');
    const entry = workspaceId && chatId ? findRecentByChatId(workspaceId, chatId) : null;
    const message = findMessageForReminderAnnotation(annotation);
    const title = cleanText(entry?.title || 'Чат', 120) || 'Чат';
    const body = cleanText(
      message?.text
      || annotation?.text
      || annotation?.note
      || 'Пора вернуться к сообщению',
      220
    ) || 'Пора вернуться к сообщению';
    return {
      title: 'Напоминание',
      subtitle: title,
      body,
      iconDataUrl: normalizeAssetUrl(entry?.avatarUrl || '', 4096)
    };
  }

  function buildProductivityReminderKey(workspaceId = '', chatId = '', messageId = '') {
    const ws = String(workspaceId || '').trim();
    const chat = normalizeChatId(chatId || '');
    const msg = String(messageId || '').trim();
    if (!ws || !chat || !msg) return '';
    return `${ws}\u0001${chat}\u0001${msg}`;
  }

  function syncProductivityReminderScheduleWithMainProcess(options = {}) {
    const workspaceId = String(options.workspaceId || '').trim();
    const chatId = normalizeChatId(options.chatId || '');
    const messageId = String(options.messageId || '').trim();
    const reminderKey = String(options.reminderKey || '').trim().slice(0, 420)
      || buildProductivityReminderKey(workspaceId, chatId, messageId);
    if (!reminderKey) return false;
    const dueAt = Math.max(0, Number(options.dueAt || 0));
    try {
      if (!dueAt) {
        ipcRenderer.send('productivity-reminder-cancel', { reminderKey });
        return true;
      }
      const payload = buildReminderNotificationPayload({
        workspaceId,
        chatId,
        messageId,
        timestamp: Math.max(0, Number(options.timestamp || 0)),
        authorMemberId: String(options.authorMemberId || '').trim(),
        text: cleanText(options.text || '', 600),
        note: cleanText(options.note || '', 600),
        snoozedUntil: dueAt
      });
      ipcRenderer.send('productivity-reminder-schedule', {
        reminderKey,
        dueAt,
        notification: payload
      });
      return true;
    } catch {
      return false;
    }
  }

  function syncProductivityReminderSchedulesFromState(stateSnapshot = null) {
    const snapshot = stateSnapshot && typeof stateSnapshot === 'object'
      ? stateSnapshot
      : getProductivityState();
    const annotationsById = snapshot?.messageAnnotationsById && typeof snapshot.messageAnnotationsById === 'object'
      ? snapshot.messageAnnotationsById
      : {};
    const nextKeys = new Set();
    const nowAt = now();
    Object.values(annotationsById).forEach((annotation) => {
      if (!annotation || typeof annotation !== 'object') return;
      if (String(annotation.kind || '').trim().toLowerCase() !== PRODUCTIVITY_MESSAGE_ANNOTATION_KIND.SNOOZE) return;
      const workspaceId = String(annotation.workspaceId || '').trim();
      const chatId = normalizeChatId(annotation.chatId || '');
      const messageId = String(annotation.messageId || '').trim();
      const dueAt = Math.max(0, Number(annotation.snoozedUntil || 0));
      const reminderKey = buildProductivityReminderKey(workspaceId, chatId, messageId);
      if (!reminderKey || dueAt <= nowAt) return;
      nextKeys.add(reminderKey);
      syncProductivityReminderScheduleWithMainProcess({
        workspaceId: annotation.workspaceId,
        chatId: annotation.chatId,
        messageId: annotation.messageId,
        dueAt,
        timestamp: annotation.timestamp,
        authorMemberId: annotation.authorMemberId,
        text: annotation.text,
        note: annotation.note
      });
    });
    Array.from(runtime.productivityReminderSyncedKeys || []).forEach((key) => {
      if (nextKeys.has(key)) return;
      syncProductivityReminderScheduleWithMainProcess({
        reminderKey: key,
        dueAt: 0
      });
    });
    runtime.productivityReminderSyncedKeys = nextKeys;
  }

  function flushDueProductivityMessageReminders(stateSnapshot = null, nowAt = now()) {
    const snapshot = stateSnapshot && typeof stateSnapshot === 'object'
      ? stateSnapshot
      : getProductivityState();
    const annotationsById = snapshot?.messageAnnotationsById && typeof snapshot.messageAnnotationsById === 'object'
      ? snapshot.messageAnnotationsById
      : {};
    const activeIds = new Set();
    let fired = 0;

    Object.values(annotationsById).forEach((annotation) => {
      if (!annotation || typeof annotation !== 'object') return;
      const annotationId = String(annotation.id || '').trim();
      const kind = String(annotation.kind || '').trim().toLowerCase();
      if (!annotationId || kind !== PRODUCTIVITY_MESSAGE_ANNOTATION_KIND.SNOOZE) return;
      const dueAt = Math.max(0, Number(annotation.snoozedUntil || 0));
      if (!dueAt) return;
      activeIds.add(annotationId);
      if (dueAt > nowAt) return;
      const lastFiredAt = Number(runtime.productivityReminderFiredByAnnotationId.get(annotationId) || 0);
      if (lastFiredAt === dueAt) return;
      runtime.productivityReminderFiredByAnnotationId.set(annotationId, dueAt);
      const payload = buildReminderNotificationPayload(annotation);
      notifyFromApp(payload);
      showTemporaryStatus(`Напоминание: ${payload.subtitle} — ${payload.body}`, 5200);
      setProductivityMessageSnooze({
        workspaceId: String(annotation.workspaceId || '').trim(),
        chatId: normalizeChatId(annotation.chatId || ''),
        messageId: String(annotation.messageId || '').trim(),
        timestamp: Number(annotation.timestamp || 0),
        authorMemberId: String(annotation.authorMemberId || '').trim(),
        text: annotation.text || ''
      }, 0);
      fired += 1;
    });

    Array.from(runtime.productivityReminderFiredByAnnotationId.keys()).forEach((annotationId) => {
      if (!activeIds.has(annotationId)) {
        runtime.productivityReminderFiredByAnnotationId.delete(annotationId);
      }
    });
    return fired;
  }

  function ensureProductivityReminderMonitor() {
    if (!runtime.productivityReminderInterval) {
      runtime.productivityReminderInterval = window.setInterval(() => {
        const fired = flushDueProductivityMessageReminders(getProductivityState(), now());
        if (fired > 0) {
          scheduleRender(resolveChatMutationRenderScopes());
        }
        scheduleProductivityReminderCheck(getProductivityState());
      }, 10000);
    }
    if (runtime.productivityReminderHooksBound) return;
    runtime.productivityReminderHooksBound = true;
    const sweep = () => {
      const fired = flushDueProductivityMessageReminders(getProductivityState(), now());
      if (fired > 0) {
        scheduleRender(resolveChatMutationRenderScopes());
      }
      scheduleProductivityReminderCheck(getProductivityState());
    };
    window.addEventListener('focus', sweep, { passive: true });
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState !== 'visible') return;
      sweep();
    });
  }

  function scheduleProductivityReminderCheck(stateSnapshot = null) {
    if (runtime.productivityReminderTimer) {
      clearTimeout(runtime.productivityReminderTimer);
      runtime.productivityReminderTimer = 0;
    }
    const snapshot = stateSnapshot && typeof stateSnapshot === 'object'
      ? stateSnapshot
      : getProductivityState();
    const annotationsById = snapshot?.messageAnnotationsById && typeof snapshot.messageAnnotationsById === 'object'
      ? snapshot.messageAnnotationsById
      : {};
    let nearestDueAt = 0;
    const nowAt = now();
    Object.values(annotationsById).forEach((annotation) => {
      if (!annotation || typeof annotation !== 'object') return;
      if (String(annotation.kind || '').trim().toLowerCase() !== PRODUCTIVITY_MESSAGE_ANNOTATION_KIND.SNOOZE) return;
      const dueAt = Math.max(0, Number(annotation.snoozedUntil || 0));
      if (!dueAt) return;
      if (!nearestDueAt || dueAt < nearestDueAt) {
        nearestDueAt = dueAt;
      }
    });
    if (!nearestDueAt) {
      runtime.productivityReminderFiredByAnnotationId.clear();
      return;
    }
    if (nearestDueAt <= nowAt) {
      flushDueProductivityMessageReminders(snapshot, nowAt);
      return;
    }
    const delay = Math.max(250, Math.min(90_000, nearestDueAt - nowAt));
    runtime.productivityReminderTimer = window.setTimeout(() => {
      runtime.productivityReminderTimer = 0;
      flushDueProductivityMessageReminders(getProductivityState(), now());
      scheduleProductivityReminderCheck(getProductivityState());
    }, delay);
  }

  function replaceProductivityState(nextState = null, options = {}) {
    if (runtime.productivityStore && typeof runtime.productivityStore.replaceState === 'function') {
      runtime.productivitySkipPersistOnce = options.skipPersist === true;
      const changed = runtime.productivityStore.replaceState(nextState) === true;
      if (!changed) {
        runtime.productivitySkipPersistOnce = false;
        return false;
      }
      if (options.flushPersist === true) {
        runtime.productivityPersistence?.flush(getProductivityState());
      }
      return true;
    }
    const previous = JSON.stringify(getProductivityState());
    runtime.productivityFallbackState = clonePlain(nextState || createEmptyProductivityState());
    const changed = previous !== JSON.stringify(runtime.productivityFallbackState);
    if (changed) {
      markProductivityStateChanged(runtime.productivityFallbackState, options);
    }
    return changed;
  }

  function updateProductivityState(mutator = null, options = {}) {
    if (typeof mutator !== 'function') return false;
    if (runtime.productivityStore && typeof runtime.productivityStore.update === 'function') {
      runtime.productivitySkipPersistOnce = options.skipPersist === true;
      const changed = runtime.productivityStore.update((draft) => {
        const result = mutator(draft);
        if (result === false) return false;
        draft.updatedAt = now();
        return true;
      }) === true;
      if (!changed) {
        runtime.productivitySkipPersistOnce = false;
        return false;
      }
      if (options.flushPersist === true) {
        runtime.productivityPersistence?.flush(getProductivityState());
      }
      return true;
    }

    const draft = clonePlain(getProductivityState());
    const result = mutator(draft);
    if (result === false) return false;
    draft.updatedAt = now();
    runtime.productivityFallbackState = draft;
    markProductivityStateChanged(draft, options);
    if (options.flushPersist === true) {
      runtime.productivityPersistence?.flush(getProductivityState());
    }
    return true;
  }

  function getProductivityInboxMode() {
    return getProductivityInboxModes()[0] || PRODUCTIVITY_INBOX_MODE.ALL;
  }

  function normalizeProductivityInboxModeList(modeInput = PRODUCTIVITY_INBOX_MODE.ALL) {
    const source = Array.isArray(modeInput) ? modeInput : [modeInput];
    const normalized = [];
    source.forEach((value) => {
      const mode = String(value || '').trim().toLowerCase();
      if (!PRODUCTIVITY_INBOX_MODE_LIST.includes(mode) || normalized.includes(mode)) return;
      normalized.push(mode);
    });
    if (!normalized.length) return [PRODUCTIVITY_INBOX_MODE.ALL];
    if (normalized.includes(PRODUCTIVITY_INBOX_MODE.ALL) && normalized.length > 1) {
      return normalized.filter((mode) => mode !== PRODUCTIVITY_INBOX_MODE.ALL);
    }
    return normalized;
  }

  function normalizeProductivityInboxMatchMode(value = PRODUCTIVITY_INBOX_MATCH_MODE.OR) {
    const mode = String(value || '').trim().toLowerCase();
    return PRODUCTIVITY_INBOX_MATCH_MODE_LIST.includes(mode) ? mode : PRODUCTIVITY_INBOX_MATCH_MODE.OR;
  }

  function createDefaultProductivityInboxModeVisibilityMap() {
    return PRODUCTIVITY_INBOX_MODE_LIST.reduce((accumulator, mode) => {
      accumulator[mode] = true;
      return accumulator;
    }, {});
  }

  function createDefaultSendAssistRuleSettings() {
    return SEND_ASSIST_RULE_DEFINITIONS.reduce((accumulator, rule) => {
      const ruleId = String(rule?.id || '').trim();
      if (ruleId) {
        accumulator[ruleId] = true;
      }
      return accumulator;
    }, {});
  }

  function normalizeProductivityInboxModeVisibilityMap(source = null) {
    const raw = source && typeof source === 'object' && !Array.isArray(source)
      ? source
      : {};
    const defaults = createDefaultProductivityInboxModeVisibilityMap();
    PRODUCTIVITY_INBOX_MODE_LIST.forEach((mode) => {
      if (mode === PRODUCTIVITY_INBOX_MODE.ALL) {
        defaults[mode] = true;
        return;
      }
      if (Object.prototype.hasOwnProperty.call(raw, mode)) {
        defaults[mode] = raw[mode] !== false;
      }
    });
    return defaults;
  }

  function normalizeSendAssistRuleSettings(source = null) {
    const raw = source && typeof source === 'object' && !Array.isArray(source)
      ? source
      : {};
    const defaults = createDefaultSendAssistRuleSettings();
    SEND_ASSIST_RULE_DEFINITIONS.forEach((rule) => {
      const ruleId = String(rule?.id || '').trim();
      if (!ruleId) return;
      if (Object.prototype.hasOwnProperty.call(raw, ruleId)) {
        defaults[ruleId] = raw[ruleId] !== false;
      }
    });
    return defaults;
  }

  function isProductivityFiltersFeatureEnabled() {
    return state.productivityFiltersEnabled !== false;
  }

  function isProductivityFoldersFeatureEnabled() {
    return state.productivityFoldersEnabled !== false;
  }

  function isProductivityChatTagsFeatureEnabled() {
    return state.productivityChatTagsEnabled === true;
  }

  function isProductivityWorkbenchFeatureEnabled() {
    return false;
  }

  function getMaxWebSplitLayoutType() {
    return PRODUCTIVITY_SPLIT_LAYOUT_TYPE.MAX_WEB || 'max-web';
  }

  function normalizeMaxWebSplitOrientation(_value = '') {
    return 'vertical';
  }

  function isMaxWebSplitLayout(layoutType = '') {
    return String(layoutType || '').trim().toLowerCase() === getMaxWebSplitLayoutType();
  }

  function isMaxWebSplitSession(session = null) {
    return Boolean(session && typeof session === 'object' && isMaxWebSplitLayout(session.layoutType));
  }

  function getActiveMaxWebSplitSession() {
    const session = selectActiveSplitViewSession(getProductivityState());
    return isMaxWebSplitSession(session) ? session : null;
  }

  function isPollsFeatureEnabled() {
    return state.pollsFeatureEnabled !== false;
  }

  function isSendAssistFeatureEnabled() {
    return state.sendAssistEnabled !== false;
  }

  function getSendAssistRuleDefinition(ruleId = '') {
    const normalizedRuleId = cleanText(ruleId || '', 120);
    return SEND_ASSIST_RULE_DEFINITION_MAP.get(normalizedRuleId) || null;
  }

  function isSendAssistRuleEnabled(ruleId = '') {
    const definition = getSendAssistRuleDefinition(ruleId);
    if (!definition?.id) return false;
    const settings = normalizeSendAssistRuleSettings(state.sendAssistRuleSettingsById);
    return settings[definition.id] !== false;
  }

  function getVisibleProductivityInboxModes() {
    const visibility = normalizeProductivityInboxModeVisibilityMap(state.productivityInboxModeVisibilityByMode);
    const visible = PRODUCTIVITY_INBOX_MODE_LIST.filter((mode) => (
      mode === PRODUCTIVITY_INBOX_MODE.ALL
      || visibility[mode] !== false
    ));
    if (visible.length <= 1 && isProductivityFiltersFeatureEnabled()) {
      return PRODUCTIVITY_INBOX_MODE_LIST.slice();
    }
    return visible.length ? visible : [PRODUCTIVITY_INBOX_MODE.ALL];
  }

  function applyProductivityInboxModeFeatureGates(modeInput = PRODUCTIVITY_INBOX_MODE.ALL) {
    const normalized = normalizeProductivityInboxModeList(modeInput);
    if (!isProductivityFiltersFeatureEnabled()) {
      return [PRODUCTIVITY_INBOX_MODE.ALL];
    }
    const visibleModesSet = new Set(getVisibleProductivityInboxModes());
    const filtered = normalized.filter((mode) => (
      mode === PRODUCTIVITY_INBOX_MODE.ALL || visibleModesSet.has(mode)
    ));
    if (!filtered.length) return [PRODUCTIVITY_INBOX_MODE.ALL];
    if (filtered.includes(PRODUCTIVITY_INBOX_MODE.ALL) && filtered.length > 1) {
      return filtered.filter((mode) => mode !== PRODUCTIVITY_INBOX_MODE.ALL);
    }
    return filtered;
  }

  function getProductivityInboxModeLabel(mode = '') {
    const normalized = String(mode || '').trim().toLowerCase();
    return PRODUCTIVITY_INBOX_MODE_LABEL[normalized] || normalized || 'Фильтр';
  }

  function getProductivityInboxModes() {
    const stateSnapshot = getProductivityState();
    const list = applyProductivityInboxModeFeatureGates(
      stateSnapshot?.inboxModes
      || stateSnapshot?.inboxMode
      || PRODUCTIVITY_INBOX_MODE.ALL
    );
    return list.length ? list : [PRODUCTIVITY_INBOX_MODE.ALL];
  }

  function getProductivityInboxMatchMode() {
    const stateSnapshot = getProductivityState();
    return normalizeProductivityInboxMatchMode(
      stateSnapshot?.inboxMatchMode
      || PRODUCTIVITY_INBOX_MATCH_MODE.OR
    );
  }

  function setProductivityInboxModes(modeInput = PRODUCTIVITY_INBOX_MODE.ALL) {
    const nextModes = applyProductivityInboxModeFeatureGates(modeInput);
    const nextModePrimary = nextModes[0] || PRODUCTIVITY_INBOX_MODE.ALL;
    return updateProductivityState((draft) => {
      const currentModes = applyProductivityInboxModeFeatureGates(
        draft?.inboxModes
        || draft?.inboxMode
        || PRODUCTIVITY_INBOX_MODE.ALL
      );
      if (
        currentModes.length === nextModes.length
        && currentModes.every((value, index) => value === nextModes[index])
      ) {
        return false;
      }
      draft.inboxModes = nextModes.slice();
      draft.inboxMode = nextModePrimary;
      return true;
    });
  }

  function syncProductivityInboxModesWithFeatureSettings() {
    return setProductivityInboxModes(getProductivityInboxModes());
  }

  function setProductivityInboxMode(mode = PRODUCTIVITY_INBOX_MODE.ALL) {
    return setProductivityInboxModes(mode);
  }

  function toggleProductivityInboxMode(mode = PRODUCTIVITY_INBOX_MODE.ALL) {
    const normalizedMode = applyProductivityInboxModeFeatureGates(mode)[0] || PRODUCTIVITY_INBOX_MODE.ALL;
    const currentModes = getProductivityInboxModes();
    if (normalizedMode === PRODUCTIVITY_INBOX_MODE.ALL) {
      return setProductivityInboxModes([PRODUCTIVITY_INBOX_MODE.ALL]);
    }
    const withoutAll = currentModes.filter((value) => value !== PRODUCTIVITY_INBOX_MODE.ALL);
    const exists = withoutAll.includes(normalizedMode);
    const nextModes = exists
      ? withoutAll.filter((value) => value !== normalizedMode)
      : [...withoutAll, normalizedMode];
    if (!nextModes.length) {
      return setProductivityInboxModes([PRODUCTIVITY_INBOX_MODE.ALL]);
    }
    return setProductivityInboxModes(nextModes);
  }

  function setProductivityInboxMatchMode(mode = PRODUCTIVITY_INBOX_MATCH_MODE.OR) {
    const nextMode = normalizeProductivityInboxMatchMode(mode);
    return updateProductivityState((draft) => {
      const currentMode = normalizeProductivityInboxMatchMode(draft?.inboxMatchMode || PRODUCTIVITY_INBOX_MATCH_MODE.OR);
      if (currentMode === nextMode) return false;
      draft.inboxMatchMode = nextMode;
      return true;
    });
  }

  function getProductivityTodoTasks(options = {}) {
    const snapshot = getProductivityState();
    return listTodoTasks(snapshot, options);
  }

  function getProductivityTodoProjects() {
    const snapshot = getProductivityState();
    return listTodoProjects(snapshot);
  }

  function getProductivityTodoHiddenProjects() {
    const snapshot = getProductivityState();
    return listTodoHiddenProjects(snapshot);
  }

  function getProductivityTodoTags() {
    const snapshot = getProductivityState();
    return listTodoTags(snapshot);
  }

  function getProductivityTodoSavedFilters() {
    const snapshot = getProductivityState();
    return listTodoSavedFilters(snapshot);
  }

  function normalizeTodoAttachmentUrl(value = '') {
    const source = String(value || '').trim();
    if (!source) return '';
    try {
      const parsed = new URL(source);
      if (!/^https?:$/i.test(parsed.protocol)) return '';
      return parsed.toString().slice(0, 2200);
    } catch {
      return '';
    }
  }

  function createProductivityTodoTask(title = '', options = {}) {
    const normalizedTitle = cleanText(title || '', 420);
    if (!normalizedTitle) return false;
    const normalizedProject = normalizeTodoProjectLabel(options?.project || '');
    const normalizedPriority = normalizeTodoPriorityValue(options?.priority);
    const normalizedDueAt = normalizeTodoDueAtValue(options?.dueAt);
    const normalizedNote = cleanMultiline(options?.note || '', 2000);
    const normalizedTags = Array.isArray(options?.tags)
      ? options.tags
      : (options?.tags ? [options.tags] : []);
    let createdTask = null;
    const changed = updateProductivityState((draft) => {
      ensureTodoState(draft, now());
      createdTask = createTodoTask(draft, normalizedTitle, {
        project: normalizedProject,
        priority: normalizedPriority,
        dueAt: normalizedDueAt,
        note: normalizedNote,
        tags: normalizedTags
      }, now());
      return Boolean(createdTask);
    });
    return changed ? createdTask : null;
  }

  function createProductivityTodoProject(project = '') {
    const normalizedProject = normalizeTodoProjectLabel(project || '');
    if (!normalizedProject) return '';
    let createdProject = '';
    const changed = updateProductivityState((draft) => {
      ensureTodoState(draft, now());
      const created = createTodoProject(draft, normalizedProject, now());
      createdProject = normalizeTodoProjectLabel(created || '');
      return Boolean(createdProject);
    });
    return changed ? createdProject : createdProject;
  }

  function createProductivityTodoTag(tag = '') {
    const normalizedTag = normalizeTodoTagLabel(tag || '');
    if (!normalizedTag) return '';
    let createdTag = '';
    const changed = updateProductivityState((draft) => {
      ensureTodoState(draft, now());
      const created = createTodoTag(draft, normalizedTag, now());
      createdTag = normalizeTodoTagLabel(created || '');
      return Boolean(createdTag);
    });
    return changed ? createdTag : createdTag;
  }

  function createProductivityTodoSavedFilter(title = '', options = {}) {
    const normalizedTitle = cleanText(title || '', 120);
    if (!normalizedTitle) return null;
    let createdFilter = null;
    const changed = updateProductivityState((draft) => {
      ensureTodoState(draft, now());
      createdFilter = createTodoSavedFilter(draft, {
        title: normalizedTitle,
        query: cleanSearchInputValue(options?.query || '', 240),
        view: normalizeTodoSavedFilterView(options?.view || 'all'),
        project: normalizeTodoProjectLabel(options?.project || ''),
        tag: normalizeTodoTagLabel(options?.tag || ''),
        showCompleted: options?.showCompleted === true
      }, now());
      return Boolean(createdFilter);
    });
    return changed ? createdFilter : null;
  }

  function renameProductivityTodoProject(project = '', nextProject = '') {
    const normalizedProject = normalizeTodoProjectLabel(project || '');
    const normalizedNextProject = normalizeTodoProjectLabel(nextProject || '');
    if (!normalizedProject || !normalizedNextProject) return false;
    return updateProductivityState((draft) => {
      ensureTodoState(draft, now());
      return renameTodoProject(draft, normalizedProject, normalizedNextProject, now());
    });
  }

