  const CORPORATE_PORTAL_PROFILE_BASE_URL = 'https://w3c.portal.rt.ru/profiles/html/profileView.do';
  const CORPORATE_PORTAL_HEALTHCHECK_URL = 'https://w3c.portal.rt.ru/profiles/';
