      systemNotifications: clonePlain(normalizeSystemNotificationSettings(state.systemNotifications)),
      productivityInboxModeVisibilityByMode: normalizeProductivityInboxModeVisibilityMap(state.productivityInboxModeVisibilityByMode),
      sidebarRailCollapsed: state.sidebarRailCollapsed,
      sidebarRailUserWidth: state.sidebarRailUserWidth,
      foldersRailCollapsed: state.foldersRailCollapsed,
