    const memberId = String(profile?.memberId || profile?.profile?.memberId || profile?.id || '').trim();
    const overrideName = getLocalMemberDisplayNameOverride(memberId);
    if (overrideName) return overrideName;
    const sharedName = cleanText(getSharedMemberOverride(memberId)?.displayName || '', 180);
    if (sharedName) return sharedName;
    return getProfileDisplayNameBase(profile);
