  async function openImportArchiveViaDialog(options = {}) {
    try {
      const result = await ipcRenderer.invoke('open-import-archive', {
        title: cleanText(options?.title || 'Открыть архив', 120) || 'Открыть архив',
        filePath: cleanText(options?.filePath || '', 1024),
        filters: Array.isArray(options?.filters) && options.filters.length
          ? options.filters
          : [{ name: 'ZIP', extensions: ['zip'] }],
        maxBytes: Math.max(1024 * 1024, Number(options?.maxBytes) || (64 * 1024 * 1024))
      });
      if (result && typeof result === 'object') {
        return {
          canceled: result.canceled === true,
          fileName: cleanText(result.fileName || '', 240),
          filePath: cleanText(result.filePath || '', 1024),
          error: cleanText(result.error || '', 240),
          entries: (Array.isArray(result.entries) ? result.entries : []).map((entry) => ({
            path: cleanText(entry?.path || '', 1024).replace(/\\/g, '/'),
            size: Math.max(0, Number(entry?.size || 0)),
            mimeType: cleanText(entry?.mimeType || '', 180),
            contentsBase64: String(entry?.contentsBase64 || '')
          }))
        };
      }
    } catch {
      // ignore archive-open failures and return a canceled result
    }
    return {
      canceled: true,
      fileName: '',
      filePath: '',
      error: '',
      entries: []
    };
  }

  function downloadBlobFile(filename = 'file.bin', blob = null) {
    if (!(blob instanceof Blob)) return;
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.setTimeout(() => {
      URL.revokeObjectURL(url);
    }, 1500);
  }

  function isGeneratedAudioNoteFileName(value = '') {
    const normalized = cleanText(value || '', 220);
    if (!normalized) return false;
    return /^(?:audio|voice) note - \d{4}-\d{2}-\d{2}\s+\d{2}\.\d{2}\.\d{2}\.(mp4|m4a|aac|ogg|oga|opus|webm|wav|mp3)$/i.test(normalized);
  }

  function isLikelyVoiceAttachment(value = null) {
    const label = cleanText(
      value?.name
      || value?.fileName
      || value?.title
      || value?.metadata?.fileName
      || '',
      240
    );
    const source = [
      label,
      String(value?.url || value?.downloadUrl || ''),
      String(value?.mimeType || value?.contentType || ''),
      String(value?.metadata?.mimeType || value?.metadata?.contentType || '')
    ].join(' ').toLowerCase();
    if (
      /\bvoice[-_\d]*\b/.test(source)
      || /\bptt\b/.test(source)
      || /\b(?:audio|voice)\s*note\b/.test(source)
      || /\b(?:голосов(?:ое|ой|ые|ая|ые сообщения?)|аудиозаметк(?:а|и|е|у|ой)|аудиосообщени(?:е|я|ю|ем))\b/u.test(source)
      || isGeneratedAudioNoteFileName(label)
    ) {
      return true;
    }
    return Boolean(
      value?.isVoice === true
      || value?.voice === true
      || value?.voiceNote === true
      || value?.waveform
      || value?.durationMs
      || value?.voiceDurationMs
      || value?.metadata?.isVoice === true
      || value?.metadata?.voice === true
      || value?.metadata?.voiceNote === true
      || value?.metadata?.waveform
      || value?.metadata?.voiceDurationMs
    );
  }

  function isGeneratedVideoNoteFileName(value = '') {
    const normalized = cleanText(value || '', 220);
    if (!normalized) return false;
    return /^video note - \d{4}-\d{2}-\d{2}\s+\d{2}\.\d{2}\.\d{2}\.(webm|mp4|m4v|mov)$/i.test(normalized);
  }

  function isVideoNoteMediaTypeValue(value = '') {
    const normalized = cleanText(value || '', 80)
      .toUpperCase()
      .replace(/[\s-]+/g, '_');
    if (!normalized) return false;
    return /^(VIDEO_NOTE|VIDEO_MESSAGE|VIDEO_MEDIA_NOTE|MEDIA_NOTE_VIDEO|MEDIA_VIDEO_NOTE|ROUND_VIDEO|CIRCLE_VIDEO|CIRCULAR_VIDEO|VIDEO_NOTE_CONTENT)$/.test(normalized);
  }

  function isVideoMediaNoteTypeValue(value = '') {
    const normalized = cleanText(value || '', 80)
      .toUpperCase()
      .replace(/[\s-]+/g, '_');
    if (!normalized) return false;
    return normalized === 'VIDEO' || isVideoNoteMediaTypeValue(normalized);
  }

  function isGenericVideoNoteMessageText(value = '') {
    const normalized = cleanText(
      markdownToPlain(value || '', { preserveLineBreaks: true }),
      220
    );
    if (!normalized) return false;
    return /^(видео ?сообщение|видеосообщение|видеозаметка|video note|video message)$/i.test(normalized);
  }

  function extractVideoNotePreviewLabelFromValue(value = null, depth = 0) {
    if (value === null || value === undefined || depth > 4) return '';
    const parsedValue = tryParseRealtimeJsonObject(value) || value;
    if (Array.isArray(parsedValue)) {
      for (const entry of parsedValue) {
        const label = extractVideoNotePreviewLabelFromValue(entry, depth + 1);
        if (label) return label;
      }
      return '';
    }
    if (parsedValue && typeof parsedValue === 'object') {
      const mediaType = cleanText(
        parsedValue?.mediaType
        || parsedValue?.type
        || parsedValue?.mediaNoteType
        || parsedValue?.contentInfo?.mediaType
        || parsedValue?.contentInfo?.type
        || parsedValue?.contentInfo?.mediaNoteType
        || parsedValue?.metadata?.mediaType
        || parsedValue?.metadata?.type
        || parsedValue?.metadata?.mediaNoteType
        || '',
        80
      );
      if (isVideoNoteMediaTypeValue(mediaType)) return 'Видео сообщение';
      if (
        isVideoMediaNoteTypeValue(parsedValue?.mediaNoteType)
        || isVideoMediaNoteTypeValue(parsedValue?.contentInfo?.mediaNoteType)
        || isVideoMediaNoteTypeValue(parsedValue?.metadata?.mediaNoteType)
      ) {
        return 'Видео сообщение';
      }
      if (
        parsedValue?.contentInfo?.videoNoteContentInfo
        || parsedValue?.contentInfo?.mediaNoteContentInfo
        || parsedValue?.contentInfo?.videoMessageContentInfo
        || parsedValue?.contentInfo?.roundVideoContentInfo
        || parsedValue?.contentInfo?.streamFileId
        || parsedValue?.videoNoteContentInfo
        || parsedValue?.mediaNoteContentInfo
        || parsedValue?.videoMessageContentInfo
        || parsedValue?.roundVideoContentInfo
        || parsedValue?.streamFileId
        || parsedValue?.streamFileMetadata
        || parsedValue?.metadata?.videoNoteContentInfo
        || parsedValue?.metadata?.mediaNoteContentInfo
        || parsedValue?.metadata?.videoMessageContentInfo
        || parsedValue?.metadata?.roundVideoContentInfo
        || parsedValue?.metadata?.streamFileId
        || parsedValue?.metadata?.streamFileMetadata
      ) {
        return 'Видео сообщение';
      }
      const candidateKeys = [
        'previewText',
        'previewAttachment',
        'attachmentLabel',
        'mediaNoteType',
        'fileName',
        'name',
        'title',
        'text',
        'formattedText',
        'markdown',
        'body',
        'description',
        'message',
        'subtitle'
      ];
      for (const key of candidateKeys) {
        if (!Object.prototype.hasOwnProperty.call(parsedValue, key)) continue;
        const label = extractVideoNotePreviewLabelFromValue(parsedValue[key], depth + 1);
        if (label) return label;
      }
      return '';
    }

    const plain = markdownToPlain(String(parsedValue || ''), { preserveLineBreaks: true });
    const normalized = cleanText(plain, 520);
    if (!normalized) return '';
    if (isGenericVideoNoteMessageText(normalized) || isGeneratedVideoNoteFileName(normalized)) {
      return isGeneratedVideoNoteFileName(normalized) ? 'Видео сообщение' : normalized;
    }
    const chunks = [
      ...plain.split(/\r?\n+/),
      ...normalized.split(/\s*[•·|]\s*/u)
    ];
    for (const chunk of chunks) {
      const candidate = cleanText(chunk || '', 240);
      if (!candidate) continue;
      if (isGenericVideoNoteMessageText(candidate) || isGeneratedVideoNoteFileName(candidate)) {
        return isGeneratedVideoNoteFileName(candidate) ? 'Видео сообщение' : candidate;
      }
    }
    return /(^|[\s:;,.()[\]{}"'«»_-])(видео\s*сообщение|видеосообщение|видеозаметка|video\s+note|video\s+message)(?=$|[\s:;,.()[\]{}"'«»_-])/iu.test(normalized)
      ? 'Видео сообщение'
      : '';
  }

  function isVideoNoteAttachment(value = null) {
    const mediaType = cleanText(
      value?.mediaType
      || value?.metadata?.mediaType
      || value?.contentInfo?.mediaType
      || value?.contentInfo?.type
      || value?.type
      || '',
      80
    ).toUpperCase();
    if (isVideoNoteMediaTypeValue(mediaType)) {
      return true;
    }
    if (
      isVideoMediaNoteTypeValue(value?.mediaNoteType)
      || isVideoMediaNoteTypeValue(value?.metadata?.mediaNoteType)
      || isVideoMediaNoteTypeValue(value?.contentInfo?.mediaNoteType)
    ) {
      return true;
    }
    const fileName = cleanText(
      value?.name
      || value?.fileName
      || value?.title
      || value?.metadata?.fileName
      || '',
      220
    );
    const mimeType = cleanText(
      value?.mimeType
      || value?.contentType
      || value?.metadata?.mimeType
      || value?.metadata?.contentType
      || '',
      140
    ).toLowerCase();
    const source = `${String(fileName || '')} ${String(value?.url || value?.downloadUrl || '')}`.toLowerCase();
    if (
      isGeneratedVideoNoteFileName(fileName)
      && (
        /^video\//i.test(mimeType)
        || /\.(webm|mp4|m4v|mov)(?:$|[?#])/i.test(source)
      )
    ) {
      return true;
    }
    return Boolean(
      value?.isVideoNote === true
      || value?.videoNote === true
      || value?.streamFileId
      || value?.contentInfo?.streamFileId
      || value?.metadata?.streamFileId
      || value?.streamFileMetadata
      || value?.metadata?.streamFileMetadata
      || value?.contentInfo?.videoNoteContentInfo
      || value?.contentInfo?.mediaNoteContentInfo
      || value?.contentInfo?.videoMessageContentInfo
      || value?.contentInfo?.roundVideoContentInfo
      || value?.videoNoteContentInfo
      || value?.mediaNoteContentInfo
      || value?.videoMessageContentInfo
      || value?.roundVideoContentInfo
      || value?.metadata?.videoNoteContentInfo
      || value?.metadata?.mediaNoteContentInfo
      || value?.metadata?.videoMessageContentInfo
      || value?.metadata?.roundVideoContentInfo
    );
  }

  function parseAttachmentDurationSecondsValue(value = null) {
    if (value === null || value === undefined || value === '') return 0;
    if (typeof value === 'string') {
      const raw = value.trim();
      if (!raw) return 0;
      const secondsMatch = raw.match(/^(\d+(?:\.\d+)?)s$/i);
      if (secondsMatch?.[1]) {
        return Math.max(1, Math.round(Number(secondsMatch[1]) || 0));
      }
      const millisecondsMatch = raw.match(/^(\d+(?:\.\d+)?)ms$/i);
      if (millisecondsMatch?.[1]) {
        return Math.max(1, Math.round((Number(millisecondsMatch[1]) || 0) / 1000));
      }
      const clockMatch = raw.match(/^(?:(\d{1,2}):)?(\d{1,2}):(\d{2})(?:\.\d+)?$/);
      if (clockMatch) {
        const hours = Number(clockMatch[1] || 0);
        const minutes = Number(clockMatch[2] || 0);
        const seconds = Number(clockMatch[3] || 0);
        const totalSeconds = (hours * 3600) + (minutes * 60) + seconds;
        return totalSeconds > 0 ? totalSeconds : 0;
      }
    }
    const numeric = Number(value || 0);
    if (!Number.isFinite(numeric) || numeric <= 0) return 0;
    if (numeric > 100000) {
      return Math.max(1, Math.round(numeric / 1000));
    }
    return Math.max(1, Math.round(numeric));
  }

  function extractAttachmentDurationSeconds(attachment = null) {
    if (!attachment || typeof attachment !== 'object') return 0;
    const candidates = [
      attachment?.durationSeconds,
      attachment?.durationSec,
      attachment?.voiceDurationSeconds,
      attachment?.voiceDurationSec,
      attachment?.durationMs,
      attachment?.voiceDurationMs,
      attachment?.metadata?.durationSeconds,
      attachment?.metadata?.durationSec,
      attachment?.metadata?.voiceDurationSeconds,
      attachment?.metadata?.voiceDurationSec,
      attachment?.metadata?.durationMs,
      attachment?.metadata?.voiceDurationMs,
      attachment?.contentInfo?.videoNoteContentInfo?.duration,
      attachment?.contentInfo?.mediaNoteContentInfo?.duration,
      attachment?.contentInfo?.videoMessageContentInfo?.duration,
      attachment?.contentInfo?.roundVideoContentInfo?.duration,
      attachment?.videoNoteContentInfo?.duration,
      attachment?.mediaNoteContentInfo?.duration,
      attachment?.videoMessageContentInfo?.duration,
      attachment?.roundVideoContentInfo?.duration,
      attachment?.metadata?.videoNoteContentInfo?.duration,
      attachment?.metadata?.mediaNoteContentInfo?.duration,
      attachment?.metadata?.videoMessageContentInfo?.duration,
      attachment?.metadata?.roundVideoContentInfo?.duration,
      attachment?.payload?.durationSeconds,
      attachment?.payload?.durationSec,
      attachment?.payload?.voiceDurationSeconds,
      attachment?.payload?.voiceDurationSec,
      attachment?.payload?.durationMs,
      attachment?.payload?.voiceDurationMs,
      findNestedRealtimeValue(attachment, 'durationSeconds', { maxDepth: 5, maxNodes: 120 }),
      findNestedRealtimeValue(attachment, 'durationSec', { maxDepth: 5, maxNodes: 120 }),
      findNestedRealtimeValue(attachment, 'voiceDurationSeconds', { maxDepth: 5, maxNodes: 120 }),
      findNestedRealtimeValue(attachment, 'voiceDurationSec', { maxDepth: 5, maxNodes: 120 }),
      findNestedRealtimeValue(attachment, 'durationMs', { maxDepth: 5, maxNodes: 120 }),
      findNestedRealtimeValue(attachment, 'voiceDurationMs', { maxDepth: 5, maxNodes: 120 })
    ];
    for (const candidate of candidates) {
      const durationSeconds = parseAttachmentDurationSecondsValue(candidate);
      if (durationSeconds > 0) {
        return durationSeconds;
      }
    }
    return 0;
  }

  function normalizeVoiceWaveformSamples(samples = [], maxBars = 36) {
    const numeric = (Array.isArray(samples) ? samples : [])
      .map((item) => Number(item))
      .filter((item) => Number.isFinite(item) && item >= 0);
    if (!numeric.length) return [];

    const limit = Math.max(8, Number(maxBars) || 36);
    const collapsed = numeric.length <= limit
      ? numeric
      : Array.from({ length: limit }, (_, index) => {
        const start = Math.floor((index * numeric.length) / limit);
        const end = Math.max(start + 1, Math.floor(((index + 1) * numeric.length) / limit));
        const segment = numeric.slice(start, end);
        const sum = segment.reduce((accumulator, value) => accumulator + Number(value || 0), 0);
        return sum / Math.max(1, segment.length);
      });
    const peak = Math.max(...collapsed, 1);
    return collapsed.map((value) => Math.max(0.2, Math.min(1, Number(value || 0) / peak)));
  }

  function parseVoiceWaveformSamples(value = null, maxBars = 36) {
    if (!value) return [];
    if (Array.isArray(value)) {
      return normalizeVoiceWaveformSamples(value, maxBars);
    }
    if (typeof value === 'string') {
      const raw = value.trim();
      if (!raw) return [];
      const parsed = tryParseRealtimeJsonObject(raw);
      if (Array.isArray(parsed)) {
        return normalizeVoiceWaveformSamples(parsed, maxBars);
      }
      const numeric = raw
        .split(/[,\s|;]+/g)
        .map((item) => Number(item))
        .filter((item) => Number.isFinite(item) && item >= 0);
      return normalizeVoiceWaveformSamples(numeric, maxBars);
    }
    if (value && typeof value === 'object') {
      return parseVoiceWaveformSamples(
        value?.samples
        || value?.values
        || value?.data
        || value?.points
        || null,
        maxBars
      );
    }
    return [];
  }

  function getAttachmentVoiceWaveformSamples(attachment = null, maxBars = 36) {
    if (!attachment || typeof attachment !== 'object') return [];
    const candidates = [
      attachment?.waveform,
      attachment?.voiceWaveform,
      attachment?.metadata?.waveform,
      attachment?.metadata?.voiceWaveform,
      attachment?.payload?.waveform,
      attachment?.payload?.voiceWaveform,
      findNestedRealtimeValue(attachment, 'waveform', { maxDepth: 5, maxNodes: 120 }),
      findNestedRealtimeValue(attachment, 'voiceWaveform', { maxDepth: 5, maxNodes: 120 })
    ];
    for (const candidate of candidates) {
      const resolved = parseVoiceWaveformSamples(candidate, maxBars);
      if (resolved.length) {
        return resolved;
      }
    }
    const seed = cleanText(
      attachment?.id
      || attachment?.fileId
      || attachment?.name
      || attachment?.url
      || 'voice',
      240
    ) || 'voice';
    return Array.from({ length: Math.max(8, Number(maxBars) || 36) }, (_, index) => (
      0.24 + ((shortHash(`${seed}:${index}`) % 72) / 100)
    ));
  }

  function buildVoiceWaveformMarkup(attachment = null, maxBars = 36) {
    return getAttachmentVoiceWaveformSamples(attachment, maxBars)
      .map((sample, index) => (
        `<span class="yc-voice-waveform-bar" style="--yc-voice-wave:${Number(sample || 0).toFixed(3)}" data-voice-wave-index="${escapeHtml(String(index))}"></span>`
      ))
      .join('');
  }

  function getUploadFileMediaType(file = null) {
    const mimeType = cleanText(file?.type || '', 120).toLowerCase();
    const source = String(file?.name || '').toLowerCase();
    if (/^image\//.test(mimeType) || /\.(png|jpe?g|gif|webp|bmp|svg)(?:$|[?#])/.test(source)) return 'IMAGE';
    if (/^audio\//.test(mimeType) || isLikelyVoiceAttachment(file) || /\.(mp3|m4a|ogg|oga|wav|opus|aac|flac|webm)(?:$|[?#])/.test(source)) return 'AUDIO';
    if (/^video\//.test(mimeType) || /\.(mp4|mov|m4v|mkv|avi)(?:$|[?#])/.test(source)) return 'VIDEO';
    return 'RAW';
  }

  function replaceFileExtension(fileName = '', extension = 'bin') {
    const source = String(fileName || '').trim();
    const safeExtension = String(extension || '').trim().replace(/[^a-z0-9]+/gi, '').toLowerCase() || 'bin';
    if (!source) return `file-${Date.now()}.${safeExtension}`;
    const dotIndex = source.lastIndexOf('.');
    if (dotIndex <= 0) {
      return `${source}.${safeExtension}`;
    }
    return `${source.slice(0, dotIndex)}.${safeExtension}`;
  }

  function canvasToBlobAsync(canvas = null, type = 'image/jpeg', quality = undefined) {
    return new Promise((resolve) => {
      if (!(canvas instanceof HTMLCanvasElement) || typeof canvas.toBlob !== 'function') {
        resolve(null);
        return;
      }
      canvas.toBlob((blob) => resolve(blob instanceof Blob ? blob : null), type, quality);
    });
  }

  function extractBase64PayloadFromDataUrl(dataUrl = '') {
    const source = String(dataUrl || '').trim();
    const commaIndex = source.indexOf(',');
    if (commaIndex < 0) return '';
    return source.slice(commaIndex + 1).trim();
  }

  async function saveBlobViaDialog(defaultPath = '', blob = null, options = {}) {
    if (!(blob instanceof Blob)) {
      return { canceled: true, filePath: '' };
    }
    const dataUrl = await readBlobAsDataUrl(blob);
    const base64 = extractBase64PayloadFromDataUrl(dataUrl);
    if (!base64) {
      downloadBlobFile(defaultPath || 'file.bin', blob);
      return { canceled: false, filePath: '' };
    }
    return saveExportFileViaDialog(defaultPath, base64, {
      ...options,
      encoding: 'base64'
    });
  }

  function buildPdfHtmlFromImageDataUrl(title = '', imageDataUrl = '') {
    const safeTitle = escapeHtml(cleanText(title || 'Экспорт', 180) || 'Экспорт');
    const safeImageDataUrl = escapeHtml(String(imageDataUrl || '').trim());
    return `
      <!doctype html>
      <html lang="ru">
        <head>
          <meta charset="utf-8" />
          <title>${safeTitle}</title>
          <style>
            body {
              margin: 0;
              padding: 28px;
              background: #ffffff;
              color: #1d2d40;
              font-family: "SF Pro Display", "Segoe UI", sans-serif;
            }
            .sheet {
              display: grid;
              gap: 18px;
            }
            h1 {
              margin: 0;
              font-size: 24px;
            }
            img {
              max-width: 100%;
              height: auto;
              border-radius: 16px;
              border: 1px solid rgba(195, 207, 223, 0.8);
              display: block;
            }
          </style>
        </head>
        <body>
          <section class="sheet">
            <h1>${safeTitle}</h1>
            <img src="${safeImageDataUrl}" alt="${safeTitle}" />
          </section>
        </body>
      </html>
    `;
  }

