    ctx.beginPath();
    ctx.moveTo(bounds.left + (width * 0.18), bounds.bottom - (height * 0.24));
    ctx.bezierCurveTo(bounds.left + (width * 0.08), bounds.bottom - (height * 0.24), bounds.left + (width * 0.06), bounds.y, bounds.left + (width * 0.22), bounds.y);
    ctx.bezierCurveTo(bounds.left + (width * 0.26), bounds.top + (height * 0.12), bounds.left + (width * 0.4), bounds.top + (height * 0.04), bounds.left + (width * 0.5), bounds.top + (height * 0.16));
    ctx.bezierCurveTo(bounds.left + (width * 0.58), bounds.top + (height * 0.02), bounds.left + (width * 0.74), bounds.top + (height * 0.04), bounds.left + (width * 0.8), bounds.y);
    ctx.bezierCurveTo(bounds.right - (width * 0.08), bounds.y, bounds.right - (width * 0.04), bounds.bottom - (height * 0.28), bounds.right - (width * 0.18), bounds.bottom - (height * 0.24));
