  function openFolderMembershipModal(entry = null, options = {}) {
    if (!entry || typeof entry !== 'object') return Promise.resolve(null);
    const workspaceId = String(entry.workspaceId || '').trim();
    const includeGlobalFallback = options?.fallbackToGlobal === true;
    const folders = includeGlobalFallback
      ? buildUnifiedFolderList()
        .map((folder) => {
          const folderTitle = cleanText(folder?.title || 'Папка', 120) || 'Папка';
          return {
            ...folder,
            displayTitle: folderTitle,
            sourceTitle: folderTitle,
            containsEntry: hasEntryUnifiedFolder(entry, folder?.folderKey || folderTitle)
          };
        })
      : [];
    const exclusive = options?.exclusive === true;
    const sortedFolders = folders.slice().sort((left, right) => {
      const leftContains = left?.containsEntry === true ? 1 : 0;
      const rightContains = right?.containsEntry === true ? 1 : 0;
      if (rightContains !== leftContains) return rightContains - leftContains;
      const dateDiff = Number(left?.createdAt || 0) - Number(right?.createdAt || 0);
      if (dateDiff) return dateDiff;
      return String(left?.displayTitle || left?.title || '').localeCompare(String(right?.displayTitle || right?.title || ''), 'ru');
    });
    return openModal({
      mode: 'folder-picker',
      title: exclusive
        ? `Переместить «${cleanText(entry.title || 'диалог', 80) || 'диалог'}» в папку`
        : `Папки для «${cleanText(entry.title || 'диалога', 80) || 'диалога'}»`,
      description: exclusive ? 'Выберите одну папку или создайте новую.' : 'Выберите папку или создайте новую.',
      options: sortedFolders,
      meta: {
        workspaceId,
        chatId: normalizeChatId(entry.chatId || ''),
        entry,
        exclusive
      }
    });
  }

  function openTagApplyModal(entry = null) {
    if (!entry || typeof entry !== 'object') return Promise.resolve(null);
    const workspaceId = String(
      entry.workspaceId
      || getActiveWorkspaceId()
      || state.activeChatWorkspaceId
      || ''
    ).trim();
    if (!workspaceId) return Promise.resolve(null);
    const localFolders = getWorkspaceCustomFolders(workspaceId, {
      kind: CUSTOM_FOLDER_KIND.TAG,
      includeLegacy: false
    });
    const localFoldersByTagKey = new Map();
    localFolders.forEach((folder) => {
      const key = normalizeUnifiedTagKey(folder?.title || '');
      if (!key) return;
      localFoldersByTagKey.set(key, folder);
    });
    const folders = buildUnifiedTagList()
      .map((tag) => {
        const tagKey = normalizeUnifiedTagKey(tag?.tagKey || tag?.title || '');
        if (!tagKey) return null;
        const localFolder = localFoldersByTagKey.get(tagKey) || null;
        const sourceFolder = localFolder
          || (Array.isArray(tag?.sourceFolders) ? tag.sourceFolders.find(Boolean) || null : null);
        const sourceWorkspaceId = String(sourceFolder?.workspaceId || workspaceId).trim() || workspaceId;
        return {
          id: cleanText(sourceFolder?.id || tag?.id || `tag:${tagKey}`, 120) || `tag:${tagKey}`,
          title: cleanText(tag?.title || sourceFolder?.title || '', 120) || 'Тег',
          kind: CUSTOM_FOLDER_KIND.TAG,
          workspaceId: sourceWorkspaceId,
          tagKey,
          createdAt: Math.max(
            0,
            Number(tag?.createdAt || sourceFolder?.createdAt || 0)
          ) || now(),
          containsEntry: hasEntryUnifiedTag(entry, tagKey)
        };
      })
      .filter(Boolean)
      .sort((left, right) => {
        const leftIsLocal = String(left?.workspaceId || '').trim() === workspaceId ? 1 : 0;
        const rightIsLocal = String(right?.workspaceId || '').trim() === workspaceId ? 1 : 0;
        if (rightIsLocal !== leftIsLocal) return rightIsLocal - leftIsLocal;
        const byDate = Number(left?.createdAt || 0) - Number(right?.createdAt || 0);
        if (byDate) return byDate;
        return String(left?.title || '').localeCompare(String(right?.title || ''), 'ru');
      });
    return openModal({
      mode: 'folder-picker',
      title: `Применить тег для «${cleanText(entry.title || 'диалога', 80) || 'диалога'}»`,
      description: 'Выберите тег или создайте новый.',
      options: folders,
      meta: {
        workspaceId,
        chatId: normalizeChatId(entry.chatId || ''),
        entry,
        asTags: true
      }
    });
  }

  function buildMessageTagModalOptions(entry = null, workspaceId = '', chatId = '', messageId = '') {
    const ws = String(workspaceId || '').trim();
    const chat = normalizeChatId(chatId || '');
    const messageKey = String(messageId || '').trim();
    if (!entry || typeof entry !== 'object' || !ws || !chat || !messageKey) return [];
    const currentTags = getMessageTags(entry, {
      workspaceId: ws,
      chatId: chat,
      messageId: messageKey
    });
    const currentKeys = new Set(currentTags.map((tag) => normalizeMessageTagKey(tag)).filter(Boolean));
    return collectAvailableMessageTags(ws, chat)
      .map((tag, index) => {
        const safeTag = normalizeMessageTagLabel(tag || '');
        const tagKey = normalizeMessageTagKey(safeTag);
        if (!safeTag || !tagKey) return null;
        return {
          id: `message-tag:${tagKey}`,
          title: safeTag,
          workspaceId: ws,
          createdAt: index + 1,
          containsEntry: currentKeys.has(tagKey)
        };
      })
      .filter(Boolean);
  }

  function refreshOpenMessageTagModalOptions() {
    if (state.modalMode !== 'folder-picker') return false;
    if (state.modalMeta?.messageTagMode !== true) return false;
    const entry = state.modalMeta?.entry || null;
    const workspaceId = String(state.modalMeta?.workspaceId || '').trim();
    const chatId = normalizeChatId(state.modalMeta?.chatId || '');
    const messageId = String(state.modalMeta?.messageId || '').trim();
    if (!entry || !workspaceId || !chatId || !messageId) return false;
    state.modalOptions = buildMessageTagModalOptions(entry, workspaceId, chatId, messageId);
    runtime.lastModalMarkup = '';
    scheduleRender('overlays');
    return true;
  }

  function openMessageTagApplyModal(entry = null, options = {}) {
    if (!entry || typeof entry !== 'object') return Promise.resolve(null);
    const workspaceId = String(
      options.workspaceId
      || entry.workspaceId
      || getActiveWorkspaceId()
      || state.activeChatWorkspaceId
      || ''
    ).trim();
    const chatId = normalizeChatId(
      options.chatId
      || entry.chatId
      || state.activeChatId
      || ''
    );
    const messageId = String(
      options.messageId
      || entry.searchSourceMessageId
      || entry.messageId
      || entry.id
      || ''
    ).trim();
    if (!workspaceId || !chatId || !messageId) return Promise.resolve(null);

    const tagOptions = buildMessageTagModalOptions(entry, workspaceId, chatId, messageId);
    const messageLabel = cleanText(
      entry.text
      || getAttachmentLabel(entry?.raw || entry)
      || entry.authorName
      || 'сообщение',
      80
    ) || 'сообщение';

    return openModal({
      mode: 'folder-picker',
      title: `Применить тег к «${messageLabel}»`,
      description: tagOptions.length
        ? 'Можно выбрать несколько тегов подряд, изменения применяются сразу.'
        : 'Создайте первый тег для этого сообщения.',
      options: tagOptions,
      cancelLabel: 'Готово',
      meta: {
        workspaceId,
        chatId,
        messageId,
        entry,
        asTags: true,
        messageTagMode: true
      }
    });
  }

  function cleanupVoiceRecorderResources() {
    const stream = runtime.voiceRecorderStream;
    runtime.voiceRecorderStream = null;
    if (stream && typeof stream.getTracks === 'function') {
      stream.getTracks().forEach((track) => {
        try {
          track.stop();
        } catch {
          // ignore track stop failures
        }
      });
    }
  }

  function cleanupVideoNoteRecorderResources() {
    const stream = runtime.videoNoteRecorderStream;
    runtime.videoNoteRecorderStream = null;
    if (stream && typeof stream.getTracks === 'function') {
      stream.getTracks().forEach((track) => {
        try {
          track.stop();
        } catch {
          // ignore track stop failures
        }
      });
    }
  }

  function canUseVoiceRecording() {
    return Boolean(navigator?.mediaDevices?.getUserMedia)
      && typeof MediaRecorder === 'function';
  }

  function canUseVideoNoteRecording() {
    return Boolean(navigator?.mediaDevices?.getUserMedia)
      && typeof MediaRecorder === 'function'
      && typeof window.WebSocket === 'function';
  }

  async function ensureMicrophoneAccess() {
    const access = await ipcRenderer.invoke('media-access-request', 'microphone').catch(() => null);
    const accessStatus = cleanText(access?.status || '', 40).toLowerCase();
    if (access && access.granted === false) {
      throw new Error(accessStatus === 'restricted'
        ? 'Доступ к микрофону ограничен системой.'
        : 'Нет доступа к микрофону. Разрешите его для приложения.');
    }
    if (!navigator?.mediaDevices?.getUserMedia) {
      throw new Error('Запись голоса недоступна в этой сборке.');
    }
  }

  async function ensureCameraAccess() {
    const access = await ipcRenderer.invoke('media-access-request', 'camera').catch(() => null);
    const accessStatus = cleanText(access?.status || '', 40).toLowerCase();
    if (access && access.granted === false) {
      throw new Error(accessStatus === 'restricted'
        ? 'Доступ к камере ограничен системой.'
        : 'Нет доступа к камере. Разрешите её для приложения.');
    }
    if (!navigator?.mediaDevices?.getUserMedia) {
      throw new Error('Запись видео недоступна в этой сборке.');
    }
  }

  function getVoiceDictationAudioContextClass() {
    return window.AudioContext || window.webkitAudioContext || null;
  }

  function canUseVoiceDictation() {
    return Boolean(navigator?.mediaDevices?.getUserMedia)
      && Boolean(getVoiceDictationAudioContextClass())
      && typeof ipcRenderer?.invoke === 'function';
  }

  function isAnyVoiceAssistActive() {
    return state.voiceDictationActive === true || state.voiceCommandActive === true;
  }

  function isAnyVoiceAssistProcessing() {
    return state.voiceDictationProcessing === true || state.voiceCommandProcessing === true;
  }

  function setVoiceAssistActive(mode = '', active = false) {
    const normalizedMode = cleanText(mode || '', 24).toLowerCase();
    if (normalizedMode === 'command') {
      state.voiceCommandActive = active === true;
      if (active === true) {
        state.voiceDictationActive = false;
      }
    } else {
      state.voiceDictationActive = active === true;
      if (active === true) {
        state.voiceCommandActive = false;
      }
    }
    runtime.voiceCaptureMode = active === true ? normalizedMode : '';
  }

  function setVoiceAssistProcessing(mode = '', processing = false) {
    const normalizedMode = cleanText(mode || '', 24).toLowerCase();
    if (normalizedMode === 'command') {
      state.voiceCommandProcessing = processing === true;
      if (processing === true) {
        state.voiceDictationProcessing = false;
      }
    } else {
      state.voiceDictationProcessing = processing === true;
      if (processing === true) {
        state.voiceCommandProcessing = false;
      }
    }
  }

  function clearVoiceAssistState() {
    state.voiceDictationActive = false;
    state.voiceDictationProcessing = false;
    state.voiceCommandActive = false;
    state.voiceCommandProcessing = false;
    runtime.voiceCaptureMode = '';
  }

  async function transcribePcmChunksWithOfflineVosk(chunks = [], sampleRate = 16000, options = {}) {
    throwIfMediaTranscriptAborted(options?.signal || null);
    const wavBase64 = encodeVoiceDictationWavBase64(chunks, sampleRate);
    if (!wavBase64) {
      throw new Error('Не удалось подготовить аудио для распознавания.');
    }
    const response = await ipcRenderer.invoke('yuchat-transcribe-vosk-dictation', {
      wavBase64,
      mode: cleanText(options?.mode || '', 32).toLowerCase(),
      transferId: cleanText(options?.transferId || '', 180)
    }).catch((error) => ({
      ok: false,
      error: cleanText(error?.message || 'Не удалось распознать речь.', 220)
    }));
    if (response?.code === 'TRANSFER_ABORTED') {
      throw createMediaTranscriptAbortError(response?.reason || 'canceled');
    }
    if (!response || response.ok !== true) {
      throw new Error(cleanText(response?.error || 'Не удалось распознать речь.', 220));
    }
    return cleanText(response.text || '', 12000);
  }

  function parseDataUrlToArrayBuffer(dataUrl = '') {
    const raw = String(dataUrl || '').trim();
    const match = raw.match(/^data:([^;,]+)?(?:;base64)?,([\s\S]+)$/i);
    if (!match) {
      throw new Error('Не удалось прочитать загруженное вложение.');
    }
    const mimeType = cleanText(match[1] || '', 180).toLowerCase();
    const payload = String(match[2] || '');
    const buffer = /;base64,/i.test(raw)
      ? Buffer.from(payload, 'base64')
      : Buffer.from(decodeURIComponent(payload), 'utf8');
    return {
      arrayBuffer: buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength),
      mimeType
    };
  }

  async function fetchAttachmentDataUrlForTranscript(attachment = null, options = {}) {
    if (!attachment || typeof attachment !== 'object') {
      throw new Error('Не удалось определить вложение для распознавания.');
    }
    throwIfMediaTranscriptAborted(options?.signal || null);
    const fileId = String(attachment?.id || attachment?.fileId || '').trim();
    const expectedMimeType = cleanText(
      inferAttachmentMimeType(attachment) || attachment?.mimeType || '',
      180
    );
    const explicitUrl = normalizeAssetUrl(resolveAttachmentDownloadUrl(attachment) || attachment?.url || '', 8192);
    const canonicalUrl = fileId && window.location?.origin
      ? `${window.location.origin}/api/file.download/${encodeURIComponent(fileId)}`
      : '';
    const candidates = Array.from(new Set([canonicalUrl, explicitUrl].filter(Boolean)));
    if (!candidates.length) {
      throw new Error('У вложения нет ссылки на аудио или видео.');
    }

    let lastErrorText = '';
    for (const candidateUrl of candidates) {
      try {
        const result = await ipcRenderer.invoke('fetch-attachment-data-url', {
          url: candidateUrl,
          fileId,
          authToken: getAuthToken(),
          transferId: cleanText(options?.transferId || '', 180),
          expectedMimeType
        });
        if (result?.code === 'TRANSFER_ABORTED') {
          throw createMediaTranscriptAbortError(result?.reason || 'canceled');
        }
        if (result?.ok === true && /^data:/i.test(String(result?.dataUrl || ''))) {
          const resolvedMimeType = resolveProtectedAssetMimeType(candidateUrl, {
            responseMimeType: String(result?.contentType || ''),
            expectedMimeType
          });
          return {
            dataUrl: rewriteMediaDataUrlMimeType(String(result.dataUrl || ''), resolvedMimeType),
            mimeType: cleanText(resolvedMimeType || result?.contentType || '', 180)
          };
        }
        lastErrorText = cleanText(result?.error || '', 220);
      } catch (error) {
        lastErrorText = cleanText(error?.message || '', 220);
      }
    }

    throw new Error(formatMediaTranscriptErrorText(lastErrorText || 'Не удалось загрузить вложение для TXT.'));
  }

  async function fetchAttachmentArrayBufferForTranscript(attachment = null, options = {}) {
    throwIfMediaTranscriptAborted(options?.signal || null);
    const transferId = cleanText(options?.transferId || '', 180);
    const fileId = String(attachment?.id || attachment?.fileId || '').trim();
    const expectedMimeType = cleanText(
      inferAttachmentMimeType(attachment) || attachment?.mimeType || '',
      180
    );
    const primaryUrl = normalizeAssetUrl(resolveAttachmentDownloadUrl(attachment) || attachment?.url || '', 8192);
    if (primaryUrl) {
      try {
        const protectedSourceUrl = await fetchProtectedAssetObjectUrl(primaryUrl, {
          fileId,
          expectedMimeType,
          progressTransferId: transferId,
          trackProgress: Boolean(transferId),
          progressScope: 'download'
        });
        if (protectedSourceUrl) {
          if (/^data:/i.test(protectedSourceUrl)) {
            const parsedDataUrl = parseDataUrlToArrayBuffer(protectedSourceUrl);
            return {
              ...parsedDataUrl,
              dataUrl: protectedSourceUrl,
              mimeType: cleanText(
                parsedDataUrl.mimeType
                || resolveProtectedAssetMimeType(primaryUrl, {
                  expectedMimeType
                }),
                180
              )
            };
          }
          const protectedResponse = await window.fetch(protectedSourceUrl, {
            method: 'GET',
            cache: 'no-store'
          });
          if (protectedResponse.ok) {
            const arrayBuffer = await protectedResponse.arrayBuffer();
            if (arrayBuffer instanceof ArrayBuffer && arrayBuffer.byteLength > 0) {
              return {
                arrayBuffer,
                dataUrl: '',
                mimeType: cleanText(
                  resolveProtectedAssetMimeType(primaryUrl, {
                    responseMimeType: String(protectedResponse.headers?.get?.('content-type') || ''),
                    expectedMimeType
                  }),
                  180
                )
              };
            }
          }
        }
      } catch {
        // fall through to the dedicated TXT fetch pipeline
      }
    }
    const fetched = await fetchAttachmentDataUrlForTranscript(attachment, options);
    const parsed = parseDataUrlToArrayBuffer(fetched.dataUrl || '');
    return {
      ...parsed,
      dataUrl: fetched.dataUrl || '',
      mimeType: cleanText(parsed.mimeType || fetched.mimeType || '', 180)
    };
  }

  async function decodeTranscriptAudioBuffer(arrayBuffer = null, options = {}) {
    const AudioContextClass = getVoiceDictationAudioContextClass();
    if (!(arrayBuffer instanceof ArrayBuffer) || arrayBuffer.byteLength <= 0 || !AudioContextClass) {
      throw new Error('Локальная расшифровка медиа недоступна в этой сборке.');
    }
    throwIfMediaTranscriptAborted(options?.signal || null);
    const audioContext = new AudioContextClass();
    try {
      const sourceBuffer = arrayBuffer.slice(0);
      const decoded = await audioContext.decodeAudioData(sourceBuffer);
      throwIfMediaTranscriptAborted(options?.signal || null);
      return decoded;
    } catch {
      throw new Error('Не удалось прочитать аудиодорожку этого файла.');
    } finally {
      if (typeof audioContext.close === 'function' && audioContext.state !== 'closed') {
        await audioContext.close().catch(() => {});
      }
    }
  }

  function mixAudioBufferToMono(audioBuffer = null) {
    if (!audioBuffer || typeof audioBuffer.length !== 'number' || audioBuffer.length <= 0) {
      return new Float32Array(0);
    }
    const channelCount = Math.max(1, Number(audioBuffer.numberOfChannels || 1));
    const output = new Float32Array(audioBuffer.length);
    for (let channelIndex = 0; channelIndex < channelCount; channelIndex += 1) {
      const channelData = audioBuffer.getChannelData(channelIndex);
      for (let sampleIndex = 0; sampleIndex < output.length; sampleIndex += 1) {
        output[sampleIndex] += Number(channelData[sampleIndex] || 0) / channelCount;
      }
    }
    return output;
  }

  function resampleMonoPcm(input = null, inputRate = 16000, outputRate = 16000) {
    const source = input instanceof Float32Array ? input : new Float32Array(0);
    const fromRate = Math.max(8000, Math.round(Number(inputRate) || 16000));
    const toRate = Math.max(8000, Math.round(Number(outputRate) || 16000));
    if (!source.length) return new Float32Array(0);
    if (fromRate === toRate) {
      return new Float32Array(source);
    }
    const ratio = fromRate / toRate;
    const outputLength = Math.max(1, Math.round(source.length / ratio));
    const output = new Float32Array(outputLength);
    for (let index = 0; index < outputLength; index += 1) {
      const position = index * ratio;
      const baseIndex = Math.floor(position);
      const nextIndex = Math.min(source.length - 1, baseIndex + 1);
      const fraction = position - baseIndex;
      const baseValue = Number(source[baseIndex] || 0);
      const nextValue = Number(source[nextIndex] || 0);
      output[index] = baseValue + ((nextValue - baseValue) * fraction);
    }
    return output;
  }

  async function captureTranscriptPcmChunksFromMediaSource(sourceUrl = '', attachment = null, options = {}) {
    const mediaSourceUrl = String(sourceUrl || '').trim();
    const AudioContextClass = getVoiceDictationAudioContextClass();
    const signal = options?.signal || null;
    const transferId = cleanText(options?.transferId || '', 180);
    if (!mediaSourceUrl || !AudioContextClass) {
      throw new Error('Не удалось подготовить медиа для TXT.');
    }
    throwIfMediaTranscriptAborted(signal);

    const kind = getAttachmentVisualKind(attachment);
    const mediaElement = document.createElement(kind === 'video' ? 'video' : 'audio');
    mediaElement.dataset.ycAllowAudio = '1';
    mediaElement.dataset.ycCustomMedia = '1';
    mediaElement.preload = 'auto';
    mediaElement.src = mediaSourceUrl;
    mediaElement.crossOrigin = 'anonymous';
    mediaElement.playsInline = true;
    mediaElement.controls = false;
    mediaElement.muted = false;
    mediaElement.volume = 1;
    mediaElement.playbackRate = kind === 'video' ? 1.6 : 2;
    mediaElement.style.cssText = 'position:fixed;left:-9999px;top:-9999px;width:1px;height:1px;opacity:0;pointer-events:none;';
    document.body.appendChild(mediaElement);

    let audioContext = null;
    let sourceNode = null;
    let processorNode = null;
    let sinkNode = null;
    let mediaAbortCleanup = null;

    try {
      await new Promise((resolve, reject) => {
        let settled = false;
        const timeoutId = window.setTimeout(() => {
          if (settled) return;
          settled = true;
          cleanup();
          reject(new Error('Медиа не успело подготовиться для TXT.'));
        }, 15000);

        const cleanup = () => {
          window.clearTimeout(timeoutId);
          mediaElement.removeEventListener('loadedmetadata', handleLoadedMetadata);
          mediaElement.removeEventListener('error', handleError);
        };

        const handleLoadedMetadata = () => {
          if (settled) return;
          settled = true;
          cleanup();
          resolve();
        };

        const handleError = () => {
          if (settled) return;
          settled = true;
          cleanup();
          reject(new Error('Не удалось открыть медиафайл для TXT.'));
        };
        const handleAbort = () => {
          if (settled) return;
          settled = true;
          cleanup();
          reject(createMediaTranscriptAbortError(signal?.reason?.reason || signal?.reason || 'canceled'));
        };

        mediaElement.addEventListener('loadedmetadata', handleLoadedMetadata);
        mediaElement.addEventListener('error', handleError);
        signal?.addEventListener?.('abort', handleAbort, { once: true });
        mediaAbortCleanup = () => {
          signal?.removeEventListener?.('abort', handleAbort);
        };
        mediaElement.load();
      });

      const durationSeconds = Number(mediaElement.duration || 0);
      if (!durationSeconds || durationSeconds <= 0.08) {
        throw new Error('В этом файле слишком мало звука для распознавания.');
      }
      if (durationSeconds > MEDIA_TRANSCRIPT_MAX_DURATION_SECONDS) {
        throw new Error(`Оффлайн-распознавание пока поддерживает записи до ${Math.round(MEDIA_TRANSCRIPT_MAX_DURATION_SECONDS / 60)} минут.`);
      }

      audioContext = markCustomAudibleAudioContext(new AudioContextClass({
        sampleRate: 16000
      }));
      if (typeof audioContext.createScriptProcessor !== 'function' || typeof audioContext.createMediaElementSource !== 'function') {
        throw new Error('Локальная расшифровка медиа недоступна в этой версии Chromium.');
      }

      sourceNode = audioContext.createMediaElementSource(mediaElement);
      processorNode = audioContext.createScriptProcessor(4096, 1, 1);
      sinkNode = audioContext.createGain();
      sinkNode.gain.value = 0;

      const pcmChunks = [];
      processorNode.onaudioprocess = (event) => {
        try {
          const channelData = event?.inputBuffer?.getChannelData?.(0);
          if (!(channelData instanceof Float32Array) || !channelData.length) return;
          pcmChunks.push(new Float32Array(channelData));
        } catch {
          // ignore chunk capture failures
        }
      };

      sourceNode.connect(processorNode);
      processorNode.connect(sinkNode);
      sinkNode.connect(audioContext.destination);
      if (typeof audioContext.resume === 'function' && audioContext.state === 'suspended') {
        await audioContext.resume();
      }

      await new Promise((resolve, reject) => {
        let settled = false;
        const timeoutId = window.setTimeout(() => {
          if (settled) return;
          settled = true;
          cleanup();
          try {
            mediaElement.pause();
          } catch {}
          reject(new Error('Медиа не успело проиграться для TXT.'));
        }, Math.max(15000, Math.round((durationSeconds / Math.max(1, mediaElement.playbackRate || 1)) * 1000) + 12000));

        const cleanup = () => {
          window.clearTimeout(timeoutId);
          mediaElement.removeEventListener('ended', handleEnded);
          mediaElement.removeEventListener('error', handleError);
          mediaElement.removeEventListener('timeupdate', handleTimeUpdate);
          signal?.removeEventListener?.('abort', handleAbort);
        };

        const handleEnded = () => {
          if (settled) return;
          settled = true;
          cleanup();
          resolve();
        };

        const handleError = () => {
          if (settled) return;
          settled = true;
          cleanup();
          reject(new Error('Не удалось воспроизвести медиа для TXT.'));
        };
        const handleAbort = () => {
          if (settled) return;
          settled = true;
          cleanup();
          try {
            mediaElement.pause();
          } catch {}
          reject(createMediaTranscriptAbortError(signal?.reason?.reason || signal?.reason || 'canceled'));
        };
        const handleTimeUpdate = () => {
          if (!transferId || !durationSeconds) return;
          updateLocalTransferProgress(transferId, {
            scope: 'transcript',
            stage: 'extracting',
            percent: Math.max(30, Math.min(58, 30 + Math.round((Number(mediaElement.currentTime || 0) / durationSeconds) * 28))),
            message: kind === 'video' ? 'Считываю звук из видео' : 'Считываю звук из аудио'
          });
        };

        mediaElement.addEventListener('ended', handleEnded);
        mediaElement.addEventListener('error', handleError);
        mediaElement.addEventListener('timeupdate', handleTimeUpdate);
        signal?.addEventListener?.('abort', handleAbort, { once: true });
        mediaElement.play().catch((error) => {
          if (settled) return;
          settled = true;
          cleanup();
          reject(new Error(cleanText(error?.message || 'Не удалось запустить воспроизведение медиа для TXT.', 220)));
        });
      });

      if (!pcmChunks.length) {
        throw new Error('Не удалось снять аудиодорожку с этого файла.');
      }
      throwIfMediaTranscriptAborted(signal);

      return {
        chunks: pcmChunks,
        sampleRate: Math.max(8000, Math.round(Number(audioContext.sampleRate) || 16000))
      };
    } finally {
      if (typeof mediaAbortCleanup === 'function') {
        mediaAbortCleanup();
      }
      try {
        mediaElement.pause();
      } catch {}
      if (sourceNode && typeof sourceNode.disconnect === 'function') {
        try {
          sourceNode.disconnect();
        } catch {}
      }
      if (processorNode && typeof processorNode.disconnect === 'function') {
        try {
          processorNode.disconnect();
        } catch {}
      }
      if (sinkNode && typeof sinkNode.disconnect === 'function') {
        try {
          sinkNode.disconnect();
        } catch {}
      }
      if (audioContext && typeof audioContext.close === 'function' && audioContext.state !== 'closed') {
        await audioContext.close().catch(() => {});
      }
      mediaElement.removeAttribute('src');
      mediaElement.load();
      if (mediaElement.isConnected) {
        mediaElement.remove();
      }
    }
  }

  async function buildTranscriptPcmChunksFromAttachment(attachment = null, options = {}) {
    const transferId = cleanText(options?.transferId || '', 180);
    const signal = options?.signal || null;
    let fetched = null;
    let initialFetchError = null;
    try {
      fetched = await fetchAttachmentArrayBufferForTranscript(attachment, options);
    } catch (error) {
      initialFetchError = error;
    }
    if (!fetched) {
      const fallbackSourceUrl = await fetchProtectedAssetObjectUrl(
        normalizeAssetUrl(resolveAttachmentDownloadUrl(attachment) || attachment?.url || '', 8192),
        {
          fileId: String(attachment?.id || attachment?.fileId || '').trim(),
          expectedMimeType: inferAttachmentMimeType(attachment) || attachment?.mimeType || ''
        }
      ).catch(() => '');
      if (fallbackSourceUrl) {
        return captureTranscriptPcmChunksFromMediaSource(fallbackSourceUrl, attachment, options);
      }
      throw initialFetchError || new Error('Не удалось загрузить вложение для TXT.');
    }
    try {
      if (transferId) {
        updateLocalTransferProgress(transferId, {
          scope: 'transcript',
          stage: 'extracting',
          percent: 34,
          message: 'Извлекаю аудиодорожку'
        });
      }
      const audioBuffer = await decodeTranscriptAudioBuffer(fetched.arrayBuffer, options);
      const durationSeconds = Number(audioBuffer?.duration || 0);
      if (!durationSeconds || durationSeconds <= 0.08) {
        throw new Error('В этом файле слишком мало звука для распознавания.');
      }
      if (durationSeconds > MEDIA_TRANSCRIPT_MAX_DURATION_SECONDS) {
        throw new Error(`Оффлайн-распознавание пока поддерживает записи до ${Math.round(MEDIA_TRANSCRIPT_MAX_DURATION_SECONDS / 60)} минут.`);
      }
      const mono = mixAudioBufferToMono(audioBuffer);
      const resampled = resampleMonoPcm(mono, Number(audioBuffer.sampleRate || 16000), 16000);
      if (!resampled.length) {
        throw new Error('Не удалось извлечь аудиодорожку из файла.');
      }
      throwIfMediaTranscriptAborted(signal);
      if (transferId) {
        updateLocalTransferProgress(transferId, {
          scope: 'transcript',
          stage: 'extracting',
          percent: 58,
          message: 'Аудиодорожка готова'
        });
      }
      return {
        chunks: [resampled],
        sampleRate: 16000
      };
    } catch (error) {
      const fallbackMessage = cleanText(error?.message || '', 240);
      const fallbackSources = [];
      const pushFallbackSource = (value = '') => {
        const rawValue = String(value || '').trim();
        const normalized = normalizeAssetUrl(
          rawValue,
          /^data:/i.test(rawValue) ? (16 * 1024 * 1024) : 8192
        );
        if (!normalized || fallbackSources.includes(normalized)) return;
        fallbackSources.push(normalized);
      };
      pushFallbackSource(fetched.dataUrl || '');

      if (!fallbackSources.length) {
        const fallbackDownloadUrl = normalizeAssetUrl(
          resolveAttachmentDownloadUrl(attachment) || attachment?.url || '',
          8192
        );
        if (fallbackDownloadUrl) {
          throwIfMediaTranscriptAborted(signal);
          const resolvedFallbackSource = await fetchProtectedAssetObjectUrl(fallbackDownloadUrl, {
            fileId: String(attachment?.id || attachment?.fileId || '').trim(),
            expectedMimeType: inferAttachmentMimeType(attachment) || attachment?.mimeType || '',
            availabilityTimeoutMs: 14000
          }).catch(() => '');
          pushFallbackSource(resolvedFallbackSource);
        }
      }

      let lastFallbackError = null;
      for (const fallbackSource of fallbackSources) {
        throwIfMediaTranscriptAborted(signal);
        try {
          return await captureTranscriptPcmChunksFromMediaSource(fallbackSource, attachment, options);
        } catch (fallbackError) {
          lastFallbackError = fallbackError;
        }
      }
      throw new Error(cleanText(
        lastFallbackError?.message || fallbackMessage || 'Не удалось подготовить аудиодорожку для TXT.',
        240
      ));
    }
  }

  function buildMediaTranscriptContextFromDataset(node = null) {
    const dataset = node instanceof HTMLElement ? node.dataset : {};
    return {
      workspaceId: String(dataset?.mediaTranscriptWorkspaceId || '').trim(),
      chatId: normalizeChatId(dataset?.mediaTranscriptChatId || ''),
      messageId: String(dataset?.mediaTranscriptMessageId || '').trim()
    };
  }

  function buildMediaTranscriptAttachmentFromDataset(node = null) {
    const dataset = node instanceof HTMLElement ? node.dataset : {};
    return {
      id: String(dataset?.mediaTranscriptAttachmentId || '').trim(),
      fileId: String(dataset?.mediaTranscriptAttachmentId || '').trim(),
      url: normalizeAssetUrl(dataset?.mediaTranscriptAttachmentUrl || '', 8192),
      name: cleanText(dataset?.mediaTranscriptAttachmentName || '', 180),
      mimeType: cleanText(dataset?.mediaTranscriptAttachmentMimeType || '', 180),
      size: Math.max(0, Number(dataset?.mediaTranscriptAttachmentSize || 0))
    };
  }

  function abortMediaTranscriptTransfer(key = '', reason = 'canceled') {
    const normalizedKey = cleanText(key || '', 420);
    if (!normalizedKey) return;
    const controller = runtime.mediaTranscriptAbortControllersByKey.get(normalizedKey) || null;
    if (controller && controller.signal?.aborted !== true) {
      try {
        controller.abort(createMediaTranscriptAbortError(reason));
      } catch {
        // ignore local abort failures
      }
    }
    const record = ensureMediaTranscriptIndexLoaded().get(normalizedKey) || null;
    const transferContext = Array.from(runtime.mediaTranscriptTransferContextById.entries())
      .find(([, entry]) => String(entry?.key || '').trim() === normalizedKey) || null;
    const transferId = cleanText(record?.transferId || transferContext?.[0] || '', 180);
    if (transferId) {
      void ipcRenderer.invoke('abort-transfer-operation', {
        transferId,
        reason: cleanText(reason || '', 32).toLowerCase() === 'paused' ? 'paused' : 'canceled'
      }).catch(() => false);
    }
  }

  function setMediaTranscriptStateByKey(key = '', status = 'paused', message = '') {
    const normalizedKey = cleanText(key || '', 420);
    if (!normalizedKey) return null;
    const record = ensureMediaTranscriptIndexLoaded().get(normalizedKey) || null;
    if (!record) return null;
    return setMediaTranscriptRecord(record, record, {
      status,
      stage: status,
      message,
      error: status === 'error' ? cleanText(message || record?.error || 'Не удалось подготовить TXT.', 220) : '',
      percent: status === 'canceled' ? 0 : Number(record?.percent || 0)
    });
  }

  function pauseMediaTranscriptByKey(key = '') {
    const normalizedKey = cleanText(key || '', 420);
    if (!normalizedKey) return false;
    runtime.mediaTranscriptQueue = runtime.mediaTranscriptQueue.filter((item) => String(item?.key || '').trim() !== normalizedKey);
    runtime.mediaTranscriptQueuedKeys.delete(normalizedKey);
    abortMediaTranscriptTransfer(normalizedKey, 'paused');
    setMediaTranscriptStateByKey(normalizedKey, 'paused', 'TXT поставлен на паузу');
    scheduleMediaTranscriptRender();
    return true;
  }

  function cancelMediaTranscriptByKey(key = '') {
    const normalizedKey = cleanText(key || '', 420);
    if (!normalizedKey) return false;
    runtime.mediaTranscriptQueue = runtime.mediaTranscriptQueue.filter((item) => String(item?.key || '').trim() !== normalizedKey);
    runtime.mediaTranscriptQueuedKeys.delete(normalizedKey);
    abortMediaTranscriptTransfer(normalizedKey, 'canceled');
    setMediaTranscriptStateByKey(normalizedKey, 'canceled', 'Подготовка TXT отменена');
    scheduleMediaTranscriptRender();
    return true;
  }

  function handleMediaTranscriptActionNode(actionNode = null) {
    if (!(actionNode instanceof HTMLElement)) return false;
    const action = cleanText(actionNode.dataset.mediaTranscriptAction || '', 40).toLowerCase();
    const context = buildMediaTranscriptContextFromDataset(actionNode);
    const attachment = buildMediaTranscriptAttachmentFromDataset(actionNode);
    const key = buildMediaTranscriptKey(context, attachment);
    if (!key) {
      showTemporaryStatus('Не удалось определить вложение для TXT');
      return true;
    }
    const existing = getMediaTranscriptRecord(context, attachment);
    if (action === 'copy') {
      const text = cleanMultiline(existing?.text || '', 12000);
      if (!text) {
        showTemporaryStatus('TXT пока пустой');
        return true;
      }
      void copyTextToClipboard(text).then((copied) => {
        showTemporaryStatus(copied ? 'TXT скопирован' : 'Не удалось скопировать TXT');
      });
      return true;
    }
    if (action === 'toggle-visibility') {
      setMediaTranscriptRecord(context, attachment, {
        hidden: existing?.hidden !== true
      });
      refreshMediaTranscriptInlineUi(actionNode, context, attachment);
      return true;
    }
    if (action === 'pause') {
      const paused = pauseMediaTranscriptByKey(key);
      if (paused) {
        refreshMediaTranscriptInlineUi(actionNode, context, attachment);
      }
      return paused;
    }
    if (action === 'cancel') {
      const canceled = cancelMediaTranscriptByKey(key);
      if (canceled) {
        refreshMediaTranscriptInlineUi(actionNode, context, attachment);
      }
      return canceled;
    }
    if (action !== 'transcribe' && action !== 'retry' && action !== 'resume') return false;
    if (
      action === 'transcribe'
      && (
        runtime.mediaTranscriptInFlightKey === key
        || runtime.mediaTranscriptQueuedKeys.has(key)
        || existing?.status === 'processing'
        || existing?.status === 'queued'
      )
    ) {
      refreshMediaTranscriptInlineUi(actionNode, context, attachment);
      return true;
    }
    const normalizedStatus = normalizeMediaTranscriptStatus(existing?.status || '');
    const enqueued = enqueueMediaTranscript(context, attachment, {
      force: action !== 'transcribe'
        || normalizedStatus === 'ready'
        || normalizedStatus === 'error'
        || normalizedStatus === 'canceled',
      userInitiated: true
    });
    if (enqueued) {
      refreshMediaTranscriptInlineUi(actionNode, context, attachment);
    } else {
      showTemporaryStatus('Не удалось запустить TXT');
    }
    return true;
  }

  async function executeMediaTranscriptJob(job = null) {
    const context = job?.context && typeof job.context === 'object' ? job.context : null;
    const attachment = job?.attachment && typeof job.attachment === 'object' ? job.attachment : null;
    if (!context || !attachment || !isTranscriptableAttachment(attachment)) {
      return null;
    }
    const userInitiated = job?.options?.userInitiated === true;
    const existingRecord = getMediaTranscriptRecord(context, attachment);
    const shouldExposeProgress = userInitiated || Boolean(existingRecord);
    const key = buildMediaTranscriptKey(context, attachment);
    const transferId = shouldExposeProgress && key
      ? beginLocalTransferProgress({
        scope: 'transcript',
        label: 'Подготовка TXT',
        doneText: 'TXT готов',
        message: 'Подготавливаю файл',
        percent: 2,
        suppressHud: true,
        suppressToast: true
      })
      : '';
    const abortController = (shouldExposeProgress && typeof AbortController === 'function') ? new AbortController() : null;
    if (key && abortController) {
      runtime.mediaTranscriptAbortControllersByKey.set(key, abortController);
    }
    if (transferId) {
      registerMediaTranscriptTransferContext(transferId, context, attachment);
    }
    if (shouldExposeProgress) {
      setMediaTranscriptRecord(context, attachment, {
        status: 'processing',
        error: '',
        percent: 2,
        stage: 'start',
        message: 'Готовлю TXT…',
        transferId
      });
      scheduleMediaTranscriptRender();
    }
    try {
      if (transferId) {
        updateLocalTransferProgress(transferId, {
          scope: 'transcript',
          stage: 'start',
          percent: 2,
          message: 'Подготавливаю файл'
        });
      }
      const { chunks, sampleRate } = await buildTranscriptPcmChunksFromAttachment(attachment, {
        transferId,
        signal: abortController?.signal || null
      });
      const transcript = await transcribePcmChunksWithOfflineVosk(chunks, sampleRate, {
        mode: 'attachment',
        transferId,
        signal: abortController?.signal || null
      });
      const record = setMediaTranscriptRecord(context, attachment, {
        status: 'ready',
        text: transcript,
        error: '',
        percent: 100,
        stage: 'done',
        message: transcript ? 'TXT готов' : 'Речь не найдена.',
        transferId: ''
      });
      if (transferId) {
        completeLocalTransferProgress(transferId, {
          scope: 'transcript',
          message: transcript ? 'TXT готов' : 'Речь не найдена'
        });
      }
      if (shouldExposeProgress || transcript) {
        scheduleMediaTranscriptRender();
      }
      return record;
    } catch (error) {
      const abortReason = getMediaTranscriptAbortReason(error);
      const message = cleanText(error?.message || 'Не удалось распознать аудио.', 220);
      const record = shouldExposeProgress
        ? setMediaTranscriptRecord(context, attachment, {
          status: abortReason || 'error',
          error: abortReason ? '' : message,
          stage: abortReason || 'error',
          message,
          transferId: '',
          percent: abortReason === 'canceled' ? 0 : Number(getMediaTranscriptRecord(context, attachment)?.percent || 0)
        })
        : null;
      if (transferId) {
        if (abortReason === 'paused' || abortReason === 'canceled') {
          cancelLocalTransferProgress(transferId);
        } else {
          failLocalTransferProgress(transferId, message, {
            scope: 'transcript'
          });
        }
      }
      if (shouldExposeProgress) {
        scheduleMediaTranscriptRender();
      }
      return record;
    } finally {
      if (transferId) {
        unregisterMediaTranscriptTransferContext(transferId);
      }
      if (key) {
        runtime.mediaTranscriptAbortControllersByKey.delete(key);
      }
    }
  }

  async function processMediaTranscriptQueue() {
    if (runtime.mediaTranscriptInFlightPromise) {
      return runtime.mediaTranscriptInFlightPromise;
    }
    runtime.mediaTranscriptInFlightPromise = (async () => {
      while (runtime.mediaTranscriptQueue.length) {
        const job = runtime.mediaTranscriptQueue.shift();
        const key = String(job?.key || '').trim();
        if (key) {
          runtime.mediaTranscriptQueuedKeys.delete(key);
          runtime.mediaTranscriptInFlightKey = key;
        }
        try {
          await executeMediaTranscriptJob(job);
        } finally {
          runtime.mediaTranscriptInFlightKey = '';
        }
      }
    })().finally(() => {
      runtime.mediaTranscriptInFlightPromise = null;
      runtime.mediaTranscriptInFlightKey = '';
    });
    return runtime.mediaTranscriptInFlightPromise;
  }

  function enqueueMediaTranscript(context = null, attachment = null, options = {}) {
    if (!context || !attachment || !isTranscriptableAttachment(attachment)) {
      return false;
    }
    const key = buildMediaTranscriptKey(context, attachment);
    if (!key) return false;
    const existing = getMediaTranscriptRecord(context, attachment);
    const isUserInitiated = options?.userInitiated === true;
    const force = options?.force === true;
    if (!force) {
      if (runtime.mediaTranscriptInFlightKey === key || runtime.mediaTranscriptQueuedKeys.has(key)) {
        return false;
      }
      if (existing?.status === 'processing' || existing?.status === 'queued' || existing?.status === 'ready' || existing?.status === 'error') {
        return false;
      }
    }
    if (force) {
      runtime.mediaTranscriptQueue = runtime.mediaTranscriptQueue.filter((item) => String(item?.key || '').trim() !== key);
      runtime.mediaTranscriptQueuedKeys.delete(key);
    }
    if (isUserInitiated) {
      setMediaTranscriptRecord(context, attachment, {
        status: 'queued',
        error: '',
        percent: 0,
        stage: 'queued',
        message: 'Файл ждёт обработки'
      });
      scheduleMediaTranscriptRender();
    }
    runtime.mediaTranscriptQueuedKeys.add(key);
    runtime.mediaTranscriptQueue.push({
      key,
      context: {
        workspaceId: String(context.workspaceId || '').trim(),
        chatId: normalizeChatId(context.chatId || ''),
        messageId: String(context.messageId || '').trim()
      },
      attachment: {
        ...attachment,
        id: String(attachment?.id || attachment?.fileId || '').trim(),
        url: normalizeAssetUrl(resolveAttachmentDownloadUrl(attachment) || attachment?.url || '', 8192),
        name: cleanText(attachment?.name || '', 180),
        mimeType: cleanText(inferAttachmentMimeType(attachment) || attachment?.mimeType || '', 180),
        size: Math.max(0, Number(attachment?.size || 0))
      },
      options: {
        userInitiated: isUserInitiated
      }
    });
    void processMediaTranscriptQueue();
    return true;
  }

  function scheduleActiveChatMediaTranscriptWarmup(messages = [], workspaceId = '', chatId = '') {
    void messages;
    void workspaceId;
    void chatId;
    if (runtime.mediaTranscriptWarmupTimer) {
      window.clearTimeout(runtime.mediaTranscriptWarmupTimer);
      runtime.mediaTranscriptWarmupTimer = 0;
    }
    runtime.mediaTranscriptWarmupSignature = '';
    runtime.mediaTranscriptQueue = runtime.mediaTranscriptQueue.filter((job) => job?.options?.userInitiated === true);
    runtime.mediaTranscriptQueuedKeys = new Set(
      runtime.mediaTranscriptQueue
        .map((job) => String(job?.key || '').trim())
        .filter(Boolean)
    );
  }

  function terminateVoiceDictationModel(model = null) {
    if (!model || typeof model.terminate !== 'function') {
      return;
    }
    try {
      model.terminate();
    } catch {
      // ignore model teardown failures
    }
  }

  async function loadVoiceDictationModelFromUrl(modelUrl = '') {
    const normalizedUrl = String(modelUrl || '').trim();
    if (!normalizedUrl) {
      throw new Error('Не найдена локальная модель распознавания.');
    }
    const VoskBrowser = getLazyVoskBrowser();
    if (!VoskBrowser || typeof VoskBrowser.Model !== 'function') {
      throw new Error('Локальная диктовка недоступна в этой сборке.');
    }

    return new Promise((resolve, reject) => {
      const timeoutMs = 30 * 1000;
      let settled = false;
      let timeoutHandle = 0;
      let model = null;

      const cleanup = () => {
        if (timeoutHandle) {
          clearTimeout(timeoutHandle);
          timeoutHandle = 0;
        }
        if (model instanceof EventTarget) {
          model.removeEventListener('load', handleLoad);
          model.removeEventListener('error', handleModelError);
        }
        if (model?.worker && typeof model.worker.removeEventListener === 'function') {
          model.worker.removeEventListener('error', handleWorkerError);
          model.worker.removeEventListener('messageerror', handleWorkerError);
        }
      };

      const fail = (error) => {
        if (settled) return;
        settled = true;
        cleanup();
        terminateVoiceDictationModel(model);
        reject(error instanceof Error
          ? error
          : new Error(cleanText(String(error || 'Не удалось загрузить локальную модель распознавания.'), 240)));
      };

      const succeed = () => {
        if (settled || !model) return;
        settled = true;
        cleanup();
        resolve(model);
      };

      const handleLoad = (event) => {
        if (event?.detail?.result === true) {
          succeed();
          return;
        }
        const errorText = cleanText(
          event?.detail?.error || 'Не удалось загрузить локальную модель распознавания.',
          240
        );
        fail(new Error(errorText));
      };

      const handleModelError = (event) => {
        fail(new Error(cleanText(
          event?.detail?.error || event?.message || 'Не удалось загрузить локальную модель распознавания.',
          240
        )));
      };

      const handleWorkerError = (event) => {
        fail(new Error(cleanText(
          event?.message || 'Не удалось запустить воркер локальной диктовки.',
          240
        )));
      };

      timeoutHandle = window.setTimeout(() => {
        fail(new Error('Локальная модель распознавания не ответила вовремя.'));
      }, timeoutMs);

      try {
        model = new VoskBrowser.Model(normalizedUrl, -1);
      } catch (error) {
        fail(error);
        return;
      }

      if (!(model instanceof EventTarget)) {
        fail(new Error('Не удалось инициализировать локальную модель распознавания.'));
        return;
      }

      model.addEventListener('load', handleLoad);
      model.addEventListener('error', handleModelError);
      if (model?.worker && typeof model.worker.addEventListener === 'function') {
        model.worker.addEventListener('error', handleWorkerError);
        model.worker.addEventListener('messageerror', handleWorkerError);
      }
      if (model.ready === true) {
        succeed();
      }
    });
  }

  async function ensureVoiceDictationModel() {
    if (runtime.voiceDictationModel) {
      return runtime.voiceDictationModel;
    }
    if (runtime.voiceDictationModelPromise) {
      return runtime.voiceDictationModelPromise;
    }

    runtime.voiceDictationModelPromise = (async () => {
      const modelUrl = cleanText(
        await ipcRenderer.invoke('read-local-asset-url', VOSK_BROWSER_MODEL_ASSET_PATH).catch(() => ''),
        4000
      );
      if (modelUrl) {
        try {
          const model = await loadVoiceDictationModelFromUrl(modelUrl);
          runtime.voiceDictationModel = model;
          return model;
        } catch (error) {
          console.warn?.('[YuChat] Voice dictation model URL load failed:', error);
        }
      }

      const dataUrl = String(
        await ipcRenderer.invoke('read-local-asset-data-url', VOSK_BROWSER_MODEL_ASSET_PATH).catch(() => '')
      ).trim();
      if (!dataUrl) {
        throw new Error('Не найдена локальная модель распознавания.');
      }

      const model = await loadVoiceDictationModelFromUrl(dataUrl);
      runtime.voiceDictationModel = model;
      return model;
    })();

    try {
      return await runtime.voiceDictationModelPromise;
    } catch (error) {
      runtime.voiceDictationModelPromise = null;
      runtime.voiceDictationModel = null;
      throw error;
    }
  }

  function cleanupVoiceDictationAudioGraph() {
    const processorNode = runtime.voiceDictationProcessorNode;
    runtime.voiceDictationProcessorNode = null;
    if (processorNode && typeof processorNode.disconnect === 'function') {
      try {
        processorNode.disconnect();
      } catch {
        // ignore processor disconnect failures
      }
    }

    const sinkNode = runtime.voiceDictationSinkNode;
    runtime.voiceDictationSinkNode = null;
    if (sinkNode && typeof sinkNode.disconnect === 'function') {
      try {
        sinkNode.disconnect();
      } catch {
        // ignore sink disconnect failures
      }
    }

    const sourceNode = runtime.voiceDictationSourceNode;
    runtime.voiceDictationSourceNode = null;
    if (sourceNode && typeof sourceNode.disconnect === 'function') {
      try {
        sourceNode.disconnect();
      } catch {
        // ignore source disconnect failures
      }
    }

    const stream = runtime.voiceDictationStream;
    runtime.voiceDictationStream = null;
    if (stream && typeof stream.getTracks === 'function') {
      stream.getTracks().forEach((track) => {
        try {
          track.stop();
        } catch {
          // ignore track stop failures
        }
      });
    }

    const audioContext = runtime.voiceDictationAudioContext;
    runtime.voiceDictationAudioContext = null;
    if (audioContext && typeof audioContext.close === 'function' && audioContext.state !== 'closed') {
      void audioContext.close().catch(() => {});
    }
  }

  function cleanupVoiceDictationRecognizer() {
    const recognizer = runtime.voiceDictationRecognizer;
    runtime.voiceDictationRecognizer = null;
    runtime.voiceDictationTranscriptParts = [];
    runtime.voiceDictationPcmChunks = [];
    runtime.voiceDictationSampleRate = 16000;

    if (recognizer instanceof EventTarget) {
      if (typeof runtime.voiceDictationResultListener === 'function') {
        recognizer.removeEventListener('result', runtime.voiceDictationResultListener);
      }
      if (typeof runtime.voiceDictationErrorListener === 'function') {
        recognizer.removeEventListener('error', runtime.voiceDictationErrorListener);
      }
    }

    runtime.voiceDictationResultListener = null;
    runtime.voiceDictationErrorListener = null;

    if (recognizer && typeof recognizer.remove === 'function') {
      try {
        recognizer.remove();
      } catch {
        // ignore recognizer cleanup failures
      }
    }
  }

  function buildVoiceDictationInsertText(text = '') {
    const normalizedText = formatVoiceDictationTranscript(text);
    if (!normalizedText) return '';
    const currentValue = getComposerPlainText();
    const { start, end } = getComposerSelectionOffsets();
    const before = currentValue.slice(0, start);
    const after = currentValue.slice(end);
    const prefix = (
      before
      && !normalizedText.startsWith('\n')
      && !/[\s([{«"“„'`-]$/u.test(before)
    ) ? ' ' : '';
    const suffix = (
      after
      && !normalizedText.endsWith('\n')
      && !/^[\s,.;:!?)}\]»"“„']/u.test(after)
    ) ? ' ' : '';
    return `${prefix}${normalizedText}${suffix}`;
  }

  function normalizeVoiceDictationTranscriptSource(text = '') {
    return cleanMultiline(
      String(text || '')
        .toLowerCase()
        .replace(/ё/g, 'е')
        .replace(/\s+/gu, ' ')
        .trim(),
      6000
    );
  }

  function applyVoiceDictationReplacements(source = '', replacements = []) {
    let output = String(source || '');
    (Array.isArray(replacements) ? replacements : []).forEach((entry) => {
      if (!entry || !(entry.pattern instanceof RegExp)) return;
      output = output.replace(entry.pattern, String(entry.replacement ?? ''));
    });
    return output;
  }

  function buildVoiceDictationPhrasePattern(phrases = []) {
    const parts = (Array.isArray(phrases) ? phrases : [])
      .map((phrase) => cleanText(String(phrase || '').toLowerCase(), 120))
      .filter(Boolean)
      .map((phrase) => escapeRegExp(phrase).replace(/\s+/gu, '\\s+'));
    if (!parts.length) return null;
    return new RegExp(`(?<![\\p{L}\\p{N}_])(?:${parts.join('|')})(?![\\p{L}\\p{N}_])`, 'gu');
  }

  function capitalizeVoiceDictationSentences(text = '') {
    let shouldCapitalize = true;
    let output = '';
    for (const char of String(text || '')) {
      if (shouldCapitalize && /\p{L}/u.test(char)) {
        output += char.toLocaleUpperCase('ru-RU');
        shouldCapitalize = false;
        continue;
      }
      output += char;
      if (/[.!?]/u.test(char) || char === '\n') {
        shouldCapitalize = true;
        continue;
      }
      if (!/[\s«"“„([{]/u.test(char)) {
        shouldCapitalize = false;
      }
    }
    return output;
  }

  function formatVoiceDictationTranscript(text = '') {
    const paragraphToken = '\u0000PARA\u0000';
    const lineToken = '\u0000LINE\u0000';
    let output = normalizeVoiceDictationTranscriptSource(text);
    if (!output) return '';

    output = applyVoiceDictationReplacements(output, [
      { pattern: buildVoiceDictationPhrasePattern(['новый абзац', 'новый параграф', 'нового абзаца', 'нового параграфа']), replacement: ` ${paragraphToken} ` },
      { pattern: buildVoiceDictationPhrasePattern(['новая строка', 'новая строчка', 'с новой строки', 'с новой строчки', 'перенос строки', 'перенос строчки']), replacement: ` ${lineToken} ` },
      { pattern: buildVoiceDictationPhrasePattern(['точка с запятой']), replacement: ';' },
      { pattern: buildVoiceDictationPhrasePattern(['вопросительный знак', 'знак вопроса', 'знак вопрос']), replacement: '?' },
      { pattern: buildVoiceDictationPhrasePattern(['восклицательный знак', 'знак восклицания', 'знак восклицание']), replacement: '!' },
      { pattern: buildVoiceDictationPhrasePattern(['двоеточие']), replacement: ':' },
      { pattern: buildVoiceDictationPhrasePattern(['запятая', 'запятую', 'запятой']), replacement: ',' },
      { pattern: buildVoiceDictationPhrasePattern(['точка', 'точку']), replacement: '.' },
      { pattern: buildVoiceDictationPhrasePattern(['тире', 'длинное тире']), replacement: ' — ' },
      { pattern: buildVoiceDictationPhrasePattern(['дефис']), replacement: '-' },
      { pattern: buildVoiceDictationPhrasePattern(['открывающая скобка', 'открыть скобку', 'открой скобку', 'скобка открывается']), replacement: '(' },
      { pattern: buildVoiceDictationPhrasePattern(['закрывающая скобка', 'закрыть скобку', 'закрой скобку', 'скобка закрывается']), replacement: ')' },
      { pattern: buildVoiceDictationPhrasePattern(['открывающая кавычка', 'открывающие кавычки', 'открываются кавычки', 'открывающиеся кавычки', 'открыть кавычки', 'открой кавычки']), replacement: '«' },
      { pattern: buildVoiceDictationPhrasePattern(['закрывающая кавычка', 'закрывающие кавычки', 'закрываются кавычки', 'закрывающиеся кавычки', 'закрыть кавычки', 'закрой кавычки']), replacement: '»' },
      { pattern: buildVoiceDictationPhrasePattern(['палец вверх', 'пальцы вверх', 'большой палец вверх', 'эмодзи палец вверх', 'эмоджи палец вверх', 'эмодзи лайк', 'эмоджи лайк', 'смайл лайк', 'смайлик лайк', 'смайл палец вверх', 'смайлик палец вверх', 'лайк']), replacement: '👍' },
      { pattern: buildVoiceDictationPhrasePattern(['дизлайк', 'палец вниз', 'эмодзи дизлайк', 'эмоджи дизлайк']), replacement: '👎' },
      { pattern: buildVoiceDictationPhrasePattern(['сердечко', 'сердце', 'смайл сердце', 'смайлик сердце', 'эмодзи сердечко', 'эмоджи сердечко']), replacement: '❤️' },
      { pattern: buildVoiceDictationPhrasePattern(['эмодзи огонь', 'эмоджи огонь', 'эмодзи огонек', 'эмоджи огонек', 'эмоджи огонёк', 'смайл огонь', 'смайлик огонь', 'смайл огонек', 'смайлик огонек', 'смайл огонёк', 'смайлик огонёк']), replacement: '🔥' },
      { pattern: buildVoiceDictationPhrasePattern(['эмодзи ракета', 'эмоджи ракета', 'смайл ракета', 'смайлик ракета']), replacement: '🚀' },
      { pattern: buildVoiceDictationPhrasePattern(['эмодзи хлопаю', 'эмоджи хлопаю', 'аплодисменты', 'смайл хлопаю', 'смайлик хлопаю']), replacement: '👏' }
      ,{ pattern: buildVoiceDictationPhrasePattern(['смайлик смех', 'смайл смех']), replacement: '😄' }
      ,{ pattern: buildVoiceDictationPhrasePattern(['грустный смайлик', 'смайл грусть', 'смайлик грусть']), replacement: '🙁' }
      ,{ pattern: buildVoiceDictationPhrasePattern(['подмигивающий смайлик', 'смайлик подмигивание', 'смайл подмигивание']), replacement: '😉' }
      ,{ pattern: buildVoiceDictationPhrasePattern(['смайлик улыбка', 'смайл улыбка', 'смайлик', 'смайл']), replacement: '🙂' }
    ]);

    output = output
      .replace(new RegExp(`\\s*${paragraphToken}\\s*`, 'gu'), '\n\n')
      .replace(new RegExp(`\\s*${lineToken}\\s*`, 'gu'), '\n')
      .replace(/[ \t]+\n/gu, '\n')
      .replace(/\n[ \t]+/gu, '\n')
      .replace(/\s+([,.;:!?)}\]»])/gu, '$1')
      .replace(/([([{«])\s+/gu, '$1')
      .replace(/([,.;:!?])(?=[^\s\n»)}\]])/gu, '$1 ')
      .replace(/([»)}\]])(?=[\p{L}\p{N}])/gu, '$1 ')
      .replace(/[ \t]{2,}/gu, ' ')
      .replace(/\n{3,}/gu, '\n\n')
      .trim();

    return capitalizeVoiceDictationSentences(output);
  }

  function encodeVoiceDictationWavBase64(chunks = [], sampleRate = 16000) {
    const normalizedChunks = (Array.isArray(chunks) ? chunks : [])
      .filter((chunk) => chunk instanceof Float32Array && chunk.length > 0);
    const totalSamples = normalizedChunks.reduce((sum, chunk) => sum + chunk.length, 0);
    if (!totalSamples) {
      return '';
    }

    const wavBuffer = new ArrayBuffer(44 + totalSamples * 2);
    const view = new DataView(wavBuffer);
    const writeAscii = (offset, value) => {
      for (let index = 0; index < value.length; index += 1) {
        view.setUint8(offset + index, value.charCodeAt(index));
      }
    };

    writeAscii(0, 'RIFF');
    view.setUint32(4, 36 + totalSamples * 2, true);
    writeAscii(8, 'WAVE');
    writeAscii(12, 'fmt ');
    view.setUint32(16, 16, true);
    view.setUint16(20, 1, true);
    view.setUint16(22, 1, true);
    view.setUint32(24, Math.max(8000, Math.round(Number(sampleRate) || 16000)), true);
    view.setUint32(28, Math.max(8000, Math.round(Number(sampleRate) || 16000)) * 2, true);
    view.setUint16(32, 2, true);
    view.setUint16(34, 16, true);
    writeAscii(36, 'data');
    view.setUint32(40, totalSamples * 2, true);

    let offset = 44;
    normalizedChunks.forEach((chunk) => {
      for (let index = 0; index < chunk.length; index += 1) {
        const sample = Math.max(-1, Math.min(1, Number(chunk[index]) || 0));
        const pcm = sample < 0 ? sample * 0x8000 : sample * 0x7fff;
        view.setInt16(offset, Math.round(pcm), true);
        offset += 2;
      }
    });

    return Buffer.from(wavBuffer).toString('base64');
  }

  async function finalizeVoiceDictation(recognizer = null) {
    if (!(recognizer instanceof EventTarget) || typeof recognizer.retrieveFinalResult !== 'function') {
      return '';
    }

    const finalChunk = cleanText(await new Promise((resolve, reject) => {
      let settled = false;
      const handleResult = (event) => {
        if (settled) return;
        settled = true;
        recognizer.removeEventListener('result', handleResult);
        recognizer.removeEventListener('error', handleError);
        resolve(cleanText(event?.detail?.result?.text || '', 6000));
      };
      const handleError = (event) => {
        if (settled) return;
        settled = true;
        recognizer.removeEventListener('result', handleResult);
        recognizer.removeEventListener('error', handleError);
        reject(new Error(cleanText(event?.detail?.error || 'Не удалось завершить распознавание.', 220)));
      };

      recognizer.addEventListener('result', handleResult);
      recognizer.addEventListener('error', handleError);

      try {
        recognizer.retrieveFinalResult();
      } catch (error) {
        recognizer.removeEventListener('result', handleResult);
        recognizer.removeEventListener('error', handleError);
        reject(error);
      }
    }), 6000);

    return [
      ...(Array.isArray(runtime.voiceDictationTranscriptParts) ? runtime.voiceDictationTranscriptParts : []),
      finalChunk
    ]
      .map((part) => cleanText(part || '', 6000))
      .filter(Boolean)
      .join(' ')
      .trim();
  }

  async function stopVoiceDictation(options = {}) {
    const recordedChunks = Array.isArray(runtime.voiceDictationPcmChunks)
      ? runtime.voiceDictationPcmChunks.slice()
      : [];
    const recordedSampleRate = Math.max(8000, Math.round(Number(runtime.voiceDictationSampleRate) || 16000));
    const shouldCommit = options.commit !== false;

    cleanupVoiceDictationAudioGraph();
    setVoiceAssistActive('dictation', false);
    setVoiceAssistProcessing('dictation', Boolean(shouldCommit && recordedChunks.length));
    scheduleRender('chat');

    cleanupVoiceDictationRecognizer();

    if (!shouldCommit) {
      setVoiceAssistProcessing('dictation', false);
      scheduleRender('chat');
      return;
    }

    if (!recordedChunks.length) {
      setVoiceAssistProcessing('dictation', false);
      scheduleRender('chat');
      showTemporaryStatus('Речь не распознана');
      return;
    }

    showTemporaryStatus('Распознаю речь…', 2600);

    try {
      const transcript = cleanText(
        await transcribePcmChunksWithOfflineVosk(recordedChunks, recordedSampleRate, {
          mode: 'dictation'
        }),
        6000
      );
      setVoiceAssistProcessing('dictation', false);
      scheduleRender('chat');

      const insertion = buildVoiceDictationInsertText(transcript);
      if (!insertion) {
        showTemporaryStatus('Речь не распознана');
        return;
      }

      insertComposerText(insertion, { selectInserted: false });
      touchComposerTypingActivity(state.activeChatWorkspaceId, state.activeChatId, getComposerPlainText());
      showTemporaryStatus('Текст вставлен в сообщение');
    } catch (error) {
      setVoiceAssistProcessing('dictation', false);
      scheduleRender('chat');
      throw error;
    }
  }

  async function startVoiceAssistCapture(mode = 'dictation') {
    const normalizedMode = cleanText(mode || '', 24).toLowerCase() === 'command' ? 'command' : 'dictation';
    if (state.voiceRecordingActive) {
      throw new Error('Сначала остановите голосовое сообщение.');
    }
    if (!canUseVoiceDictation()) {
      throw new Error(normalizedMode === 'command'
        ? 'Голосовые команды недоступны в этой сборке.'
        : 'Локальная диктовка недоступна в этой сборке.');
    }
    if (isAnyVoiceAssistActive() || isAnyVoiceAssistProcessing()) {
      throw new Error(normalizedMode === 'command'
        ? 'Сначала завершите текущую диктовку.'
        : 'Сначала завершите текущую голосовую команду.');
    }

    await ensureMicrophoneAccess();
    setVoiceAssistProcessing(normalizedMode, true);
    scheduleRender('chat');
    showTemporaryStatus(
      normalizedMode === 'command' ? 'Готовлю голосовые команды…' : 'Готовлю локальную диктовку…',
      3200
    );

    const prepareResult = await ipcRenderer.invoke('yuchat-prepare-vosk-dictation').catch((error) => ({
      ok: false,
      error: cleanText(
        error?.message || (normalizedMode === 'command'
          ? 'Не удалось подготовить голосовые команды.'
          : 'Не удалось подготовить локальную диктовку.'),
        220
      )
    }));
    if (!prepareResult || prepareResult.ok !== true) {
      throw new Error(cleanText(
        prepareResult?.error || (normalizedMode === 'command'
          ? 'Не удалось подготовить голосовые команды.'
          : 'Не удалось подготовить локальную диктовку.'),
        220
      ));
    }

    const AudioContextClass = getVoiceDictationAudioContextClass();
    if (!AudioContextClass) {
      throw new Error('Локальная диктовка недоступна в этой сборке.');
    }

    let stream = null;
    try {
      stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          channelCount: 1,
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        },
        video: false
      });
    } catch (error) {
      const errorName = cleanText(error?.name || error?.code || '', 80).toLowerCase();
      if (/(notallowed|permission|security)/i.test(errorName)) {
        throw new Error('Нет доступа к микрофону. Разрешите его для приложения.');
      }
      if (/(notfound|devicesnotfound|overconstrained)/i.test(errorName)) {
        throw new Error('Микрофон не найден.');
      }
      throw new Error(cleanText(error?.message || 'Не удалось начать диктовку.', 180));
    }

    let audioContext = null;
    try {
      audioContext = markCustomAudibleAudioContext(new AudioContextClass({
        sampleRate: 16000
      }));
      if (typeof audioContext.createScriptProcessor !== 'function') {
        throw new Error('Локальная диктовка недоступна в этой версии Chromium.');
      }

      const sourceNode = audioContext.createMediaStreamSource(stream);
      const processorNode = audioContext.createScriptProcessor(4096, 1, 1);
      const sinkNode = audioContext.createGain();
      sinkNode.gain.value = 0;

      runtime.voiceDictationPcmChunks = [];
      runtime.voiceDictationSampleRate = Math.max(8000, Math.round(Number(audioContext.sampleRate) || 16000));
      runtime.voiceDictationTranscriptParts = [];
      runtime.voiceCaptureMode = normalizedMode;

      processorNode.onaudioprocess = (event) => {
        if (!isAnyVoiceAssistActive()) return;
        try {
          const channelData = event?.inputBuffer?.getChannelData?.(0);
          if (!(channelData instanceof Float32Array) || !channelData.length) {
            return;
          }
          runtime.voiceDictationPcmChunks.push(new Float32Array(channelData));
        } catch (error) {
          console.warn?.('[YuChat] Voice dictation chunk failed:', error);
        }
      };

      sourceNode.connect(processorNode);
      processorNode.connect(sinkNode);
      sinkNode.connect(audioContext.destination);
      if (typeof audioContext.resume === 'function' && audioContext.state === 'suspended') {
        await audioContext.resume();
      }

      runtime.voiceDictationAudioContext = audioContext;
      runtime.voiceDictationStream = stream;
      runtime.voiceDictationSourceNode = sourceNode;
      runtime.voiceDictationProcessorNode = processorNode;
      runtime.voiceDictationSinkNode = sinkNode;
      setVoiceAssistActive(normalizedMode, true);
      setVoiceAssistProcessing(normalizedMode, false);
      scheduleRender('chat');
      showTemporaryStatus(
        normalizedMode === 'command'
          ? 'Командный режим включён. Нажмите ещё раз, чтобы выполнить команду.'
          : 'Диктовка включена. Нажмите ещё раз, чтобы вставить текст.',
        2800
      );
    } catch (error) {
      if (audioContext && typeof audioContext.close === 'function' && audioContext.state !== 'closed') {
        void audioContext.close().catch(() => {});
      }
      if (stream && typeof stream.getTracks === 'function') {
        stream.getTracks().forEach((track) => {
          try {
            track.stop();
          } catch {
            // ignore track stop failures
          }
        });
      }
      throw error;
    }
  }

  async function startVoiceDictation() {
    await startVoiceAssistCapture('dictation');
  }

  function toggleVoiceDictation() {
    if (state.voiceDictationProcessing || state.voiceCommandProcessing) {
      return;
    }
    if (state.voiceDictationActive) {
      void stopVoiceDictation({ commit: true }).catch((error) => {
        showTemporaryStatus(cleanText(error?.message || 'Не удалось завершить диктовку.', 180));
      });
      return;
    }
    void startVoiceDictation().catch((error) => {
      const shouldResetCapture = !isAnyVoiceAssistActive() || runtime.voiceCaptureMode === 'dictation';
      if (shouldResetCapture) {
        cleanupVoiceDictationAudioGraph();
        cleanupVoiceDictationRecognizer();
        clearVoiceAssistState();
        scheduleRender('chat');
      }
      showTemporaryStatus(cleanText(error?.message || 'Не удалось начать диктовку.', 180));
    });
  }

  function normalizeVoiceCommandPayload(value = '', limit = 180) {
    return cleanSearchInputValue(
      String(value || '')
        .replace(/^[\s,.;:!?-]+/u, '')
        .replace(/[\s,.;:!?-]+$/u, ''),
      limit
    );
  }

  function normalizeVoiceCommandTranscriptForMatch(value = '', limit = 420) {
    return cleanMultiline(
      String(value || '')
        .toLowerCase()
        .replace(/ё/g, 'е')
        .replace(/[“”«»"'`]/gu, ' ')
        .replace(/[,:;.!?]+/gu, ' ')
        .replace(/\s+/gu, ' ')
        .trim(),
      limit
    );
  }

  function normalizeVoiceCommandCompactForMatch(value = '', limit = 420) {
    return cleanMultiline(
      String(value || '')
        .toLowerCase()
        .replace(/ё/g, 'е')
        .replace(/[^a-zа-я0-9]+/giu, '')
        .trim(),
      limit
    );
  }

  function compactVoiceCommandIncludes(compact = '', variants = []) {
    const source = cleanText(compact || '', 420).toLowerCase();
    if (!source) return false;
    const safeVariants = Array.isArray(variants) ? variants : [];
    return safeVariants.some((variant) => {
      const normalizedVariant = cleanText(variant || '', 120).toLowerCase();
      return Boolean(normalizedVariant) && source.includes(normalizedVariant);
    });
  }

  function normalizeSpokenNumberToken(token = '') {
    const normalized = cleanText(token || '', 40).toLowerCase();
    if (!normalized) return 0;
    if (/^\d+$/u.test(normalized)) return Number(normalized);
    if (normalized === 'один' || normalized === 'одна') return 1;
    if (normalized === 'два' || normalized === 'две') return 2;
    if (normalized === 'три') return 3;
    if (normalized === 'четыре') return 4;
    if (normalized === 'пять') return 5;
    if (normalized === 'шесть') return 6;
    return 0;
  }

  function extractVoicePollQuestionFromTranscript(source = '') {
    const raw = cleanMultiline(String(source || '').trim(), 420);
    if (!raw) return '';
    const match = raw.match(/^(?:создай|создать)\s+опрос(?:\s*[,:\-]\s*|\s+)?([\s\S]*)$/iu);
    if (!match) return '';
    return cleanMultiline(String(match[1] || '').trim(), 300);
  }

  function parseVoicePollOptions(source = '') {
    const normalized = normalizeVoiceCommandTranscriptForMatch(source, 800);
    if (!normalized) return [];

    const indexedMatches = Array.from(normalized.matchAll(
      /(?:^|[\s,;])(?:ответ|вариант)\s*(?:номер\s*)?(\d+|один|одна|два|две|три|четыре|пять|шесть)\s*(?:-|—|–|:)?\s*([^,;]+?)(?=(?:[\s,;]+(?:ответ|вариант)\s*(?:номер\s*)?(?:\d+|один|одна|два|две|три|четыре|пять|шесть)(?:[\s,;]|$))|$)/gu
    ));

    if (indexedMatches.length) {
      return indexedMatches
        .map((match) => ({
          order: normalizeSpokenNumberToken(match[1] || ''),
          text: cleanMultiline(String(match[2] || '').trim(), 220)
        }))
        .filter((entry) => entry.order > 0 && entry.text)
        .sort((left, right) => left.order - right.order)
        .map((entry) => entry.text)
        .slice(0, POLL_MAX_OPTIONS);
    }

    return normalized
      .split(/\s*[;,]\s*/u)
      .map((part) => cleanMultiline(String(part || '').replace(/^(?:и\s+)?(?:ответ|вариант)\s*(?:номер\s*)?\d*\s*(?:-|—|–|:)?\s*/iu, '').trim(), 220))
      .filter(Boolean)
      .slice(0, POLL_MAX_OPTIONS);
  }

  function buildVoiceCommandFlowHint(flow = null) {
    if (!flow || flow.type !== 'poll') return '';
    if (flow.step === 'question') {
      return 'Скажите вопрос для опроса';
    }
    return 'Теперь скажите варианты: “ответ 1 - да, ответ 2 - нет”';
  }

  function parseRecognizedVoiceSearchCommand(source = '') {
    const rawSource = cleanMultiline(String(source || '').replace(/\s+/gu, ' ').trim(), 220);
    if (!rawSource) return null;

    const dialogsScopeToken = String.raw`(?:диалог[\p{L}-]*|чат[\p{L}-]*|канал[\p{L}-]*|переписк[\p{L}-]*|контакт[\p{L}-]*|личк[\p{L}-]*)`;
    const chatScopeToken = String.raw`(?:чат[\p{L}-]*|канал[\p{L}-]*|диалог[\p{L}-]*|переписк[\p{L}-]*|личк[\p{L}-]*|сообщени[\p{L}-]*|личн[\p{L}-]*\s+чат[\p{L}-]*)`;
    const explicitSearchMatch = rawSource.match(/^(?:найди|найти|поищи|поиск)\s+(.+)$/iu);
    const implicitScopedMatch = rawSource.match(new RegExp(
      String.raw`^(?:(?:в|во|по|среди)\s+)?(?:(?:этом|текущем|всех|всем)\s+)?(?:${dialogsScopeToken}|${chatScopeToken})\s+.+$`,
      'iu'
    )) || rawSource.match(new RegExp(
      String.raw`^.+\s+(?:(?:в|во|по|среди)\s+)?(?:(?:этом|текущем|всех|всем)\s+)?(?:${dialogsScopeToken}|${chatScopeToken})$`,
      'iu'
    ));

    const bodySource = cleanMultiline(
      String(explicitSearchMatch?.[1] || (implicitScopedMatch ? rawSource : '') || '').replace(/\s+/gu, ' ').trim(),
      220
    );
    if (!bodySource) return null;

    const scopedMatchers = [
      {
        scope: 'dialogs',
        patterns: [
          new RegExp(
            String.raw`^(?:(?:в|во|по|среди)\s+)?(?:(?:всех|всем)\s+)?${dialogsScopeToken}\s+(.+)$`,
            'iu'
          ),
          new RegExp(
            String.raw`^(.+?)\s+(?:(?:в|во|по|среди)\s+)?(?:(?:всех|всем)\s+)?${dialogsScopeToken}$`,
            'iu'
          )
        ]
      },
      {
        scope: 'chat',
        patterns: [
          new RegExp(
            String.raw`^(?:(?:в|во|по)\s+)?(?:(?:этом|текущем)\s+)?${chatScopeToken}\s+(.+)$`,
            'iu'
          ),
          new RegExp(
            String.raw`^(.+?)\s+(?:(?:в|во|по)\s+)?(?:(?:этом|текущем)\s+)?${chatScopeToken}$`,
            'iu'
          )
        ]
      }
    ];

    for (const descriptor of scopedMatchers) {
      const patterns = Array.isArray(descriptor?.patterns) ? descriptor.patterns : [];
      for (const pattern of patterns) {
        const scopedMatch = bodySource.match(pattern);
        const query = normalizeVoiceCommandPayload(scopedMatch?.[1] || '', 180);
        if (!query) continue;
        return {
          type: 'search',
          scope: descriptor.scope,
          query
        };
      }
    }

    return {
      type: 'search',
      scope: 'auto',
      query: normalizeVoiceCommandPayload(bodySource, 180)
    };
  }

