  function buildVoiceCommandRecognitionHint() {
    const examples = getVoiceCommandCatalog()
      .map((command) => Array.isArray(command?.examples) ? cleanText(command.examples[0] || '', 120) : '')
      .filter(Boolean);
    if (!examples.length) {
      return 'Команда не распознана';
    }
    return `Команда не распознана. Попробуйте: ${examples.map((example) => `“${example}”`).join(', ')}`;
  }

  function parseVoiceFeatureToggleCommand(normalized = '') {
    const source = cleanMultiline(String(normalized || '').toLowerCase(), 420);
    const compact = normalizeVoiceCommandCompactForMatch(source, 420);
    if (!source) return null;
    const enableRequested = /(?:^|\s)включ(?:и|ить|ит|им)?(?:\s|$)/u.test(source)
      || compactVoiceCommandIncludes(compact, ['включи', 'включить', 'включит', 'включим', 'включ']);
    const disableRequested = /(?:^|\s)(?:отключ(?:и|ить|ит|им)?|выключ(?:и|ить|ит|им)?)(?:\s|$)/u.test(source)
      || compactVoiceCommandIncludes(compact, ['отключи', 'отключить', 'отключит', 'отключим', 'отключ', 'выключи', 'выключить', 'выключит', 'выключим', 'выключ']);
    if (!enableRequested && !disableRequested) return null;

    const featureMatchers = [
      {
        feature: 'folders',
        pattern: /(?:^|\s)папк(?:а|и|у|е|ой|ок|ам|ами|ах)?(?:\s|$)/u,
        compactVariants: ['папк']
      },
      {
        feature: 'tags',
        pattern: /(?:^|\s)т[еэ]г(?:и|а|у|е|ом|ов|ам|ами|ах)?(?:\s|$)/u,
        compactVariants: ['тег', 'тэг']
      },
      {
        feature: 'filters',
        pattern: /(?:^|\s)фильтр(?:ы|а|у|е|ом|ов|ам|ами|ах)?(?:\s|$)/u,
        compactVariants: ['фильтр']
      }
    ];

    const matched = featureMatchers.find((entry) => (
      entry.pattern.test(source)
      || compactVoiceCommandIncludes(compact, entry.compactVariants)
    )) || null;
    if (!matched) return null;
    return {
      type: 'feature-toggle',
      feature: matched.feature,
      enabled: enableRequested && !disableRequested
    };
  }

  function parseVoiceThemeModeCommand(normalized = '') {
    const source = cleanMultiline(String(normalized || '').toLowerCase(), 420);
    const compact = normalizeVoiceCommandCompactForMatch(source, 420);
    if (!source) return null;
    const enableRequested = /(?:^|\s)(?:включ(?:и|ить|ит|им)?|сделай)(?:\s|$)/u.test(source)
      || compactVoiceCommandIncludes(compact, ['включи', 'включить', 'включит', 'включим', 'включ', 'сделай']);
    const disableRequested = /(?:^|\s)(?:отключ(?:и|ить|ит|им)?|выключ(?:и|ить|ит|им)?|убери)(?:\s|$)/u.test(source)
      || compactVoiceCommandIncludes(compact, ['отключи', 'отключить', 'отключит', 'отключим', 'отключ', 'выключи', 'выключить', 'выключит', 'выключим', 'выключ', 'убери']);
    if (!enableRequested && !disableRequested) return null;

    const themeMatchers = [
      {
        mode: 'dark',
        pattern: /(?:^|\s)(?:темн(?:[а-я]{0,5})?|ночн(?:[а-я]{0,5})?)(?:\s|$)/u,
        compactVariants: ['темн', 'ночн']
      },
      {
        mode: 'light',
        pattern: /(?:^|\s)светл(?:[а-я]{0,5})?(?:\s|$)/u,
        compactVariants: ['светл']
      }
    ];
    const matchedMode = themeMatchers.find((entry) => (
      entry.pattern.test(source)
      || compactVoiceCommandIncludes(compact, entry.compactVariants)
    )) || null;
    if (!matchedMode) return null;

    const tokenCount = source.split(/\s+/u).filter(Boolean).length;
    const hasThemeContext = /(?:^|\s)(?:режим|тема|оформление|фон|вид)(?:\s|$)/u.test(source)
      || compactVoiceCommandIncludes(compact, ['режим', 'тема', 'оформление', 'фон', 'вид']);
    const compactDirectIntent = matchedMode.mode === 'dark'
      ? compactVoiceCommandIncludes(compact, ['темныйрежим', 'темнаятема', 'темноформление', 'ночнойрежим'])
      : compactVoiceCommandIncludes(compact, ['светлыйрежим', 'светлаятема', 'светлоеоформление']);
    if (!hasThemeContext) {
      const compactPatterns = {
        dark: /(?:^|\s)(?:темн(?:ый|ая|ую)?|ночн(?:ый|ая|ую)?)(?:\s|$)/u,
        light: /(?:^|\s)светл(?:ый|ая|ую)?(?:\s|$)/u
      };
      if (!compactPatterns[matchedMode.mode]?.test(source) && !compactDirectIntent && tokenCount > 4) {
        return null;
      }
    }

    return {
      type: 'theme-mode',
      mode: matchedMode.mode,
      enabled: enableRequested && !disableRequested
    };
  }

  function openVoiceCommandListModal() {
    return openModal({
      mode: 'voice-command-list',
      title: 'Список команд',
      description: 'Доступные голосовые команды для кнопки CMD.',
      options: getVoiceCommandCatalog(),
      cancelLabel: 'Закрыть'
    });
  }

  function parseRecognizedVoiceCommand(transcript = '') {
    const source = cleanMultiline(String(transcript || '').replace(/\s+/gu, ' ').trim(), 420);
    if (!source) return null;
    const normalized = normalizeVoiceCommandTranscriptForMatch(source, 420);
    const enableVerbPattern = String.raw`(?:включи|включить)`;
    const disableVerbPattern = String.raw`(?:отключи|отключить|выключи|выключить)`;
    if (state.voiceCommandFlow?.type === 'poll') {
      if (/^(?:отмена|отмени|отменить|сброс|сбрось)$/u.test(normalized)) {
        return {
          type: 'poll-flow-cancel'
        };
      }
      if (state.voiceCommandFlow.step === 'question') {
        return {
          type: 'poll-flow-question',
          question: cleanMultiline(source, 300)
        };
      }
      const flowOptions = parseVoicePollOptions(source);
      return {
        type: flowOptions.length >= POLL_MIN_OPTIONS ? 'poll-flow-options' : 'poll-flow-options-invalid',
        options: flowOptions
      };
    }

    const themeCommand = parseVoiceThemeModeCommand(normalized);
    if (themeCommand) {
      return themeCommand;
    }
    if (new RegExp(`^${enableVerbPattern}\\s+папки$`, 'u').test(normalized)) {
      return { type: 'feature-toggle', feature: 'folders', enabled: true };
    }
    if (new RegExp(`^${disableVerbPattern}\\s+папки$`, 'u').test(normalized)) {
      return { type: 'feature-toggle', feature: 'folders', enabled: false };
    }
    if (new RegExp(`^${enableVerbPattern}\\s+теги$`, 'u').test(normalized)) {
      return { type: 'feature-toggle', feature: 'tags', enabled: true };
    }
    if (new RegExp(`^${disableVerbPattern}\\s+теги$`, 'u').test(normalized)) {
      return { type: 'feature-toggle', feature: 'tags', enabled: false };
    }
    if (new RegExp(`^${enableVerbPattern}\\s+фильтры$`, 'u').test(normalized)) {
      return { type: 'feature-toggle', feature: 'filters', enabled: true };
    }
    if (new RegExp(`^${disableVerbPattern}\\s+фильтры$`, 'u').test(normalized)) {
      return { type: 'feature-toggle', feature: 'filters', enabled: false };
    }
    const featureToggleCommand = parseVoiceFeatureToggleCommand(normalized);
    if (featureToggleCommand) {
      return featureToggleCommand;
    }

    if (/^(?:создай|создать)\s+опрос(?:$|\s|[,:\-])/u.test(normalized)) {
      return {
        type: 'poll-flow-start',
        question: extractVoicePollQuestionFromTranscript(source)
      };
    }

    const openMatch = normalized.match(/^(?:(?:открой|открыть|перейди|переключись)(?:\s+в)?\s+)?(?:чат|диалог|канал|личку|личный чат)\s+(.+)$/u)
      || normalized.match(/^(?:открой|открыть|перейди|переключись)\s+(.+)$/u);
    if (openMatch?.[1]) {
      return {
        type: 'open-chat',
        query: normalizeVoiceCommandPayload(source.slice(source.length - openMatch[1].length), 120)
      };
    }

    const calendarSlotMatch = normalized.match(/^(?:найди|найти|подбери|подобрать)\s+(?:слот|окно|время)(?:\s+(?:с|для))?\s+(.+)$/u);
    if (calendarSlotMatch?.[1]) {
      return {
        type: 'calendar-slot',
        query: normalizeVoiceCommandPayload(source.slice(source.length - calendarSlotMatch[1].length), 180)
      };
    }

    const searchCommand = parseRecognizedVoiceSearchCommand(source);
    if (searchCommand?.query) {
      return searchCommand;
    }

    const callMatch = normalized.match(/^(?:позвони|позвонить|набери|набрать|созвонись|созвониться)(?:\s+(?:с|c))?(?:\s+(.+))?$/u);
    if (callMatch) {
      return {
        type: 'call',
        query: callMatch?.[1]
          ? normalizeVoiceCommandPayload(source.slice(source.length - callMatch[1].length), 120)
          : ''
      };
    }

    return null;
  }

  function findBestVoiceCommandChatEntry(query = '') {
    const normalizedQuery = normalizeVoiceCommandPayload(query, 120);
    if (!normalizedQuery) return null;
    const options = filterForwardTargetModalOptions(getForwardTargetModalOptions(), normalizedQuery);
    const bestOption = Array.isArray(options) ? options[0] : null;
    if (!bestOption?.workspaceId || !bestOption?.chatId) return null;
    return findRecentByChatId(bestOption.workspaceId, bestOption.chatId) || null;
  }

  async function resolveVoiceCommandDirectCallEntry(query = '') {
    const normalizedQuery = normalizeVoiceCommandPayload(query, 120);
    const activeEntry = getCurrentChatEntry();
    if (!normalizedQuery) {
      return isDirectChatEntry(activeEntry) ? activeEntry : null;
    }

    const existingEntry = findBestVoiceCommandChatEntry(normalizedQuery);
    if (existingEntry && isDirectChatEntry(existingEntry)) {
      return existingEntry;
    }

    const preferredWorkspaceId = String(
      activeEntry?.workspaceId
      || state.activeChatWorkspaceId
      || getActiveWorkspaceId()
      || ''
    ).trim();
    const workspaceIds = listWorkspaceIdsForDirectChatSearch(preferredWorkspaceId);

    for (const workspaceId of workspaceIds) {
      let contacts = [];
      try {
        contacts = await listWorkspaceContacts(workspaceId, normalizedQuery, {
          limit: 12
        });
      } catch (error) {
        contacts = [];
      }
      if (!contacts.length) {
        try {
          const fallbackPool = await listWorkspaceContacts(workspaceId, '', { limit: 160 });
          contacts = filterWorkspaceContactsByQuery(fallbackPool, normalizedQuery, 12);
        } catch (error) {
          contacts = [];
        }
      }
      const contactEntry = Array.isArray(contacts)
        ? contacts.find((entry) => String(entry?.directMemberId || '').trim())
        : null;
      if (!contactEntry) continue;

      const opened = await openOrCreateDirectChatFromContact(contactEntry);
      if (!opened) continue;

      const currentEntry = getCurrentChatEntry();
      if (currentEntry && isDirectChatEntry(currentEntry)) {
        return currentEntry;
      }

      const memberId = String(contactEntry.directMemberId || '').trim();
      const resolvedEntry = memberId
        ? findDirectRecentByMemberIdAcrossWorkspaces(memberId, {
          preferredWorkspaceId: String(contactEntry.workspaceId || workspaceId || '').trim()
        })
        : null;
      if (resolvedEntry && isDirectChatEntry(resolvedEntry)) {
        return resolvedEntry;
      }
    }

    return null;
  }

  function clearVoiceCommandFlow() {
    state.voiceCommandFlow = null;
  }

  function getVoicePollTargetContext() {
    const active = getCurrentChatState();
    const workspaceId = String(active?.workspaceId || state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
    const chatId = normalizeChatId(active?.chatId || state.activeChatId || '');
    if (!workspaceId || !chatId || /^t:/i.test(chatId)) {
      return null;
    }
    return { workspaceId, chatId };
  }

  function buildVoicePollPayload(question = '', optionTexts = []) {
    const safeQuestion = cleanMultiline(String(question || '').trim(), 600);
    const options = (Array.isArray(optionTexts) ? optionTexts : [])
      .map((item, index) => ({
        id: `opt-${index + 1}`,
        text: cleanMultiline(String(item || '').trim(), 220).replace(/\s+/gu, ' ').trim()
      }))
      .filter((entry) => entry.text)
      .slice(0, POLL_MAX_OPTIONS);
    if (!safeQuestion || options.length < POLL_MIN_OPTIONS) return null;
    return normalizePollCreatePayload({
      pollId: `poll-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`,
      question: safeQuestion,
      options,
      multiple: false,
      allowRevote: true,
      showVoters: false,
      resultsVisibility: POLL_RESULTS_VISIBILITY.ALWAYS,
      createdAt: now()
    });
  }

  function setVoiceCommandThemeMode(mode = 'light') {
    const nextMode = normalizeThemeChoice(mode);
    if (state.themeMode === nextMode) {
      showTemporaryStatus(`${getThemeModeLabel(nextMode)} тема уже включена`);
      return true;
    }
    state.themeMode = nextMode;
    saveUiPreferences();
    scheduleRender(resolveInteractiveRenderScopes({
      includeOverlaysIfVisible: true,
      forceThread: true
    }));
    showThemeButtonStatus(getThemeModeLabel(nextMode));
    showTemporaryStatus(`Тема: ${getThemeModeLabel(nextMode)}`);
    return true;
  }

  function disableVoiceCommandThemeMode(mode = 'light') {
    const targetMode = normalizeThemeChoice(mode);
    if (state.themeMode !== targetMode) {
      showTemporaryStatus(`${getThemeModeLabel(targetMode)} тема уже выключена`);
      return true;
    }
    const fallbackMode = targetMode === 'dark' ? 'light' : 'dark';
    state.themeMode = fallbackMode;
    saveUiPreferences();
    scheduleRender(resolveInteractiveRenderScopes({
      includeOverlaysIfVisible: true,
      forceThread: true
    }));
    showThemeButtonStatus(getThemeModeLabel(fallbackMode));
    showTemporaryStatus(`${getThemeModeLabel(targetMode)} тема выключена. Тема: ${getThemeModeLabel(fallbackMode)}`);
    return true;
  }

  function setVoiceCommandFeatureEnabled(feature = '', enabled = true) {
    const normalizedFeature = cleanText(feature || '', 40).toLowerCase();
    const nextEnabled = enabled === true;
    if (normalizedFeature === 'filters') {
      if (isProductivityFiltersFeatureEnabled() === nextEnabled) {
        showTemporaryStatus(`Фильтры уже ${nextEnabled ? 'включены' : 'выключены'}`);
        return true;
      }
      state.productivityFiltersEnabled = nextEnabled;
      if (!nextEnabled) {
        state.inboxModesExpanded = false;
      }
      syncProductivityInboxModesWithFeatureSettings();
      saveUiPreferences();
      showTemporaryStatus(nextEnabled ? 'Фильтры включены' : 'Фильтры выключены');
      scheduleRender(resolveChatMutationRenderScopes());
      return true;
    }
    if (normalizedFeature === 'folders') {
      if (isProductivityFoldersFeatureEnabled() === nextEnabled) {
        showTemporaryStatus(`Папки уже ${nextEnabled ? 'включены' : 'выключены'}`);
        return true;
      }
      state.productivityFoldersEnabled = nextEnabled;
      if (!nextEnabled && !isProductivityChatTagsFeatureEnabled() && !isSmartFolderId(state.activeFolderId || '')) {
        state.activeFolderId = '';
      }
      saveUiPreferences();
      showTemporaryStatus(nextEnabled ? 'Папки включены' : 'Папки выключены');
      scheduleRender(resolveChatMutationRenderScopes());
      return true;
    }
    if (normalizedFeature === 'tags') {
      if (isProductivityChatTagsFeatureEnabled() === nextEnabled) {
        showTemporaryStatus(`Теги уже ${nextEnabled ? 'включены' : 'выключены'}`);
        return true;
      }
      state.productivityChatTagsEnabled = nextEnabled;
      if (!nextEnabled) {
        runtime.dialogSearchTagPickerOpen = false;
        runtime.chatSearchTagPickerOpen = false;
        if (state.appearanceOverlayOpen && state.appearanceOverlayMode === 'tags') {
          state.appearanceOverlayOpen = false;
        }
      }
      if (!nextEnabled && !isProductivityFoldersFeatureEnabled() && !isSmartFolderId(state.activeFolderId || '')) {
        state.activeFolderId = '';
      }
      saveUiPreferences();
      showTemporaryStatus(nextEnabled ? 'Теги включены' : 'Теги выключены');
      scheduleRender(resolveChatMutationRenderScopes());
      return true;
    }
    return false;
  }

  async function executeRecognizedVoiceCommand(command = null, transcript = '') {
    if (!command || typeof command !== 'object') {
      showTemporaryStatus(buildVoiceCommandFlowHint(state.voiceCommandFlow) || buildVoiceCommandRecognitionHint());
      return false;
    }

    if (command.type === 'theme-mode') {
      return command.enabled === false
        ? disableVoiceCommandThemeMode(command.mode || 'light')
        : setVoiceCommandThemeMode(command.mode || 'light');
    }

    if (command.type === 'feature-toggle') {
      return setVoiceCommandFeatureEnabled(command.feature || '', command.enabled !== false);
    }

    if (command.type === 'poll-flow-start') {
      if (!isPollsFeatureEnabled()) {
        showTemporaryStatus('Опросы отключены в настройках');
        return false;
      }
      const target = getVoicePollTargetContext();
      if (!target) {
        showTemporaryStatus('Опрос можно создать только в основном чате');
        return false;
      }
      const question = cleanMultiline(command.question || '', 300);
      state.voiceCommandFlow = {
        type: 'poll',
        step: question ? 'options' : 'question',
        workspaceId: target.workspaceId,
        chatId: target.chatId,
        question
      };
      showTemporaryStatus(question
        ? `Опрос: ${question}. Теперь скажите варианты ответа`
        : 'Скажите вопрос для опроса');
      return true;
    }

    if (command.type === 'poll-flow-cancel') {
      clearVoiceCommandFlow();
      showTemporaryStatus('Создание опроса отменено');
      return true;
    }

    if (command.type === 'poll-flow-question') {
      const flow = state.voiceCommandFlow;
      const question = cleanMultiline(command.question || '', 300);
      if (!flow || flow.type !== 'poll' || !question) {
        showTemporaryStatus('Не удалось понять вопрос для опроса');
        return false;
      }
      state.voiceCommandFlow = {
        ...flow,
        question,
        step: 'options'
      };
      showTemporaryStatus(`Вопрос сохранён. Теперь скажите варианты: “ответ 1 - да, ответ 2 - нет”`);
      return true;
    }

    if (command.type === 'poll-flow-options-invalid') {
      showTemporaryStatus('Нужны минимум два варианта: “ответ 1 - да, ответ 2 - нет”');
      return false;
    }

    if (command.type === 'poll-flow-options') {
      const flow = state.voiceCommandFlow;
      if (!flow || flow.type !== 'poll') {
        showTemporaryStatus('Сначала скажите: “создай опрос”');
        return false;
      }
      const payload = buildVoicePollPayload(flow.question || '', command.options || []);
      if (!payload) {
        showTemporaryStatus(`Нужен вопрос и минимум ${POLL_MIN_OPTIONS} варианта ответа`);
        return false;
      }
      const fallbackText = buildPollCreateFallbackText(payload);
      if (!fallbackText) {
        showTemporaryStatus('Не удалось подготовить опрос');
        return false;
      }
      try {
        await sendChatMessage(flow.workspaceId, flow.chatId, fallbackText);
        await refreshConversationMessages(flow.workspaceId, flow.chatId, {
          count: MESSAGE_PAGE_MAX,
          force: true
        });
        schedulePostMutationSync(flow.workspaceId, flow.chatId, 'message_send');
        scheduleRender(resolveChatMutationRenderScopes({
          includeSidebar: false
        }));
        clearVoiceCommandFlow();
        showTemporaryStatus('Опрос отправлен');
        return true;
      } catch (error) {
        showTemporaryStatus(cleanText(error?.message || 'Не удалось создать опрос', 180));
        return false;
      }
    }

    if (command.type === 'open-chat') {
      const entry = findBestVoiceCommandChatEntry(command.query || '');
      if (!entry) {
        showTemporaryStatus(`Чат «${cleanText(command.query || transcript || 'запрос', 120)}» не найден`);
        return false;
      }
      setSidebarMode('chats');
      runtime.todoAppletOpen = false;
      activateDialogEntry(entry, {
        force: true,
        renderSidebar: true
      });
      showTemporaryStatus(`Открываю чат: ${getRenderableEntryTitle(entry)}`);
      return true;
    }

    if (command.type === 'search') {
      const query = normalizeVoiceCommandPayload(command.query || '', 180);
      const scope = String(command.scope || 'auto').trim();
      if (!query) {
        showTemporaryStatus('Не удалось понять, что именно искать');
        return false;
      }

      if (scope === 'dialogs') {
        if (state.chatSearchOpen) {
          closeChatSearch();
        }
        setSidebarMode('chats');
        applyDialogSearchQuery(query, { focus: true });
        showTemporaryStatus(`Ищу среди диалогов: ${query}`);
        return true;
      }

      const active = getCurrentChatState();
      const hasActiveChat = Boolean(active.workspaceId && active.chatId);
      if (scope === 'chat' && !hasActiveChat) {
        showTemporaryStatus('Для поиска в чате сначала открой диалог');
        return false;
      }

      if (hasActiveChat) {
        openChatSearch();
        state.chatSearchQuery = query;
        state.chatSearchActiveId = '';
        runtime.lastChatSearchTarget = '';
        scheduleRender('chat');
        focusChatSearchInput();
        showTemporaryStatus(`Ищу в чате: ${query}`);
        return true;
      }

      setSidebarMode('chats');
      applyDialogSearchQuery(query, { focus: true });
      showTemporaryStatus(`Ищу среди диалогов: ${query}`);
      return true;
    }

    if (command.type === 'calendar-slot') {
      const query = cleanText(command.query || '', 180);
      if (!query) {
        showTemporaryStatus('Скажите, с кем нужно найти свободный слот');
        return false;
      }
      const result = await findCalendarSlots({
        query,
        prompt: false,
        insertIntoComposer: true
      });
      return Boolean(result);
    }

    if (command.type === 'call') {
      const query = normalizeVoiceCommandPayload(command.query || '', 120);
      if (!query) {
        const activeEntry = getCurrentChatEntry();
        if (!isDirectChatEntry(activeEntry)) {
          showTemporaryStatus('Скажите, кому позвонить, или откройте личный чат');
          return false;
        }
        try {
          showTemporaryStatus(`Запускаю звонок: ${getRenderableEntryTitle(activeEntry)}`, 1800);
          const callInfo = await startDirectChatCall(activeEntry);
          presentStartedCall(activeEntry, callInfo);
          return true;
        } catch (error) {
          showTemporaryStatus(getCallStartErrorMessage(error), 2600);
          return false;
        }
      }

      const entry = await resolveVoiceCommandDirectCallEntry(query);
      if (!entry || !isDirectChatEntry(entry)) {
        showTemporaryStatus(`Не удалось найти, кому позвонить: ${cleanText(query || transcript || 'запрос', 120)}`);
        return false;
      }

      try {
        showTemporaryStatus(`Запускаю звонок: ${getRenderableEntryTitle(entry)}`, 1800);
        const callInfo = await startDirectChatCall(entry);
        presentStartedCall(entry, callInfo);
        return true;
      } catch (error) {
        showTemporaryStatus(getCallStartErrorMessage(error), 2600);
        return false;
      }
    }

    showTemporaryStatus('Команда пока не поддерживается');
    return false;
  }

  async function stopVoiceCommand(options = {}) {
    const recordedChunks = Array.isArray(runtime.voiceDictationPcmChunks)
      ? runtime.voiceDictationPcmChunks.slice()
      : [];
    const recordedSampleRate = Math.max(8000, Math.round(Number(runtime.voiceDictationSampleRate) || 16000));
    const shouldCommit = options.commit !== false;

    cleanupVoiceDictationAudioGraph();
    setVoiceAssistActive('command', false);
    setVoiceAssistProcessing('command', Boolean(shouldCommit && recordedChunks.length));
    scheduleRender('chat');

    cleanupVoiceDictationRecognizer();

    if (!shouldCommit) {
      setVoiceAssistProcessing('command', false);
      scheduleRender('chat');
      return;
    }

    if (!recordedChunks.length) {
      setVoiceAssistProcessing('command', false);
      scheduleRender('chat');
      showTemporaryStatus('Команда не распознана');
      return;
    }

    showTemporaryStatus('Распознаю команду…', 2600);

    try {
      const transcript = cleanText(
        await transcribePcmChunksWithOfflineVosk(recordedChunks, recordedSampleRate, {
          mode: 'command'
        }),
        6000
      );
      setVoiceAssistProcessing('command', false);
      scheduleRender('chat');
      if (!transcript) {
        showTemporaryStatus('Команда не распознана');
        return;
      }
      void executeRecognizedVoiceCommand(parseRecognizedVoiceCommand(transcript), transcript).catch((error) => {
        showTemporaryStatus(cleanText(error?.message || 'Не удалось выполнить голосовую команду.', 180));
      });
    } catch (error) {
      setVoiceAssistProcessing('command', false);
      scheduleRender('chat');
      throw error;
    }
  }

  async function startVoiceCommand() {
    await startVoiceAssistCapture('command');
  }

  function toggleVoiceCommand() {
    if (state.voiceCommandProcessing || state.voiceDictationProcessing) {
      return;
    }
    if (state.voiceCommandActive) {
      void stopVoiceCommand({ commit: true }).catch((error) => {
        showTemporaryStatus(cleanText(error?.message || 'Не удалось завершить голосовую команду.', 180));
      });
      return;
    }
    void startVoiceCommand().catch((error) => {
      const shouldResetCapture = !isAnyVoiceAssistActive() || runtime.voiceCaptureMode === 'command';
      if (shouldResetCapture) {
        cleanupVoiceDictationAudioGraph();
        cleanupVoiceDictationRecognizer();
        clearVoiceAssistState();
        scheduleRender('chat');
      }
      showTemporaryStatus(cleanText(error?.message || 'Не удалось начать голосовую команду.', 180));
    });
  }

  function getPreferredVoiceRecorderMimeType() {
    if (typeof MediaRecorder !== 'function' || typeof MediaRecorder.isTypeSupported !== 'function') {
      return '';
    }
    const candidates = [
      'audio/ogg;codecs=opus',
      'audio/webm;codecs=opus',
      'audio/ogg',
      'audio/webm',
      'audio/mp4'
    ];
    return candidates.find((type) => MediaRecorder.isTypeSupported(type)) || '';
  }

  async function stopVoiceRecording(options = {}) {
    const recorder = runtime.voiceRecorder;
    const mimeType = cleanText(runtime.voiceRecorderMimeType || '', 120) || 'audio/webm';
    if (!recorder) {
      cleanupVoiceRecorderResources();
      state.voiceRecordingActive = false;
      scheduleRender('chat');
      return;
    }

    const chunks = runtime.voiceRecorderChunks;
    runtime.voiceRecorder = null;
    runtime.voiceRecorderMimeType = '';
    state.voiceRecordingActive = false;
    scheduleRender('chat');

    await new Promise((resolve) => {
      const finish = () => {
        cleanupVoiceRecorderResources();
        resolve();
      };
      recorder.ondataavailable = (event) => {
        if (event?.data && Number(event.data.size || 0) > 0) {
          chunks.push(event.data);
        }
      };
      recorder.onerror = finish;
      recorder.onstop = finish;
      try {
        if (recorder.state !== 'inactive') {
          recorder.stop();
        } else {
          finish();
        }
      } catch {
        finish();
      }
    });

    const shouldCommit = options.commit !== false;
    const recordedChunks = chunks.slice();
    runtime.voiceRecorderChunks = [];
    if (!shouldCommit || !recordedChunks.length) {
      if (shouldCommit && !recordedChunks.length) {
        showTemporaryStatus('Голосовое не удалось сохранить');
      }
      return;
    }

    const extension = /ogg/i.test(mimeType)
      ? 'ogg'
      : /mp4/i.test(mimeType)
        ? 'm4a'
        : 'webm';
    const file = new File(
      recordedChunks,
      `voice-${Date.now()}.${extension}`,
      { type: mimeType }
    );
    await submitComposerFiles([file], {
      kind: 'voice_note'
    });
    showTemporaryStatus('Голосовое добавлено. Нажмите отправить.');
  }

  async function startVoiceRecording() {
    if (!canUseVoiceRecording()) {
      throw new Error('Запись голоса недоступна');
    }
    await ensureMicrophoneAccess();
    const mimeType = getPreferredVoiceRecorderMimeType();
    let stream = null;
    try {
      stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    } catch (error) {
      const errorName = cleanText(error?.name || error?.code || '', 80).toLowerCase();
      if (/(notallowed|permission|security)/i.test(errorName)) {
        throw new Error('Нет доступа к микрофону. Разрешите его для приложения.');
      }
      if (/(notfound|devicesnotfound|overconstrained)/i.test(errorName)) {
        throw new Error('Микрофон не найден.');
      }
      throw new Error(cleanText(error?.message || 'Не удалось начать запись', 160));
    }
    let recorder = null;
    try {
      recorder = mimeType
        ? new MediaRecorder(stream, { mimeType })
        : new MediaRecorder(stream);
    } catch (error) {
      if (typeof stream.getTracks === 'function') {
        stream.getTracks().forEach((track) => {
          try {
            track.stop();
          } catch {
            // ignore track stop failures
          }
        });
      }
      throw error;
    }

    runtime.voiceRecorderStream = stream;
    runtime.voiceRecorder = recorder;
    runtime.voiceRecorderChunks = [];
    runtime.voiceRecorderMimeType = mimeType || cleanText(recorder.mimeType || '', 120) || 'audio/webm';
    state.voiceRecordingActive = true;

    recorder.ondataavailable = (event) => {
      if (event?.data && Number(event.data.size || 0) > 0) {
        runtime.voiceRecorderChunks.push(event.data);
      }
    };
    recorder.onerror = () => {
      void stopVoiceRecording({ commit: false });
      showTemporaryStatus('Не удалось записать голосовое сообщение');
    };
    recorder.onstop = null;

    recorder.start(250);
    scheduleRender('chat');
    showTemporaryStatus('Идёт запись голосового…');
  }

  function toggleVoiceRecording() {
    if (state.voiceRecordingActive) {
      void stopVoiceRecording({ commit: true });
      return;
    }
    void startVoiceRecording().catch((error) => {
      showTemporaryStatus(cleanText(error?.message || 'Не удалось начать запись', 180));
      scheduleRender('chat');
    });
  }

  function getPreferredVideoNoteRecorderMimeType() {
    if (typeof MediaRecorder !== 'function' || typeof MediaRecorder.isTypeSupported !== 'function') {
      return '';
    }
    const candidates = [
      'video/webm;codecs=vp9,opus',
      'video/webm;codecs=vp8,opus',
      'video/webm;codecs=h264,opus',
      'video/webm'
    ];
    return candidates.find((type) => MediaRecorder.isTypeSupported(type)) || '';
  }

  function getAuthTokenWithoutBearer() {
    return String(getAuthToken() || '').replace(/^Bearer\s+/i, '').trim();
  }

  function buildVideoNoteFileName(timestamp = now(), mimeType = 'video/webm') {
    const date = new Date(Number(timestamp) || now());
    const year = String(date.getFullYear() || '').padStart(4, '0');
    const month = String((date.getMonth() || 0) + 1).padStart(2, '0');
    const day = String(date.getDate() || 0).padStart(2, '0');
    const hours = String(date.getHours() || 0).padStart(2, '0');
    const minutes = String(date.getMinutes() || 0).padStart(2, '0');
    const seconds = String(date.getSeconds() || 0).padStart(2, '0');
    const extension = inferArchiveFileExtension(mimeType, '', '');
    const safeExtension = extension && extension !== 'bin' ? extension : 'webm';
    return `Video Note - ${year}-${month}-${day} ${hours}.${minutes}.${seconds}.${safeExtension}`;
  }

  function buildVideoNoteStreamingSocketUrl(fileId = '') {
    const normalizedFileId = String(fileId || '').trim();
    const token = getAuthTokenWithoutBearer();
    if (!normalizedFileId || !token) return '';
    try {
      const origin = new URL(window.location.origin);
      const wsProtocol = origin.protocol === 'https:' ? 'wss:' : 'ws:';
      return `${wsProtocol}//${origin.host}/ws/stream/${encodeURIComponent(normalizedFileId)}?tkc=${encodeURIComponent(token)}`;
    } catch {
      return '';
    }
  }

  async function waitForVideoNoteFileAvailability(fileId = '', options = {}) {
    const normalizedFileId = String(fileId || '').trim();
    const origin = String(window.location?.origin || '').trim();
    if (!normalizedFileId || !origin) return '';

    const targetUrl = `${origin}/api/file.download/${encodeURIComponent(normalizedFileId)}`;
    const authToken = getAuthToken();
    const maxWaitMs = Math.max(1500, Number(options?.timeoutMs) || 12000);
    const startedAt = now();
    let attempt = 0;

    const isRetryableStatus = (status = 0) => (
      status === 0
      || status === 404
      || status === 408
      || status === 409
      || status === 423
      || status === 425
      || status === 429
      || status >= 500
    );

    while ((now() - startedAt) < maxWaitMs) {
      const remainingMs = Math.max(0, maxWaitMs - (now() - startedAt));
      const controller = typeof AbortController === 'function' ? new AbortController() : null;
      const timeoutMs = Math.min(4000, Math.max(1200, remainingMs));
      const timeoutId = controller
        ? window.setTimeout(() => controller.abort(), timeoutMs)
        : 0;

      const runProbe = async (withAuthHeader = true) => {
        const headers = {
          Accept: '*/*',
          Range: 'bytes=0-0'
        };
        if (withAuthHeader && authToken) {
          headers['X-KC-Authorization'] = authToken;
        }
        return window.fetch(targetUrl, {
          method: 'GET',
          cache: 'no-store',
          credentials: 'include',
          headers,
          signal: controller?.signal
        });
      };

      let status = 0;
      try {
        let response = await runProbe(true);
        status = Number(response?.status || 0) || 0;
        if (authToken && [400, 401, 403].includes(status)) {
          response = await runProbe(false);
          status = Number(response?.status || 0) || 0;
        }
        if (status === 200 || status === 206) {
          return targetUrl;
        }
      } catch {
        status = 0;
      } finally {
        if (timeoutId) {
          window.clearTimeout(timeoutId);
        }
      }

      if (!isRetryableStatus(status) || remainingMs <= 250) {
        break;
      }

      const delayMs = Math.min(1600, 220 + (attempt * 260));
      attempt += 1;
      await new Promise((resolve) => window.setTimeout(resolve, Math.min(delayMs, remainingMs)));
    }

    return '';
  }

  function waitForVideoNoteSocketOpen(socket = null, timeoutMs = 12000) {
    return new Promise((resolve, reject) => {
      if (!socket || typeof socket.addEventListener !== 'function') {
        reject(new Error('VIDEO_NOTE_SOCKET_UNAVAILABLE'));
        return;
      }
      const timer = window.setTimeout(() => {
        cleanup();
        reject(new Error('VIDEO_NOTE_SOCKET_TIMEOUT'));
      }, Math.max(1000, Number(timeoutMs) || 12000));
      const cleanup = () => {
        window.clearTimeout(timer);
        socket.removeEventListener('open', handleOpen);
        socket.removeEventListener('error', handleError);
      };
      const handleOpen = () => {
        cleanup();
        resolve(true);
      };
      const handleError = () => {
        cleanup();
        reject(new Error('VIDEO_NOTE_SOCKET_FAILED'));
      };
      if (socket.readyState === WebSocket.OPEN) {
        cleanup();
        resolve(true);
        return;
      }
      if (socket.readyState === WebSocket.CLOSED || socket.readyState === WebSocket.CLOSING) {
        cleanup();
        reject(new Error('VIDEO_NOTE_SOCKET_CLOSED'));
        return;
      }
      socket.addEventListener('open', handleOpen, { once: true });
      socket.addEventListener('error', handleError, { once: true });
    });
  }

  function waitForVideoNoteSocketClose(socket = null, timeoutMs = 16000) {
    return new Promise((resolve) => {
      if (!socket || typeof socket.addEventListener !== 'function') {
        resolve(true);
        return;
      }
      const timer = window.setTimeout(() => {
        cleanup();
        resolve(true);
      }, Math.max(1000, Number(timeoutMs) || 16000));
      const cleanup = () => {
        window.clearTimeout(timer);
        socket.removeEventListener('close', handleClose);
        socket.removeEventListener('error', handleClose);
      };
      const handleClose = () => {
        cleanup();
        resolve(true);
      };
      if (socket.readyState === WebSocket.CLOSED) {
        cleanup();
        resolve(true);
        return;
      }
      socket.addEventListener('close', handleClose, { once: true });
      socket.addEventListener('error', handleClose, { once: true });
    });
  }

  async function waitForVideoNoteSocketDrain(socket = null, timeoutMs = 12000) {
    const deadline = now() + Math.max(1000, Number(timeoutMs) || 12000);
    while (socket && socket.readyState === WebSocket.OPEN && Number(socket.bufferedAmount || 0) > 0 && now() < deadline) {
      await new Promise((resolve) => window.setTimeout(resolve, 60));
    }
    return !socket || Number(socket.bufferedAmount || 0) <= 0;
  }

  async function uploadVideoNoteChunksViaSocket(fileId = '', chunks = [], options = {}) {
    const uploadChunks = (Array.isArray(chunks) ? chunks : []).filter((chunk) => (
      (typeof Blob === 'function' && chunk instanceof Blob)
      || chunk instanceof ArrayBuffer
      || ArrayBuffer.isView(chunk)
    ));
    if (!uploadChunks.length) {
      throw new Error('Нет данных видеозаметки для отправки.');
    }
    const socketUrl = buildVideoNoteStreamingSocketUrl(fileId);
    if (!socketUrl) {
      throw new Error('Не удалось подготовить соединение для видеозаметки.');
    }
    const socket = new WebSocket(socketUrl);
    socket.binaryType = 'blob';
    await waitForVideoNoteSocketOpen(socket, Math.max(4000, Number(options?.timeoutMs) || 12000));
    try {
      uploadChunks.forEach((chunk) => {
        socket.send(chunk);
      });
      await waitForVideoNoteSocketDrain(socket, Math.max(4000, Number(options?.timeoutMs) || 12000));
    } finally {
      try {
        if (socket.readyState === WebSocket.OPEN) {
          socket.close(1000, 'done');
        }
      } catch {
        // ignore socket close failures
      }
      await waitForVideoNoteSocketClose(socket, Math.max(2000, Number(options?.timeoutMs) || 12000));
    }
    return true;
  }

  async function stopVideoNoteRecording(options = {}) {
    const workspaceId = String(options.workspaceId || state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
    const chatId = normalizeChatId(options.chatId || state.activeChatId || '');
    const recorder = runtime.videoNoteRecorder;
    const mimeType = cleanText(runtime.videoNoteRecorderMimeType || '', 120) || 'video/webm';
    const stopActivity = () => {
      if (workspaceId && chatId) {
        void sendChatActivityState(workspaceId, chatId, ['RECORDING_A_VIDEONOTE'], false).catch(() => {});
      }
    };

    if (!recorder) {
      cleanupVideoNoteRecorderResources();
      state.videoNoteRecordingActive = false;
      scheduleRender('chat');
      stopActivity();
      return;
    }

    const chunks = runtime.videoNoteRecorderChunks;
    runtime.videoNoteRecorder = null;
    runtime.videoNoteRecorderMimeType = '';
    state.videoNoteRecordingActive = false;
    scheduleRender('chat');
    stopActivity();

    await new Promise((resolve) => {
      const finish = () => {
        cleanupVideoNoteRecorderResources();
        resolve();
      };
      recorder.ondataavailable = (event) => {
        if (event?.data && Number(event.data.size || 0) > 0) {
          chunks.push(event.data);
        }
      };
      recorder.onerror = finish;
      recorder.onstop = finish;
      try {
        if (recorder.state !== 'inactive') {
          recorder.stop();
        } else {
          finish();
        }
      } catch {
        finish();
      }
    });

    const shouldCommit = options.commit !== false;
    const recordedChunks = chunks.slice();
    runtime.videoNoteRecorderChunks = [];
    if (!shouldCommit || !recordedChunks.length) {
      if (shouldCommit && !recordedChunks.length) {
        showTemporaryStatus('Видеозаметку не удалось сохранить');
      }
      return;
    }
    if (!workspaceId || !chatId) {
      showTemporaryStatus('Не удалось определить чат для видеозаметки');
      return;
    }

    try {
      const fileName = buildVideoNoteFileName(now(), mimeType);
      const file = new File(
        recordedChunks,
        fileName,
        { type: mimeType }
      );
      const staged = stageComposerFiles([file], {
        kind: 'video_note'
      });
      if (!staged) {
        throw new Error('Не удалось добавить видеозаметку в черновик.');
      }
      clearError();
      showTemporaryStatus('Видеозаметка добавлена. Нажмите отправить.');
    } catch (error) {
      setError(`Не удалось сохранить видеозаметку (${cleanText(error?.message || '', 110)})`);
      scheduleRender('chat');
      refs.chatComposerInput?.focus({ preventScroll: true });
    }
  }

  async function startVideoNoteRecording() {
    if (!canUseVideoNoteRecording()) {
      throw new Error('Видеозаметки недоступны в этой сборке.');
    }
    if (state.videoNoteUploading) {
      throw new Error('Подождите, предыдущая видеозаметка ещё отправляется.');
    }

    const workspaceId = String(state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
    const chatId = normalizeChatId(state.activeChatId || '');
    if (!workspaceId || !chatId) {
      throw new Error('Сначала откройте чат.');
    }
    if (state.pinnedMessagesViewOpen || state.favoritesCollectionViewOpen || state.scheduledMessagesViewOpen) {
      throw new Error('Закройте текущую служебную панель и попробуйте снова.');
    }

    const draftText = cleanMultiline(getComposerPlainText(), 6000);
    const pendingFiles = getComposerPendingFiles(workspaceId, chatId);
    if (draftText || pendingFiles.length > 0) {
      throw new Error('Сначала отправьте или очистите текущий черновик.');
    }
    if (state.voiceRecordingActive || state.voiceDictationActive || state.voiceDictationProcessing || state.voiceCommandActive || state.voiceCommandProcessing) {
      throw new Error('Сначала завершите текущую запись или голосовую команду.');
    }

    await ensureMicrophoneAccess();
    await ensureCameraAccess();
    const mimeType = getPreferredVideoNoteRecorderMimeType();
    let stream = null;
    try {
      stream = await navigator.mediaDevices.getUserMedia({
        audio: true,
        video: {
          facingMode: 'user',
          width: { ideal: 640 },
          height: { ideal: 480 }
        }
      });
    } catch (error) {
      const errorName = cleanText(error?.name || error?.code || '', 80).toLowerCase();
      if (/(notallowed|permission|security)/i.test(errorName)) {
        throw new Error('Нет доступа к камере или микрофону. Разрешите его для приложения.');
      }
      if (/(notfound|devicesnotfound|overconstrained)/i.test(errorName)) {
        throw new Error('Камера или микрофон не найдены.');
      }
      throw new Error(cleanText(error?.message || 'Не удалось начать видеозаметку', 160));
    }

    let recorder = null;
    try {
      recorder = mimeType
        ? new MediaRecorder(stream, { mimeType })
        : new MediaRecorder(stream);
    } catch (error) {
      if (typeof stream.getTracks === 'function') {
        stream.getTracks().forEach((track) => {
          try {
            track.stop();
          } catch {
            // ignore track stop failures
          }
        });
      }
      throw error;
    }

    runtime.videoNoteRecorderStream = stream;
    runtime.videoNoteRecorder = recorder;
    runtime.videoNoteRecorderChunks = [];
    runtime.videoNoteRecorderMimeType = mimeType || cleanText(recorder.mimeType || '', 120) || 'video/webm';
    state.videoNoteRecordingActive = true;
    state.videoNoteUploading = false;

    recorder.ondataavailable = (event) => {
      if (event?.data && Number(event.data.size || 0) > 0) {
        runtime.videoNoteRecorderChunks.push(event.data);
      }
    };
    recorder.onerror = () => {
      void stopVideoNoteRecording({ commit: false, workspaceId, chatId });
      showTemporaryStatus('Не удалось записать видеозаметку');
    };
    recorder.onstop = null;

    recorder.start(250);
    void sendChatActivityState(workspaceId, chatId, ['RECORDING_A_VIDEONOTE'], true).catch(() => {});
    scheduleRender('chat');
    showTemporaryStatus('Идёт запись видеозаметки…');
  }

  function toggleVideoNoteRecording() {
    if (state.videoNoteRecordingActive) {
      void stopVideoNoteRecording({ commit: true });
      return;
    }
    void startVideoNoteRecording().catch((error) => {
      showTemporaryStatus(cleanText(error?.message || 'Не удалось начать видеозаметку', 180));
      scheduleRender('chat');
    });
  }

  async function openChatDrawingComposerTool() {
    const result = await openModal({
      mode: 'chat-drawing',
      title: 'Рисунок',
      description: 'Нарисуйте схему или пометку, экспортируйте её в нужный формат или добавьте прямо в текущий чат.',
      confirmLabel: 'Добавить в чат',
      cancelLabel: 'Закрыть'
    });
    const file = result?.file;
    if (!(typeof File === 'function' && file instanceof File)) {
      return false;
    }
    await submitComposerFiles([file]);
    showTemporaryStatus('Рисунок добавлен. Нажмите отправить.');
    return true;
  }

  function getComposerToolsActions() {
    if (state.composerToolsMenuMode === 'send') {
      return [
        { id: 'send-later', label: 'Отправить позже', icon: 'clock' }
      ];
    }
    if (state.composerToolsMenuMode === 'voice-command') {
      return [
        { id: 'voice-command-list', label: 'Список команд', icon: 'list' }
      ];
    }
    if (state.composerToolsMenuMode === 'voice') {
      return [
        { id: 'voice-note', label: state.voiceRecordingActive ? 'Остановить запись' : 'Записать голосовое', icon: 'call' }
      ];
    }
    const active = getCurrentChatState();
    const activeEntry = active?.workspaceId && active?.chatId
      ? findRecentByChatId(active.workspaceId, active.chatId)
      : null;
    const canCreatePoll = Boolean(
      isPollsFeatureEnabled()
      && active?.workspaceId
      && active?.chatId
      && !/^t:/i.test(active.chatId || '')
      && activeEntry?.isThread !== true
    );
    return [
      { id: 'upload', label: 'Загрузить файл', icon: 'attachment' },
      { id: 'drawing', label: 'Рисунок', icon: 'highlight' },
      { id: 'calendar-compose', label: 'Встреча из чата', icon: 'people' },
      { id: 'calendar-slot', label: 'Найти слот', icon: 'clock' },
      ...(canCreatePoll ? [{ id: 'poll-create', label: 'Опрос', icon: 'list' }] : []),
      { id: 'bold', label: 'Жирный', icon: 'bold' },
      { id: 'italic', label: 'Курсив', icon: 'italic' },
      { id: 'strike', label: 'Зачеркнутый', icon: 'strikethrough' },
      { id: 'quote', label: 'Цитата', icon: 'quote' },
      { id: 'link', label: 'Ссылка', icon: 'link' },
      { id: 'list', label: 'Список', icon: 'list' },
      { id: 'ordered-list', label: 'Нумерованный список', icon: 'ordered-list' },
      { id: 'code', label: 'Код', icon: 'code' }
    ];
  }

  function buildEmojiMenuMarkup(options = {}) {
    const buttonClass = options?.buttonClass || 'yc-composer-emoji-btn';
    const dataAttribute = options?.dataAttribute || 'data-composer-emoji';
    const ariaLabelPrefix = options?.ariaLabelPrefix || 'Эмодзи';
    return COMPOSER_EMOJI_GROUPS.map((group) => `
      <section class="yc-composer-emoji-section">
        <div class="yc-composer-emoji-title">${escapeHtml(group.title || '')}</div>
        <div class="yc-composer-emoji-grid">
          ${(Array.isArray(group.items) ? group.items : []).map((emoji) => (
            `<button class="${buttonClass}" type="button" ${dataAttribute}="${escapeHtml(emoji)}" aria-label="${escapeHtml(`${ariaLabelPrefix} ${emoji}`)}">${escapeHtml(emoji)}</button>`
          )).join('')}
        </div>
      </section>
    `).join('');
  }

  function buildComposerEmojiMenuMarkup() {
    return buildEmojiMenuMarkup();
  }

  function buildContextReactionPickerMarkup() {
    return buildEmojiMenuMarkup({
      dataAttribute: 'data-context-reaction',
      ariaLabelPrefix: 'Реакция'
    });
  }

  function getComposerSelectionRange() {
    if (!isComposerInputElement(refs.chatComposerInput)) return null;
    const selection = window.getSelection?.();
    if (!selection || !selection.rangeCount) return null;
    const range = selection.getRangeAt(0);
    const root = refs.chatComposerInput;
    if (!(root instanceof HTMLElement)) return null;
    if (!root.contains(range.startContainer) || !root.contains(range.endContainer)) {
      return null;
    }
    return range;
  }

  function getComposerNodeTextLength(node = null) {
    if (!node) return 0;
    if (node.nodeType === Node.TEXT_NODE) {
      return String(node.nodeValue || '').length;
    }
    if (node instanceof HTMLBRElement) {
      return 1;
    }
    return Array.from(node.childNodes || []).reduce((total, child) => (
      total + getComposerNodeTextLength(child)
    ), 0);
  }

  function resolveComposerSelectionBoundary(offset = 0, preferEnd = false) {
    const root = refs.chatComposerInput;
    if (!(root instanceof HTMLElement)) {
      return {
        container: null,
        offset: 0
      };
    }
    const safeOffset = Math.max(0, Math.min(getComposerNodeTextLength(root), Math.round(Number(offset) || 0)));
    if (!root.childNodes.length) {
      return {
        container: root,
        offset: 0
      };
    }

    let traversed = 0;
    let resolved = {
      container: root,
      offset: root.childNodes.length
    };
    const visit = (node) => {
      if (node.nodeType === Node.TEXT_NODE) {
        const length = String(node.nodeValue || '').length;
        if (traversed + length >= safeOffset) {
          resolved = {
            container: node,
            offset: safeOffset - traversed
          };
          return true;
        }
        traversed += length;
        return false;
      }
      if (node instanceof HTMLBRElement) {
        if (traversed + 1 >= safeOffset) {
          const parentNode = node.parentNode instanceof Node ? node.parentNode : root;
          const childIndex = Array.prototype.indexOf.call(parentNode.childNodes, node);
          resolved = {
            container: parentNode,
            offset: (preferEnd || safeOffset > traversed) ? childIndex + 1 : childIndex
          };
          return true;
        }
        traversed += 1;
        return false;
      }
      const children = Array.from(node.childNodes || []);
      for (const child of children) {
        if (visit(child)) {
          return true;
        }
      }
      return false;
    };
    visit(root);
    return resolved;
  }

  function setComposerSelectionOffsets(start = 0, end = start) {
    if (!isComposerInputElement(refs.chatComposerInput)) return false;
    const root = refs.chatComposerInput;
    if (!(root instanceof HTMLElement)) return false;
    const selection = window.getSelection?.();
    if (!selection) return false;
    const startBoundary = resolveComposerSelectionBoundary(start, false);
    const endBoundary = resolveComposerSelectionBoundary(end, true);
    if (!(startBoundary.container instanceof Node) || !(endBoundary.container instanceof Node)) {
      return false;
    }
    try {
      const range = document.createRange();
      range.setStart(startBoundary.container, startBoundary.offset);
      range.setEnd(endBoundary.container, endBoundary.offset);
      selection.removeAllRanges();
      selection.addRange(range);
      runtime.composerSelectionRange = range.cloneRange();
      runtime.composerSelectionStart = Math.max(0, Math.round(Number(start) || 0));
      runtime.composerSelectionEnd = Math.max(runtime.composerSelectionStart, Math.round(Number(end) || 0));
      runtime.composerSelectionValue = getComposerPlainText();
      return true;
    } catch {
      return false;
    }
  }

  function getComposerSelectionOffsets(plainTextOverride = null) {
    if (!isComposerInputElement(refs.chatComposerInput)) {
      return { start: 0, end: 0 };
    }
    const range = getComposerSelectionRange();
    const value = typeof plainTextOverride === 'string'
      ? plainTextOverride
      : getComposerPlainText();
    if (!range) {
      const caret = value.length;
      return {
        start: caret,
        end: caret
      };
    }
    const startProbe = document.createRange();
    startProbe.selectNodeContents(refs.chatComposerInput);
    startProbe.setEnd(range.startContainer, range.startOffset);
    const endProbe = document.createRange();
    endProbe.selectNodeContents(refs.chatComposerInput);
    endProbe.setEnd(range.endContainer, range.endOffset);
    const start = String(startProbe.toString() || '').replace(/\r\n?/g, '\n').length;
    const end = String(endProbe.toString() || '').replace(/\r\n?/g, '\n').length;
    return {
      start,
      end: Math.max(start, end)
    };
  }

  function serializeComposerNodeToMarkdown(node = null) {
    if (!node) return '';
    if (node.nodeType === Node.TEXT_NODE) {
      return String(node.nodeValue || '').replace(/\u00a0/g, ' ');
    }
    if (node instanceof HTMLBRElement) {
      return '\n';
    }
    if (!(node instanceof HTMLElement)) {
      return '';
    }

    const tag = String(node.tagName || '').toLowerCase();
    const style = String(node.getAttribute('style') || '').toLowerCase();
    const children = Array.from(node.childNodes || [])
      .map((child) => serializeComposerNodeToMarkdown(child))
      .join('');

    if (tag === 'strong' || tag === 'b' || /font-weight\s*:\s*(bold|[6-9]00)/i.test(style)) {
      return `**${children}**`;
    }
    if (tag === 'em' || tag === 'i' || /font-style\s*:\s*italic/i.test(style)) {
      return `_${children}_`;
    }
    if (tag === 's' || tag === 'strike' || tag === 'del' || /line-through/i.test(style)) {
      return `~~${children}~~`;
    }
    if (tag === 'code') {
      const codeText = markdownToPlain(children || node.textContent || '', { preserveLineBreaks: true }).replace(/\n+/g, ' ');
      return `\`${codeText}\``;
    }
    if (tag === 'a') {
      const href = cleanText(node.getAttribute('href') || '', 8192);
      if (!href) return children;
      return `[${children || cleanText(node.textContent || href, 240)}](${href})`;
    }
    if (tag === 'div' || tag === 'p') {
      return `${children}${children.endsWith('\n') ? '' : '\n'}`;
    }
    return children;
  }

  function serializeComposerNodeToPlainText(node = null) {
    if (!node) return '';
    if (node.nodeType === Node.TEXT_NODE) {
      return String(node.nodeValue || '').replace(/\u00a0/g, ' ');
    }
    if (node instanceof HTMLBRElement) {
      return '\n';
    }
    if (!(node instanceof HTMLElement)) {
      return '';
    }

    const tag = String(node.tagName || '').toLowerCase();
    const children = Array.from(node.childNodes || [])
      .map((child) => serializeComposerNodeToPlainText(child))
      .join('');
    if (tag === 'div' || tag === 'p' || tag === 'li') {
      return `${children}${children.endsWith('\n') ? '' : '\n'}`;
    }
    return children;
  }

  function getComposerMarkdownValue() {
    if (!isComposerInputElement(refs.chatComposerInput)) return '';
    const root = refs.chatComposerInput;
    const markdown = Array.from(root.childNodes || [])
      .map((child) => serializeComposerNodeToMarkdown(child))
      .join('');
    return String(markdown || '')
      .replace(/\r\n?/g, '\n')
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  function invalidateComposerPlainTextCache() {
    runtime.composerPlainTextCacheHtml = null;
    runtime.composerPlainTextCacheValue = '';
  }

  function updateComposerInputEmptyState(plainTextOverride = null) {
    if (!(refs.chatComposerInput instanceof HTMLElement)) return false;
    const plainText = typeof plainTextOverride === 'string'
      ? plainTextOverride
      : getComposerPlainText();
    const isEmpty = !cleanMultiline(plainText || '', 6000);
    refs.chatComposerInput.classList.toggle('is-empty', isEmpty);
    return isEmpty;
  }

  function getComposerPlainText(forceRefresh = false) {
    if (!isComposerInputElement(refs.chatComposerInput)) return '';
    const currentHtml = String(refs.chatComposerInput.innerHTML || '');
    if (!forceRefresh && runtime.composerPlainTextCacheHtml === currentHtml) {
      return String(runtime.composerPlainTextCacheValue || '');
    }
    const nextValue = Array.from(refs.chatComposerInput.childNodes || [])
      .map((child) => serializeComposerNodeToPlainText(child))
      .join('')
      .replace(/\r\n?/g, '\n')
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .replace(/\n+$/g, '');
    runtime.composerPlainTextCacheHtml = currentHtml;
    runtime.composerPlainTextCacheValue = nextValue;
    return nextValue;
  }

  function setComposerMarkdownValue(nextValue = '') {
    if (!isComposerInputElement(refs.chatComposerInput)) return false;
    refs.chatComposerInput.innerHTML = renderComposerEditableHtml(nextValue || '');
    invalidateComposerPlainTextCache();
    updateComposerInputEmptyState(getComposerPlainText(true));
    autosizeComposerInput();
    cacheComposerSelectionRange();
    return true;
  }

  function cacheComposerSelectionRange(plainTextOverride = null) {
    if (!isComposerInputElement(refs.chatComposerInput)) return false;
    const range = getComposerSelectionRange();
    const value = typeof plainTextOverride === 'string'
      ? plainTextOverride
      : getComposerPlainText();
    if (!range) {
      const caret = value.length;
      runtime.composerSelectionRange = null;
      runtime.composerSelectionStart = caret;
      runtime.composerSelectionEnd = caret;
      runtime.composerSelectionValue = value;
      return false;
    }
    const startProbe = document.createRange();
    startProbe.selectNodeContents(refs.chatComposerInput);
    startProbe.setEnd(range.startContainer, range.startOffset);
    const endProbe = document.createRange();
    endProbe.selectNodeContents(refs.chatComposerInput);
    endProbe.setEnd(range.endContainer, range.endOffset);
    const start = String(startProbe.toString() || '').replace(/\r\n?/g, '\n').length;
    const end = String(endProbe.toString() || '').replace(/\r\n?/g, '\n').length;
    runtime.composerSelectionRange = range.cloneRange();
    runtime.composerSelectionStart = start;
    runtime.composerSelectionEnd = end;
    runtime.composerSelectionValue = value;
    return true;
  }

  function restoreComposerSelectionRange() {
    if (!isComposerInputElement(refs.chatComposerInput)) return false;
    const root = refs.chatComposerInput;
    if (!(root instanceof HTMLElement)) return false;
    const selection = window.getSelection?.();
    if (!selection) return false;
    const cachedRange = runtime.composerSelectionRange;
    if (cachedRange instanceof Range) {
      try {
        if (root.contains(cachedRange.startContainer) && root.contains(cachedRange.endContainer)) {
          selection.removeAllRanges();
          selection.addRange(cachedRange.cloneRange());
          return true;
        }
      } catch {
        // fall through to offset-based restore
      }
    }
    const value = getComposerPlainText();
    let start = Number(runtime.composerSelectionStart);
    let end = Number(runtime.composerSelectionEnd);
    if (!Number.isFinite(start) || !Number.isFinite(end)) {
      return false;
    }
    if (String(runtime.composerSelectionValue || '') !== value) {
      start = value.length;
      end = value.length;
    }
    try {
      return setComposerSelectionOffsets(start, end);
    } catch {
      return false;
    }
  }

  function setComposerSelectionValue(nextValue = '', selectionStart = null, selectionEnd = null) {
    if (!setComposerMarkdownValue(String(nextValue || ''))) return;
    refs.chatComposerInput.focus({ preventScroll: true });
    const plainText = getComposerPlainText();
    if (typeof selectionStart === 'number' && typeof selectionEnd === 'number') {
      setComposerSelectionOffsets(
        Math.max(0, Math.min(plainText.length, Math.round(selectionStart))),
        Math.max(0, Math.min(plainText.length, Math.round(selectionEnd)))
      );
    } else {
      setComposerSelectionOffsets(plainText.length, plainText.length);
    }
    cacheComposerSelectionRange();
    refs.chatComposerInput.dispatchEvent(new Event('input', { bubbles: true }));
  }

  function buildComposerTextFragment(text = '') {
    const fragment = document.createDocumentFragment();
    const lines = String(text || '').replace(/\r\n?/g, '\n').split('\n');
    lines.forEach((line, index) => {
      if (line) {
        fragment.appendChild(document.createTextNode(line));
      }
      if (index < lines.length - 1) {
        fragment.appendChild(document.createElement('br'));
      }
    });
    return fragment;
  }

  function replaceComposerSelectionWithHtml(html = '', options = {}) {
    if (!isComposerInputElement(refs.chatComposerInput)) return false;
    refs.chatComposerInput.focus({ preventScroll: true });
    restoreComposerSelectionRange();
    let range = getComposerSelectionRange();
    if (!range) {
      range = document.createRange();
      range.selectNodeContents(refs.chatComposerInput);
      range.collapse(false);
    }
    range.deleteContents();
    const template = document.createElement('template');
    template.innerHTML = String(html || '');
    const nodes = Array.from(template.content.childNodes || []);
    if (!nodes.length) return false;
    const firstNode = nodes[0];
    const lastNode = nodes[nodes.length - 1];
    range.insertNode(template.content);
    invalidateComposerPlainTextCache();
    const selection = window.getSelection?.();
    if (selection) {
      const nextRange = document.createRange();
      if (options.selectInserted === true && firstNode.parentNode && lastNode.parentNode) {
        nextRange.setStartBefore(firstNode);
        nextRange.setEndAfter(lastNode);
      } else if (lastNode.parentNode) {
        nextRange.setStartAfter(lastNode);
        nextRange.collapse(true);
      } else {
        nextRange.selectNodeContents(refs.chatComposerInput);
        nextRange.collapse(false);
      }
      selection.removeAllRanges();
      selection.addRange(nextRange);
      runtime.composerSelectionRange = nextRange.cloneRange();
      const offsets = getComposerSelectionOffsets();
      runtime.composerSelectionStart = offsets.start;
      runtime.composerSelectionEnd = offsets.end;
      runtime.composerSelectionValue = getComposerPlainText();
    }
    refs.chatComposerInput.dispatchEvent(new Event('input', { bubbles: true }));
    return true;
  }

  function insertComposerText(text = '', options = {}) {
    const fragment = buildComposerTextFragment(text);
    if (!fragment.childNodes.length) return false;
    return replaceComposerSelectionWithHtml(Array.from(fragment.childNodes).map((node) => {
      if (node instanceof HTMLBRElement) return '<br>';
      return escapeHtml(node.textContent || '');
    }).join(''), options);
  }

  function applyComposerInlineFormat(tagName = '', placeholder = 'текст', className = '') {
    if (!isComposerInputElement(refs.chatComposerInput)) return false;
    const tag = String(tagName || '').trim().toLowerCase();
    const normalizedClassName = cleanText(className || '', 80);
    if (!tag) return false;
    refs.chatComposerInput.focus({ preventScroll: true });
    restoreComposerSelectionRange();
    const range = getComposerSelectionRange();
    const hasSelection = Boolean(range && !range.collapsed && String(range.toString() || '').length > 0);

    if (!hasSelection) {
      const classMarkup = normalizedClassName ? ` class="${escapeHtml(normalizedClassName)}"` : '';
      return replaceComposerSelectionWithHtml(
        `<${tag}${classMarkup}>${escapeHtml(placeholder)}</${tag}>`,
        { selectInserted: true }
      );
    }

    try {
      const selectedFragment = range.extractContents();
      const wrapper = document.createElement(tag);
      if (normalizedClassName) {
        wrapper.className = normalizedClassName;
      }
      wrapper.appendChild(selectedFragment);
      range.insertNode(wrapper);
      refs.chatComposerInput.normalize();

      const selection = window.getSelection?.();
      if (selection) {
        const nextRange = document.createRange();
        nextRange.selectNodeContents(wrapper);
        selection.removeAllRanges();
        selection.addRange(nextRange);
        runtime.composerSelectionRange = nextRange.cloneRange();
      }

      cacheComposerSelectionRange();
      refs.chatComposerInput.dispatchEvent(new Event('input', { bubbles: true }));
      return true;
    } catch {
      const selectedText = String(range?.toString() || '') || placeholder;
      const classMarkup = normalizedClassName ? ` class="${escapeHtml(normalizedClassName)}"` : '';
      return replaceComposerSelectionWithHtml(
        `<${tag}${classMarkup}>${escapeHtml(selectedText)}</${tag}>`,
        { selectInserted: false }
      );
    }
  }

  function applyComposerInlineCode(placeholder = 'код') {
    const range = getComposerSelectionRange();
    const selectedText = String(range?.toString() || '');
    const content = selectedText || placeholder;
    return replaceComposerSelectionWithHtml(`<code class="yc-inline-code">${escapeHtml(content)}</code>`, {
      selectInserted: selectedText.length === 0
    });
  }

  function insertComposerEmoji(emoji = '') {
    if (!isComposerInputElement(refs.chatComposerInput)) return false;
    const normalizedEmoji = cleanText(emoji || '', 16);
    if (!normalizedEmoji) return false;
    const value = getComposerPlainText();
    const { start, end } = getComposerSelectionOffsets();
    const before = value.slice(0, start);
    const after = value.slice(end);
    const prefix = before && !/\s$/u.test(before) ? ' ' : '';
    const suffix = after && !/^\s/u.test(after) ? ' ' : '';
    const insertion = `${prefix}${normalizedEmoji}${suffix}`;
    if (!setComposerSelectionOffsets(start, end)) {
      refs.chatComposerInput.focus({ preventScroll: true });
      restoreComposerSelectionRange();
    }
    return insertComposerText(insertion, { selectInserted: false });
  }

  function applyContextMenuReaction(entry = null, emoji = '') {
    const value = cleanText(emoji || '', 16);
    if (!entry || typeof entry !== 'object' || !value) return false;
    const workspaceId = String(entry.workspaceId || '').trim();
    const chatId = normalizeChatId(entry.chatId || '');
    const messageId = String(entry.id || '').trim();
    if (!workspaceId || !chatId || !messageId) return false;
    const hadOwnReaction = hasSelfReactionOnMessage(
      getCachedMessageById(workspaceId, chatId, messageId) || entry,
      value,
      workspaceId
    );
    const shouldAdd = !hadOwnReaction;
    const appliedLocal = applyLocalReactionToggle(workspaceId, chatId, messageId, value);
    if (appliedLocal) {
      const patched = patchTimelineMessageDom(workspaceId, chatId, messageId, {
        includeText: false
      });
      if (!patched || hasVisibleThreadSurface()) {
        scheduleRender(resolveChatMutationRenderScopes({
          includeSidebar: false
        }));
      }
      scheduleRender('sidebar');
    }
    void toggleMessageReaction(workspaceId, chatId, messageId, value, { add: shouldAdd }).then((ok) => {
      if (ok) return;
      if (appliedLocal) {
        reconcileFailedOptimisticReactionToggle(
          workspaceId,
          chatId,
          messageId,
          value,
          'reaction_toggle_failed_context'
        );
        return;
      }
      showTemporaryStatus('Не удалось поставить реакцию');
    });
    return true;
  }

  function setComposerAttachmentMode(active = false) {
    const nextActive = Boolean(active);
    refs.chatComposer?.classList?.toggle('is-attachment-mode', nextActive);
    refs.root?.classList?.toggle('yc-attachment-composer-active', nextActive);
  }

  function syncComposerActionButtons(workspaceId = '', chatId = '', draftTextOverride = null) {
    if (!(refs.chatComposer instanceof HTMLElement)) return;

    const ws = String(workspaceId || state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
    const chat = normalizeChatId(chatId || state.activeChatId || '');
    const hasActiveChat = Boolean(ws && chat);
    const composerBusy = state.sendingMessage || state.sendingAttachments || state.videoNoteUploading;
    const pinnedMessagesViewOpen = Boolean(state.pinnedMessagesViewOpen);
    const scheduledMessagesViewOpen = Boolean(state.scheduledMessagesViewOpen);
    const pendingFiles = hasActiveChat ? getComposerPendingFiles(ws, chat) : [];
    const scheduledMessages = hasActiveChat ? getScheduledMessagesForChat(ws, chat) : [];
    const scheduledCount = scheduledMessages.length;
    const draftText = cleanMultiline(
      typeof draftTextOverride === 'string' ? draftTextOverride : getComposerPlainText(),
      6000
    );
    const hasDraft = Boolean(draftText || pendingFiles.length);
    const actionSignature = [
      hasActiveChat ? '1' : '0',
      composerBusy ? '1' : '0',
      hasDraft ? '1' : '0',
      String(pendingFiles.length),
      String(scheduledCount),
      pinnedMessagesViewOpen ? '1' : '0',
      scheduledMessagesViewOpen ? '1' : '0',
      state.sendingMessage ? '1' : '0',
      state.sendingAttachments ? '1' : '0',
      state.videoNoteRecordingActive ? '1' : '0',
      state.videoNoteUploading ? '1' : '0',
      state.voiceRecordingActive ? '1' : '0',
      state.voiceRecordingSupported ? '1' : '0',
      state.voiceDictationActive ? '1' : '0',
      state.voiceDictationProcessing ? '1' : '0',
      state.voiceDictationSupported ? '1' : '0',
      state.voiceCommandActive ? '1' : '0',
      state.voiceCommandProcessing ? '1' : '0',
      state.voiceCommandSupported ? '1' : '0',
      state.composerEmojiMenuOpen ? '1' : '0'
    ].join('\u001f');
    if (refs.chatComposer.dataset.actionSignature === actionSignature) {
      return;
    }
    refs.chatComposer.dataset.actionSignature = actionSignature;

    refs.chatComposer.classList.toggle('has-draft', hasDraft);
    setComposerAttachmentMode(pendingFiles.length > 0);

    if (refs.chatComposerButton instanceof HTMLButtonElement) {
      refs.chatComposerButton.disabled = !hasActiveChat
        || composerBusy
        || !hasDraft
        || state.videoNoteRecordingActive
        || state.voiceDictationActive
        || state.voiceDictationProcessing
        || state.voiceCommandActive
        || state.voiceCommandProcessing;
      refs.chatComposerButton.classList.toggle('is-hidden', !hasDraft);
    }

    if (refs.chatComposerScheduledButton instanceof HTMLButtonElement) {
      const showScheduledButton = hasActiveChat && (scheduledCount > 0 || scheduledMessagesViewOpen);
      refs.chatComposerScheduledButton.classList.toggle('is-hidden', !showScheduledButton);
      refs.chatComposerScheduledButton.disabled = !showScheduledButton || composerBusy;
      refs.chatComposerScheduledButton.classList.toggle('is-active', showScheduledButton && scheduledMessagesViewOpen);
      refs.chatComposerScheduledButton.dataset.count = showScheduledButton && scheduledCount > 0
        ? String(Math.min(99, scheduledCount))
        : '';
      const scheduledTitle = scheduledCount > 0
        ? `Отложенные сообщения: ${scheduledCount}`
        : 'Отложенные сообщения';
      refs.chatComposerScheduledButton.title = scheduledTitle;
      refs.chatComposerScheduledButton.setAttribute('aria-label', scheduledTitle);
      refs.chatComposerScheduledButton.setAttribute('aria-pressed', scheduledMessagesViewOpen ? 'true' : 'false');
    }

    if (refs.chatComposerTextMicButton instanceof HTMLButtonElement) {
      refs.chatComposerTextMicButton.classList.toggle('is-hidden', pendingFiles.length > 0);
      refs.chatComposerTextMicButton.disabled = state.voiceDictationProcessing || state.voiceCommandProcessing || (
        !state.voiceDictationActive && (
          !hasActiveChat
          || composerBusy
          || pinnedMessagesViewOpen
          || !state.voiceDictationSupported
          || state.videoNoteRecordingActive
          || state.voiceRecordingActive
          || state.voiceCommandActive
        )
      );
    }

    if (refs.chatComposerCommandMicButton instanceof HTMLButtonElement) {
      refs.chatComposerCommandMicButton.classList.toggle('is-hidden', pendingFiles.length > 0);
      refs.chatComposerCommandMicButton.disabled = state.voiceCommandProcessing || state.voiceDictationProcessing || (
        !state.voiceCommandActive && (
          !hasActiveChat
          || composerBusy
          || pinnedMessagesViewOpen
          || !state.voiceCommandSupported
          || state.videoNoteRecordingActive
          || state.voiceRecordingActive
          || state.voiceDictationActive
        )
      );
    }

    if (refs.chatComposerMicButton instanceof HTMLButtonElement) {
      refs.chatComposerMicButton.classList.toggle('is-hidden', pendingFiles.length > 0);
      refs.chatComposerMicButton.disabled = !state.voiceRecordingActive && (
        !hasActiveChat
        || composerBusy
        || pinnedMessagesViewOpen
        || !state.voiceRecordingSupported
        || state.videoNoteRecordingActive
        || state.voiceDictationActive
        || state.voiceDictationProcessing
        || state.voiceCommandActive
        || state.voiceCommandProcessing
      );
    }

    if (refs.chatComposerEmojiButton instanceof HTMLButtonElement) {
      refs.chatComposerEmojiButton.disabled = !hasActiveChat || composerBusy;
      const emojiShell = refs.chatComposerEmojiButton.closest('.yc-composer-emoji-shell');
      if (emojiShell instanceof HTMLElement) {
        emojiShell.classList.toggle('is-disabled', refs.chatComposerEmojiButton.disabled);
        emojiShell.classList.toggle('is-open', state.composerEmojiMenuOpen && !refs.chatComposerEmojiButton.disabled);
      }
      refs.chatComposerEmojiButton.setAttribute('aria-expanded', state.composerEmojiMenuOpen && !refs.chatComposerEmojiButton.disabled ? 'true' : 'false');
      if (refs.chatComposerEmojiButton.disabled) {
        setComposerEmojiMenuOpen(false);
      }
    }
  }

  function wrapComposerSelection(prefix = '', suffix = '', placeholder = 'текст') {
    if (prefix === '**' && suffix === '**') {
      applyComposerInlineFormat('strong', placeholder);
      return;
    }
    if ((prefix === '_' && suffix === '_') || (prefix === '*' && suffix === '*')) {
      applyComposerInlineFormat('em', placeholder);
      return;
    }
    if (prefix === '~~' && suffix === '~~') {
      applyComposerInlineFormat('s', placeholder);
      return;
    }
    if (prefix === '`' && suffix === '`') {
      applyComposerInlineCode(placeholder);
      return;
    }
    insertComposerText(`${prefix}${placeholder}${suffix}`, { selectInserted: true });
  }

  function prefixComposerSelection(prefix = '', placeholder = 'текст', numbered = false) {
    if (!isComposerInputElement(refs.chatComposerInput)) return;
    const range = getComposerSelectionRange();
    const selected = String(range?.toString() || '');
    const base = selected || placeholder;
    const lines = String(base || '').split(/\r?\n/).filter((line, index, array) => line || array.length === 1);
    const insertion = lines.map((line, index) => (
      numbered ? `${index + 1}. ${line || placeholder}` : `${prefix}${line || placeholder}`
    )).join('\n');
    insertComposerText(insertion, { selectInserted: !selected });
  }

  async function insertComposerLink() {
    if (!isComposerInputElement(refs.chatComposerInput)) return false;
    refs.chatComposerInput.focus({ preventScroll: true });
    restoreComposerSelectionRange();
    const range = getComposerSelectionRange();
    const selected = String(range?.toString() || '');
    const label = selected || 'текст';
    const rawUrl = await requestTextInputModal({
      title: 'Вставить ссылку',
      description: 'Укажите адрес ссылки для выбранного текста.',
      inputPlaceholder: 'https://example.com',
      confirmLabel: 'Вставить',
      maxLength: 2048
    });
    if (rawUrl === null) return false;
    const href = normalizeAssetUrl(rawUrl || '', 8192) || cleanText(rawUrl || '', 2048);
    if (!href) {
      showTemporaryStatus('Введите корректную ссылку');
      return false;
    }
    if (!selected) {
      if (!insertComposerText(label, { selectInserted: true })) {
        return false;
      }
    } else {
      restoreComposerSelectionRange();
    }
    return replaceComposerSelectionWithHtml(
      `<a class="yc-message-inline-link" href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer">${escapeHtml(label)}</a>`,
      { selectInserted: false }
    );
  }

  function hideComposerToolsMenu() {
    clearComposerSendMenuTimer();
    if (!state.composerToolsMenuVisible) return;
    state.composerToolsMenuVisible = false;
    state.composerToolsMenuMode = 'default';
    scheduleRender(['chat', 'overlays']);
  }

  function setComposerEmojiMenuOpen(open = false) {
    state.composerEmojiMenuOpen = open === true;
    const shell = refs.chatComposerEmojiButton?.closest('.yc-composer-emoji-shell');
    if (shell instanceof HTMLElement) {
      shell.classList.toggle('is-open', state.composerEmojiMenuOpen);
    }
    if (refs.chatComposerEmojiButton instanceof HTMLButtonElement) {
      refs.chatComposerEmojiButton.setAttribute('aria-expanded', state.composerEmojiMenuOpen ? 'true' : 'false');
    }
  }

  function hideComposerEmojiMenu() {
    if (!state.composerEmojiMenuOpen) return;
    setComposerEmojiMenuOpen(false);
  }

  function toggleComposerEmojiMenu() {
    setComposerEmojiMenuOpen(!state.composerEmojiMenuOpen);
  }

  function showComposerToolsMenu(anchorNode = null, options = {}) {
    if (!(anchorNode instanceof HTMLElement)) return;
    cacheComposerSelectionRange();
    hideComposerEmojiMenu();
    hideComposerMentionMenu(true);
    state.dialogContextMenuVisible = false;
    state.dialogContextMenuEntry = null;
    const requestedMode = String(options?.mode || '').trim().toLowerCase();
    const mode = requestedMode === 'send' || requestedMode === 'voice' || requestedMode === 'voice-command'
      ? requestedMode
      : 'default';
    const rect = anchorNode.getBoundingClientRect();
    state.composerToolsMenuVisible = true;
    state.composerToolsMenuMode = mode;
    state.composerToolsMenuX = mode === 'send'
      ? Math.round(rect.right - 280)
      : Math.round(rect.left + (rect.width / 2) - 140);
    state.composerToolsMenuY = Math.round(rect.top - 12);
    scheduleRender(['chat', 'overlays']);
  }

  function buildPollComposerOptionDraft(option = null, index = 0) {
    const safeIndex = Math.max(0, Math.round(Number(index || 0)));
    return {
      id: cleanText(option?.id || `opt-${safeIndex + 1}-${Math.random().toString(16).slice(2, 8)}`, 120) || `opt-${safeIndex + 1}`,
      text: cleanMultiline(option?.text || '', 220).replace(/\s+/g, ' ').trim()
    };
  }

  function normalizePollComposerModalMeta(meta = null) {
    const source = meta && typeof meta === 'object' ? meta : {};
    const maxMode = source.maxMode === true || String(source.mode || '').trim().toLowerCase() === 'max';
    const rawOptions = Array.isArray(source.options) ? source.options.slice(0, POLL_MAX_OPTIONS) : [];
    const options = rawOptions.map((option, index) => buildPollComposerOptionDraft(option, index));
    while (options.length < POLL_MIN_OPTIONS) {
      options.push(buildPollComposerOptionDraft(null, options.length));
    }
    const correctOptionIds = normalizePollOptionIdList(source.correctOptionIds || [])
      .filter((optionId) => options.some((option) => option.id === optionId));
    const normalized = {
      question: cleanMultiline(source.question || '', 600),
      description: cleanMultiline(source.description || '', 1200),
      options,
      showVoters: source.showVoters === true,
      multiple: source.multiple === true,
      allowRevote: source.allowRevote !== false,
      shuffleOptions: source.shuffleOptions === true,
      quizMode: source.quizMode === true || correctOptionIds.length > 0,
      correctOptionIds,
      closeEnabled: source.closeEnabled === true,
      closeHours: Math.max(1, Math.min(168, Math.round(Number(source.closeHours || 24) || 24))),
      resultsVisibility: normalizePollResultsVisibilityChoice(source.resultsVisibility || '')
    };
    if (!maxMode) {
      return normalized;
    }
    return {
      ...normalized,
      maxMode: true,
      description: '',
      showVoters: false,
      multiple: false,
      allowRevote: source.allowRevote !== false,
      shuffleOptions: false,
      quizMode: false,
      correctOptionIds: [],
      closeEnabled: false,
      resultsVisibility: POLL_RESULTS_VISIBILITY.ALWAYS
    };
  }

  function buildPollPayloadFromComposerMeta(meta = null) {
    const normalized = normalizePollComposerModalMeta(meta);
    const question = cleanMultiline(normalized.question || '', 600);
    const options = normalized.options
      .map((option, index) => ({
        id: cleanText(option?.id || `opt-${index + 1}`, 120) || `opt-${index + 1}`,
        text: cleanMultiline(option?.text || '', 220).replace(/\s+/g, ' ').trim()
      }))
      .filter((option) => option.text);
    if (!question || options.length < POLL_MIN_OPTIONS) return null;
    let correctOptionIds = normalized.quizMode
      ? normalizePollOptionIdList(normalized.correctOptionIds || [])
        .filter((optionId) => options.some((option) => option.id === optionId))
      : [];
    if (!normalized.multiple && correctOptionIds.length > 1) {
      correctOptionIds = correctOptionIds.slice(0, 1);
    }
    const closeAt = normalized.closeEnabled
      ? now() + (Math.max(1, Math.min(168, normalized.closeHours)) * 60 * 60 * 1000)
      : 0;
    return normalizePollCreatePayload({
      pollId: `poll-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`,
      question,
      description: normalized.description,
      options,
      multiple: normalized.multiple,
      allowRevote: normalized.allowRevote,
      showVoters: normalized.showVoters,
      shuffleOptions: normalized.shuffleOptions,
      correctOptionIds,
      resultsVisibility: closeAt > 0
        ? POLL_RESULTS_VISIBILITY.AFTER_CLOSE
        : (normalized.resultsVisibility || POLL_RESULTS_VISIBILITY.ALWAYS),
      closeAt,
      createdAt: now()
    });
  }

  async function openPollComposerModal(options = {}) {
    const maxMode = options?.maxMode === true;
    const result = await openModal({
      mode: 'poll-create',
      title: 'Новый опрос',
      confirmLabel: maxMode ? 'Создать' : 'Отправить',
      cancelLabel: 'Отмена',
      meta: normalizePollComposerModalMeta({
        maxMode,
        allowRevote: true,
        closeHours: 24,
        resultsVisibility: POLL_RESULTS_VISIBILITY.ALWAYS
      })
    });
    return result && typeof result === 'object'
      ? normalizePollCreatePayload(result)
      : null;
  }

  async function createPollFromComposerTool() {
    if (!isPollsFeatureEnabled()) {
      showTemporaryStatus('Опросы отключены в настройках');
      return false;
    }
    const active = getCurrentChatState();
    const workspaceId = String(active?.workspaceId || state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
    const chatId = normalizeChatId(active?.chatId || state.activeChatId || '');
    const activeEntry = workspaceId && chatId ? findRecentByChatId(workspaceId, chatId) : null;
    const activeChatTitle = cleanText(
      getRenderableEntryTitle(activeEntry)
      || activeEntry?.title
      || state.activeChatTitle
      || '',
      180
    );
    if (!workspaceId || !chatId || /^t:/i.test(chatId)) {
      showTemporaryStatus('Опрос можно создать только в основном чате');
      return false;
    }

    const pollPayload = await openPollComposerModal();
    if (!pollPayload) {
      return false;
    }

    if (isTelegramConversationChat(workspaceId, chatId)) {
      try {
        const response = await ipcRenderer.invoke('yuchat-telegram-send-poll', {
          ...getTelegramIpcPayload(),
          chatId,
          poll: pollPayload
        });
        if (!response || typeof response !== 'object' || response.ok === false) {
          throw new Error(cleanText(response?.error || 'Не удалось отправить опрос Telegram', 220));
        }
        await refreshConversationMessages(workspaceId, chatId, {
          count: MESSAGE_PAGE_MAX,
          force: true
        }).catch(() => null);
        void refreshTelegramDialogs({ silent: true }).catch(() => {});
        schedulePostMutationSync(workspaceId, chatId, 'message_send');
        scheduleRender(resolveChatMutationRenderScopes({
          includeSidebar: false
        }));
        showTemporaryStatus('Опрос отправлен');
        return true;
      } catch (error) {
        setError(`Не удалось создать опрос (${cleanText(error?.message || '', 160)})`);
        scheduleRender('chat');
        return false;
      }
    }

    const fallbackText = buildPollCreateFallbackText(pollPayload);
    if (!fallbackText) {
      showTemporaryStatus('Не удалось подготовить опрос');
      return false;
    }

    try {
      await sendChatMessage(workspaceId, chatId, fallbackText);
      await refreshConversationMessages(workspaceId, chatId, {
        count: MESSAGE_PAGE_MAX,
        force: true
      });
      schedulePostMutationSync(workspaceId, chatId, 'message_send');
      scheduleRender(resolveChatMutationRenderScopes({
        includeSidebar: false
      }));
      showTemporaryStatus('Опрос отправлен');
      return true;
    } catch (error) {
      setError(`Не удалось создать опрос (${cleanText(error?.message || '', 160)})`);
      scheduleRender('chat');
      return false;
    }
  }

  function convertComposerDraftToLiveChecklist(options = {}) {
    if (!isComposerInputElement(refs.chatComposerInput)) return false;
    const currentValue = cleanMultiline(getComposerMarkdownValue(), 6000);
    const nextValue = buildLiveChecklistMessageText(currentValue);
    if (!nextValue) {
      if (options.silent !== true) {
        showTemporaryStatus('Для живого чеклиста нужны хотя бы два пункта');
      }
      refs.chatComposerInput.focus({ preventScroll: true });
      return false;
    }
    setComposerSelectionValue(nextValue, nextValue.length, nextValue.length);
    state.sendAssistApprovedSignature = '';
    clearSendAssist();
    scheduleRender('chat');
    if (options.showStatus !== false) {
      showTemporaryStatus('Черновик превращён в живой чеклист');
    }
    refs.chatComposerInput.focus({ preventScroll: true });
    return true;
  }

  function applyComposerToolAction(actionId = '') {
    const action = String(actionId || '').trim();
    if (!action) return;

    if (action === 'voice-note') {
      toggleVoiceRecording();
      return;
    }

    if (action === 'voice-command-list') {
      void openVoiceCommandListModal();
      return;
    }

    if (action === 'upload') {
      if (refs.chatComposerFileInput instanceof HTMLInputElement) {
        refs.chatComposerFileInput.click();
      }
      return;
    }

    if (action === 'drawing') {
      void openChatDrawingComposerTool();
      return;
    }

    if (action === 'calendar-compose') {
      void createCalendarMeetingFromChat().catch((error) => {
        showTemporaryStatus(cleanText(error?.message || 'Не удалось открыть черновик встречи', 180));
      });
      return;
    }

    if (action === 'calendar-slot') {
      void findCalendarSlots({
        prompt: true,
        insertIntoComposer: true
      }).catch((error) => {
        showTemporaryStatus(cleanText(error?.message || 'Не удалось подобрать слот', 180));
      });
      return;
    }

    if (action === 'poll-create') {
      void createPollFromComposerTool();
      return;
    }

    if (action === 'live-checklist') {
      convertComposerDraftToLiveChecklist();
      return;
    }

    if (action === 'send-later') {
      void openComposerScheduleModal().then((result) => {
        if (result?.scheduledAt) {
          void submitComposerMessage({
            scheduledAt: result.scheduledAt
          });
          return;
        }
        refs.chatComposerInput?.focus({ preventScroll: true });
      });
      return;
    }

    if (!isComposerInputElement(refs.chatComposerInput)) return;
    refs.chatComposerInput.focus({ preventScroll: true });
    restoreComposerSelectionRange();

    if (action === 'bold') {
      wrapComposerSelection('**', '**', 'жирный текст');
      return;
    }
    if (action === 'italic') {
      wrapComposerSelection('_', '_', 'курсив');
      return;
    }
    if (action === 'strike') {
      wrapComposerSelection('~~', '~~', 'зачеркнутый текст');
      return;
    }
    if (action === 'quote') {
      prefixComposerSelection('> ', 'цитата');
      return;
    }
    if (action === 'link') {
      void insertComposerLink();
      return;
    }
    if (action === 'list') {
      prefixComposerSelection('- ', 'пункт списка');
      return;
    }
    if (action === 'ordered-list') {
      prefixComposerSelection('', 'пункт списка', true);
      return;
    }
    if (action === 'code') {
      wrapComposerSelection('`', '`', 'код');
    }
  }

  function getMentionCandidateLabelFromProfile(profile = null) {
    const label = cleanText(
      getProfileDisplayName(profile)
      || profile?.fullName
      || profile?.displayName
      || profile?.profile?.fullName
      || profile?.profile?.displayName
      || '',
      120
    );
    return label;
  }

  function getMentionCandidateFallbackLabel(memberId = '') {
    const rawMemberId = String(memberId || '').trim();
    if (!rawMemberId) return '';
    const email = normalizeEmailIdentity(rawMemberId);
    if (email) {
      const localPart = cleanText(String(email.split('@')[0] || ''), 120);
      if (localPart) return localPart;
    }
    const alias = normalizeMentionAliasValue(rawMemberId);
    if (alias && !/^\d+$/u.test(alias)) {
      return cleanText(alias, 120);
    }
    return cleanText(`Участник ${rawMemberId.slice(0, 8)}`, 120);
  }

  function collectMentionCandidateRawMemberRecords(entry = null) {
    if (!entry || typeof entry !== 'object') return [];
    const rawChat = entry?.rawChat && typeof entry.rawChat === 'object' ? entry.rawChat : null;
    if (!rawChat) return [];
    const collections = [
      Array.isArray(rawChat?.members) ? rawChat.members : [],
      Array.isArray(rawChat?.participants) ? rawChat.participants : [],
      Array.isArray(rawChat?.memberRecords) ? rawChat.memberRecords : [],
      Array.isArray(rawChat?.memberProfiles) ? rawChat.memberProfiles : [],
      Array.isArray(rawChat?.metadata?.members) ? rawChat.metadata.members : [],
      Array.isArray(rawChat?.metadata?.workspace?.members) ? rawChat.metadata.workspace.members : [],
      Array.isArray(rawChat?.metadata?.channel?.members) ? rawChat.metadata.channel.members : [],
      Array.isArray(rawChat?.metadata?.group?.members) ? rawChat.metadata.group.members : []
    ];
    return collections.flat().filter((item) => item && typeof item === 'object');
  }

  function countMentionCandidateRawMemberRecords(entry = null) {
    if (!entry || typeof entry !== 'object') return 0;
    const rawChat = entry?.rawChat && typeof entry.rawChat === 'object' ? entry.rawChat : null;
    if (!rawChat) return 0;
    return [
      Array.isArray(rawChat?.members) ? rawChat.members.length : 0,
      Array.isArray(rawChat?.participants) ? rawChat.participants.length : 0,
      Array.isArray(rawChat?.memberRecords) ? rawChat.memberRecords.length : 0,
      Array.isArray(rawChat?.memberProfiles) ? rawChat.memberProfiles.length : 0,
      Array.isArray(rawChat?.metadata?.members) ? rawChat.metadata.members.length : 0,
      Array.isArray(rawChat?.metadata?.workspace?.members) ? rawChat.metadata.workspace.members.length : 0,
      Array.isArray(rawChat?.metadata?.channel?.members) ? rawChat.metadata.channel.members.length : 0,
      Array.isArray(rawChat?.metadata?.group?.members) ? rawChat.metadata.group.members.length : 0
    ].reduce((total, value) => total + Math.max(0, Number(value) || 0), 0);
  }

  function getComposerMentionCandidatesFingerprint(workspaceId = '', chatId = '', selfMemberId = '', activeEntry = null, messageState = null) {
    const ws = String(workspaceId || '').trim();
    const chat = normalizeChatId(chatId || '');
    const entryMemberIds = Array.isArray(activeEntry?.memberIds) ? activeEntry.memberIds : [];
    const rawMemberIds = Array.isArray(activeEntry?.rawChat?.memberIds) ? activeEntry.rawChat.memberIds : [];
    const items = Array.isArray(messageState?.items) ? messageState.items : [];
    const firstMessage = items[0] || null;
    const lastMessage = items.length ? items[items.length - 1] : null;
    return [
      ws,
      chat,
      String(selfMemberId || '').trim(),
      Number(runtime.knownProfileVersion || 0),
      Number(activeEntry?.updatedAt || 0),
      entryMemberIds.length,
      String(entryMemberIds[0] || ''),
      String(entryMemberIds[entryMemberIds.length - 1] || ''),
      rawMemberIds.length,
      String(rawMemberIds[0] || ''),
      String(rawMemberIds[rawMemberIds.length - 1] || ''),
      countMentionCandidateRawMemberRecords(activeEntry),
      Number(messageState?.updatedAt || 0),
      items.length,
      String(firstMessage?.id || ''),
      String(lastMessage?.id || ''),
      String(lastMessage?.authorMemberId || ''),
      String(activeEntry?.previewAuthorMemberId || '')
    ].join('\u001f');
  }

  function normalizeTelegramParticipantForUi(participant = null) {
    if (!participant || typeof participant !== 'object') return null;
    const memberId = cleanText(participant.memberId || participant.id || '', 180);
    if (!memberId) return null;
    const label = cleanText(
      participant.label
      || participant.title
      || participant.fullName
      || participant.displayName
      || participant.name
      || participant.username
      || memberId,
      140
	    ) || memberId;
	    const username = cleanText(participant.username || participant.userName || '', 120);
	    const phone = cleanText(participant.phone || participant.phoneNumber || participant.profile?.phone || '', 120);
	    const about = cleanText(
	      participant.about
	      || participant.bio
	      || participant.details?.about
	      || participant.details?.bio
	      || participant.profile?.about
	      || participant.profile?.bio
	      || participant.profile?.details?.about
	      || participant.profile?.details?.bio
	      || '',
	      2400
	    );
	    const birthday = cleanText(
	      participant.birthday
	      || participant.birthDate
	      || participant.birthDay
	      || participant.details?.birthday
	      || participant.details?.birthDate
	      || participant.profile?.birthday
	      || participant.profile?.birthDate
	      || participant.profile?.details?.birthday
	      || participant.profile?.details?.birthDate
	      || '',
	      120
	    );
	    const avatarUrl = normalizeAssetUrl(participant.avatarUrl || participant.avatarResourceUrl || participant.photoUrl || '', 2097152);
	    const details = {
	      ...(participant.details && typeof participant.details === 'object' ? participant.details : {}),
	      username,
	      phone,
	      about,
	      bio: about,
	      birthday
	    };
	    return {
	      ...participant,
	      id: memberId,
      memberId,
      fullName: label,
      displayName: label,
      name: label,
	      label,
	      title: label,
	      username,
	      phone,
	      about,
	      bio: about,
	      birthday,
	      details,
	      avatarUrl,
	      photoUrl: avatarUrl,
	      profile: {
	        ...(participant.profile && typeof participant.profile === 'object' ? participant.profile : {}),
	        memberId,
        fullName: label,
	        displayName: label,
	        username,
	        phone,
	        about,
	        bio: about,
	        birthday,
	        avatarUrl,
	        photoUrl: avatarUrl,
	        details: {
	          ...(participant.profile?.details && typeof participant.profile.details === 'object' ? participant.profile.details : {}),
	          ...details
	        }
	      }
	    };
	  }

  function applyTelegramParticipantsToDialogEntry(workspaceId = '', chatId = '', participants = []) {
    const ws = String(workspaceId || '').trim() || 'telegram';
    const chat = normalizeChatId(chatId || '');
    const normalizedParticipants = (Array.isArray(participants) ? participants : [])
      .map((participant) => normalizeTelegramParticipantForUi(participant))
      .filter(Boolean);
    if (!ws || !chat || !normalizedParticipants.length) return [];
    normalizedParticipants.forEach((participant) => cacheKnownProfile(participant));
    const memberIds = Array.from(new Set(
      normalizedParticipants
        .map((participant) => String(participant.memberId || '').trim())
        .filter(Boolean)
    ));
    const participantsSearchText = normalizedParticipants.map((participant) => cleanText([
      participant.label,
      participant.username ? `@${participant.username}` : '',
      participant.phone,
      participant.memberId
    ].filter(Boolean).join(' '), 220)).join(' ');
    const applyToEntry = (entry = null) => {
      if (!entry || typeof entry !== 'object') return;
      const existingRaw = entry.rawChat && typeof entry.rawChat === 'object' ? entry.rawChat : {};
      entry.rawChat = {
        ...existingRaw,
        participants: normalizedParticipants,
        memberIds: Array.from(new Set([
          ...(Array.isArray(existingRaw.memberIds) ? existingRaw.memberIds : []),
          ...(Array.isArray(entry.memberIds) ? entry.memberIds : []),
          ...memberIds
        ].map((value) => String(value || '').trim()).filter(Boolean)))
      };
      entry.memberIds = entry.rawChat.memberIds;
      entry.searchText = cleanText([
        entry.searchText || '',
        participantsSearchText
      ].filter(Boolean).join(' '), 720);
    };
    let updatedActive = false;
    mutateRecentEntry(ws, chat, (entry) => {
      applyToEntry(entry);
      updatedActive = true;
    });
    if (!updatedActive && Array.isArray(state.archivedRecentsByWorkspace?.[ws])) {
      const archived = state.archivedRecentsByWorkspace[ws].slice();
      const index = archived.findIndex((entry) => chatIdsAreEquivalent(entry?.chatId || '', chat));
      if (index >= 0) {
        const nextEntry = { ...archived[index] };
        applyToEntry(nextEntry);
        archived[index] = sanitizeRecentEntry(nextEntry);
        state.archivedRecentsByWorkspace = {
          ...state.archivedRecentsByWorkspace,
          [ws]: sanitizeRecentCollection(archived.map((entry) => ({ ...entry, isArchived: true })))
        };
        runtime.recentsStateVersion += 1;
        invalidateRecentsDerivedCache();
      }
    }
    runtime.composerMentionCacheByChatKey.delete(getChatStateKey(ws, chat));
    return normalizedParticipants;
  }

  async function loadTelegramParticipantsForMentions(workspaceId = '', chatId = '', options = {}) {
    const ws = String(workspaceId || '').trim() || 'telegram';
    const chat = normalizeChatId(chatId || '');
    const key = getChatStateKey(ws, chat);
    if (!key || !isTelegramConversationChat(ws, chat)) return [];
    const entry = findRecentByChatId(ws, chat);
    if (entry && isDirectChatEntry(entry)) return [];
    const rawParticipants = Array.isArray(entry?.rawChat?.participants) ? entry.rawChat.participants : [];
    if (options.force !== true && rawParticipants.length >= 8) {
      return rawParticipants.map((participant) => normalizeTelegramParticipantForUi(participant)).filter(Boolean);
    }
    const existingRequest = runtime.composerMentionHydrationByChatKey.get(key);
    if (existingRequest && options.force !== true) {
      return existingRequest;
    }
    const request = (async () => {
      try {
        const response = await ipcRenderer.invoke('yuchat-telegram-list-participants', {
          ...getTelegramIpcPayload(),
          chatId: chat,
          peerId: String(chat).replace(/^tg:/i, ''),
          limit: Math.max(40, Math.min(300, Number(options.limit) || 180))
        });
        const participants = Array.isArray(response?.participants) ? response.participants : [];
        return applyTelegramParticipantsToDialogEntry(ws, chat, participants);
      } catch {
        return [];
      } finally {
        if (runtime.composerMentionHydrationByChatKey.get(key) === request) {
          runtime.composerMentionHydrationByChatKey.delete(key);
        }
      }
    })();
    runtime.composerMentionHydrationByChatKey.set(key, request);
    return request;
  }

  function scheduleComposerMentionMembersHydration(workspaceId = '', chatId = '', memberIds = []) {
    const ws = String(workspaceId || '').trim();
    const chat = normalizeChatId(chatId || '');
    const key = getChatStateKey(ws, chat);
    if (!ws || !chat || !key) return;
    if (isMaxConversationChat(ws, chat)) return;
    const uniqueMissing = Array.from(new Set(
      (Array.isArray(memberIds) ? memberIds : [])
        .map((memberId) => String(memberId || '').trim())
        .filter(Boolean)
    )).slice(0, 220);
    if (!uniqueMissing.length) return;
    if (runtime.composerMentionHydrationByChatKey.has(key)) return;

    const request = (async () => {
      try {
        const accountId = await resolveAccountId();
        if (accountId) {
          await ensureWorkspaceMembers(ws, uniqueMissing, accountId, {
            requireAvatar: true
          });
        }
        await ensureProfiles(uniqueMissing);
        runtime.composerMentionCacheByChatKey.delete(key);
        if (!isComposerInputElement(refs.chatComposerInput)) return;
        const activeWorkspaceId = String(state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
        const activeChatId = normalizeChatId(state.activeChatId || '');
        if (activeWorkspaceId === ws && chatIdsAreEquivalent(activeChatId, chat)) {
          updateComposerMentionMenuFromInput();
        }
      } catch {
        // mention hydration is best-effort
      } finally {
        if (runtime.composerMentionHydrationByChatKey.get(key) === request) {
          runtime.composerMentionHydrationByChatKey.delete(key);
        }
      }
    })();

    runtime.composerMentionHydrationByChatKey.set(key, request);
  }

  function maybeWarmComposerMentionCandidates(workspaceId = '', chatId = '', options = {}) {
    const ws = String(workspaceId || '').trim();
    const chat = normalizeChatId(chatId || '');
    const key = getChatStateKey(ws, chat);
    if (!ws || !chat || !key) return;

    const cooldownMs = Math.max(1200, Number(options?.cooldownMs || 5000));
    const currentTs = now();
    const lastWarmAt = Number(runtime.composerMentionWarmAtByChatKey.get(key) || 0);
    if (options?.force !== true && lastWarmAt > 0 && (currentTs - lastWarmAt) < cooldownMs) {
      return;
    }
    runtime.composerMentionWarmAtByChatKey.set(key, currentTs);

    const activeEntry = findRecentByChatId(ws, chat);
    const messageItems = Array.isArray(state.messagesByChatKey?.[key]?.items)
      ? state.messagesByChatKey[key].items
      : [];
    if (isMaxConversationChat(ws, chat)) {
      const warmNow = () => {
        try {
          buildComposerMentionCandidates(ws, chat);
        } catch {
          // ignore mention prewarm failures
        }
      };
      if (typeof window.requestIdleCallback === 'function') {
        window.requestIdleCallback(() => warmNow(), { timeout: 240 });
      } else {
        window.requestAnimationFrame(() => warmNow());
      }
      return;
    }
    if (isTelegramConversationChat(ws, chat)) {
      void loadTelegramParticipantsForMentions(ws, chat, {
        force: options?.force === true,
        limit: 220
      }).then((participants) => {
        if (!Array.isArray(participants) || !participants.length) return;
        runtime.composerMentionCacheByChatKey.delete(key);
        const activeWorkspaceId = String(state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
        const activeChatId = normalizeChatId(state.activeChatId || '');
        if (activeWorkspaceId === ws && chatIdsAreEquivalent(activeChatId, chat)) {
          updateComposerMentionMenuFromInput();
        }
      }).catch(() => {});

      const warmNow = () => {
        try {
          buildComposerMentionCandidates(ws, chat);
        } catch {
          // ignore mention prewarm failures
        }
      };
      if (typeof window.requestIdleCallback === 'function') {
        window.requestIdleCallback(() => warmNow(), { timeout: 240 });
      } else {
        window.requestAnimationFrame(() => warmNow());
      }
      return;
    }
    if (
      activeEntry
      && !isDirectChatEntry(activeEntry)
      && countMentionCandidateRawMemberRecords(activeEntry) < 10
    ) {
      void loadChannelMembersWithRoles(activeEntry, { force: false }).then((members) => {
        if (!Array.isArray(members) || !members.length) return;
        runtime.composerMentionCacheByChatKey.delete(key);
        const activeWorkspaceId = String(state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
        const activeChatId = normalizeChatId(state.activeChatId || '');
        if (activeWorkspaceId === ws && chatIdsAreEquivalent(activeChatId, chat)) {
          updateComposerMentionMenuFromInput();
        }
      }).catch(() => {});
    }
    const memberIds = Array.from(new Set([
      ...(activeEntry ? collectEntryMemberIds(activeEntry) : []),
      ...messageItems
        .map((message) => String(message?.authorMemberId || '').trim())
        .filter(Boolean)
    ])).slice(0, 320);
    if (memberIds.length) {
      scheduleComposerMentionMembersHydration(ws, chat, memberIds);
    }

    const warmNow = () => {
      try {
        buildComposerMentionCandidates(ws, chat);
      } catch {
        // ignore mention prewarm failures
      }
    };
    if (typeof window.requestIdleCallback === 'function') {
      window.requestIdleCallback(() => warmNow(), { timeout: 240 });
      return;
    }
    window.requestAnimationFrame(() => warmNow());
  }

  function buildComposerMentionFallbackCandidates(workspaceId = '', chatId = '', options = {}) {
    const ws = String(workspaceId || '').trim();
    const chat = normalizeChatId(chatId || '');
    const key = getChatStateKey(ws, chat);
    if (!ws || !chat || !key) return [];

    const query = normalizeSearchText(options?.query || '');
    const maxCandidates = Math.max(12, Math.min(72, Number(options?.limit || (query ? 24 : 48)) || 48));
    const selfMemberId = String(
      isTelegramConversationChat(ws, chat)
        ? 'telegram:self'
        : (getWorkspaceMemberIdByWorkspaceId(ws) || getCurrentWorkspaceMemberId() || '')
    ).trim();
    const isMaxMentionChat = isMaxConversationChat(ws, chat);
    const activeEntry = findRecentByChatId(ws, chat);
    const messageItems = Array.isArray(state.messagesByChatKey?.[key]?.items)
      ? state.messagesByChatKey[key].items
      : [];
    const rawMembers = collectMentionCandidateRawMemberRecords(activeEntry);
    const activeEntryMemberIds = activeEntry
      ? collectEntryMemberIds(activeEntry).map((memberId) => String(memberId || '').trim()).filter(Boolean)
      : [];
    const restrictFallbackToActiveMembers = Boolean(
      activeEntry
      && (activeEntryMemberIds.length > 0 || isMaxMentionChat)
    );
    const allowedMemberIds = restrictFallbackToActiveMembers
      ? new Set(activeEntryMemberIds)
      : null;
    const allowedMemberIdList = allowedMemberIds ? Array.from(allowedMemberIds) : [];
    const isAllowedMaxMentionMember = (memberId = '') => {
      if (!allowedMemberIds) return true;
      const normalizedMemberId = String(memberId || '').trim();
      if (!normalizedMemberId) return false;
      if (allowedMemberIds.has(normalizedMemberId)) return true;
      return allowedMemberIdList.some((allowedMemberId) => (
        areMemberIdentitiesEquivalent(allowedMemberId, normalizedMemberId)
      ));
    };
    const fallbackById = new Map();
    const addCandidate = (memberId = '', label = '', avatarUrl = '') => {
      const id = String(memberId || '').trim();
      if (!id) return;
      if (!isMaxMentionChat && selfMemberId && areMemberIdentitiesEquivalent(id, selfMemberId)) return;
      if (!isAllowedMaxMentionMember(id)) return;
      const safeLabel = cleanText(label || '', 120) || (isMaxMentionChat ? '' : getMentionCandidateFallbackLabel(id));
      if (!safeLabel) return;
      const searchLabel = normalizeSearchText(safeLabel);
      if (!searchLabel) return;
      const aliases = new Set([searchLabel]);
      safeLabel.split(/\s+/u).forEach((part) => {
        const token = normalizeSearchText(part);
        if (token.length >= 2) {
          aliases.add(token);
        }
      });
      if (query) {
        const matches = searchLabel.includes(query) || Array.from(aliases).some((alias) => alias.includes(query));
        if (!matches) return;
      }
      const previous = fallbackById.get(id) || null;
      fallbackById.set(id, {
        memberId: id,
        label: safeLabel,
        avatarUrl: normalizeAssetUrl(avatarUrl || previous?.avatarUrl || '', 4096),
        searchLabel,
        aliases: Array.from(aliases)
      });
    };

    if (!isMaxMentionChat || allowedMemberIds?.size) {
      for (let index = messageItems.length - 1; index >= 0; index -= 1) {
        if (fallbackById.size >= maxCandidates) break;
        const message = messageItems[index];
        const rawMessage = message?.raw && typeof message.raw === 'object'
          ? message.raw
          : message;
        const resolvedAuthorMemberId = String(
          getMessageAuthorMemberId(rawMessage)
          || message?.authorMemberId
          || ''
        ).trim();
        const resolvedAuthorName = cleanText(
          getMessageAuthorName(rawMessage)
          || message?.authorName
          || '',
          120
        );
      const authorProfile = resolvedAuthorMemberId
        ? getKnownProfileByMemberId(resolvedAuthorMemberId)
        : null;
      addCandidate(
        resolvedAuthorMemberId,
        getMentionCandidateLabelFromProfile(authorProfile) || (isMaxMentionChat ? '' : resolvedAuthorName),
        message?.authorAvatarUrl
          || getProfileAvatarUrl(authorProfile)
          || ''
      );
      }
    }

    if (fallbackById.size < maxCandidates) {
      rawMembers.forEach((member) => {
        if (fallbackById.size >= maxCandidates) return;
        addCandidate(
          member?.memberId || member?.id || member?.userId || '',
          member?.fullName
            || member?.displayName
            || member?.name
            || member?.profile?.fullName
            || member?.profile?.displayName
            || member?.profile?.name
            || '',
          member?.avatarUrl
            || member?.avatar
            || member?.photoUrl
            || member?.profile?.avatarUrl
            || member?.profile?.avatar
            || member?.profile?.photoUrl
            || ''
        );
      });
    }

    if (fallbackById.size < maxCandidates && activeEntry) {
      collectEntryMemberIds(activeEntry).forEach((memberId) => {
        if (fallbackById.size >= maxCandidates) return;
        const profile = getKnownProfileByMemberId(memberId);
        const entryTitleLabel = isMaxMentionChat && areMemberIdentitiesEquivalent(memberId, activeEntry?.directMemberId || '')
          ? cleanText(getRenderableEntryTitle(activeEntry) || activeEntry?.title || '', 120)
          : '';
        addCandidate(
          memberId,
          getMentionCandidateLabelFromProfile(profile) || entryTitleLabel,
          getProfileAvatarUrl(profile)
        );
      });
    }

    return Array.from(fallbackById.values())
      .sort((left, right) => String(left.label || '').localeCompare(String(right.label || ''), 'ru'))
      .slice(0, maxCandidates);
  }

  function buildComposerMentionCandidates(workspaceId = '', chatId = '') {
    const ws = String(workspaceId || '').trim();
    const chat = normalizeChatId(chatId || '');
    const stateKey = getChatStateKey(ws, chat);
    if (!ws || !chat || !stateKey) return [];
    const selfMemberId = isTelegramConversationChat(ws, chat)
      ? 'telegram:self'
      : (getWorkspaceMemberIdByWorkspaceId(ws) || getCurrentWorkspaceMemberId());
    const isTelegramMentionChat = isTelegramConversationChat(ws, chat);
    const isMaxMentionChat = isMaxConversationChat(ws, chat);
    const activeEntry = findRecentByChatId(ws, chat);
    const activeMessageState = state.messagesByChatKey?.[stateKey] || null;
    const candidatesFingerprint = getComposerMentionCandidatesFingerprint(
      ws,
      chat,
      selfMemberId,
      activeEntry,
      activeMessageState
    );
    const cached = runtime.composerMentionCacheByChatKey.get(stateKey) || null;
    if (cached?.fingerprint === candidatesFingerprint && Array.isArray(cached?.candidates)) {
      return cached.candidates.slice();
    }

    const byMemberId = new Map();
    const activeEntryMemberIds = activeEntry ? collectEntryMemberIds(activeEntry) : [];
    const rawMemberRecords = collectMentionCandidateRawMemberRecords(activeEntry);
    const activeMessages = Array.isArray(activeMessageState?.items)
      ? activeMessageState.items
      : [];
    const messageAuthorMemberIds = new Set(
      activeMessages
        .map((message) => String(message?.authorMemberId || '').trim())
        .filter(Boolean)
    );
    const restrictToActiveMembers = Boolean(
      activeEntry
      && (activeEntryMemberIds.length > 0 || isMaxMentionChat)
    );
    const allowedMemberIds = restrictToActiveMembers
      ? new Set(activeEntryMemberIds)
      : null;
    const allowedMemberIdList = allowedMemberIds
      ? Array.from(allowedMemberIds).filter(Boolean)
      : [];
    const hasAllowedMemberIdentity = (memberId = '') => {
      const normalizedMemberId = String(memberId || '').trim();
      if (!allowedMemberIds || !allowedMemberIds.size || !normalizedMemberId) {
        return false;
      }
      if (allowedMemberIds.has(normalizedMemberId)) {
        return true;
      }
      return allowedMemberIdList.some((allowedMemberId) => (
        areMemberIdentitiesEquivalent(allowedMemberId, normalizedMemberId)
      ));
    };
    const hasAllowedAuthorOverlap = Boolean(
      allowedMemberIds
      && Array.from(messageAuthorMemberIds).some((memberId) => hasAllowedMemberIdentity(memberId))
    );
    const shouldEnforceAllowedMemberIds = Boolean(
      allowedMemberIds
      && (
        rawMemberRecords.length > 0
        || hasAllowedAuthorOverlap
        || allowedMemberIds.size >= 25
        || isMaxMentionChat
      )
    );

    const addCandidate = (memberId = '', label = '', avatarUrl = '', extraAliases = []) => {
      const id = String(memberId || '').trim();
      const title = cleanText(label || '', 120) || (isMaxMentionChat ? '' : getMentionCandidateFallbackLabel(id));
      if (!id || !title) return;
      if (!isMaxMentionChat && selfMemberId && id === selfMemberId) return;
      if (shouldEnforceAllowedMemberIds && allowedMemberIds && !hasAllowedMemberIdentity(id)) return;
      const normalizedLabel = normalizeSearchText(title);
      if (!normalizedLabel) return;
      const existing = byMemberId.get(id) || null;
      const aliases = new Set(existing?.aliases || []);
      aliases.add(normalizedLabel);
      title.split(/\s+/u).forEach((part) => {
        const token = normalizeSearchText(part);
        if (token.length >= 2) {
          aliases.add(token);
        }
      });
      (Array.isArray(extraAliases) ? extraAliases : []).forEach((alias) => {
        const token = normalizeMentionAliasValue(alias || '');
        if (token.length >= 2) {
          aliases.add(token);
        }
      });
      if (/^[\p{L}\p{N}._-]{2,64}$/u.test(id)) {
        aliases.add(normalizeMentionAliasValue(id));
      }

      byMemberId.set(id, {
        memberId: id,
        label: title,
        avatarUrl: normalizeAssetUrl(avatarUrl || existing?.avatarUrl || '', 4096),
        searchLabel: normalizedLabel,
        aliases: Array.from(aliases).filter(Boolean)
      });
    };

    activeMessages.forEach((message) => {
      const authorMemberId = String(message?.authorMemberId || '').trim();
      const authorProfile = authorMemberId ? getKnownProfileByMemberId(authorMemberId) : null;
      addCandidate(
        authorMemberId,
        getMentionCandidateLabelFromProfile(authorProfile) || (isMaxMentionChat ? '' : (message?.authorName || '')),
        message?.authorAvatarUrl || getProfileAvatarUrl(authorProfile) || ''
      );
    });
    rawMemberRecords.forEach((member) => {
      const memberId = String(member?.memberId || member?.id || member?.userId || '').trim();
      const label = cleanText(
        member?.fullName
        || member?.displayName
        || member?.name
        || member?.profile?.fullName
        || member?.profile?.displayName
        || member?.profile?.name
        || '',
        120
      );
      const avatarUrl = normalizeAssetUrl(
        member?.avatarUrl
        || member?.avatar
        || member?.photoUrl
        || member?.profile?.avatarUrl
        || member?.profile?.avatar
        || member?.profile?.photoUrl
        || '',
        4096
      );
      const aliases = [];
      const usernameAlias = normalizeMentionAliasValue(
        member?.username
        || member?.userName
        || member?.login
        || member?.profile?.username
        || member?.profile?.userName
        || member?.profile?.login
        || ''
      );
      if (usernameAlias) aliases.push(usernameAlias);
      const email = normalizeEmailIdentity(
        member?.email
        || member?.mail
        || member?.profile?.email
        || member?.profile?.mail
        || ''
      );
      if (email) {
        aliases.push(String(email.split('@')[0] || ''));
      }
      addCandidate(memberId, label, avatarUrl, aliases);
    });

    const recents = Array.isArray(state.recentsByWorkspace?.[ws]) ? state.recentsByWorkspace[ws] : [];
    if (!isTelegramMentionChat && !isMaxMentionChat) {
      recents.forEach((entry) => {
        addCandidate(
          entry?.directMemberId || entry?.previewAuthorMemberId || '',
          entry?.title || entry?.previewAuthor || '',
          entry?.avatarUrl || entry?.previewAuthorAvatarUrl || ''
        );
        addCandidate(
          entry?.previewAuthorMemberId || '',
          entry?.previewAuthor || '',
          entry?.previewAuthorAvatarUrl || ''
        );
      });
    }

    const memberIdSources = shouldEnforceAllowedMemberIds && allowedMemberIds
      ? Array.from(allowedMemberIds)
      : (isTelegramMentionChat ? [
          ...(Array.isArray(activeEntry?.memberIds) ? activeEntry.memberIds : [])
        ] : isMaxMentionChat ? [
          ...(Array.isArray(activeEntry?.memberIds) ? activeEntry.memberIds : [])
        ] : [
          ...(Array.isArray(activeEntry?.memberIds) ? activeEntry.memberIds : []),
          ...recents.flatMap((entry) => (Array.isArray(entry?.memberIds) ? entry.memberIds : []))
        ]);
    const pendingHydrationMemberIds = [];
    memberIdSources
      .map((memberId) => String(memberId || '').trim())
      .filter(Boolean)
      .forEach((memberId) => {
        const profile = getKnownProfileByMemberId(memberId);
        const entryTitleLabel = isMaxMentionChat && areMemberIdentitiesEquivalent(memberId, activeEntry?.directMemberId || '')
          ? cleanText(getRenderableEntryTitle(activeEntry) || activeEntry?.title || '', 120)
          : '';
        const label = getMentionCandidateLabelFromProfile(profile) || entryTitleLabel;
        const avatarUrl = getProfileAvatarUrl(profile);
        const profileAliases = [];
        const usernameAlias = normalizeMentionAliasValue(getProfileUsernameValue(profile));
        if (usernameAlias) {
          profileAliases.push(usernameAlias);
        }
        collectProfileEmailCandidates(profile).forEach((email) => {
          const localPart = normalizeMentionAliasValue(String(String(email || '').split('@')[0] || ''));
          if (localPart) {
            profileAliases.push(localPart);
          }
        });
        addCandidate(memberId, label, avatarUrl, profileAliases);
        if (!byMemberId.has(memberId)) {
          pendingHydrationMemberIds.push(memberId);
        }
      });

    if (!allowedMemberIds && !isTelegramMentionChat && !isMaxMentionChat) {
      let globalCandidatesAdded = 0;
      runtime.knownProfileByMemberId.forEach((profile, memberId) => {
        if (globalCandidatesAdded >= 260) return;
        const label = getMentionCandidateLabelFromProfile(profile);
        if (!label) return;
        const profileAliases = [];
        const usernameAlias = normalizeMentionAliasValue(getProfileUsernameValue(profile));
        if (usernameAlias) {
          profileAliases.push(usernameAlias);
        }
        collectProfileEmailCandidates(profile).forEach((email) => {
          const localPart = normalizeMentionAliasValue(String(String(email || '').split('@')[0] || ''));
          if (localPart) {
            profileAliases.push(localPart);
          }
        });
        const beforeSize = byMemberId.size;
        addCandidate(memberId, label, getProfileAvatarUrl(profile), profileAliases);
        if (byMemberId.size > beforeSize) {
          globalCandidatesAdded += 1;
        }
      });
    }

    const resolved = Array.from(byMemberId.values())
      .sort((left, right) => left.label.localeCompare(right.label, 'ru'))
      .slice(0, 300);
    runtime.composerMentionCacheByChatKey.set(stateKey, {
      fingerprint: candidatesFingerprint,
      candidates: resolved
    });
    if (runtime.composerMentionCacheByChatKey.size > 30) {
      const oldestKey = runtime.composerMentionCacheByChatKey.keys().next().value;
      if (oldestKey) {
        runtime.composerMentionCacheByChatKey.delete(oldestKey);
      }
    }
    if (pendingHydrationMemberIds.length) {
      scheduleComposerMentionMembersHydration(ws, chat, pendingHydrationMemberIds);
    }
    return resolved;
  }

  function findComposerMentionToken(value = '', caretPosition = 0) {
    const text = String(value || '');
    const caret = Math.max(0, Math.min(text.length, Number(caretPosition) || 0));
    const beforeCaret = text.slice(0, caret);
    const atIndex = beforeCaret.lastIndexOf('@');
    if (atIndex < 0) return null;
    if (atIndex > 0) {
      const prevChar = beforeCaret[atIndex - 1];
      // Allow mentions after punctuation and line breaks, but keep email/word matches blocked.
      if (prevChar && /[\p{L}\p{N}._-]/u.test(prevChar)) {
        return null;
      }
    }
    const query = beforeCaret.slice(atIndex + 1);
    if (!/^[\p{L}\p{N}._\-\s]{0,64}$/u.test(query)) {
      return null;
    }
    return {
      anchor: atIndex,
      query,
      caret
    };
  }

  function hideComposerMentionMenu(skipRender = false) {
    const hadVisibleState = state.composerMentionMenuVisible || state.composerMentionSuggestions.length > 0;
    if (hadVisibleState && refs.chatComposerMentions instanceof HTMLElement) {
      refs.chatComposerMentions.classList.add('is-hidden');
      refs.chatComposerMentions.innerHTML = '';
    }
    state.composerMentionMenuVisible = false;
    state.composerMentionAnchor = -1;
    state.composerMentionSuggestions = [];
    state.composerMentionSelectedIndex = 0;
    if (!skipRender && hadVisibleState) {
      scheduleRender('overlays');
    }
  }

  function scheduleComposerMentionRefresh(options = {}) {
    const useImmediate = options?.immediate === true;
    const plainText = typeof options?.plainText === 'string'
      ? options.plainText
      : null;
    const caret = Number.isFinite(Number(options?.caret))
      ? Math.max(0, Math.round(Number(options.caret)))
      : null;

    if (useImmediate) {
      if (runtime.composerMentionRefreshFrame) {
        window.cancelAnimationFrame(runtime.composerMentionRefreshFrame);
        runtime.composerMentionRefreshFrame = 0;
      }
      runtime.composerMentionRefreshValue = null;
      runtime.composerMentionRefreshCaret = null;
      updateComposerMentionMenuFromInput(plainText, caret);
      return;
    }

    runtime.composerMentionRefreshValue = plainText;
    runtime.composerMentionRefreshCaret = caret;
    if (runtime.composerMentionRefreshFrame) return;
    runtime.composerMentionRefreshFrame = window.requestAnimationFrame(() => {
      runtime.composerMentionRefreshFrame = 0;
      const pendingValue = typeof runtime.composerMentionRefreshValue === 'string'
        ? runtime.composerMentionRefreshValue
        : null;
      const pendingCaret = Number.isFinite(Number(runtime.composerMentionRefreshCaret))
        ? Math.max(0, Math.round(Number(runtime.composerMentionRefreshCaret)))
        : null;
      runtime.composerMentionRefreshValue = null;
      runtime.composerMentionRefreshCaret = null;
      updateComposerMentionMenuFromInput(pendingValue, pendingCaret);
    });
  }

  function updateComposerMentionMenuFromInput(plainTextOverride = null, caretOverride = null) {
    if (!isComposerInputElement(refs.chatComposerInput)) {
      hideComposerMentionMenu(true);
      return;
    }
    const workspaceId = String(state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
    const chatId = normalizeChatId(state.activeChatId || '');
    if (!workspaceId || !chatId) {
      hideComposerMentionMenu();
      return;
    }

    const value = typeof plainTextOverride === 'string'
      ? plainTextOverride
      : getComposerPlainText();
    const caret = Number.isFinite(Number(caretOverride))
      ? Math.max(0, Math.round(Number(caretOverride)))
      : getComposerSelectionOffsets(value).end;
    const token = findComposerMentionToken(value, caret);
    if (!token) {
      hideComposerMentionMenu();
      return;
    }

    const query = normalizeSearchText(token.query || '');
    const activeEntry = findRecentByChatId(workspaceId, chatId);
    const isTelegramMentionChat = isTelegramConversationChat(workspaceId, chatId);
    const isMaxMentionChat = isMaxConversationChat(workspaceId, chatId);
    const chatParticipantIds = new Set(
      (activeEntry ? collectEntryMemberIds(activeEntry) : [])
        .map((memberId) => String(memberId || '').trim())
        .filter(Boolean)
    );
    const shouldLimitToChatParticipants = Boolean(
      activeEntry
      && !isTelegramMentionChat
      && (chatParticipantIds.size > 0 || isMaxMentionChat)
    );
    if (isMaxMentionChat && shouldLimitToChatParticipants && chatParticipantIds.size <= 0) {
      hideComposerMentionMenu();
      return;
    }
    const isChatParticipantCandidate = (candidate = null) => {
      const candidateMemberId = String(candidate?.memberId || '').trim();
      if (!candidateMemberId) return false;
      if (chatParticipantIds.has(candidateMemberId)) return true;
      return Array.from(chatParticipantIds).some((memberId) => (
        areMemberIdentitiesEquivalent(memberId, candidateMemberId)
      ));
    };
    const candidates = buildComposerMentionCandidates(workspaceId, chatId);
    let filtered = candidates
      .filter((candidate) => {
        if (!query) return true;
        if (candidate.searchLabel.includes(query)) return true;
        return candidate.aliases.some((alias) => alias.includes(query));
      })
      .filter((candidate) => (
        shouldLimitToChatParticipants
          ? isChatParticipantCandidate(candidate)
          : true
      ));

    if (shouldLimitToChatParticipants && !filtered.length && chatParticipantIds.size > 0) {
      const selfMemberId = String(
        isTelegramConversationChat(workspaceId, chatId)
          ? 'telegram:self'
          : (getWorkspaceMemberIdByWorkspaceId(workspaceId) || getCurrentWorkspaceMemberId() || '')
      ).trim();
      filtered = Array.from(chatParticipantIds)
        .filter((memberId) => isMaxMentionChat || !selfMemberId || !areMemberIdentitiesEquivalent(memberId, selfMemberId))
        .map((memberId) => {
          const profile = getKnownProfileByMemberId(memberId);
          const entryTitleLabel = isMaxMentionChat && areMemberIdentitiesEquivalent(memberId, activeEntry?.directMemberId || '')
            ? cleanText(getRenderableEntryTitle(activeEntry) || activeEntry?.title || '', 120)
            : '';
          const label = cleanText(getMentionCandidateLabelFromProfile(profile), 120)
            || entryTitleLabel
            || (isMaxMentionChat ? '' : getMentionCandidateFallbackLabel(memberId));
          const normalizedLabel = normalizeSearchText(label);
          if (!normalizedLabel) return null;
          const aliases = new Set([normalizedLabel]);
          const usernameAlias = normalizeMentionAliasValue(getProfileUsernameValue(profile));
          if (usernameAlias) aliases.add(usernameAlias);
          collectProfileEmailCandidates(profile).forEach((email) => {
            const localPart = normalizeMentionAliasValue(String(String(email || '').split('@')[0] || ''));
            if (localPart) aliases.add(localPart);
          });
          return {
            memberId,
            label,
            avatarUrl: normalizeAssetUrl(getProfileAvatarUrl(profile), 4096),
            searchLabel: normalizedLabel,
            aliases: Array.from(aliases)
          };
        })
        .filter((candidate) => {
          if (!candidate) return false;
          if (!query) return true;
          if (candidate.searchLabel.includes(query)) return true;
          return candidate.aliases.some((alias) => alias.includes(query));
        })
        .filter(Boolean)
        .sort((left, right) => String(left.label || '').localeCompare(String(right.label || ''), 'ru'));
    }

    const limit = query ? 24 : 48;
    filtered = filtered.slice(0, limit);

    if (!filtered.length) {
      const fallbackCandidates = buildComposerMentionFallbackCandidates(workspaceId, chatId, {
        query,
        limit: query ? 24 : 48
      });
      if (fallbackCandidates.length) {
        filtered = fallbackCandidates;
      }
    }

    if (!filtered.length) {
      if (isTelegramMentionChat || isMaxMentionChat || !candidates.length || query) {
        maybeWarmComposerMentionCandidates(workspaceId, chatId, {
          force: true,
          cooldownMs: 0
        });
        if (state.composerMentionMenuVisible === true && Number(state.composerMentionAnchor) === token.anchor) {
          return;
        }
      }
      hideComposerMentionMenu();
      return;
    }

    const previousVisible = state.composerMentionMenuVisible === true;
    const previousAnchor = Number(state.composerMentionAnchor);
    const previousSelectedIndex = Number(state.composerMentionSelectedIndex || 0);
    const previousSuggestions = Array.isArray(state.composerMentionSuggestions)
      ? state.composerMentionSuggestions
      : [];
    state.composerMentionMenuVisible = true;
    state.composerMentionAnchor = token.anchor;
    state.composerMentionSuggestions = filtered;
    const nextSelectedIndex = Math.max(
      0,
      Math.min(Number(state.composerMentionSelectedIndex || 0), filtered.length - 1)
    );
    state.composerMentionSelectedIndex = nextSelectedIndex;

    const suggestionsChanged = (
      previousSuggestions.length !== filtered.length
      || previousSuggestions.some((candidate, index) => {
        const nextCandidate = filtered[index] || null;
        return (
          String(candidate?.memberId || '') !== String(nextCandidate?.memberId || '')
          || String(candidate?.label || '') !== String(nextCandidate?.label || '')
          || String(candidate?.avatarUrl || '') !== String(nextCandidate?.avatarUrl || '')
        );
      })
    );
    const selectedChanged = previousSelectedIndex !== nextSelectedIndex;
    const anchorChanged = previousAnchor !== token.anchor;
    if (!previousVisible || suggestionsChanged || selectedChanged || anchorChanged) {
      scheduleRender('overlays');
    }
  }

  function applyComposerMentionSuggestion(index = 0) {
    if (!isComposerInputElement(refs.chatComposerInput)) return false;
    const suggestions = Array.isArray(state.composerMentionSuggestions) ? state.composerMentionSuggestions : [];
    if (!suggestions.length) return false;
    const safeIndex = Math.max(0, Math.min(Number(index) || 0, suggestions.length - 1));
    const candidate = suggestions[safeIndex];
    if (!candidate) return false;

    const value = getComposerPlainText();
    const { end: caret } = getComposerSelectionOffsets();
    const token = findComposerMentionToken(value, caret);
    const anchor = token ? token.anchor : Number(state.composerMentionAnchor);
    if (!Number.isFinite(anchor) || anchor < 0 || anchor > value.length) return false;
    const insertion = `@${candidate.label} `;
    const nextCaret = anchor + insertion.length;
    hideComposerMentionMenu(true);
    if (!setComposerSelectionOffsets(anchor, caret)) {
      return false;
    }
    insertComposerText(insertion, { selectInserted: false });
    setComposerSelectionOffsets(nextCaret, nextCaret);
    scheduleRender(['chat', 'overlays']);
    return true;
  }

  function renderComposerMentionMenu() {
    if (!(refs.chatComposerMentions instanceof HTMLElement)) return;
    if (!state.composerMentionMenuVisible || !Array.isArray(state.composerMentionSuggestions) || !state.composerMentionSuggestions.length) {
      refs.chatComposerMentions.classList.add('is-hidden');
      refs.chatComposerMentions.innerHTML = '';
      return;
    }

    refs.chatComposerMentions.innerHTML = state.composerMentionSuggestions
      .map((candidate, index) => (
        `<button class="yc-mention-item${index === state.composerMentionSelectedIndex ? ' is-selected' : ''}" type="button" data-mention-index="${index}">
          <span class="yc-mention-item-avatar">${buildMiniAvatarMarkup(candidate.label, candidate.avatarUrl || '', `mention:${candidate.memberId || ''}`)}</span>
          <span class="yc-mention-item-text">${escapeHtml(candidate.label || 'Участник')}</span>
        </button>`
      ))
      .join('');
    refs.chatComposerMentions.classList.remove('is-hidden');
  }

  function convertComposerMentionsToMarkdown(text = '', workspaceId = '', chatId = '') {
    let source = cleanMultiline(text || '', 6000);
    if (!source) return '';

    const candidateMapByMemberId = new Map();
    const registerCandidate = (candidate = null) => {
      const memberId = String(candidate?.memberId || '').trim();
      const label = cleanText(candidate?.label || '', 120);
      if (!memberId || !label) return;
      const existing = candidateMapByMemberId.get(memberId) || null;
      const aliases = new Set(Array.isArray(existing?.aliases) ? existing.aliases : []);
      (Array.isArray(candidate?.aliases) ? candidate.aliases : []).forEach((alias) => {
        const token = normalizeSearchText(alias || '');
        if (token) aliases.add(token);
      });
      candidateMapByMemberId.set(memberId, {
        memberId,
        label: existing?.label || label,
        aliases: Array.from(aliases)
      });
    };
    buildComposerMentionCandidates(workspaceId, chatId).forEach(registerCandidate);
    buildComposerMentionFallbackCandidates(workspaceId, chatId, { limit: 72 }).forEach(registerCandidate);
    const candidates = Array.from(candidateMapByMemberId.values());
    const byLabel = new Map();
    const byAlias = new Map();
    candidates.forEach((candidate) => {
      const memberId = String(candidate?.memberId || '').trim();
      const label = cleanText(candidate?.label || '', 120);
      if (!memberId || !label) return;
      byLabel.set(normalizeSearchText(label), { memberId, label });
      (Array.isArray(candidate?.aliases) ? candidate.aliases : []).forEach((alias) => {
        const token = normalizeSearchText(alias || '');
        if (!token || byAlias.has(token)) return;
        byAlias.set(token, { memberId, label });
      });
    });

    source = source.replace(/@\[((?:[^\]\\]|\\.){1,120})\]/gu, (match, rawLabel) => {
      const plainLabel = cleanText(String(rawLabel || '').replace(/\\]/g, ']'), 120);
      const key = normalizeSearchText(plainLabel);
      const resolved = byLabel.get(key) || null;
      if (!resolved) return `@${plainLabel}`;
      return `[@${resolved.label}](member:${resolved.memberId})`;
    });

    const labelsByLength = candidates
      .map((candidate) => ({
        memberId: String(candidate?.memberId || '').trim(),
        label: cleanText(candidate?.label || '', 120)
      }))
      .filter((candidate) => candidate.memberId && candidate.label)
      .sort((left, right) => right.label.length - left.label.length);
    labelsByLength.forEach((candidate) => {
      const escapedLabelPattern = candidate.label
        .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
        .replace(/\s+/g, '\\s+');
      const fullNameMentionPattern = new RegExp(`(^|[\\s(])@${escapedLabelPattern}(?=$|[\\s),.!?;:])`, 'giu');
      source = source.replace(fullNameMentionPattern, (fullMatch, prefix) => `${prefix}[@${candidate.label}](member:${candidate.memberId})`);
    });

    source = source.replace(/(^|[\s(])@([\p{L}\p{N}._-]{2,64})(?=$|[\s),.!?;:])/gu, (fullMatch, prefix, rawAlias) => {
      const aliasKey = normalizeSearchText(rawAlias || '');
      const resolved = byAlias.get(aliasKey) || null;
      if (!resolved) return fullMatch;
      return `${prefix}[@${resolved.label}](member:${resolved.memberId})`;
    });

    return source;
  }

  function collectComposerMentionSendTargets(text = '', workspaceId = '', chatId = '') {
    const source = cleanMultiline(text || '', 6000);
    if (!source || !isMaxConversationChat(workspaceId, chatId)) return [];
    const candidatesByLabel = new Map();
    const registerCandidate = (candidate = null) => {
      const memberId = String(candidate?.memberId || '').trim();
      const label = cleanText(candidate?.label || '', 120);
      if (!memberId || !label) return;
      const key = normalizeSearchText(label);
      if (!key || candidatesByLabel.has(key)) return;
      candidatesByLabel.set(key, {
        memberId,
        label
      });
    };
    buildComposerMentionCandidates(workspaceId, chatId).forEach(registerCandidate);
    buildComposerMentionFallbackCandidates(workspaceId, chatId, { limit: 72 }).forEach(registerCandidate);
    const candidates = Array.from(candidatesByLabel.values())
      .sort((left, right) => right.label.length - left.label.length);
    if (!candidates.length) return [];
    const mentions = [];
    const occupiedRanges = [];
    const isRangeFree = (start, end) => !occupiedRanges.some((range) => start < range.end && end > range.start);
    candidates.forEach((candidate) => {
      const escapedLabelPattern = candidate.label
        .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
        .replace(/\s+/g, '\\s+');
      const mentionPattern = new RegExp(`(^|[\\s(])@${escapedLabelPattern}(?=$|[\\s),.!?;:])`, 'giu');
      let match = null;
      while ((match = mentionPattern.exec(source)) !== null) {
        const prefix = String(match[1] || '');
        const start = Number(match.index || 0) + prefix.length;
        const end = start + String(match[0] || '').length - prefix.length;
        if (!isRangeFree(start, end)) continue;
        occupiedRanges.push({ start, end });
        mentions.push({
          memberId: candidate.memberId,
          label: candidate.label,
          start,
          end
        });
      }
    });
    return mentions.sort((left, right) => left.start - right.start);
  }

  function normalizeAssetUrl(value = '', maxLength = 2048) {
    let url = String(value || '').trim();
    if (!url) return '';
    for (let index = 0; index < 4; index += 1) {
      const next = url
        .replace(/&quot;/g, '"')
        .replace(/&#34;/g, '"')
        .replace(/&amp;/g, '&')
        .replace(/\\u002f/gi, '/')
        .replace(/\\u003a/gi, ':')
        .replace(/\\\//g, '/')
        .trim();
      if (next === url) break;
      url = next;
    }
    url = url.replace(/^['"]+|['"]+$/g, '').trim();
    const nestedUrl = url.match(/https?:\/\/[^\s"'()<>]+/i);
    if (nestedUrl?.[0]) {
      url = nestedUrl[0];
    }
    if (!/^(https?:|yuchat-resource:|data:(?:image|video|audio)\/|blob:|\/)/i.test(url)) return '';
    const requestedMaxLength = Math.max(256, Number(maxLength) || 2048);
    const isDataMedia = /^data:(?:image|video|audio)\//i.test(url);
    const effectiveMaxLength = isDataMedia
      ? Math.max(requestedMaxLength, 2097152)
      : requestedMaxLength;
    return url.slice(0, effectiveMaxLength);
  }

  function buildTypedLocalResourceUrl(sourceUrl = '', mimeType = '') {
    const normalizedUrl = normalizeAssetUrl(sourceUrl || '', 8388608);
    if (!/^yuchat-resource:/i.test(normalizedUrl || '')) return normalizedUrl;
    const normalizedMimeType = cleanText(mimeType || '', 180).toLowerCase().split(';')[0].trim();
    if (!/^(?:audio|video|image)\//i.test(normalizedMimeType)) return normalizedUrl;
    try {
      const parsedUrl = new URL(normalizedUrl);
      parsedUrl.searchParams.set('contentType', normalizedMimeType);
      return normalizeAssetUrl(parsedUrl.toString(), 8388608) || normalizedUrl;
    } catch {
      return normalizedUrl;
    }
  }

	  function inferProtectedAssetMimeType(sourceUrl = '', fallbackMimeType = '') {
	    const explicit = cleanText(fallbackMimeType || '', 180).toLowerCase();
	    if (explicit) {
	      return explicit.split(';')[0].trim();
	    }
	    const normalizedUrl = normalizeAssetUrl(sourceUrl || '', 8192).toLowerCase();
	    if (!normalizedUrl) return '';
	    const inferred = inferMimeTypeFromAttachmentSource(normalizedUrl);
	    if (inferred === 'video/webm' && /\b(?:voice|ptt)\b/.test(normalizedUrl)) {
	      return 'audio/webm';
	    }
	    return inferred;
	  }

  function normalizeProtectedAssetMimeTypeValue(value = '') {
    return cleanText(value || '', 180).toLowerCase().split(';')[0].trim();
  }

  function shouldPreferExpectedProtectedAssetMimeType(sourceUrl = '', expectedMimeType = '', actualMimeType = '') {
    const expected = normalizeProtectedAssetMimeTypeValue(expectedMimeType);
    const actual = normalizeProtectedAssetMimeTypeValue(actualMimeType);
    if (!expected || !actual || expected === actual) {
      return false;
    }
    if (!/^audio\//.test(expected)) {
      return false;
    }
    if (actual === 'application/octet-stream' || actual === 'binary/octet-stream') {
      return true;
    }
    if (expected === 'audio/mp4' && /^(video\/mp4|application\/mp4)$/.test(actual)) {
      return true;
    }
    if (expected === 'audio/webm' && /^video\/webm$/.test(actual)) {
      return true;
    }
    if (expected === 'audio/ogg' && /^application\/ogg$/.test(actual)) {
      return true;
    }
    const normalizedUrl = normalizeAssetUrl(sourceUrl || '', 8192).toLowerCase();
    return Boolean(
      normalizedUrl
      && /\b(?:voice|ptt)\b/.test(normalizedUrl)
      && (/^video\/(?:mp4|webm)$/.test(actual) || actual === 'application/mp4')
    );
  }

  function resolveProtectedAssetMimeType(sourceUrl = '', options = {}) {
    const expectedMimeType = normalizeProtectedAssetMimeTypeValue(options?.expectedMimeType || '');
    const responseMimeType = normalizeProtectedAssetMimeTypeValue(options?.responseMimeType || '');
    const blobMimeType = normalizeProtectedAssetMimeTypeValue(options?.blobMimeType || '');
    const fallbackMimeType = shouldPreferExpectedProtectedAssetMimeType(
      sourceUrl,
      expectedMimeType,
      responseMimeType
    )
      ? expectedMimeType
      : (responseMimeType || expectedMimeType || blobMimeType || '');
    return inferProtectedAssetMimeType(sourceUrl, fallbackMimeType);
  }

  function rewriteMediaDataUrlMimeType(dataUrl = '', mimeType = '') {
    const normalizedDataUrl = String(dataUrl || '').trim();
    const normalizedMimeType = normalizeProtectedAssetMimeTypeValue(mimeType);
    if (!/^data:/i.test(normalizedDataUrl) || !normalizedMimeType) {
      return normalizedDataUrl;
    }
    const commaIndex = normalizedDataUrl.indexOf(',');
    if (commaIndex < 0) {
      return normalizedDataUrl;
    }
    const metadata = normalizedDataUrl.slice(0, commaIndex);
    const payload = normalizedDataUrl.slice(commaIndex);
    const suffix = /;base64$/i.test(metadata) ? ';base64' : '';
    return `data:${normalizedMimeType}${suffix}${payload}`;
  }

  async function fetchProtectedAssetDataUrlViaMain(sourceUrl = '', options = {}) {
    const normalizedUrl = normalizeAssetUrl(sourceUrl || '', 8192);
    if (!normalizedUrl) return '';
    try {
      const transferId = cleanText(options?.progressTransferId || '', 180);
      const result = await ipcRenderer.invoke('fetch-attachment-data-url', {
        url: normalizedUrl,
        fileId: String(options?.fileId || '').trim(),
        authToken: getAuthToken(),
        transferId,
        expectedMimeType: cleanText(options?.expectedMimeType || '', 180),
        availabilityTimeoutMs: Math.max(0, Number(options?.availabilityTimeoutMs) || 0)
      });
      if (result?.ok !== true || !/^data:/i.test(String(result?.dataUrl || ''))) {
        return '';
      }
      const resolvedMimeType = resolveProtectedAssetMimeType(normalizedUrl, {
        responseMimeType: String(result?.contentType || ''),
        expectedMimeType: cleanText(options?.expectedMimeType || '', 180)
      });
      return rewriteMediaDataUrlMimeType(String(result.dataUrl || ''), resolvedMimeType);
    } catch {
      return '';
    }
  }

  async function fetchProtectedAssetObjectUrl(sourceUrl = '', options = {}) {
    const normalizedUrl = normalizeAssetUrl(sourceUrl || '', 8192);
    if (!normalizedUrl) return '';
    const progressTransferId = cleanText(options?.progressTransferId || '', 180);
    const trackProgress = options?.trackProgress === true && Boolean(progressTransferId);
    const progressScope = cleanText(options?.progressScope || 'download', 32).toLowerCase() || 'download';
    const reportProgress = (payload = {}) => {
      if (!trackProgress) return;
      handleTransferProgressEvent({
        transferId: progressTransferId,
        scope: progressScope,
        ...payload
      });
    };
    const forceObjectUrl = options?.forceObjectUrl === true;
    if (/^(data:(?:image|video|audio)\/|blob:)/i.test(normalizedUrl) || (/^yuchat-resource:/i.test(normalizedUrl) && !forceObjectUrl)) {
      if (trackProgress) {
        reportProgress({
          stage: 'done',
          done: true,
          ok: true,
          percent: 100
        });
      }
      return normalizedUrl;
    }

    const localAbortController = (trackProgress && typeof AbortController === 'function')
      ? new AbortController()
      : null;

    const cached = runtime.attachmentObjectUrlBySource.get(normalizedUrl);
    if (cached) {
      if (trackProgress) {
        reportProgress({
          stage: 'done',
          done: true,
          ok: true,
          percent: 100
        });
      }
      return cached;
    }

    const inFlight = runtime.attachmentObjectUrlInFlightBySource.get(normalizedUrl);
    if (inFlight) {
      if (trackProgress) {
        reportProgress({
          stage: 'downloading',
          percent: null
        });
        return inFlight.then((resolvedUrl) => {
          reportProgress({
            stage: 'done',
            done: true,
            ok: true,
            percent: 100
          });
          return resolvedUrl;
        }).catch((error) => {
          reportProgress({
            stage: 'error',
            done: true,
            ok: false,
            percent: 100,
            error: cleanText(error?.message || 'Не удалось загрузить вложение', 200)
          });
          throw error;
        });
      }
      return inFlight;
    }
    if (trackProgress && localAbortController) {
      registerLocalTransferAbortHandler(progressTransferId, (reason = 'canceled') => {
        if (localAbortController.signal?.aborted === true) return;
        localAbortController.abort(createTransferAbortError(reason));
      });
    }

    const authToken = getAuthToken();
    const headers = {
      accept: '*/*'
    };
    const fallbackFileId = String(options?.fileId || '').trim();
    const expectedMimeType = cleanText(options?.expectedMimeType || '', 180).toLowerCase();
    const requestedAvailabilityTimeoutMs = Math.max(0, Math.min(32000, Number(options?.availabilityTimeoutMs) || 0));
    const shouldWaitForMediaAvailability = Boolean(
      fallbackFileId
      && /^(video|audio)\//i.test(expectedMimeType)
    );
    const availabilityTimeoutMs = shouldWaitForMediaAvailability
      ? Math.max(
        8000,
        requestedAvailabilityTimeoutMs || (/^video\//i.test(expectedMimeType) ? 22000 : 14000)
      )
      : requestedAvailabilityTimeoutMs;

    const requestPromise = (async () => {
      let requestUrl = normalizedUrl;
      const runRequest = async (targetUrl = requestUrl, withAuthHeader = true) => {
        const requestHeaders = { ...headers };
        if (withAuthHeader && authToken && !/^yuchat-resource:/i.test(String(targetUrl || ''))) {
          requestHeaders['X-KC-Authorization'] = authToken;
        }
        try {
          return await window.fetch(targetUrl, {
            method: 'GET',
            cache: 'no-store',
            credentials: 'include',
            headers: requestHeaders,
            signal: localAbortController?.signal
          });
        } catch (error) {
          const knownAbortReason = getTransferAbortReason(error);
          if (localAbortController?.signal?.aborted === true || knownAbortReason) {
            const signalReason = localAbortController?.signal?.reason;
            const abortReason = normalizeTransferAbortReasonValue(
              knownAbortReason
              || signalReason
              || error?.reason
              || 'canceled'
            );
            throw createTransferAbortError(abortReason);
          }
          return {
            ok: false,
            status: 0,
            headers: null,
            body: null,
            __fetchError: error
          };
        }
      };

      let response = await runRequest(requestUrl, true);
      if (authToken && [400, 401, 403].includes(Number(response.status || 0))) {
        response = await runRequest(requestUrl, false);
      }
      const canonicalFallbackUrl = fallbackFileId
        ? normalizeAssetUrl(buildCanonicalAttachmentDownloadUrl(fallbackFileId), 8192)
        : '';
      if (
        !response.ok
        && canonicalFallbackUrl
        && normalizeAssetUrl(requestUrl, 8192) !== canonicalFallbackUrl
        && !/^yuchat-resource:/i.test(String(requestUrl || ''))
      ) {
        reportProgress({
          stage: 'retry',
          percent: null,
          message: 'Пробую резервную ссылку'
        });
        requestUrl = canonicalFallbackUrl;
        response = await runRequest(requestUrl, true);
        if (authToken && [400, 401, 403].includes(Number(response.status || 0))) {
          response = await runRequest(requestUrl, false);
        }
      }
      if (!response.ok && Number(response.status || 0) === 404 && fallbackFileId) {
        if (availabilityTimeoutMs > 0) {
          const readyUrl = await waitForVideoNoteFileAvailability(fallbackFileId, {
            timeoutMs: availabilityTimeoutMs
          });
          if (readyUrl) {
            requestUrl = normalizeAssetUrl(readyUrl, 8192) || readyUrl;
            response = await runRequest(requestUrl, true);
            if (authToken && [400, 401, 403].includes(Number(response.status || 0))) {
              response = await runRequest(requestUrl, false);
            }
          }
        }
        const retryDelaysMs = [240, 420, 760, 1200, 1800];
        for (let index = 0; index < retryDelaysMs.length; index += 1) {
          if (response.ok || Number(response.status || 0) !== 404) {
            break;
          }
          reportProgress({
            stage: 'retry',
            percent: null
          });
          await new Promise((resolve) => window.setTimeout(resolve, retryDelaysMs[index]));
          response = await runRequest(requestUrl, true);
          if (authToken && [400, 401, 403].includes(Number(response.status || 0))) {
            response = await runRequest(requestUrl, false);
          }
        }
      }
      if (!response.ok) {
        const requestError = response?.__fetchError;
        const fallbackDataUrl = await fetchProtectedAssetDataUrlViaMain(requestUrl, {
          ...options,
          availabilityTimeoutMs
        });
        if (fallbackDataUrl) {
          runtime.attachmentObjectUrlBySource.set(normalizedUrl, fallbackDataUrl);
          return fallbackDataUrl;
        }
        if (requestError instanceof Error) {
          throw requestError;
        }
        throw new Error(`ASSET_FETCH_FAILED:${response.status || 0}`);
      }

      const responseMimeType = cleanText(String(response.headers?.get?.('content-type') || ''), 180).toLowerCase();
      const responseTotalBytes = Math.max(0, Number(response.headers?.get?.('content-length') || 0) || 0);
      let blob = null;
      if (trackProgress && response.body && typeof response.body.getReader === 'function') {
        const reader = response.body.getReader();
        const chunks = [];
        let loadedBytes = 0;
        reportProgress({
          stage: 'downloading',
          percent: responseTotalBytes > 0 ? 0 : null,
          loadedBytes: 0,
          totalBytes: responseTotalBytes
        });
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          if (!(value instanceof Uint8Array) || !value.length) continue;
          chunks.push(value);
          loadedBytes += value.length;
          const nextPercent = responseTotalBytes > 0
            ? Math.max(1, Math.min(99, Math.round((loadedBytes / responseTotalBytes) * 100)))
            : null;
          reportProgress({
            stage: 'downloading',
            percent: nextPercent,
            loadedBytes,
            totalBytes: responseTotalBytes
          });
        }
        blob = new Blob(chunks, {
          type: responseMimeType || cleanText(options?.expectedMimeType || '', 180) || 'application/octet-stream'
        });
      } else {
        blob = await response.blob();
      }
      if (!(blob instanceof Blob) || Number(blob.size || 0) <= 0) {
        const fallbackDataUrl = await fetchProtectedAssetDataUrlViaMain(requestUrl, {
          ...options,
          availabilityTimeoutMs
        });
        if (fallbackDataUrl) {
          runtime.attachmentObjectUrlBySource.set(normalizedUrl, fallbackDataUrl);
          return fallbackDataUrl;
        }
        throw new Error('ASSET_FETCH_EMPTY');
      }

      const effectiveMimeType = resolveProtectedAssetMimeType(requestUrl, {
        responseMimeType,
        expectedMimeType: cleanText(options?.expectedMimeType || '', 180),
        blobMimeType: blob.type || ''
      });
      const normalizedBlob = effectiveMimeType && blob.type !== effectiveMimeType
        ? new Blob([blob], { type: effectiveMimeType })
        : blob;
      const objectUrl = URL.createObjectURL(normalizedBlob);
      runtime.attachmentObjectUrlBySource.set(normalizedUrl, objectUrl);
      if (runtime.attachmentObjectUrlBySource.size > 96) {
        const oldestKey = runtime.attachmentObjectUrlBySource.keys().next().value;
        const oldestUrl = oldestKey ? runtime.attachmentObjectUrlBySource.get(oldestKey) : '';
        if (oldestKey) {
          runtime.attachmentObjectUrlBySource.delete(oldestKey);
        }
        if (oldestUrl && oldestUrl !== objectUrl) {
          try {
            URL.revokeObjectURL(oldestUrl);
          } catch {
            // ignore object URL cleanup failures
          }
        }
      }
      reportProgress({
        stage: 'done',
        done: true,
        ok: true,
        percent: 100,
        loadedBytes: Number(blob.size || 0),
        totalBytes: Number(blob.size || 0)
      });
      return objectUrl;
    })();

    runtime.attachmentObjectUrlInFlightBySource.set(normalizedUrl, requestPromise);
    try {
      return await requestPromise;
    } catch (error) {
      const abortReason = getTransferAbortReason(error);
      if (abortReason) {
        reportProgress({
          stage: abortReason === 'paused' ? 'paused' : 'canceled',
          done: true,
          ok: false,
          percent: 100,
          error: abortReason === 'paused'
            ? 'Загрузка поставлена на паузу.'
            : 'Загрузка отменена.'
        });
        throw error;
      }
      reportProgress({
        stage: 'error',
        done: true,
        ok: false,
        percent: 100,
        error: cleanText(error?.message || 'Не удалось загрузить вложение', 200)
      });
      throw error;
    } finally {
      if (trackProgress) {
        unregisterLocalTransferAbortHandler(progressTransferId);
      }
      runtime.attachmentObjectUrlInFlightBySource.delete(normalizedUrl);
    }
  }

  function buildVideoPreviewCacheKey(sourceUrl = '', fileId = '') {
    const normalizedSource = normalizeAssetUrl(sourceUrl || '', 8192);
    const normalizedFileId = String(fileId || '').trim();
    if (!normalizedSource) return '';
    return normalizedFileId ? `${normalizedSource}::${normalizedFileId}` : normalizedSource;
  }

  function getCachedVideoPreviewImageUrl(sourceUrl = '', fileId = '') {
    const cacheKey = buildVideoPreviewCacheKey(sourceUrl, fileId);
    if (!cacheKey) return '';
    return normalizeAssetUrl(runtime.videoPreviewImageBySource.get(cacheKey) || '', 8192);
  }

  function isCachedVideoPreviewUrlReferencedElsewhere(previewUrl = '', excludedKey = '') {
    const normalizedPreviewUrl = normalizeAssetUrl(previewUrl || '', 8192);
    const normalizedExcludedKey = String(excludedKey || '').trim();
    if (!normalizedPreviewUrl) return false;
    for (const [key, value] of runtime.videoPreviewImageBySource.entries()) {
      if (normalizedExcludedKey && key === normalizedExcludedKey) continue;
      if (normalizeAssetUrl(value || '', 8192) === normalizedPreviewUrl) {
        return true;
      }
    }
    return false;
  }

  function setCachedVideoPreviewImageUrl(sourceUrl = '', previewUrl = '', fileId = '') {
    const cacheKey = buildVideoPreviewCacheKey(sourceUrl, fileId);
    const normalizedPreviewUrl = normalizeAssetUrl(previewUrl || '', 8192);
    if (!cacheKey || !normalizedPreviewUrl) return false;
    const previousPreviewUrl = normalizeAssetUrl(runtime.videoPreviewImageBySource.get(cacheKey) || '', 8192);
    runtime.videoPreviewImageBySource.set(cacheKey, normalizedPreviewUrl);
    if (
      previousPreviewUrl
      && previousPreviewUrl !== normalizedPreviewUrl
      && !isCachedVideoPreviewUrlReferencedElsewhere(previousPreviewUrl, cacheKey)
    ) {
      revokeBlobObjectUrl(previousPreviewUrl);
    }
    while (runtime.videoPreviewImageBySource.size > 72) {
      const oldestKey = runtime.videoPreviewImageBySource.keys().next().value;
      const oldestUrl = oldestKey ? normalizeAssetUrl(runtime.videoPreviewImageBySource.get(oldestKey) || '', 8192) : '';
      if (!oldestKey || oldestKey === cacheKey) break;
      runtime.videoPreviewImageBySource.delete(oldestKey);
      if (
        oldestUrl
        && oldestUrl !== normalizedPreviewUrl
        && !isCachedVideoPreviewUrlReferencedElsewhere(oldestUrl, oldestKey)
      ) {
        revokeBlobObjectUrl(oldestUrl);
      }
    }
    return true;
  }

  async function createVideoPreviewImageUrlFromSource(sourceUrl = '', options = {}) {
    const normalizedSource = normalizeAssetUrl(sourceUrl || '', 8192);
    if (!normalizedSource || typeof document === 'undefined') return '';
    const targetSeekSeconds = Math.max(0, Number(options?.seekSeconds) || 0.72);
    const outputMimeType = cleanText(options?.outputMimeType || 'image/jpeg', 120).toLowerCase() || 'image/jpeg';
    const quality = Math.max(0.5, Math.min(0.96, Number(options?.quality) || 0.86));
    return new Promise((resolve) => {
      const video = document.createElement('video');
      let settled = false;
      let pendingSeekTargets = [];
      let lastCapturedPreviewUrl = '';
      let lastCapturedFrameScore = 0;
      let fallbackTimer = 0;
      const revokePreviewUrl = (value = '') => {
        const normalizedValue = normalizeAssetUrl(value || '', 8192);
        if (!normalizedValue || !/^blob:/i.test(normalizedValue)) return;
        try {
          URL.revokeObjectURL(normalizedValue);
        } catch {}
      };
      const finish = (value = '') => {
        if (settled) return;
        settled = true;
        if (fallbackTimer) {
          window.clearTimeout(fallbackTimer);
        }
        video.pause();
        video.removeAttribute('src');
        try {
          video.load();
        } catch {}
        resolve(normalizeAssetUrl(value || '', 8192));
      };
      const scoreCanvasFrame = (canvas = null) => {
        if (!(canvas instanceof HTMLCanvasElement)) return 0;
        const sampleCanvas = document.createElement('canvas');
        sampleCanvas.width = 24;
        sampleCanvas.height = 24;
        const sampleContext = sampleCanvas.getContext('2d', { alpha: false, willReadFrequently: true });
        if (!sampleContext) return 0;
        sampleContext.drawImage(canvas, 0, 0, sampleCanvas.width, sampleCanvas.height);
        const imageData = sampleContext.getImageData(0, 0, sampleCanvas.width, sampleCanvas.height);
        const pixels = imageData?.data instanceof Uint8ClampedArray ? imageData.data : null;
        if (!pixels || !pixels.length) return 0;
        let lightnessSum = 0;
        for (let index = 0; index < pixels.length; index += 4) {
          const red = Number(pixels[index] || 0);
          const green = Number(pixels[index + 1] || 0);
          const blue = Number(pixels[index + 2] || 0);
          lightnessSum += (0.2126 * red) + (0.7152 * green) + (0.0722 * blue);
        }
        return lightnessSum / Math.max(1, pixels.length / 4);
      };
      const seekToNextFrameCandidate = () => {
        if (settled) return;
        if (!pendingSeekTargets.length) {
          finish(lastCapturedPreviewUrl);
          return;
        }
        const nextSeekTarget = Math.max(0, Number(pendingSeekTargets.shift() || 0));
        try {
          if (Math.abs(Number(video.currentTime || 0) - nextSeekTarget) < 0.03) {
            window.requestAnimationFrame(() => {
              void captureFrame();
            });
            return;
          }
          video.currentTime = nextSeekTarget;
        } catch {
          window.requestAnimationFrame(() => {
            void captureFrame();
          });
        }
      };
      const captureFrame = async () => {
        if (settled) return;
        const width = Math.max(0, Number(video.videoWidth || 0));
        const height = Math.max(0, Number(video.videoHeight || 0));
        if (!width || !height) {
          finish('');
          return;
        }
        try {
          const canvas = document.createElement('canvas');
          canvas.width = width;
          canvas.height = height;
          const context = canvas.getContext('2d', { alpha: false });
          if (!context) {
            finish('');
            return;
          }
          context.drawImage(video, 0, 0, width, height);
          const blob = await canvasToBlobAsync(canvas, outputMimeType, quality);
          if (!(blob instanceof Blob) || Number(blob.size || 0) <= 0) {
            finish('');
            return;
          }
          const nextPreviewUrl = URL.createObjectURL(blob);
          const frameScore = scoreCanvasFrame(canvas);
          const hasUsefulFrame = frameScore >= 14;
          if (!lastCapturedPreviewUrl || frameScore >= lastCapturedFrameScore) {
            if (lastCapturedPreviewUrl && lastCapturedPreviewUrl !== nextPreviewUrl) {
              revokePreviewUrl(lastCapturedPreviewUrl);
            }
            lastCapturedPreviewUrl = nextPreviewUrl;
            lastCapturedFrameScore = frameScore;
          } else {
            revokePreviewUrl(nextPreviewUrl);
          }
          if (hasUsefulFrame || !pendingSeekTargets.length) {
            finish(lastCapturedPreviewUrl);
            return;
          }
          seekToNextFrameCandidate();
        } catch {
          if (pendingSeekTargets.length) {
            seekToNextFrameCandidate();
            return;
          }
          finish(lastCapturedPreviewUrl);
        }
      };
      const requestCapture = () => {
        window.requestAnimationFrame(() => {
          void captureFrame();
        });
      };
      video.preload = 'auto';
      video.muted = true;
      video.playsInline = true;
      video.disablePictureInPicture = true;
      video.addEventListener('error', () => finish(''), { once: true });
      video.addEventListener('loadeddata', () => {
        const duration = Number.isFinite(video.duration) ? Math.max(0, Number(video.duration || 0)) : 0;
        const seekCandidates = [
          targetSeekSeconds,
          Math.max(0.18, Math.min(duration * 0.2, 0.92)),
          Math.max(0.36, Math.min(duration * 0.35, 1.4)),
          Math.max(0.54, Math.min(duration * 0.5, 2.2)),
          0
        ];
        pendingSeekTargets = Array.from(new Set(
          seekCandidates
            .map((value) => {
              const numericValue = Math.max(0, Number(value || 0));
              if (duration > 0.08) {
                return Math.max(0, Math.min(duration - 0.04, numericValue));
              }
              return 0;
            })
            .filter((value) => Number.isFinite(value))
        ));
        seekToNextFrameCandidate();
      }, { once: true });
      video.addEventListener('seeked', requestCapture);
      fallbackTimer = window.setTimeout(() => {
        if (lastCapturedPreviewUrl) {
          finish(lastCapturedPreviewUrl);
          return;
        }
        requestCapture();
      }, 2400);
      video.src = normalizedSource;
      try {
        video.load();
      } catch {}
    });
  }

  async function ensureVideoPreviewImageUrl(sourceUrl = '', options = {}) {
    const normalizedSource = normalizeAssetUrl(sourceUrl || '', 8192);
    const fileId = String(options?.fileId || '').trim();
    const cacheKey = buildVideoPreviewCacheKey(normalizedSource, fileId);
    if (!cacheKey) return '';
    const cachedPreview = getCachedVideoPreviewImageUrl(normalizedSource, fileId);
    if (cachedPreview) return cachedPreview;
    const inFlight = runtime.videoPreviewImageInFlightBySource.get(cacheKey);
    if (inFlight instanceof Promise) {
      return inFlight;
    }
    const requestPromise = (async () => {
      try {
        const resolvedSource = /^(blob:|data:(?:image|video|audio)\/)/i.test(normalizedSource)
          ? normalizedSource
          : await fetchProtectedAssetObjectUrl(normalizedSource, {
            expectedMimeType: cleanText(options?.expectedMimeType || '', 140).toLowerCase(),
            fileId,
            forceObjectUrl: /^yuchat-resource:/i.test(normalizedSource)
          });
        const previewUrl = await createVideoPreviewImageUrlFromSource(resolvedSource || normalizedSource, options);
        if (!previewUrl) return '';
        setCachedVideoPreviewImageUrl(normalizedSource, previewUrl, fileId);
        return previewUrl;
      } catch {
        return '';
      }
    })();
    runtime.videoPreviewImageInFlightBySource.set(cacheKey, requestPromise);
    try {
      return await requestPromise;
    } finally {
      runtime.videoPreviewImageInFlightBySource.delete(cacheKey);
    }
  }

  function applyVideoNotePosterToStage(videoNode = null, previewUrl = '', options = {}) {
    if (!(videoNode instanceof HTMLVideoElement)) return false;
    const normalizedPreviewUrl = normalizeAssetUrl(previewUrl || '', 8192);
    if (!normalizedPreviewUrl) return false;
    const stageNode = videoNode.closest('.yc-video-note-stage, .yc-inline-video-preview-stage, .yc-dialog-video-note-stage');
    if (!(stageNode instanceof HTMLElement)) return false;
    let imageNode = stageNode.querySelector('.yc-video-note-preview, .yc-dialog-video-note-poster');
    if (!(imageNode instanceof HTMLImageElement)) {
      imageNode = document.createElement('img');
      imageNode.alt = '';
      imageNode.decoding = 'async';
      imageNode.loading = 'eager';
      imageNode.className = stageNode.classList.contains('yc-dialog-video-note-stage')
        ? 'yc-dialog-video-note-poster'
        : 'yc-video-note-preview';
      stageNode.insertBefore(imageNode, stageNode.firstChild);
    }
    if (imageNode.dataset.ycPosterBound !== '1') {
      imageNode.dataset.ycPosterBound = '1';
      imageNode.addEventListener('load', () => {
        stageNode.classList.add('has-poster');
      });
      imageNode.addEventListener('error', () => {
        const activePosterUrl = normalizeAssetUrl(imageNode.dataset.ycPosterUrl || '', 8192);
        const currentImageUrl = normalizeAssetUrl(
          imageNode.currentSrc || imageNode.getAttribute('src') || '',
          8192
        );
        if (activePosterUrl && currentImageUrl && activePosterUrl !== currentImageUrl) {
          return;
        }
        stageNode.classList.remove('has-poster');
        imageNode.removeAttribute('src');
        videoNode.removeAttribute('poster');
      });
    }
    imageNode.alt = '';
    imageNode.dataset.ycPosterUrl = normalizedPreviewUrl;
    stageNode.classList.remove('has-poster');
    imageNode.src = normalizedPreviewUrl;
    imageNode.dataset.ycAttachmentSource = normalizedPreviewUrl;
    videoNode.setAttribute('poster', normalizedPreviewUrl);
    return true;
  }

  async function ensureVoiceAttachmentAudioSource(audioNode = null, options = {}) {
    if (!(audioNode instanceof HTMLAudioElement)) return false;
    const fallbackFileId = String(audioNode.dataset.ycVoiceFileId || '').trim();
    const canonicalSource = normalizeAssetUrl(buildCanonicalAttachmentDownloadUrl(fallbackFileId), 8192);
    const primarySource = normalizeAssetUrl(
      audioNode.dataset.ycVoiceSource
      || audioNode.getAttribute('src')
      || audioNode.currentSrc
      || canonicalSource
      || '',
      8388608
    );
    if (!primarySource) return false;
    if (!audioNode.dataset.ycVoiceSource) {
      audioNode.dataset.ycVoiceSource = primarySource;
    }
    if (!options.force && audioNode.dataset.ycVoiceResolved === '1' && audioNode.getAttribute('src')) {
      return true;
    }
    const existingResolution = audioNode._ycVoiceResolvePromise;
    if (existingResolution instanceof Promise) {
      return existingResolution;
    }
    if (/^(blob:|data:)/i.test(primarySource)) {
      const directVoiceMime = cleanText(audioNode.dataset.ycVoiceMime || '', 140).toLowerCase()
        || inferLikelyVoiceAttachmentMimeType(primarySource, '');
      const directPrimarySource = buildTypedLocalResourceUrl(primarySource, directVoiceMime);
      if (audioNode.getAttribute('src') !== directPrimarySource) {
        audioNode.setAttribute('src', directPrimarySource);
        if (typeof audioNode.load === 'function') {
          audioNode.load();
        }
      }
      audioNode.dataset.ycVoiceSource = directPrimarySource;
      audioNode.dataset.ycVoiceResolved = '1';
      return true;
    }
    if (audioNode.dataset.ycVoiceResolving === '1') {
      return existingResolution instanceof Promise ? existingResolution : false;
    }

    const sourceCandidates = [];
    const pushSourceCandidate = (value = '') => {
      const normalized = normalizeAssetUrl(value || '', 8192);
      if (!normalized || sourceCandidates.includes(normalized)) return;
      sourceCandidates.push(normalized);
    };
    if (options.force === true && canonicalSource && canonicalSource !== primarySource) {
      pushSourceCandidate(canonicalSource);
    }
    pushSourceCandidate(primarySource);
    pushSourceCandidate(audioNode.dataset.ycVoiceSource || '');
    pushSourceCandidate(audioNode.getAttribute('src') || '');
    pushSourceCandidate(audioNode.currentSrc || '');
    if (canonicalSource) {
      pushSourceCandidate(canonicalSource);
    }

    const knownVoiceMime = cleanText(audioNode.dataset.ycVoiceMime || '', 140).toLowerCase();
    const inferredVoiceMime = inferLikelyVoiceAttachmentMimeType(
      sourceCandidates.join(' '),
      knownVoiceMime
    );
    const expectedMimeCandidates = [];
    const pushExpectedMime = (value = '') => {
      const normalized = cleanText(value || '', 140).toLowerCase();
      if (!normalized || expectedMimeCandidates.includes(normalized)) return;
      expectedMimeCandidates.push(normalized);
    };
    if (options.force === true && options.relaxMime === true) {
      expectedMimeCandidates.push('');
      pushExpectedMime(inferredVoiceMime);
      pushExpectedMime(knownVoiceMime);
      pushExpectedMime('audio/mp4');
      pushExpectedMime('audio/webm');
      pushExpectedMime('audio/ogg');
    } else {
      pushExpectedMime(knownVoiceMime);
      pushExpectedMime(inferredVoiceMime);
    }
    if (!expectedMimeCandidates.length) {
      expectedMimeCandidates.push('');
    }

    audioNode.dataset.ycVoiceResolving = '1';
    const resolutionPromise = (async () => {
      try {
        for (const sourceCandidate of sourceCandidates) {
          for (const expectedMimeType of expectedMimeCandidates) {
            if (options.force === true) {
              runtime.attachmentObjectUrlInFlightBySource.delete(sourceCandidate);
              runtime.attachmentObjectUrlBySource.delete(sourceCandidate);
            }
            const objectUrl = await fetchProtectedAssetObjectUrl(sourceCandidate, {
              expectedMimeType,
              fileId: fallbackFileId,
              forceObjectUrl: /^yuchat-resource:/i.test(sourceCandidate)
            });
            if (!objectUrl) continue;
            if (audioNode.getAttribute('src') !== objectUrl) {
              audioNode.setAttribute('src', objectUrl);
              if (typeof audioNode.load === 'function') {
                audioNode.load();
              }
            }
            audioNode.dataset.ycVoiceSource = sourceCandidate;
            if (expectedMimeType) {
              audioNode.dataset.ycVoiceMime = expectedMimeType;
            }
            audioNode.dataset.ycVoiceResolved = '1';
            return true;
          }
        }
        return false;
      } catch {
        return false;
      } finally {
        delete audioNode.dataset.ycVoiceResolving;
      }
    })();
    audioNode._ycVoiceResolvePromise = resolutionPromise;
    try {
      return await resolutionPromise;
    } finally {
      if (audioNode._ycVoiceResolvePromise === resolutionPromise) {
        audioNode._ycVoiceResolvePromise = null;
      }
    }
  }

  async function ensureVideoAttachmentSource(videoNode = null, options = {}) {
    if (!(videoNode instanceof HTMLVideoElement)) return false;
    const fallbackFileId = String(videoNode.dataset.ycVideoFileId || '').trim();
    const originalSource = normalizeAssetUrl(
      videoNode.dataset.ycVideoSource
      || videoNode.getAttribute('src')
      || videoNode.currentSrc
      || buildCanonicalAttachmentDownloadUrl(fallbackFileId)
      || '',
      8388608
    );
    if (!originalSource) return false;
    if (!videoNode.dataset.ycVideoSource) {
      videoNode.dataset.ycVideoSource = originalSource;
    }
    if (!options.force && videoNode.dataset.ycVideoResolved === '1') {
      return true;
    }
    const existingResolution = videoNode._ycVideoResolvePromise;
    if (existingResolution instanceof Promise) {
      return existingResolution;
    }
    if (/^(blob:|data:(?:image|video|audio)\/)/i.test(originalSource)) {
      const directVideoMime = cleanText(videoNode.dataset.ycVideoMime || '', 140).toLowerCase()
        || inferProtectedAssetMimeType(originalSource, '');
      const directVideoSource = buildTypedLocalResourceUrl(originalSource, directVideoMime);
      if (videoNode.getAttribute('src') !== directVideoSource) {
        videoNode.setAttribute('src', directVideoSource);
        if (typeof videoNode.load === 'function') {
          videoNode.load();
        }
      }
      videoNode.dataset.ycVideoSource = directVideoSource;
      videoNode.dataset.ycVideoResolved = '1';
      return true;
    }
    if (/^yuchat-resource:/i.test(originalSource)) {
      const directVideoMime = cleanText(videoNode.dataset.ycVideoMime || '', 140).toLowerCase()
        || inferProtectedAssetMimeType(originalSource, '');
      const directVideoSource = buildTypedLocalResourceUrl(originalSource, directVideoMime);
      if (videoNode.getAttribute('src') !== directVideoSource) {
        videoNode.setAttribute('src', directVideoSource);
        if (typeof videoNode.load === 'function') {
          videoNode.load();
        }
      }
      videoNode.dataset.ycVideoSource = directVideoSource;
      videoNode.dataset.ycVideoResolved = '1';
      return true;
    }
    if (videoNode.dataset.ycVideoResolving === '1') {
      return existingResolution instanceof Promise ? existingResolution : false;
    }
    videoNode.dataset.ycVideoResolving = '1';
    const resolutionPromise = (async () => {
      try {
      const objectUrl = await fetchProtectedAssetObjectUrl(originalSource, {
        expectedMimeType: cleanText(videoNode.dataset.ycVideoMime || '', 140).toLowerCase(),
        fileId: fallbackFileId,
        forceObjectUrl: /^yuchat-resource:/i.test(originalSource)
      });
        if (!objectUrl) return false;
        if (videoNode.getAttribute('src') !== objectUrl) {
          videoNode.setAttribute('src', objectUrl);
          if (typeof videoNode.load === 'function') {
            videoNode.load();
          }
        }
        videoNode.dataset.ycVideoResolved = '1';
        return true;
      } catch {
        return false;
      } finally {
        delete videoNode.dataset.ycVideoResolving;
      }
    })();
    videoNode._ycVideoResolvePromise = resolutionPromise;
    try {
      return await resolutionPromise;
    } finally {
      if (videoNode._ycVideoResolvePromise === resolutionPromise) {
        videoNode._ycVideoResolvePromise = null;
      }
    }
  }

  function syncDialogImageViewerImageState(imageNode = null, options = {}) {
    if (!(imageNode instanceof HTMLImageElement)) return;
    if (!imageNode.classList.contains('yc-dialog-image-viewer-image')) return;
    if (state.dialogImageViewerOpen !== true) return;
    const currentSrc = normalizeAssetUrl(
      imageNode.currentSrc || imageNode.getAttribute('src') || '',
      8192
    );
    const changed = currentSrc && normalizeAssetUrl(state.dialogImageViewerUrl || '', 8192) !== currentSrc;
    if (!changed && state.dialogImageViewerLoading !== true && options.force !== true) {
      return;
    }
    if (currentSrc) {
      state.dialogImageViewerUrl = currentSrc;
    }
    state.dialogImageViewerLoading = false;
    scheduleRender('overlays');
  }

  function hasDialogVideoVisualTrack(videoNode = null) {
    if (!(videoNode instanceof HTMLVideoElement)) return false;
    return Math.max(0, Number(videoNode.videoWidth || 0)) > 0
      && Math.max(0, Number(videoNode.videoHeight || 0)) > 0;
  }

  function getDialogVideoDecodedFrameCount(videoNode = null) {
    if (!(videoNode instanceof HTMLVideoElement)) return 0;
    try {
      if (typeof videoNode.getVideoPlaybackQuality === 'function') {
        const quality = videoNode.getVideoPlaybackQuality();
        const frames = Math.max(0, Number(quality?.totalVideoFrames || 0));
        if (frames > 0) return frames;
      }
    } catch {
      // ignore unsupported playback quality APIs
    }
    return Math.max(0, Number(videoNode.webkitDecodedFrameCount || 0));
  }

  function getDialogVideoFrameVisibilityScore(videoNode = null) {
    if (!(videoNode instanceof HTMLVideoElement)) return null;
    if (!hasDialogVideoVisualTrack(videoNode)) return null;
    if (videoNode.readyState < 2) return null;
    try {
      const canvas = document.createElement('canvas');
      const sampleWidth = 36;
      const sampleHeight = 24;
      canvas.width = sampleWidth;
      canvas.height = sampleHeight;
      const context = canvas.getContext('2d', { alpha: false, willReadFrequently: true });
      if (!context) return null;
      context.drawImage(videoNode, 0, 0, sampleWidth, sampleHeight);
      const imageData = context.getImageData(0, 0, sampleWidth, sampleHeight);
      const pixels = imageData?.data instanceof Uint8ClampedArray ? imageData.data : null;
      if (!pixels || !pixels.length) return null;
      let sum = 0;
      let sumSquares = 0;
      let min = 255;
      let max = 0;
      let visiblePixels = 0;
      const pixelCount = Math.max(1, pixels.length / 4);
      for (let index = 0; index < pixels.length; index += 4) {
        const lightness = (pixels[index] * 0.2126) + (pixels[index + 1] * 0.7152) + (pixels[index + 2] * 0.0722);
        sum += lightness;
        sumSquares += lightness * lightness;
        min = Math.min(min, lightness);
        max = Math.max(max, lightness);
        if (lightness > 18) {
          visiblePixels += 1;
        }
      }
      const average = sum / pixelCount;
      const variance = Math.max(0, (sumSquares / pixelCount) - (average * average));
      return {
        average,
        contrast: max - min,
        variance,
        visibleRatio: visiblePixels / pixelCount
      };
    } catch {
      return null;
    }
  }

  function isDialogVideoFrameVisiblyBlank(videoNode = null) {
    const score = getDialogVideoFrameVisibilityScore(videoNode);
    if (!score) return false;
    return (
      score.average < 7
      && score.contrast < 18
      && score.variance < 18
      && score.visibleRatio < 0.006
    );
  }

  function getFavoritesResourceFileRef(sourceUrl = '') {
    const normalizedUrl = normalizeAssetUrl(sourceUrl || '', 8388608);
    if (!normalizedUrl) return null;
    try {
      const parsedUrl = new URL(normalizedUrl);
      if (parsedUrl.protocol !== 'yuchat-resource:') return null;
      if (String(parsedUrl.host || '').trim().toLowerCase() !== 'favorites') return null;
      const [fileId = '', fileName = ''] = parsedUrl.pathname
        .split('/')
        .filter(Boolean)
        .map((segment) => decodeURIComponent(segment));
      return {
        sourceUrl: normalizedUrl,
        fileId: String(fileId || '').trim(),
        fileName: cleanText(fileName || '', 180)
      };
    } catch {
      return null;
    }
  }

  function getDialogVideoViewerFavoritesSourceRef(videoNode = null) {
    const candidates = [
      state.dialogImageViewerDownloadUrl,
      state.dialogImageViewerSourceUrl,
      videoNode instanceof HTMLVideoElement ? videoNode.dataset.ycVideoOriginalSource : '',
      videoNode instanceof HTMLVideoElement ? videoNode.dataset.ycVideoSource : '',
      videoNode instanceof HTMLVideoElement ? videoNode.currentSrc : '',
      videoNode instanceof HTMLVideoElement ? videoNode.getAttribute('src') : '',
      state.dialogImageViewerUrl
    ];
    for (const candidate of candidates) {
      const ref = getFavoritesResourceFileRef(candidate || '');
      if (ref?.fileId && ref?.fileName) return ref;
    }
    return null;
  }

  function isBrowserNativePlayableVideoSource(sourceUrl = '', fileName = '', mimeType = '') {
    const normalizedMimeType = cleanText(mimeType || '', 140).toLowerCase().split(';')[0].trim();
    if (/^(?:video\/mp4|application\/mp4|video\/webm)$/i.test(normalizedMimeType)) return true;
    const hint = `${sourceUrl || ''} ${fileName || ''}`.toLowerCase();
    return /\.(?:mp4|m4v|webm)(?=$|[?#&\s])/i.test(hint);
  }

  function shouldTranscodeFavoritesVideoForViewer(favoritesRef = null) {
    if (!favoritesRef?.sourceUrl && !favoritesRef?.fileName) return false;
    const expectedMimeType = cleanText(
      state.dialogImageViewerExpectedMimeType
      || inferMimeTypeFromFileName(favoritesRef.fileName || '')
      || inferProtectedAssetMimeType(favoritesRef.sourceUrl || '', ''),
      140
    ).toLowerCase();
    return !isBrowserNativePlayableVideoSource(favoritesRef.sourceUrl || '', favoritesRef.fileName || '', expectedMimeType);
  }

  function requestPlayableFavoritesVideoForViewer(videoNode = null, reason = '') {
    if (state.dialogImageViewerOpen !== true || state.dialogImageViewerKind !== 'video') return false;
    const favoritesRef = getDialogVideoViewerFavoritesSourceRef(videoNode);
    if (!favoritesRef?.sourceUrl || !favoritesRef.fileId || !favoritesRef.fileName) return false;
    if (
      state.dialogImageViewerVideoRepairing === true
      && normalizeAssetUrl(state.dialogImageViewerVideoRepairSource || '', 8388608) === normalizeAssetUrl(favoritesRef.sourceUrl || '', 8388608)
    ) {
      return true;
    }
    if (
      normalizeAssetUrl(state.dialogImageViewerVideoRepairAttemptedSource || '', 8388608) === normalizeAssetUrl(favoritesRef.sourceUrl || '', 8388608)
    ) {
      return false;
    }
    state.dialogImageViewerVideoRepairing = true;
    state.dialogImageViewerVideoRepairSource = favoritesRef.sourceUrl;
    state.dialogImageViewerVideoRepairAttemptedSource = favoritesRef.sourceUrl;
    state.dialogImageViewerLoading = true;
    state.dialogImageViewerAutoplay = false;
    state.dialogImageViewerVideoUnavailable = false;
    state.dialogImageViewerVideoUnavailableReason = '';
    try {
      if (videoNode instanceof HTMLVideoElement) {
        videoNode.pause();
      }
    } catch {}
    showTemporaryStatus('Готовлю видео для просмотра…');
    scheduleRender('overlays');
    const shouldTranscode = shouldTranscodeFavoritesVideoForViewer(favoritesRef);
    const playableRequest = shouldTranscode
      ? ipcRenderer.invoke('yuchat-favorites-prepare-playable-video', {
        sourceUrl: favoritesRef.sourceUrl,
        fileId: favoritesRef.fileId,
        fileName: favoritesRef.fileName,
        mimeType: cleanText(state.dialogImageViewerExpectedMimeType || '', 140).toLowerCase(),
        reason: cleanText(reason || '', 180)
      })
      : fetchProtectedAssetObjectUrl(favoritesRef.sourceUrl, {
        fileId: state.dialogImageViewerFileId || favoritesRef.fileId,
        expectedMimeType: cleanText(state.dialogImageViewerExpectedMimeType || 'video/mp4', 140).toLowerCase() || 'video/mp4',
        forceObjectUrl: true,
        availabilityTimeoutMs: 12000
      });
    void playableRequest.then((result) => {
      if (state.dialogImageViewerOpen !== true || state.dialogImageViewerKind !== 'video') return;
      if (normalizeAssetUrl(state.dialogImageViewerVideoRepairSource || '', 8388608) !== normalizeAssetUrl(favoritesRef.sourceUrl || '', 8388608)) return;
      const playableUrl = normalizeAssetUrl(shouldTranscode ? result?.url : result, 8388608);
      if (playableUrl) {
        state.dialogImageViewerUrl = playableUrl;
        state.dialogImageViewerSourceUrl = shouldTranscode ? playableUrl : favoritesRef.sourceUrl;
        state.dialogImageViewerExpectedMimeType = 'video/mp4';
        state.dialogImageViewerPosterUrl = getCachedVideoPreviewImageUrl(favoritesRef.sourceUrl, favoritesRef.fileId) || '';
        state.dialogImageViewerAutoplay = true;
        state.dialogImageViewerLoading = false;
        state.dialogImageViewerVideoRepairing = false;
        state.dialogImageViewerVideoRepairSource = '';
        state.dialogImageViewerVideoUnavailable = false;
        state.dialogImageViewerVideoUnavailableReason = '';
        scheduleRender('overlays');
        void ensureVideoPreviewImageUrl(playableUrl, {
          fileId: favoritesRef.fileId,
          expectedMimeType: 'video/mp4'
        }).then((previewUrl) => {
          const normalizedPreviewUrl = normalizeAssetUrl(previewUrl || '', 8192);
          if (!normalizedPreviewUrl) return;
          if (state.dialogImageViewerOpen !== true || state.dialogImageViewerKind !== 'video') return;
          if (normalizeAssetUrl(state.dialogImageViewerSourceUrl || '', 8388608) !== normalizeAssetUrl(favoritesRef.sourceUrl || '', 8388608)) return;
          setCachedVideoPreviewImageUrl(favoritesRef.sourceUrl, normalizedPreviewUrl, favoritesRef.fileId);
          const activeVideoNode = refs.dialogPreviewList?.querySelector?.('.yc-dialog-image-viewer-video');
          if (
            activeVideoNode instanceof HTMLVideoElement
            && (!activeVideoNode.paused || Number(activeVideoNode.currentTime || 0) > 0.08)
          ) {
            activeVideoNode.setAttribute('poster', normalizedPreviewUrl);
            return;
          }
          state.dialogImageViewerPosterUrl = normalizedPreviewUrl;
          scheduleRender('overlays');
        }).catch(() => {});
        return;
      }
      state.dialogImageViewerVideoRepairing = false;
      state.dialogImageViewerVideoRepairSource = '';
      markDialogVideoViewerUnavailable(videoNode, reason || 'Видео не удалось подготовить для просмотра', {
        skipPlayableRepair: true
      });
    }).catch((error) => {
      if (state.dialogImageViewerOpen !== true || state.dialogImageViewerKind !== 'video') return;
      if (normalizeAssetUrl(state.dialogImageViewerVideoRepairSource || '', 8388608) !== normalizeAssetUrl(favoritesRef.sourceUrl || '', 8388608)) return;
      state.dialogImageViewerVideoRepairing = false;
      state.dialogImageViewerVideoRepairSource = '';
      markDialogVideoViewerUnavailable(videoNode, error?.message || reason || 'Видео не удалось подготовить для просмотра', {
        skipPlayableRepair: true
      });
    });
    return true;
  }

  function markDialogVideoViewerUnavailable(videoNode = null, reason = '', options = {}) {
    if (state.dialogImageViewerOpen !== true || state.dialogImageViewerKind !== 'video') return false;
    if (options?.skipPlayableRepair !== true && requestPlayableFavoritesVideoForViewer(videoNode, reason)) {
      return true;
    }
    const currentSource = normalizeAssetUrl(
      videoNode instanceof HTMLVideoElement
        ? (videoNode.dataset.ycVideoSource || videoNode.currentSrc || videoNode.getAttribute('src') || '')
        : '',
      8192
    );
    const expectedSource = normalizeAssetUrl(
      state.dialogImageViewerDownloadUrl
      || state.dialogImageViewerSourceUrl
      || state.dialogImageViewerUrl
      || '',
      8192
    );
    if (currentSource && expectedSource && currentSource !== expectedSource) {
      const currentResolved = normalizeAssetUrl(
        videoNode?.currentSrc || videoNode?.getAttribute?.('src') || '',
        8192
      );
      const expectedResolved = normalizeAssetUrl(runtime.attachmentObjectUrlBySource.get(expectedSource) || '', 8192);
      if (currentResolved && expectedResolved && currentResolved !== expectedResolved) {
        return false;
      }
    }
    stopDialogPreviewMedia({ releaseSource: true });
    state.dialogImageViewerLoading = false;
    state.dialogImageViewerAutoplay = false;
    state.dialogImageViewerVideoRepairing = false;
    state.dialogImageViewerVideoRepairSource = '';
    state.dialogImageViewerVideoUnavailable = true;
    state.dialogImageViewerVideoUnavailableReason = cleanText(reason || 'Видео не удалось показать в приложении', 180);
    scheduleRender('overlays');
    return true;
  }

  function scheduleDialogVideoVisualGuard(videoNode = null, options = {}) {
    if (!(videoNode instanceof HTMLVideoElement)) return;
    const delayMs = Math.max(120, Math.min(4000, Number(options?.delayMs) || 900));
    window.setTimeout(() => {
      if (!(videoNode instanceof HTMLVideoElement) || !videoNode.isConnected) return;
      if (state.dialogImageViewerOpen !== true || state.dialogImageViewerKind !== 'video') return;
      if (state.dialogImageViewerVideoUnavailable === true) return;
      if (hasDialogVideoVisualTrack(videoNode)) {
        const currentTime = Math.max(0, Number(videoNode.currentTime || 0));
        const decodedFrames = getDialogVideoDecodedFrameCount(videoNode);
        if ((!videoNode.paused || currentTime > 0.6) && currentTime > 0.6 && isDialogVideoFrameVisiblyBlank(videoNode)) {
          markDialogVideoViewerUnavailable(videoNode, 'Видео воспроизводится, но кадр остается черным');
          return;
        }
        if ((!videoNode.paused || currentTime > 0.6) && currentTime > 0.6 && decodedFrames <= 0) {
          markDialogVideoViewerUnavailable(videoNode, 'Видео воспроизводит звук, но кадры не декодируются');
        }
        return;
      }
      if (videoNode.readyState >= 1 || videoNode.error) {
        markDialogVideoViewerUnavailable(videoNode, 'Видео воспроизводит звук, но видеодорожка не декодируется');
      }
    }, delayMs);
  }

  function syncDialogVideoViewerState(videoNode = null, options = {}) {
    if (!(videoNode instanceof HTMLVideoElement)) return;
    if (!videoNode.classList.contains('yc-dialog-image-viewer-video')) return;
    if (state.dialogImageViewerOpen !== true || state.dialogImageViewerKind !== 'video') return;
    const videoWidth = Math.max(0, Number(videoNode.videoWidth || 0));
    const videoHeight = Math.max(0, Number(videoNode.videoHeight || 0));
    if (videoWidth > 0 && videoHeight > 0) {
      videoNode.style.setProperty('--yc-dialog-video-aspect', `${Math.round(videoWidth)} / ${Math.round(videoHeight)}`);
    } else if (videoNode.readyState >= 1) {
      scheduleDialogVideoVisualGuard(videoNode, { delayMs: 700 });
    }
    const currentSrc = normalizeAssetUrl(
      videoNode.currentSrc || videoNode.getAttribute('src') || '',
      8388608
    );
    const changed = currentSrc && normalizeAssetUrl(state.dialogImageViewerUrl || '', 8388608) !== currentSrc;
    if (!changed && state.dialogImageViewerLoading !== true && options.force !== true) {
      return;
    }
    if (currentSrc) {
      state.dialogImageViewerUrl = currentSrc;
    }
    state.dialogImageViewerLoading = false;
    scheduleRender('overlays');
  }

  function syncInlineVideoNotePlaybackUi(container = null) {
    if (!(container instanceof HTMLElement)) return;
    const stageNode = container.querySelector('.yc-video-note-stage');
    const videoNode = container.querySelector('.yc-video-note-preview-video');
    if (!(videoNode instanceof HTMLVideoElement)) return;
    const fallbackDuration = Math.max(0, Number(container.dataset.videoNoteDurationSeconds || 0));
    const liveDuration = Number.isFinite(videoNode.duration) && videoNode.duration > 0
      ? Math.max(0, Number(videoNode.duration || 0))
      : fallbackDuration;
    const currentTime = Math.max(0, Number(videoNode.currentTime || 0));
    const started = currentTime > 0.04;
    const isPlaying = !videoNode.paused && !videoNode.ended;
    const progressPercent = liveDuration > 0
      ? Math.max(0, Math.min(100, Math.round((currentTime / liveDuration) * 100)))
      : 0;
    const displaySeconds = currentTime > 0.08 ? currentTime : liveDuration;
    const timeNode = container.querySelector('[data-video-note-time]');
    container.classList.toggle('is-playing', isPlaying);
    container.classList.toggle('is-started', started || isPlaying);
    if (stageNode instanceof HTMLElement) {
      stageNode.style.setProperty('--yc-video-note-progress', String(progressPercent));
      stageNode.classList.toggle('is-started', started || isPlaying);
    }
    if (timeNode instanceof HTMLElement) {
      timeNode.textContent = formatCallDuration(displaySeconds);
    }
  }

  async function toggleInlineVideoNotePlayback(container = null) {
    if (!(container instanceof HTMLElement)) return false;
    const videoNode = container.querySelector('.yc-video-note-preview-video');
    if (!(videoNode instanceof HTMLVideoElement)) return false;
    if (!videoNode.paused && !videoNode.ended) {
      videoNode.pause();
      syncInlineVideoNotePlaybackUi(container);
      return true;
    }
    const resolved = await ensureVideoAttachmentSource(videoNode);
    if (!resolved) {
      syncInlineVideoNotePlaybackUi(container);
      showTemporaryStatus('Не удалось загрузить видеозаметку');
      return false;
    }
    document.querySelectorAll('.yc-video-note-preview-video, .yc-dialog-video-note-media').forEach((otherNode) => {
      if (!(otherNode instanceof HTMLVideoElement) || otherNode === videoNode) return;
      if (!otherNode.paused && !otherNode.ended) {
        otherNode.pause();
      }
    });
    document.querySelectorAll('.yc-voice-note-audio').forEach((otherNode) => {
      if (!(otherNode instanceof HTMLAudioElement)) return;
      if (!otherNode.paused && !otherNode.ended) {
        otherNode.pause();
      }
    });
    try {
      if (videoNode.ended) {
        videoNode.currentTime = 0;
      }
      videoNode.defaultMuted = true;
      videoNode.muted = true;
    } catch {}
    return videoNode.play().then(() => {
      syncInlineVideoNotePlaybackUi(container);
      return true;
    }).catch(() => {
      syncInlineVideoNotePlaybackUi(container);
      return false;
    });
  }

  function bindInlineVideoNotePreview(container = null) {
    if (!(container instanceof HTMLElement)) return;
    const videoNode = container.querySelector('.yc-video-note-preview-video');
    if (!(videoNode instanceof HTMLVideoElement)) return;
    if (container.dataset.ycVideoNoteBound === '1') return;
    container.dataset.ycVideoNoteBound = '1';
    const previewFileId = String(videoNode.dataset.ycVideoFileId || '').trim();
    const previewMimeType = cleanText(videoNode.dataset.ycVideoMime || '', 140).toLowerCase();

    const refreshPoster = (preferredSource = '') => {
      const previewSource = normalizeAssetUrl(
        preferredSource
        || videoNode.currentSrc
        || videoNode.getAttribute('src')
        || videoNode.dataset.ycVideoSource
        || '',
        8192
      );
      const canonicalSource = normalizeAssetUrl(videoNode.dataset.ycVideoSource || '', 8192);
      if (!previewSource) return;
      void ensureVideoPreviewImageUrl(previewSource, {
        fileId: previewFileId,
        expectedMimeType: previewMimeType
      }).then((previewUrl) => {
        if (!previewUrl || !container.isConnected) return;
        if (canonicalSource && canonicalSource !== previewSource) {
          setCachedVideoPreviewImageUrl(canonicalSource, previewUrl, previewFileId);
        }
        const applied = applyVideoNotePosterToStage(videoNode, previewUrl, {
          title: cleanText(videoNode.dataset.ycVideoTitle || '', 180)
        });
        if (applied) {
          syncInlineVideoNotePlaybackUi(container);
          stabilizeChatViewportAfterMediaLoad(videoNode);
        }
      }).catch(() => {});
    };

    const togglePlayback = (event = null) => {
      if (event) {
        event.preventDefault();
        event.stopPropagation();
      }
      void toggleInlineVideoNotePlayback(container);
    };

    container.querySelectorAll('[data-video-note-toggle]').forEach((toggleNode) => {
      if (!(toggleNode instanceof HTMLElement)) return;
      toggleNode.addEventListener('click', togglePlayback);
      toggleNode.addEventListener('keydown', (event) => {
        if (!(event instanceof KeyboardEvent)) return;
        if (event.key !== 'Enter' && event.key !== ' ') return;
        togglePlayback(event);
      });
    });

    videoNode.addEventListener('loadedmetadata', () => {
      const durationSeconds = Number.isFinite(videoNode.duration) && videoNode.duration > 0
        ? Math.max(0, Number(videoNode.duration || 0))
        : 0;
      if (durationSeconds > 0) {
        container.dataset.videoNoteDurationSeconds = String(Math.round(durationSeconds));
      }
      refreshPoster(videoNode.currentSrc || videoNode.getAttribute('src') || '');
      syncInlineVideoNotePlaybackUi(container);
      stabilizeChatViewportAfterMediaLoad(videoNode);
    });
    videoNode.addEventListener('loadeddata', () => {
      refreshPoster(videoNode.currentSrc || videoNode.getAttribute('src') || '');
      syncInlineVideoNotePlaybackUi(container);
      stabilizeChatViewportAfterMediaLoad(videoNode);
    });
    videoNode.addEventListener('canplay', () => {
      refreshPoster(videoNode.currentSrc || videoNode.getAttribute('src') || '');
      syncInlineVideoNotePlaybackUi(container);
    });
    videoNode.addEventListener('play', () => {
      syncInlineVideoNotePlaybackUi(container);
    });
    videoNode.addEventListener('pause', () => {
      syncInlineVideoNotePlaybackUi(container);
    });
    videoNode.addEventListener('timeupdate', () => {
      syncInlineVideoNotePlaybackUi(container);
    });
    videoNode.addEventListener('ended', () => {
      try {
        videoNode.currentTime = 0;
      } catch {}
      syncInlineVideoNotePlaybackUi(container);
    });
    videoNode.addEventListener('error', () => {
      void ensureVideoAttachmentSource(videoNode, { force: true }).then(() => {
        refreshPoster(videoNode.currentSrc || videoNode.getAttribute('src') || '');
        syncInlineVideoNotePlaybackUi(container);
      });
    });

    refreshPoster(videoNode.dataset.ycVideoSource || videoNode.getAttribute('src') || '');
    void ensureVideoAttachmentSource(videoNode).then((resolved) => {
      if (resolved) {
        try {
          videoNode.defaultMuted = true;
          videoNode.muted = true;
        } catch {}
        refreshPoster(videoNode.currentSrc || videoNode.getAttribute('src') || videoNode.dataset.ycVideoSource || '');
      }
      syncInlineVideoNotePlaybackUi(container);
    });
    syncInlineVideoNotePlaybackUi(container);
  }

  function syncDialogVideoNoteViewerUi(container = null) {
    if (!(container instanceof HTMLElement)) return;
    const videoNode = container.querySelector('.yc-dialog-video-note-media');
    if (!(videoNode instanceof HTMLVideoElement)) return;
    const fallbackDuration = Math.max(0, Number(container.dataset.dialogVideoNoteDurationSeconds || 0));
    const liveDuration = Number.isFinite(videoNode.duration) && videoNode.duration > 0
      ? Math.max(0, Number(videoNode.duration || 0))
      : fallbackDuration;
    const currentTime = Math.max(0, Number(videoNode.currentTime || 0));
    const started = currentTime > 0.04;
    const isPlaying = !videoNode.paused && !videoNode.ended;
    const progressPercent = liveDuration > 0
      ? Math.max(0, Math.min(100, Math.round((currentTime / liveDuration) * 100)))
      : 0;
    const displaySeconds = currentTime > 0.08 ? currentTime : liveDuration;
    const timeNode = container.querySelector('[data-dialog-video-note-time]');
    container.classList.toggle('is-playing', isPlaying);
    container.classList.toggle('is-started', started || isPlaying);
    container.style.setProperty('--yc-dialog-video-note-progress', String(progressPercent));
    if (timeNode instanceof HTMLElement) {
      timeNode.textContent = formatCallDuration(displaySeconds);
    }
  }

  async function toggleDialogVideoNoteViewerPlayback(container = null) {
    if (!(container instanceof HTMLElement)) return false;
    const videoNode = container.querySelector('.yc-dialog-video-note-media');
    if (!(videoNode instanceof HTMLVideoElement)) return false;
    if (!videoNode.paused && !videoNode.ended) {
      videoNode.pause();
      syncDialogVideoNoteViewerUi(container);
      return true;
    }
    const resolved = await ensureVideoAttachmentSource(videoNode);
    if (!resolved) {
      syncDialogVideoNoteViewerUi(container);
      showTemporaryStatus('Не удалось загрузить видеозаметку');
      return false;
    }
    try {
      if (videoNode.ended) {
        videoNode.currentTime = 0;
      }
    } catch {}
    return videoNode.play().then(() => {
      syncDialogVideoNoteViewerUi(container);
      return true;
    }).catch(() => {
      syncDialogVideoNoteViewerUi(container);
      return false;
    });
  }

  function bindDialogVideoNoteViewer(container = null) {
    if (!(container instanceof HTMLElement)) return;
    const videoNode = container.querySelector('.yc-dialog-video-note-media');
    if (!(videoNode instanceof HTMLVideoElement)) return;
    if (container.dataset.ycDialogVideoNoteBound === '1') return;
    container.dataset.ycDialogVideoNoteBound = '1';

    const togglePlayback = (event = null) => {
      if (event) {
        event.preventDefault();
        event.stopPropagation();
      }
      void toggleDialogVideoNoteViewerPlayback(container);
    };

    container.querySelectorAll('[data-dialog-video-note-toggle]').forEach((toggleNode) => {
      if (!(toggleNode instanceof HTMLElement)) return;
      toggleNode.addEventListener('click', togglePlayback);
      toggleNode.addEventListener('keydown', (event) => {
        if (!(event instanceof KeyboardEvent)) return;
        if (event.key !== 'Enter' && event.key !== ' ') return;
        togglePlayback(event);
      });
    });

    videoNode.addEventListener('loadedmetadata', () => {
      const durationSeconds = Number.isFinite(videoNode.duration) && videoNode.duration > 0
        ? Math.max(0, Number(videoNode.duration || 0))
        : 0;
      if (durationSeconds > 0) {
        container.dataset.dialogVideoNoteDurationSeconds = String(Math.round(durationSeconds));
      }
      refreshPoster(videoNode.currentSrc || videoNode.getAttribute('src') || '');
      syncDialogVideoViewerState(videoNode);
      syncDialogVideoNoteViewerUi(container);
      stabilizeChatViewportAfterMediaLoad(videoNode);
    });
    videoNode.addEventListener('loadeddata', () => {
      refreshPoster(videoNode.currentSrc || videoNode.getAttribute('src') || '');
      syncDialogVideoNoteViewerUi(container);
      stabilizeChatViewportAfterMediaLoad(videoNode);
    });
    videoNode.addEventListener('canplay', () => {
      refreshPoster(videoNode.currentSrc || videoNode.getAttribute('src') || '');
      syncDialogVideoViewerState(videoNode);
      syncDialogVideoNoteViewerUi(container);
    });
    videoNode.addEventListener('play', () => {
      syncDialogVideoNoteViewerUi(container);
    });
    videoNode.addEventListener('pause', () => {
      syncDialogVideoNoteViewerUi(container);
    });
    videoNode.addEventListener('timeupdate', () => {
      syncDialogVideoNoteViewerUi(container);
    });
    videoNode.addEventListener('ended', () => {
      try {
        videoNode.currentTime = 0;
      } catch {}
      syncDialogVideoNoteViewerUi(container);
    });
    videoNode.addEventListener('error', () => {
      void ensureVideoAttachmentSource(videoNode, { force: true }).then(() => {
        syncDialogVideoViewerState(videoNode);
        syncDialogVideoNoteViewerUi(container);
      });
    });

    const previewSource = normalizeAssetUrl(
      videoNode.dataset.ycVideoSource || videoNode.getAttribute('src') || '',
      8192
    );
    const previewFileId = String(videoNode.dataset.ycVideoFileId || '').trim();
    const previewMimeType = cleanText(videoNode.dataset.ycVideoMime || '', 140).toLowerCase();
    const refreshPoster = (preferredSource = '') => {
      const effectiveSource = normalizeAssetUrl(
        preferredSource
        || videoNode.currentSrc
        || videoNode.getAttribute('src')
        || videoNode.dataset.ycVideoSource
        || '',
        8192
      );
      const canonicalSource = normalizeAssetUrl(videoNode.dataset.ycVideoSource || '', 8192);
      if (!effectiveSource) return;
      void ensureVideoPreviewImageUrl(effectiveSource, {
        fileId: previewFileId,
        expectedMimeType: previewMimeType
      }).then((previewUrl) => {
        if (!previewUrl || !container.isConnected) return;
        if (canonicalSource && canonicalSource !== effectiveSource) {
          setCachedVideoPreviewImageUrl(canonicalSource, previewUrl, previewFileId);
        }
        applyVideoNotePosterToStage(videoNode, previewUrl, {
          title: cleanText(videoNode.dataset.ycVideoTitle || '', 180)
        });
        if (
          state.dialogImageViewerOpen === true
          && state.dialogImageViewerVariant === 'video_note'
          && normalizeAssetUrl(state.dialogImageViewerSourceUrl || '', 8192) === normalizeAssetUrl(canonicalSource || effectiveSource, 8192)
        ) {
          state.dialogImageViewerPosterUrl = normalizeAssetUrl(previewUrl, 8192);
        }
        syncDialogVideoNoteViewerUi(container);
      }).catch(() => {});
    };

    void ensureVideoAttachmentSource(videoNode).then(() => {
      refreshPoster(videoNode.currentSrc || videoNode.getAttribute('src') || videoNode.dataset.ycVideoSource || '');
      syncDialogVideoViewerState(videoNode);
      syncDialogVideoNoteViewerUi(container);
    });
    refreshPoster(previewSource);
    syncDialogVideoNoteViewerUi(container);
  }

  async function recoverBrokenAttachmentPreview(imageNode = null) {
    if (!(imageNode instanceof HTMLImageElement)) return;
    if (imageNode.dataset.ycAttachmentRecovering === '1' || imageNode.dataset.ycAttachmentRecovered === '1') {
      return;
    }

    const sourceUrl = normalizeAssetUrl(
      imageNode.dataset.ycAttachmentSource
      || imageNode.getAttribute('src')
      || imageNode.closest('a[href]')?.getAttribute('href')
      || '',
      8192
    );
    if (!sourceUrl || /^(data:image\/|blob:)/i.test(sourceUrl)) return;
    const fallbackFileId = String(
      imageNode.dataset.fileId
      || imageNode.closest('[data-image-preview-file-id]')?.dataset?.imagePreviewFileId
      || imageNode.closest('[data-download-file-id]')?.dataset?.downloadFileId
      || imageNode.closest('[data-open-file-id]')?.dataset?.openFileId
      || ''
    ).trim();

    imageNode.dataset.ycAttachmentRecovering = '1';
    try {
      const objectUrl = await fetchProtectedAssetObjectUrl(sourceUrl, {
        fileId: fallbackFileId,
        forceObjectUrl: /^yuchat-resource:/i.test(sourceUrl)
      });
      if (!objectUrl || objectUrl === sourceUrl) return;
      imageNode.dataset.ycAttachmentRecovered = '1';
      imageNode.src = objectUrl;
      const anchor = imageNode.closest('a[href]');
      if (anchor instanceof HTMLAnchorElement) {
        const currentHref = normalizeAssetUrl(anchor.getAttribute('href') || '', 8192);
        if (currentHref === sourceUrl) {
          anchor.setAttribute('href', objectUrl);
        }
      }
      syncDialogImageViewerImageState(imageNode, { force: true });
    } catch {
      // ignore preview recovery failures and keep the default broken-image state
    } finally {
      imageNode.dataset.ycAttachmentRecovering = '0';
    }
  }

  function disconnectAttachmentPreviewObserver() {
    const observer = runtime.attachmentPreviewObserver;
    if (observer && typeof observer.disconnect === 'function') {
      try {
        observer.disconnect();
      } catch {
        // ignore observer disconnect failures
      }
    }
    runtime.attachmentPreviewObserver = null;
  }

  function ensureAttachmentPreviewObserver() {
    if (runtime.attachmentPreviewObserver) {
      return runtime.attachmentPreviewObserver;
    }
    if (typeof window === 'undefined' || typeof window.IntersectionObserver !== 'function') {
      return null;
    }
    runtime.attachmentPreviewObserver = new window.IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry?.isIntersecting || !(entry.target instanceof HTMLImageElement)) return;
        const imageNode = entry.target;
        runtime.attachmentPreviewObserver?.unobserve(imageNode);
        imageNode.dataset.ycAttachmentVisible = '1';
        if (imageNode.complete && Number(imageNode.naturalWidth || 0) === 0) {
          void recoverBrokenAttachmentPreview(imageNode);
        }
      });
    }, {
      root: null,
      rootMargin: '900px 0px',
      threshold: 0.01
    });
    return runtime.attachmentPreviewObserver;
  }

  function syncVoiceAttachmentPlaybackUi(container = null) {
    if (!(container instanceof HTMLElement)) return;
    const audioNode = container.querySelector('.yc-voice-note-audio');
    const durationNode = container.querySelector('[data-voice-duration]');
    const waveformBars = Array.from(container.querySelectorAll('.yc-voice-waveform-bar'));
    if (!(audioNode instanceof HTMLAudioElement)) return;

    const fallbackDuration = Math.max(0, Number(container.dataset.voiceDurationSeconds || 0));
    const liveDuration = Number.isFinite(audioNode.duration) && audioNode.duration > 0
      ? Math.max(0, Number(audioNode.duration || 0))
      : fallbackDuration;
    const currentTime = Math.max(0, Number(audioNode.currentTime || 0));
    const isPlaying = !audioNode.paused && !audioNode.ended;
    const displaySeconds = currentTime > 0.05 ? currentTime : liveDuration;
    const progress = liveDuration > 0
      ? Math.max(0, Math.min(1, currentTime / liveDuration))
      : 0;

    container.classList.toggle('is-playing', isPlaying);
    container.style.setProperty('--yc-voice-progress', String(progress));
    waveformBars.forEach((barNode, index) => {
      if (!(barNode instanceof HTMLElement)) return;
      const threshold = (index + 0.35) / Math.max(1, waveformBars.length);
      barNode.classList.toggle('is-played', progress >= threshold);
    });
    if (durationNode instanceof HTMLElement) {
      durationNode.textContent = formatCallDuration(displaySeconds);
    }
  }

  function bindVoiceAttachmentPreview(container = null) {
    if (!(container instanceof HTMLElement)) return;
    const audioNode = container.querySelector('.yc-voice-note-audio');
    if (!(audioNode instanceof HTMLAudioElement)) return;
    if (container.dataset.ycVoiceBound === '1') return;
    container.dataset.ycVoiceBound = '1';

    const togglePlayback = async () => {
      if (!audioNode.paused && !audioNode.ended) {
        audioNode.pause();
        syncVoiceAttachmentPlaybackUi(container);
        return;
      }
      const hasPreparedSource = Boolean(normalizeAssetUrl(
        audioNode.getAttribute('src')
        || audioNode.currentSrc
        || '',
        8192
      ));
      const resolved = hasPreparedSource
        ? true
        : await ensureVoiceAttachmentAudioSource(audioNode);
      if (!resolved) {
        syncVoiceAttachmentPlaybackUi(container);
        showTemporaryStatus(container.dataset.audioNote === '1' ? 'Не удалось загрузить аудио' : 'Не удалось загрузить голосовое сообщение');
        return;
      }
      document.querySelectorAll('.yc-voice-note-audio').forEach((otherNode) => {
        if (!(otherNode instanceof HTMLAudioElement) || otherNode === audioNode) return;
        if (!otherNode.paused && !otherNode.ended) {
          otherNode.pause();
        }
      });
      document.querySelectorAll('.yc-video-note-preview-video, .yc-dialog-video-note-media').forEach((otherNode) => {
        if (!(otherNode instanceof HTMLVideoElement)) return;
        if (!otherNode.paused && !otherNode.ended) {
          otherNode.pause();
        }
      });
      void audioNode.play().then(() => {
        syncVoiceAttachmentPlaybackUi(container);
      }).catch(async () => {
        const refreshed = await ensureVoiceAttachmentAudioSource(audioNode, {
          force: true,
          relaxMime: true
        });
        if (refreshed) {
          try {
            await audioNode.play();
            syncVoiceAttachmentPlaybackUi(container);
            return;
          } catch {
            // fall through to user-facing error
          }
        }
        syncVoiceAttachmentPlaybackUi(container);
        showTemporaryStatus(container.dataset.audioNote === '1'
          ? 'Не удалось воспроизвести аудио'
          : 'Не удалось воспроизвести голосовое сообщение');
      });
    };

    container.querySelectorAll('[data-voice-toggle]').forEach((buttonNode) => {
      if (!(buttonNode instanceof HTMLElement)) return;
      buttonNode.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        togglePlayback();
      });
    });

    audioNode.addEventListener('loadedmetadata', () => {
      const durationSeconds = Number.isFinite(audioNode.duration) && audioNode.duration > 0
        ? Math.max(0, Number(audioNode.duration || 0))
        : 0;
      if (durationSeconds > 0) {
        container.dataset.voiceDurationSeconds = String(Math.round(durationSeconds));
      }
      syncVoiceAttachmentPlaybackUi(container);
      stabilizeChatViewportAfterMediaLoad(audioNode);
    });
    audioNode.addEventListener('play', () => {
      syncVoiceAttachmentPlaybackUi(container);
    });
    audioNode.addEventListener('pause', () => {
      syncVoiceAttachmentPlaybackUi(container);
    });
    audioNode.addEventListener('timeupdate', () => {
      syncVoiceAttachmentPlaybackUi(container);
    });
    audioNode.addEventListener('ended', () => {
      try {
        audioNode.currentTime = 0;
      } catch {}
      syncVoiceAttachmentPlaybackUi(container);
    });
    audioNode.addEventListener('error', () => {
      void ensureVoiceAttachmentAudioSource(audioNode, { force: true }).then(() => {
        syncVoiceAttachmentPlaybackUi(container);
      });
    });

    void ensureVoiceAttachmentAudioSource(audioNode);
    syncVoiceAttachmentPlaybackUi(container);
  }

  function hydrateAttachmentPreviews(scope = null) {
    if (!(scope instanceof HTMLElement || scope instanceof DocumentFragment)) return;
    const previewNodes = Array.from(scope.querySelectorAll(
      'img.yc-message-attachment-preview:not([data-yc-attachment-bound="1"]), img.yc-attachment-thumb:not([data-yc-attachment-bound="1"]), img.yc-dialog-image-viewer-image:not([data-yc-attachment-bound="1"]), img.yc-video-note-preview:not([data-yc-attachment-bound="1"]), img.yc-dialog-video-note-poster:not([data-yc-attachment-bound="1"])'
    ));
    const previewObserver = ensureAttachmentPreviewObserver();
    previewNodes.forEach((imageNode) => {
      if (!(imageNode instanceof HTMLImageElement)) return;
      if (!imageNode.dataset.ycAttachmentSource) {
        const sourceUrl = normalizeAssetUrl(
          imageNode.getAttribute('src')
          || imageNode.closest('a[href]')?.getAttribute('href')
          || '',
          8192
        );
        if (sourceUrl) {
          imageNode.dataset.ycAttachmentSource = sourceUrl;
        }
      }
      if (imageNode.dataset.ycAttachmentBound === '1') return;
      imageNode.dataset.ycAttachmentBound = '1';
      imageNode.addEventListener('load', () => {
        previewObserver?.unobserve(imageNode);
        stabilizeChatViewportAfterMediaLoad(imageNode);
        syncDialogImageViewerImageState(imageNode);
      });
      imageNode.addEventListener('error', () => {
        previewObserver?.unobserve(imageNode);
        void recoverBrokenAttachmentPreview(imageNode);
      });
      if (previewObserver) {
        previewObserver.observe(imageNode);
      } else if (imageNode.complete && Number(imageNode.naturalWidth || 0) === 0) {
        void recoverBrokenAttachmentPreview(imageNode);
      }
      const insidePreviewOverlay = Boolean(imageNode.closest('.yc-dialog-preview-body'));
      if (insidePreviewOverlay) {
        void recoverBrokenAttachmentPreview(imageNode);
      }
    });

    const videoNodes = Array.from(scope.querySelectorAll(
      'video.yc-message-attachment-media.is-video:not([data-yc-attachment-bound="1"]), video.yc-dialog-image-viewer-video:not([data-yc-attachment-bound="1"])'
    ));
    videoNodes.forEach((videoNode) => {
      if (!(videoNode instanceof HTMLVideoElement)) return;
      if (videoNode.dataset.ycAttachmentBound === '1') return;
      if (!videoNode.dataset.ycVideoSource) {
        const sourceUrl = normalizeAssetUrl(
          videoNode.getAttribute('src')
          || videoNode.currentSrc
          || '',
          8192
        );
        if (sourceUrl) {
          videoNode.dataset.ycVideoSource = sourceUrl;
        }
      }
      videoNode.dataset.ycAttachmentBound = '1';
      videoNode.addEventListener('loadedmetadata', () => {
        stabilizeChatViewportAfterMediaLoad(videoNode);
        syncDialogVideoViewerState(videoNode);
      });
      videoNode.addEventListener('loadeddata', () => {
        stabilizeChatViewportAfterMediaLoad(videoNode);
      });
      videoNode.addEventListener('canplay', () => {
        syncDialogVideoViewerState(videoNode);
      });
      videoNode.addEventListener('error', () => {
        void ensureVideoAttachmentSource(videoNode, { force: true }).then((resolved) => {
          if (!resolved) {
            syncDialogVideoViewerState(videoNode);
          }
        });
      });
      const insideVideoPreviewStage = Boolean(videoNode.closest('.yc-video-note-stage, .yc-inline-video-preview-stage'));
      if (insideVideoPreviewStage) {
        const previewSource = normalizeAssetUrl(
          videoNode.dataset.ycVideoSource || videoNode.getAttribute('src') || '',
          8192
        );
        const previewFileId = String(videoNode.dataset.ycVideoFileId || '').trim();
        const previewMimeType = cleanText(videoNode.dataset.ycVideoMime || '', 140).toLowerCase();
        void ensureVideoPreviewImageUrl(previewSource, {
          fileId: previewFileId,
          expectedMimeType: previewMimeType
        }).then((previewUrl) => {
          if (!previewUrl || !videoNode.isConnected) return;
          const applied = applyVideoNotePosterToStage(videoNode, previewUrl, {
            title: cleanText(videoNode.dataset.ycVideoTitle || '', 180)
          });
          if (applied) {
            stabilizeChatViewportAfterMediaLoad(videoNode);
          }
        }).catch(() => {});
      }
      if (videoNode.classList.contains('yc-dialog-image-viewer-video')) {
        void ensureVideoAttachmentSource(videoNode).then((resolved) => {
          if (!resolved) {
            syncDialogVideoViewerState(videoNode);
          }
        });
      }
    });

    const inlineVideoNoteNodes = Array.from(scope.querySelectorAll(
      '.yc-video-note-message[data-inline-video-note="1"]:not([data-yc-video-note-bound="1"])'
    ));
    inlineVideoNoteNodes.forEach((videoNoteNode) => {
      if (!(videoNoteNode instanceof HTMLElement)) return;
      bindInlineVideoNotePreview(videoNoteNode);
    });

    const dialogVideoNoteViewers = Array.from(scope.querySelectorAll(
      '.yc-dialog-video-note-viewer:not([data-yc-dialog-video-note-bound="1"])'
    ));
    dialogVideoNoteViewers.forEach((viewerNode) => {
      if (!(viewerNode instanceof HTMLElement)) return;
      bindDialogVideoNoteViewer(viewerNode);
    });

    const voiceNodes = Array.from(scope.querySelectorAll(
      '.yc-message-attachment-card.is-voice[data-voice-note="1"]:not([data-yc-voice-bound="1"]), .yc-message-attachment-card.is-audio[data-audio-note="1"]:not([data-yc-voice-bound="1"])'
    ));
    voiceNodes.forEach((voiceNode) => {
      if (!(voiceNode instanceof HTMLElement)) return;
      bindVoiceAttachmentPreview(voiceNode);
    });
  }

  function resolveRecentSortPriority(entry = null) {
    return Math.max(0, Number(entry?.sortPriority || 0));
  }

  function resolveRecentSidebarUnreadCount(entry = null) {
    if (!entry || typeof entry !== 'object') return 0;
    const unreadCount = resolveEntryUnreadCount(entry);
    if (entry.isThread === true) {
      return unreadCount;
    }
    return Math.max(
      unreadCount,
      getThreadUnreadCountForParentChat(entry.workspaceId, entry.chatId)
    );
  }

  function resolveRecentOrderingTimestamp(entry = null) {
    return Math.max(
      resolveRecentSortPriority(entry),
      Number(entry?.previewTimestamp || 0),
      Number(entry?.updatedAt || 0)
    );
  }

  function resolveRecentTopShelfPriority(entry = null) {
    const sortPriority = resolveRecentSortPriority(entry);
    const unreadCount = Math.max(0, resolveRecentSidebarUnreadCount(entry));
    if (sortPriority <= 0 && unreadCount <= 0) return 0;
    return Math.max(
      sortPriority,
      Number(entry?.previewTimestamp || 0),
      Number(entry?.updatedAt || 0),
      unreadCount > 0 ? 1 : 0
    );
  }

  function sumRecentSidebarUnreadCounts(entries = []) {
    return (Array.isArray(entries) ? entries : []).reduce((sum, entry) => (
      sum + Math.max(0, resolveRecentSidebarUnreadCount(entry))
    ), 0);
  }

  function compareRecentEntries(left = null, right = null) {
    const leftPinned = left?.pinnedAt ? 1 : 0;
    const rightPinned = right?.pinnedAt ? 1 : 0;
    if (rightPinned !== leftPinned) return rightPinned - leftPinned;

    const timeDiff = resolveRecentOrderingTimestamp(right) - resolveRecentOrderingTimestamp(left);
    if (timeDiff) return timeDiff;

    // Keep equal-time rows stable when a chat is opened.
    // Opening a dialog clears unread/attention flags, but that should not move the row away
    // from the place the user clicked in the sidebar.
    return cleanText(left?.title || '', 120).localeCompare(cleanText(right?.title || '', 120), 'ru');
  }

  function sortRecentEntries(entries = []) {
    return entries.slice().sort((left, right) => compareRecentEntries(left, right));
  }

  function sanitizeRecentEntry(entry = null) {
    if (!entry || typeof entry !== 'object') return null;

    const workspaceId = String(entry.workspaceId || '').trim();
    const chatId = normalizeChatId(entry.chatId || '');
    if (!workspaceId || !chatId) return null;

    const updatedAt = Math.max(0, Number(entry.updatedAt || 0));
    const previewTimestamp = Math.max(
      0,
      Number(entry.previewTimestamp || 0),
      updatedAt
    );
    const unreadCount = resolveEntryUnreadCount(entry);
    const readSuppressed = isReadBadgeSuppressed(workspaceId, chatId);
    const storedMentionFlag = getStoredMentionFlag(workspaceId, chatId);
    const storedReactionFlag = getStoredReactionOnMineFlag(workspaceId, chatId);
    const unreadMentionsCount = Math.max(0, Math.trunc(Number(
      entry.unreadMentionsCount
      ?? entry.unreadMentionCount
      ?? entry.unread_mentions_count
      ?? entry.rawChat?.unreadMentionsCount
      ?? entry.rawChat?.unreadMentionCount
      ?? entry.rawChat?.unread_mentions_count
      ?? entry.chat?.unreadMentionsCount
      ?? entry.chat?.unreadMentionCount
      ?? entry.chat?.unread_mentions_count
      ?? 0
    ) || 0));
    const unreadReactionsCount = Math.max(0, Math.trunc(Number(
      entry.unreadReactionsCount
      ?? entry.unreadReactionCount
      ?? entry.unread_reactions_count
      ?? entry.rawChat?.unreadReactionsCount
      ?? entry.rawChat?.unreadReactionCount
      ?? entry.rawChat?.unread_reactions_count
      ?? entry.chat?.unreadReactionsCount
      ?? entry.chat?.unreadReactionCount
      ?? entry.chat?.unread_reactions_count
      ?? 0
    ) || 0));
    const derivedMentionFlag = (
      resolveRealtimeMentionFlagFromBadge(entry)
      ?? resolveRealtimeMentionFlagFromBadge(entry?.rawChat || null)
      ?? resolveRealtimeMentionFlagFromBadge(entry?.chat || null)
      ?? null
    );
    const derivedReactionFlag = (
      resolveRealtimeReactionFlagFromBadge(entry)
      ?? resolveRealtimeReactionFlagFromBadge(entry?.rawChat || null)
      ?? resolveRealtimeReactionFlagFromBadge(entry?.chat || null)
      ?? null
    );
    const hasExplicitMentionFlag = Object.prototype.hasOwnProperty.call(entry || {}, 'mentionedMe');
    const hasExplicitReactionFlag = Object.prototype.hasOwnProperty.call(entry || {}, 'reactionOnMine');
    const workspaceMemberId = String(
      entry.workspaceMemberId
      || state.workspaceMemberIdByWorkspace?.[workspaceId]
      || getCurrentWorkspaceMemberId()
      || ''
    ).trim();
    const directMemberIdFromEntry = String(entry.directMemberId || '').trim();
    const directMemberIdFromChatId = String(chatId.match(/^p:(.+)$/i)?.[1] || '').trim();
    const directMemberIdFromRaw = String(resolveDirectMemberId(
      entry?.rawChat && typeof entry.rawChat === 'object' ? entry.rawChat : entry,
      workspaceMemberId,
      entry
    ) || '').trim();
    let directMemberIdCandidate = [
      directMemberIdFromEntry,
      directMemberIdFromChatId,
      directMemberIdFromRaw
    ].find((memberId) => hasUsableDirectMemberId(memberId, workspaceMemberId)) || '';
    if (!directMemberIdCandidate) {
      const contactFallbackEntryForMember = findBestCachedContactEntryForProfileResolution(entry, {
        workspaceId,
        chatId,
        title: cleanText(entry?.title || '', 180)
      });
      const contactFallbackMemberId = String(
        contactFallbackEntryForMember?.directMemberId
        || resolveDirectTargetMemberId(contactFallbackEntryForMember)
        || ''
      ).trim();
      if (hasUsableDirectMemberId(contactFallbackMemberId, workspaceMemberId)) {
        directMemberIdCandidate = contactFallbackMemberId;
      }
    }
    const hasWorkspaceChannelMeta = hasWorkspaceChannelMetadata(entry) || hasWorkspaceChannelMetadata(entry.rawChat);
    const isUserEventsChat = isUserEventsChatEntry(entry);
    const hasDirectMemberId = hasUsableDirectMemberId(directMemberIdCandidate, workspaceMemberId);
    const memberCount = Array.isArray(entry.memberIds) ? entry.memberIds.filter(Boolean).length : 0;
    const isTelegramEntry = entry.isTelegram === true || isTelegramConversationChat(workspaceId, chatId);
    const isTrueconfEntry = entry.isTrueconf === true || isTrueconfConversationChat(workspaceId, chatId);
    const isMaxEntry = entry.isMax === true || isMaxConversationChat(workspaceId, chatId);
    const telegramEntryForType = {
      ...entry,
      workspaceId,
      chatId
    };
    const telegramDialogType = getTelegramDialogType(telegramEntryForType);
    const isTelegramDirect = isTelegramEntry && (
      telegramDialogType === 'direct'
      || (!telegramDialogType && hasTelegramDirectDialogEvidence(telegramEntryForType))
    );
    const isMaxDirect = isMaxEntry && (
      normalizeTelegramDialogTypeValue(entry.maxType || entry.type || entry.rawChat?.maxType || entry.rawChat?.type || '') === 'direct'
      || /^max:/i.test(cleanText(entry.directMemberId || entry.rawChat?.directMemberId || '', 180))
    );
    const isTrueconfDirect = isTrueconfEntry && (
      normalizeTelegramDialogTypeValue(entry.trueconfType || entry.type || entry.rawChat?.trueconfType || entry.rawChat?.type || '') === 'direct'
      || /^trueconf:/i.test(cleanText(entry.directMemberId || entry.rawChat?.directMemberId || '', 180))
    );
    let isDirect = false;
    if (isTelegramEntry) {
      isDirect = isTelegramDirect;
    } else if (isTrueconfEntry) {
      isDirect = isTrueconfDirect;
    } else if (isMaxEntry) {
      isDirect = isMaxDirect;
    } else {
      isDirect = !hasWorkspaceChannelMeta && Boolean(
        !isUserEventsChat
        && (
          entry.isDirect === true
          || hasPersonalChatMetadata(entry)
          || hasPersonalChatMetadata(entry.rawChat)
          || /^p:/i.test(chatId)
          || (
            hasDirectMemberId
            && memberCount <= 2
            && !/^(t|thread):/i.test(chatId)
            && !/^c:/i.test(chatId)
          )
        )
      );
    }
    const directMemberId = isDirect && hasDirectMemberId ? directMemberIdCandidate : '';
    const directProfile = directMemberId
      ? getKnownProfileByMemberId(directMemberId)
      : null;
    const contactFallbackEntry = isDirect
      ? findBestCachedContactEntryForProfileResolution(entry, {
        workspaceId,
        chatId,
        directMemberId,
        title: cleanText(entry?.title || '', 180)
      })
      : null;
    const contactFallbackProfile = getProfileFromCachedContactEntry(contactFallbackEntry);
    const avatarOverrideUrl = directMemberId
      ? getCustomAvatarOverrideUrl(directMemberId)
      : '';
    const channelAvatarOverrideUrl = !isDirect
      ? getCustomChannelAvatarOverrideUrl(workspaceId, chatId)
      : '';
    const localTitleOverride = resolveLocalEntryTitleOverride(entry, {
      workspaceId,
      chatId,
      directMemberId
    });
    const resolvedTitle = cleanText(
      localTitleOverride
      || resolveChatTitle(
        entry?.rawChat && typeof entry.rawChat === 'object' ? entry.rawChat : entry,
        entry,
        workspaceMemberId
      )
      || entry?.title
      || 'Чат',
      180
    ) || 'Чат';
    const resolvedDirectProfile = isDirect
      ? (
        directProfile
        || contactFallbackProfile
        || resolvePersonProfileForEntry(entry, {
          directMemberId,
          selfMemberId: workspaceMemberId,
          contactEntry: contactFallbackEntry,
          title: resolvedTitle
        })
      )
      : null;
    const resolvedDirectAvatarUrl = normalizeAssetUrl(getProfileAvatarUrl(resolvedDirectProfile) || '', 2097152);
    const fallbackEntryAvatarUrl = normalizeAssetUrl(
      isTelegramEntry && !isTelegramDirect
        ? (
          entry.rawChat?.avatarUrl
          || entry.rawChat?.avatarResourceUrl
          || entry.avatarResourceUrl
          || entry.avatarUrl
          || ''
        )
        : (entry.avatarUrl || ''),
      2097152
    );
    const selfProfileForAvatar = workspaceMemberId
      ? getKnownProfileByMemberId(workspaceMemberId)
      : getCurrentProfile();
    const selfAvatarUrl = normalizeAssetUrl(getProfileAvatarUrl(selfProfileForAvatar) || '', 2097152);
    const fallbackAvatarId = extractAvatarIdFromUrl(fallbackEntryAvatarUrl);
    const selfAvatarId = extractAvatarIdFromUrl(selfAvatarUrl);
    const previewAuthorMemberId = String(entry.previewAuthorMemberId || '').trim();
    const previewAuthorIsSelf = Boolean(
      workspaceMemberId
      && previewAuthorMemberId
      && areMemberIdentitiesEquivalent(previewAuthorMemberId, workspaceMemberId)
    );
    const selfTitle = cleanText(getProfileDisplayName(selfProfileForAvatar) || '', 180).toLowerCase();
    const resolvedTitleLooksLikeSelf = Boolean(
      selfTitle
      && cleanText(resolvedTitle || '', 180).toLowerCase() === selfTitle
    );
    const fallbackLooksLikeOwnPreviewAvatar = Boolean(
      fallbackEntryAvatarUrl
      && !hasWorkspaceChannelMeta
      && (entry.previewIsMine === true || previewAuthorIsSelf)
    );
    const fallbackLooksLikeForeignSelfAvatar = Boolean(
      fallbackEntryAvatarUrl
      && selfAvatarUrl
      && !resolvedTitleLooksLikeSelf
      && !(directMemberId && areMemberIdentitiesEquivalent(directMemberId, workspaceMemberId))
      && (
        (fallbackAvatarId && selfAvatarId && fallbackAvatarId === selfAvatarId)
        || fallbackEntryAvatarUrl === selfAvatarUrl
      )
    );
    const shouldSuppressFallbackAvatar = Boolean(
      (isDirect || fallbackLooksLikeOwnPreviewAvatar || fallbackLooksLikeForeignSelfAvatar)
      && !(isTelegramEntry && fallbackEntryAvatarUrl && !fallbackLooksLikeForeignSelfAvatar)
    );
    const sanitizedAvatarUrl = (
      channelAvatarOverrideUrl
      || avatarOverrideUrl
      || resolvedDirectAvatarUrl
      || (shouldSuppressFallbackAvatar ? '' : fallbackEntryAvatarUrl)
    );

    const sanitizedEntry = {
      ...entry,
      workspaceId,
      workspaceMemberId,
      workspaceTitle: cleanText(entry.workspaceTitle || '', 140),
      chatId,
      title: resolvedTitle,
      searchText: cleanText(entry.searchText || '', (isTelegramEntry || isTrueconfEntry || isMaxEntry) ? 720 : 360),
      avatarUrl: sanitizedAvatarUrl,
      directMemberId,
      isDirect: isDirect || isTelegramDirect || isTrueconfDirect,
      isTelegram: isTelegramEntry || entry.isTelegram === true,
      isTrueconf: isTrueconfEntry || entry.isTrueconf === true,
      isMax: isMaxEntry || entry.isMax === true,
      telegramType: telegramDialogType || cleanText(entry.telegramType || entry.type || '', 40),
      trueconfType: cleanText(entry.trueconfType || (isTrueconfEntry ? entry.type || entry.rawChat?.trueconfType || '' : ''), 40),
      maxType: cleanText(entry.maxType || (isMaxEntry ? entry.type || entry.rawChat?.maxType || '' : ''), 40),
      sourceLabel: cleanText(entry.sourceLabel || (isTelegramEntry ? 'Телеграм' : (isTrueconfEntry ? 'TrueConf' : (isMaxEntry ? 'MAX' : ''))), 40),
      avatarResourceUrl: normalizeAssetUrl(entry.avatarResourceUrl || entry.rawChat?.avatarResourceUrl || '', 4096),
      username: cleanText(entry.username || entry.rawChat?.username || '', 120),
      phone: cleanText(entry.phone || entry.rawChat?.phone || '', 80),
      statusText: cleanText(entry.statusText || entry.rawChat?.statusText || '', 120),
      statusKind: cleanText(entry.statusKind || entry.rawChat?.statusKind || '', 120),
      isThread: entry.isThread === true,
      threadParentChatId: normalizeChatId(entry.threadParentChatId || ''),
      memberIds: Array.isArray(entry.memberIds)
        ? entry.memberIds.map((memberId) => String(memberId || '').trim()).filter(Boolean).slice(0, 300)
        : [],
      sortPriority: unreadCount > 0
        ? Math.max(resolveRecentSortPriority(entry), previewTimestamp, updatedAt)
        : resolveRecentSortPriority(entry),
      pinnedAt: String(entry.pinnedAt || '').trim(),
      updatedAt,
      unreadCount,
      unreadMentionsCount,
      unreadReactionsCount,
      previewText: cleanText(entry.previewText || '', 200),
      previewAuthor: cleanText(entry.previewAuthor || '', 100),
      previewAuthorMemberId: String(entry.previewAuthorMemberId || '').trim(),
      previewAuthorAvatarResourceUrl: normalizeAssetUrl(entry.previewAuthorAvatarResourceUrl || entry.rawChat?.previewAuthorAvatarResourceUrl || '', 4096),
      previewAuthorAvatarUrl: resolveSafePreviewAuthorAvatarUrl({
        ...entry,
        workspaceId,
        workspaceMemberId,
        previewAuthor: cleanText(entry.previewAuthor || '', 100),
        previewAuthorMemberId: String(entry.previewAuthorMemberId || '').trim()
      }),
      previewMessageId: String(entry.previewMessageId || '').trim(),
      previewIsMine: entry.previewIsMine === true,
      previewDeliveryStatus: normalizeDeliveryStatus(entry.previewDeliveryStatus || entry.deliveryStatus || ''),
      readInboxMaxId: Math.max(0, Math.trunc(Number(entry.readInboxMaxId || entry.read_inbox_max_id || entry.rawChat?.readInboxMaxId || entry.rawChat?.read_inbox_max_id || 0) || 0)),
      readOutboxMaxId: Math.max(0, Math.trunc(Number(entry.readOutboxMaxId || entry.read_outbox_max_id || entry.rawChat?.readOutboxMaxId || entry.rawChat?.read_outbox_max_id || 0) || 0)),
      previewTimestamp,
      previewAttachment: cleanText(entry.previewAttachment || '', 100),
      previewIsSystem: entry.previewIsSystem === true,
      previewReactions: sanitizeReactionPreviewList(entry.previewReactions || entry.reactions || [], 4),
      notifySettings: sanitizeNotifySettings(entry.notifySettings || entry.notificationSettings || {}),
      isMuted: Boolean(entry.isMuted || sanitizeNotifySettings(entry.notifySettings || entry.notificationSettings || {}).isMuted),
      // Stored attention flags must win over stale cached snapshots that still carry explicit false.
      mentionedMe: readSuppressed
        ? false
        : ((hasExplicitMentionFlag && entry.mentionedMe === true) || unreadMentionsCount > 0 || storedMentionFlag === true || derivedMentionFlag === true),
      reactionOnMine: readSuppressed
        ? false
        : ((hasExplicitReactionFlag && entry.reactionOnMine === true) || unreadReactionsCount > 0 || storedReactionFlag === true || derivedReactionFlag === true)
    };
    const derivedAttention = getRecentEntryAttentionState(sanitizedEntry);
    if (derivedAttention.hasMentionAttention) {
      sanitizedEntry.mentionedMe = true;
    }
    if (derivedAttention.hasReactionAttention) {
      sanitizedEntry.reactionOnMine = true;
    }
    return sanitizedEntry;
  }

  function sanitizeRecentCollection(entries = []) {
    return sortRecentEntries(
      dedupeRecentEntries(
        (Array.isArray(entries) ? entries : [])
          .map((entry) => sanitizeRecentEntry(entry))
          .filter(Boolean)
      )
    );
  }

  function replaceWorkspaceRecents(workspaceId = '', entries = [], options = {}) {
    const ws = String(workspaceId || '').trim();
    if (!ws) return [];
    const previousEntries = Array.isArray(state.recentsByWorkspace?.[ws])
      ? state.recentsByWorkspace[ws]
      : [];
    const previousByChatId = new Map(
      previousEntries.map((entry) => [normalizeChatId(entry?.chatId || ''), entry]).filter(([chatId]) => Boolean(chatId))
    );
    const mergedEntries = (Array.isArray(entries) ? entries : []).map((entry) => {
      const chatId = normalizeChatId(entry?.chatId || '');
      const previousEntry = chatId ? previousByChatId.get(chatId) || null : null;
      if (!previousEntry) {
        return entry;
      }
      const nextSourceMember = entry?.sourceMember && typeof entry.sourceMember === 'object'
        ? entry.sourceMember
        : null;
      const previousSourceMember = previousEntry?.sourceMember && typeof previousEntry.sourceMember === 'object'
        ? previousEntry.sourceMember
        : null;
      const resolvedSourceMember = hasRenderableProfileIdentity(nextSourceMember)
        ? nextSourceMember
        : (
          hasRenderableProfileIdentity(previousSourceMember)
            ? previousSourceMember
            : (nextSourceMember || previousSourceMember || null)
        );
      const nextDirectMemberId = String(entry?.directMemberId || '').trim();
      const previousDirectMemberId = String(previousEntry?.directMemberId || '').trim();
      const resolvedDirectMemberId = nextDirectMemberId || previousDirectMemberId;
      const nextAvatarUrl = normalizeAssetUrl(entry?.avatarUrl || '', 2097152);
      const previousAvatarUrl = normalizeAssetUrl(previousEntry?.avatarUrl || '', 2097152);
      const resolvedAvatarUrl = nextAvatarUrl || previousAvatarUrl;
      const nextTitle = cleanText(entry?.title || '', 180);
      const previousTitle = cleanText(previousEntry?.title || '', 180);
      const resolvedIsDirect = entry?.isDirect === true || previousEntry?.isDirect === true;
      const preservePreviousTitle = Boolean(
        resolvedIsDirect
        && previousTitle
        && (
          !nextTitle
          || isSyntheticDirectChatTitle(nextTitle)
          || isLikelyOpaqueMemberIdentityValue(nextTitle)
        )
      );
      const nextPreviewText = cleanText(entry?.previewText || '', 200);
      const previousPreviewText = cleanText(previousEntry?.previewText || '', 200);
      const preservePreviousPreviewText = Boolean(
        entry?.previewIsSystem === true
        && previousPreviewText
        && previousEntry?.previewIsSystem !== true
      );
      const nextPreviewAuthor = cleanText(entry?.previewAuthor || '', 100);
      const previousPreviewAuthor = cleanText(previousEntry?.previewAuthor || '', 100);
      const preservePreviousPreviewAuthor = Boolean(
        preservePreviousPreviewText
        || (
        previousPreviewAuthor
        && (
          !nextPreviewAuthor
          || isLikelyOpaqueMemberIdentityValue(nextPreviewAuthor)
        )
        && !isLikelyOpaqueMemberIdentityValue(previousPreviewAuthor)
        )
      );
      const nextPreviewAuthorMemberId = String(entry?.previewAuthorMemberId || '').trim();
      const previousPreviewAuthorMemberId = String(previousEntry?.previewAuthorMemberId || '').trim();
      const nextPreviewAuthorAvatarUrl = normalizeAssetUrl(entry?.previewAuthorAvatarUrl || '', 4096);
      const previousPreviewAuthorAvatarUrl = normalizeAssetUrl(previousEntry?.previewAuthorAvatarUrl || '', 4096);
      const previewAuthorsEquivalent = Boolean(
        nextPreviewAuthorMemberId
        && previousPreviewAuthorMemberId
        && areMemberIdentitiesEquivalent(nextPreviewAuthorMemberId, previousPreviewAuthorMemberId)
      ) || (
        !nextPreviewAuthorMemberId
        && !previousPreviewAuthorMemberId
        && nextPreviewAuthor
        && previousPreviewAuthor
        && normalizeText(nextPreviewAuthor) === normalizeText(previousPreviewAuthor)
      );
      const resolvedPreviewAuthorMemberId = preservePreviousPreviewAuthor
        ? (previousPreviewAuthorMemberId || nextPreviewAuthorMemberId)
        : (
          nextPreviewAuthorMemberId
          || (previewAuthorsEquivalent ? previousPreviewAuthorMemberId : '')
        );
      const resolvedPreviewAuthorAvatarUrl = normalizeAssetUrl(
        preservePreviousPreviewAuthor
          ? (previousPreviewAuthorAvatarUrl || nextPreviewAuthorAvatarUrl || '')
          : (
            nextPreviewAuthorAvatarUrl
            || (previewAuthorsEquivalent ? previousPreviewAuthorAvatarUrl : '')
            || ''
          ),
        4096
      );
      const mergedMemberIds = Array.from(new Set([
        ...(Array.isArray(entry?.memberIds) ? entry.memberIds : []),
        ...(Array.isArray(previousEntry?.memberIds) ? previousEntry.memberIds : [])
      ].map((memberId) => String(memberId || '').trim()).filter(Boolean)));
      const mergedSearchText = cleanText([
        entry?.searchText || '',
        previousEntry?.searchText || '',
        preservePreviousTitle ? previousTitle : nextTitle,
        preservePreviousPreviewAuthor ? previousPreviewAuthor : nextPreviewAuthor
      ].filter(Boolean).join(' '), 560);
      const nextUnreadCount = Math.max(0, resolveRecentSidebarUnreadCount({
        ...(entry && typeof entry === 'object' ? entry : {}),
        workspaceId: String(entry?.workspaceId || ws).trim(),
        chatId
      }));
      const previousUnreadCount = Math.max(0, resolveRecentSidebarUnreadCount(previousEntry));
      const preserveAttention = nextUnreadCount > 0 && previousUnreadCount > 0;
      const preserveMentionFlag = preserveAttention && previousEntry?.mentionedMe === true && entry?.mentionedMe !== true;
      const preserveReactionFlag = preserveAttention && previousEntry?.reactionOnMine === true && entry?.reactionOnMine !== true;
      const nextSortPriority = nextUnreadCount > previousUnreadCount
        ? Math.max(
          resolveRecentSortPriority(entry),
          resolveRecentSortPriority(previousEntry),
          Number(entry?.previewTimestamp || 0),
          Number(entry?.updatedAt || 0),
          now()
        )
        : Math.max(
          resolveRecentSortPriority(entry),
          resolveRecentSortPriority(previousEntry)
        );
      return {
        ...entry,
        sourceMember: resolvedSourceMember,
        directMemberId: resolvedDirectMemberId,
        avatarUrl: resolvedAvatarUrl || entry?.avatarUrl || previousEntry?.avatarUrl || '',
        title: preservePreviousTitle ? previousEntry?.title : entry?.title,
        memberIds: mergedMemberIds.length ? mergedMemberIds : (Array.isArray(entry?.memberIds) ? entry.memberIds : []),
        searchText: mergedSearchText || entry?.searchText || previousEntry?.searchText || '',
        previewText: preservePreviousPreviewText ? previousEntry?.previewText : entry?.previewText,
        previewAuthor: preservePreviousPreviewAuthor ? previousEntry?.previewAuthor : entry?.previewAuthor,
        previewAuthorMemberId: resolvedPreviewAuthorMemberId,
        previewAuthorAvatarUrl: resolvedPreviewAuthorAvatarUrl,
        mentionedMe: preserveMentionFlag ? true : entry?.mentionedMe,
        reactionOnMine: preserveReactionFlag ? true : entry?.reactionOnMine,
        sortPriority: nextSortPriority
      };
    });
    const nextEntries = sanitizeRecentCollection(mergedEntries);
    state.recentsByWorkspace = {
      ...state.recentsByWorkspace,
      [ws]: nextEntries
    };
    runtime.recentsStateVersion += 1;
    invalidateRecentsDerivedCache();
    if (options.persist !== false) {
      saveRecentsCache(ws, nextEntries);
    }
    return nextEntries;
  }

  function replaceWorkspaceArchivedRecents(workspaceId = '', entries = []) {
    const ws = String(workspaceId || '').trim();
    if (!ws) return [];
    const nextEntries = sanitizeRecentCollection(
      (Array.isArray(entries) ? entries : []).map((entry) => ({ ...entry, isArchived: true }))
    );
    state.archivedRecentsByWorkspace = {
      ...state.archivedRecentsByWorkspace,
      [ws]: nextEntries
    };
    runtime.recentsStateVersion += 1;
    invalidateRecentsDerivedCache();
    return nextEntries;
  }

  function applyArchiveStateToRecentCollections(entry = null, archived = true) {
    const ws = String(entry?.workspaceId || '').trim();
    const chat = normalizeChatId(entry?.chatId || '');
    if (!ws || !chat) return false;

    const activeRecents = Array.isArray(state.recentsByWorkspace?.[ws])
      ? state.recentsByWorkspace[ws].slice()
      : [];
    const archivedRecents = Array.isArray(state.archivedRecentsByWorkspace?.[ws])
      ? state.archivedRecentsByWorkspace[ws].slice()
      : [];
    const activeEntry = activeRecents.find((item) => chatIdsAreEquivalent(item?.chatId || '', chat)) || null;
    const archivedEntry = archivedRecents.find((item) => chatIdsAreEquivalent(item?.chatId || '', chat)) || null;
    const sourceEntry = activeEntry || archivedEntry || entry;
    const nextActive = activeRecents.filter((item) => !chatIdsAreEquivalent(item?.chatId || '', chat));
    const nextArchived = archivedRecents.filter((item) => !chatIdsAreEquivalent(item?.chatId || '', chat));
    const nextEntry = sanitizeRecentEntry({
      ...(sourceEntry && typeof sourceEntry === 'object' ? sourceEntry : entry),
      workspaceId: ws,
      chatId: chat,
      isArchived: archived === true,
      archivedAt: archived === true ? (sourceEntry?.archivedAt || new Date().toISOString()) : ''
    });

    if (nextEntry) {
      if (archived === true) {
        nextArchived.unshift({ ...nextEntry, isArchived: true });
      } else {
        nextActive.unshift({ ...nextEntry, isArchived: false, archivedAt: '' });
      }
    }

    state.recentsByWorkspace = {
      ...state.recentsByWorkspace,
      [ws]: sanitizeRecentCollection(nextActive.map((item) => ({ ...item, isArchived: false, archivedAt: '' })))
    };
    state.archivedRecentsByWorkspace = {
      ...state.archivedRecentsByWorkspace,
      [ws]: sanitizeRecentCollection(nextArchived.map((item) => ({ ...item, isArchived: true })))
    };
    if (ws.toLowerCase() === 'telegram') {
      state.telegramDialogs = [
        ...(state.recentsByWorkspace.telegram || []),
        ...(state.archivedRecentsByWorkspace.telegram || [])
      ];
    } else {
      saveRecentsCache(ws, state.recentsByWorkspace[ws] || []);
    }
    setChatArchived(ws, chat, archived === true);
    runtime.recentsStateVersion += 1;
    invalidateRecentsDerivedCache();
    return true;
  }

  function sanitizeMessageEntry(message = null) {
    if (!message || typeof message !== 'object') return null;
    const workspaceId = String(message.workspaceId || '').trim();
    const chatId = normalizeChatId(message.chatId || '');
    const timestamp = Math.max(0, Number(message.timestamp || 0));
    const id = String(message.id || '').trim();
    if (!chatId || !id) return null;

    return {
      ...message,
      id,
      workspaceId,
      chatId,
      text: cleanMultiline(message.text || '', 6000),
      authorName: cleanText(message.authorName || 'Пользователь', 120) || 'Пользователь',
      authorMemberId: String(message.authorMemberId || '').trim(),
      authorAvatarUrl: normalizeAssetUrl(message.authorAvatarUrl || '', 4096),
      timestamp,
      isMine: message.isMine === true,
      isSystem: message.isSystem === true,
      deliveryStatus: message.isMine === true
        ? normalizeDeliveryStatus(message.deliveryStatus || resolveRawMessageDeliveryStatus(message))
        : '',
      replyToMessageId: String(message.replyToMessageId || extractReplyTargetMessageId(message) || '').trim(),
      threadChatId: normalizeChatId(message.threadChatId || ''),
      threadMessageCount: Math.max(0, Math.round(Number(message.threadMessageCount || 0)))
    };
  }

  function normalizeMessageTextForOptimisticMatch(value = '') {
    const source = cleanMultiline(value || '', 6000)
      .replace(/\[@([^\]]+)\]\(([^)]+)\)/gu, '@$1');
    return normalizeSearchText(source);
  }

  function getMessageClientMessageId(message = null) {
    const raw = getMessageRawObject(message) || message;
    if (!raw || typeof raw !== 'object') return '';
    const candidates = [
      message?.clientMessageId,
      raw?.clientMessageId,
      raw?.clientMsgId,
      raw?.message?.clientMessageId,
      raw?.message?.clientMsgId,
      raw?.metadata?.clientMessageId,
      raw?.metadata?.clientMsgId,
      raw?.payload?.clientMessageId,
      raw?.payload?.clientMsgId,
      findNestedRealtimeValue(raw, 'clientMessageId', { maxDepth: 6, maxNodes: 220 }),
      findNestedRealtimeValue(raw, 'clientMsgId', { maxDepth: 6, maxNodes: 220 })
    ];
    for (const candidate of candidates) {
      const normalized = String(candidate || '').trim();
      if (normalized) return normalized;
    }
    return '';
  }

  function isLikelyAttachmentPlaceholderMessageText(value = '') {
    const normalized = normalizeMessageTextForOptimisticMatch(value);
    if (!normalized) return true;
    const resolvedText = cleanText(value || '', 220);
    return (
      /^файл(?:ы)?(?:\s*\(\d+\))?$/.test(normalized)
      || /^files?(?:\s*\(\d+\))?$/.test(normalized)
      || normalized === 'сообщение'
      || normalized === 'message'
      || normalized === 'вложение'
      || normalized === 'attachment'
      || normalized === 'голосовое сообщение'
      || normalized === 'видео сообщение'
      || normalized === 'видеозаметка'
      || normalized === 'video note'
      || normalized === 'video message'
      || normalized === 'audio'
      || normalized === 'audio note'
      || normalized === 'voice message'
	      || normalized === 'voice note'
	      || isGeneratedVideoNoteFileName(resolvedText)
	      || isGeneratedAudioNoteFileName(resolvedText)
	      || isLikelyStandaloneAttachmentFileName(resolvedText)
	    );
	  }

  function getAttachmentOptimisticMatchKind(attachment = null) {
    if (!attachment || typeof attachment !== 'object') return '';
    const attachmentName = cleanText(
      attachment?.name || attachment?.fileName || attachment?.title || '',
      220
    );
    if (
      isVideoNoteAttachment(attachment)
      || isGeneratedVideoNoteFileName(attachmentName)
      || isGenericVideoNoteMessageText(attachmentName)
    ) {
      return 'video_note';
    }
    if (
      isLikelyVoiceAttachment(attachment)
      || isGeneratedAudioNoteFileName(attachmentName)
    ) {
      return 'voice_note';
    }
    return getAttachmentVisualKind(attachment);
  }

  function getAttachmentOptimisticComparableName(attachment = null) {
    if (!attachment || typeof attachment !== 'object') return '';
    const attachmentName = cleanText(
      attachment?.name || attachment?.fileName || attachment?.title || '',
      220
    );
    if (
      !attachmentName
      || isGeneratedVideoNoteFileName(attachmentName)
      || isGeneratedAudioNoteFileName(attachmentName)
      || isGenericVideoNoteMessageText(attachmentName)
      || /^(голосовое сообщение|voice note|audio note|аудио|видео сообщение|видеозаметка)$/i.test(attachmentName)
    ) {
      return '';
    }
    return normalizeSearchText(attachmentName);
  }

  function areOptimisticAndServerMessagesEquivalent(optimistic = null, confirmed = null) {
    if (!optimistic || !confirmed) return false;
    if (optimistic.optimistic !== true || confirmed.optimistic === true) return false;
    if (optimistic.isMine !== true || confirmed.isMine !== true) return false;
    if (!chatIdsAreEquivalent(optimistic.chatId || '', confirmed.chatId || '')) return false;

    const optimisticClientMessageId = getMessageClientMessageId(optimistic);
    const confirmedClientMessageId = getMessageClientMessageId(confirmed);
    if (optimisticClientMessageId && confirmedClientMessageId) {
      return optimisticClientMessageId === confirmedClientMessageId;
    }

    const optimisticWorkspaceId = String(optimistic.workspaceId || '').trim();
    const confirmedWorkspaceId = String(confirmed.workspaceId || '').trim();
    if (optimisticWorkspaceId && confirmedWorkspaceId && optimisticWorkspaceId !== confirmedWorkspaceId) return false;

    const optimisticAuthorId = String(optimistic.authorMemberId || '').trim();
    const confirmedAuthorId = String(confirmed.authorMemberId || '').trim();
    if (optimisticAuthorId && confirmedAuthorId && optimisticAuthorId !== confirmedAuthorId) return false;

    const optimisticReplyId = String(optimistic.replyToMessageId || '').trim();
    const confirmedReplyId = String(confirmed.replyToMessageId || '').trim();
    if (optimisticReplyId && confirmedReplyId && optimisticReplyId !== confirmedReplyId) return false;

    const timeDiff = Math.abs(Number(optimistic.timestamp || 0) - Number(confirmed.timestamp || 0));
    if (timeDiff > (8 * 60 * 1000)) return false;

    const optimisticAttachments = extractMessageAttachments(getMessageRawObject(optimistic) || optimistic);
    const confirmedAttachments = extractMessageAttachments(getMessageRawObject(confirmed) || confirmed);
    const optimisticHasAttachments = optimisticAttachments.length > 0;
    const confirmedHasAttachments = confirmedAttachments.length > 0;

    const optimisticText = normalizeMessageTextForOptimisticMatch(optimistic.text || '');
    const confirmedText = normalizeMessageTextForOptimisticMatch(confirmed.text || '');
    const optimisticUsesPlaceholderText = isLikelyAttachmentPlaceholderMessageText(optimistic.text || '');
    const confirmedUsesPlaceholderText = isLikelyAttachmentPlaceholderMessageText(confirmed.text || '');
    const optimisticTimestamp = Number(optimistic.timestamp || 0);
    const confirmedTimestamp = Number(confirmed.timestamp || 0);
    const placeholderAttachmentTimeWindowMs = 2 * 60 * 1000;
    const optimisticLeadAllowanceMs = 15 * 1000;
    const withinAttachmentPlaceholderWindow = (
      timeDiff <= placeholderAttachmentTimeWindowMs
      && !(
        confirmedTimestamp > 0
        && optimisticTimestamp > 0
        && confirmedTimestamp < (optimisticTimestamp - optimisticLeadAllowanceMs)
      )
    );

    if (optimisticHasAttachments || confirmedHasAttachments) {
      if (!optimisticHasAttachments || !confirmedHasAttachments) {
        if (
          optimisticHasAttachments
          && !confirmedHasAttachments
          && withinAttachmentPlaceholderWindow
          && (!confirmedText || confirmedUsesPlaceholderText)
          && (!optimisticText || optimisticUsesPlaceholderText || optimisticText === confirmedText)
        ) {
          return true;
        }
        return false;
      }
      if (Math.abs(optimisticAttachments.length - confirmedAttachments.length) > 1) return false;
      const optimisticKinds = optimisticAttachments
        .map((attachment) => getAttachmentOptimisticMatchKind(attachment))
        .filter(Boolean)
        .sort();
      const confirmedKinds = confirmedAttachments
        .map((attachment) => getAttachmentOptimisticMatchKind(attachment))
        .filter(Boolean)
        .sort();
      if (
        optimisticKinds.length
        && confirmedKinds.length
        && optimisticKinds.join('\u0001') !== confirmedKinds.join('\u0001')
      ) {
        return false;
      }
      const optimisticComparableNames = optimisticAttachments
        .map((attachment) => getAttachmentOptimisticComparableName(attachment))
        .filter(Boolean);
      const confirmedComparableNames = confirmedAttachments
        .map((attachment) => getAttachmentOptimisticComparableName(attachment))
        .filter(Boolean);
      if (
        optimisticComparableNames.length
        && confirmedComparableNames.length
        && !optimisticComparableNames.some((name) => confirmedComparableNames.includes(name))
      ) {
        return false;
      }
      if (
        (optimisticUsesPlaceholderText || confirmedUsesPlaceholderText)
        && !withinAttachmentPlaceholderWindow
      ) {
        return false;
      }
      if (optimisticText && confirmedText && optimisticText !== confirmedText) {
        if (
          !optimisticUsesPlaceholderText
          && !confirmedUsesPlaceholderText
        ) {
          return false;
        }
      }
      return true;
    }

    return Boolean(optimisticText && confirmedText && optimisticText === confirmedText);
  }

  function stripConfirmedOptimisticMessages(items = []) {
    const safeItems = Array.isArray(items) ? items : [];
    const confirmedItems = safeItems.filter((item) => item && item.optimistic !== true);
    if (!confirmedItems.length) return safeItems;

    const usedConfirmedIndexes = new Set();
    return safeItems.filter((item) => {
      if (!item || item.optimistic !== true) return true;
      const matchedIndex = confirmedItems.findIndex((candidate, index) => (
        !usedConfirmedIndexes.has(index)
        && areOptimisticAndServerMessagesEquivalent(item, candidate)
      ));
      if (matchedIndex < 0) return true;
      attachOptimisticMediaFallbackToConfirmedMessage(item, confirmedItems[matchedIndex]);
      usedConfirmedIndexes.add(matchedIndex);
      return false;
    });
  }

  function mergePendingOptimisticMessages(existingItems = [], incomingItems = []) {
    const safeExistingItems = Array.isArray(existingItems) ? existingItems.filter(Boolean) : [];
    const safeIncomingItems = Array.isArray(incomingItems) ? incomingItems.filter(Boolean) : [];
    if (!safeExistingItems.length) return safeIncomingItems;
    const optimisticExistingItems = safeExistingItems.filter((item) => item && item.optimistic === true);
    if (!optimisticExistingItems.length) return safeIncomingItems;

    const confirmedIncomingItems = safeIncomingItems.filter((item) => item && item.optimistic !== true);
    if (!confirmedIncomingItems.length) {
      return [
        ...safeIncomingItems,
        ...optimisticExistingItems
      ];
    }

    const nowTimestamp = now();
    const optimisticRetentionWindowMs = 45 * 60 * 1000;
    const incomingIds = new Set(
      safeIncomingItems
        .map((item) => String(item?.id || '').trim())
        .filter(Boolean)
    );
    const retainedOptimisticItems = optimisticExistingItems.filter((item) => {
      if (!item || item.optimistic !== true) return false;
      const optimisticId = String(item?.id || '').trim();
      if (optimisticId && incomingIds.has(optimisticId)) return false;
      const optimisticTimestamp = Math.max(0, Number(item?.timestamp || 0));
      if (
        optimisticTimestamp > 0
        && nowTimestamp > optimisticTimestamp
        && (nowTimestamp - optimisticTimestamp) > optimisticRetentionWindowMs
      ) {
        return false;
      }
      return !confirmedIncomingItems.some((candidate) => areOptimisticAndServerMessagesEquivalent(item, candidate));
    });

    if (!retainedOptimisticItems.length) {
      return safeIncomingItems;
    }
    return [
      ...safeIncomingItems,
      ...retainedOptimisticItems
    ];
  }

  function attachOptimisticMediaFallbackToConfirmedMessage(optimistic = null, confirmed = null) {
    if (!optimistic || !confirmed || typeof confirmed !== 'object') return;
    const optimisticAttachments = extractMessageAttachments(getMessageRawObject(optimistic) || optimistic)
      .filter((attachment) => attachment && typeof attachment === 'object')
      .map((attachment) => ({ ...attachment }));
    if (!optimisticAttachments.length) return;
    confirmed.optimisticAttachmentFallback = optimisticAttachments;
    rememberMessageAttachmentFallback(confirmed, optimisticAttachments);
  }

  function areMessageRowsEquivalent(leftItems = [], rightItems = []) {
    const safeLeft = Array.isArray(leftItems) ? leftItems : [];
    const safeRight = Array.isArray(rightItems) ? rightItems : [];
    if (safeLeft.length !== safeRight.length) return false;
    for (let index = 0; index < safeLeft.length; index += 1) {
      const left = safeLeft[index];
      const right = safeRight[index];
      if (String(left?.id || '') !== String(right?.id || '')) return false;
      if (getMessageRowRenderSignature(left) !== getMessageRowRenderSignature(right)) return false;
    }
    return true;
  }

  function isUnstableMaxWebMessage(message = null) {
    const id = String(message?.id || message?.messageId || '').trim();
    if (!id) return false;
    return /^web[-:]/i.test(id) || /^max-web[-:]/i.test(id);
  }

  function getMaxMessageAttachmentDedupeSignature(message = null) {
    const raw = getMessageRawObject(message) || message;
    return extractMessageAttachments(raw || message)
      .map((attachment) => {
        if (!attachment || typeof attachment !== 'object') return '';
        const kind = cleanText(attachment.type || attachment.mediaType || attachment.mimeType || '', 80);
        const stable = cleanText(
          attachment.url
          || attachment.downloadUrl
          || attachment.previewUrl
          || attachment.fileUrl
          || attachment.audioUrl
          || attachment.videoUrl
          || attachment.imageUrl
          || attachment.fileId
          || attachment.id
          || attachment.name
          || '',
          4096
        ).replace(/[?#].*$/, '');
        return normalizeSearchText([kind, stable].filter(Boolean).join(' '));
      })
      .filter(Boolean)
      .slice(0, 6)
      .sort((left, right) => left.localeCompare(right, 'en'))
      .join('|');
  }

  function shouldUseMaxContentDedupe(message = null, attachmentSignature = '') {
    if (!message || typeof message !== 'object') return false;
    if (message.optimistic === true) return false;
    if (isUnstableMaxWebMessage(message)) return true;
    if (message.isSystem === true) return true;
    const raw = getMessageRawObject(message) || message;
    if (raw?.isSystem === true || raw?.system === true || raw?.service === true) return true;
    return Boolean(attachmentSignature);
  }

  function buildMaxMessageContentDedupeKey(message = null) {
    if (!message || typeof message !== 'object' || message.optimistic === true) return '';
    const workspaceId = String(message.workspaceId || '').trim();
    const chatId = normalizeChatId(message.chatId || '');
    if (!workspaceId || !chatId || !isMaxConversationChat(workspaceId, chatId)) return '';
    const text = normalizeMessageTextForOptimisticMatch(message.text || '');
    const attachments = getMaxMessageAttachmentDedupeSignature(message);
    if (!shouldUseMaxContentDedupe(message, attachments)) return '';
    const textForKey = attachments ? '' : text;
    if (!textForKey && !attachments) return '';
    const timestamp = Math.max(0, Number(message.timestamp || 0) || 0);
    const timestampBucket = (attachments || message.isSystem === true)
      ? ''
      : (timestamp ? Math.floor(timestamp / (10 * 60 * 1000)) : 0);
    const isSystemKey = message.isSystem === true || (getMessageRawObject(message) || message)?.isSystem === true;
    const hasAttachmentKey = Boolean(attachments);
    const authorKey = hasAttachmentKey
      ? 'media'
      : isSystemKey
      ? 'system'
      : message.isMine === true
      ? 'mine'
      : normalizeSearchText(message.authorMemberId || message.authorName || '');
    return [
      workspaceId.toLowerCase(),
      chatId,
      hasAttachmentKey ? 'media' : (isSystemKey ? 'system' : (message.isMine === true ? '1' : '0')),
      authorKey,
      timestampBucket,
      textForKey,
      attachments
    ].join('\u0001');
  }

  function shouldPreferMaxMessageDuplicate(candidate = null, current = null) {
    if (!current) return true;
    const candidateUnstable = isUnstableMaxWebMessage(candidate);
    const currentUnstable = isUnstableMaxWebMessage(current);
    if (candidateUnstable !== currentUnstable) return !candidateUnstable;
    if ((candidate?.optimistic === true) !== (current?.optimistic === true)) {
      return current?.optimistic === true;
    }
    if ((candidate?.isSystem === true) !== (current?.isSystem === true)) {
      return candidate?.isSystem === true;
    }
    const candidateAttachmentCount = extractMessageAttachments(getMessageRawObject(candidate) || candidate).length;
    const currentAttachmentCount = extractMessageAttachments(getMessageRawObject(current) || current).length;
    if (candidateAttachmentCount !== currentAttachmentCount) {
      return candidateAttachmentCount > currentAttachmentCount;
    }
    const candidateTextLength = cleanText(candidate?.text || '', 6000).length;
    const currentTextLength = cleanText(current?.text || '', 6000).length;
    if (candidateTextLength !== currentTextLength) {
      return candidateTextLength > currentTextLength;
    }
    return Number(candidate?.timestamp || 0) >= Number(current?.timestamp || 0);
  }

  function dedupeMaxWebMessagesByContent(items = []) {
    const output = [];
    const indexByKey = new Map();
    (Array.isArray(items) ? items : []).forEach((item) => {
      const key = buildMaxMessageContentDedupeKey(item);
      if (!key) {
        output.push(item);
        return;
      }
      const existingIndex = indexByKey.get(key);
      if (typeof existingIndex !== 'number') {
        indexByKey.set(key, output.length);
        output.push(item);
        return;
      }
      const existing = output[existingIndex];
      if (shouldPreferMaxMessageDuplicate(item, existing)) {
        output[existingIndex] = item;
      }
    });
    return output;
  }

  function sanitizeMessagesList(items = []) {
    const uniqueById = new Map();
    (Array.isArray(items) ? items : [])
      .map((item) => sanitizeMessageEntry(item))
      .filter(Boolean)
      .sort((left, right) => {
        const timeDiff = Number(left.timestamp || 0) - Number(right.timestamp || 0);
        if (timeDiff) return timeDiff;
        return String(left.id || '').localeCompare(String(right.id || ''), 'en');
      })
      .forEach((item) => {
        uniqueById.set(item.id, item);
      });

    const sortedByTimeline = Array.from(uniqueById.values()).sort((left, right) => {
      const timeDiff = Number(left.timestamp || 0) - Number(right.timestamp || 0);
      if (timeDiff) return timeDiff;
      return String(left.id || '').localeCompare(String(right.id || ''), 'en');
    });

    return dedupeMaxWebMessagesByContent(stripConfirmedOptimisticMessages(sortedByTimeline)).sort((left, right) => {
      const timeDiff = Number(left.timestamp || 0) - Number(right.timestamp || 0);
      if (timeDiff) return timeDiff;
      return String(left.id || '').localeCompare(String(right.id || ''), 'en');
    });
  }

  function revokeBlobObjectUrl(value = '') {
    const objectUrl = String(value || '').trim();
    if (!objectUrl || !objectUrl.startsWith('blob:')) return;
    try {
      URL.revokeObjectURL(objectUrl);
    } catch {
      // ignore blob cleanup failures
    }
  }

  function collectAttachmentBlobUrls(attachments = []) {
    const urls = new Set();
    (Array.isArray(attachments) ? attachments : []).forEach((attachment) => {
      if (!attachment || typeof attachment !== 'object') return;
      [
        attachment?.url,
        attachment?.downloadUrl,
        attachment?.previewUrl
      ].forEach((candidate) => {
        const normalized = String(candidate || '').trim();
        if (normalized && /^blob:/i.test(normalized)) {
          urls.add(normalized);
        }
      });
    });
    return Array.from(urls);
  }

  function releaseOptimisticAttachmentCacheRecord(record = null) {
    if (!record || typeof record !== 'object') return;
    collectAttachmentBlobUrls(record.attachments || []).forEach((url) => {
      revokeBlobObjectUrl(url);
    });
  }

  function pruneOptimisticAttachmentCache(nowTimestamp = now()) {
    const maxAgeMs = 3 * 60 * 60 * 1000;
    const maxEntries = 80;
    const records = Array.from(runtime.optimisticAttachmentCacheByClientMessageId.entries());
    records.forEach(([clientMessageId, record]) => {
      const createdAt = Math.max(0, Number(record?.createdAt || 0));
      if (!clientMessageId || !createdAt || (nowTimestamp - createdAt) <= maxAgeMs) {
        return;
      }
      runtime.optimisticAttachmentCacheByClientMessageId.delete(clientMessageId);
      releaseOptimisticAttachmentCacheRecord(record);
    });
    while (runtime.optimisticAttachmentCacheByClientMessageId.size > maxEntries) {
      const oldestKey = runtime.optimisticAttachmentCacheByClientMessageId.keys().next().value;
      if (!oldestKey) break;
      const oldestRecord = runtime.optimisticAttachmentCacheByClientMessageId.get(oldestKey) || null;
      runtime.optimisticAttachmentCacheByClientMessageId.delete(oldestKey);
      releaseOptimisticAttachmentCacheRecord(oldestRecord);
    }
  }

  function rememberOptimisticAttachmentSnapshot(clientMessageId = '', workspaceId = '', chatId = '', attachments = []) {
    const normalizedClientMessageId = String(clientMessageId || '').trim();
    const safeAttachments = (Array.isArray(attachments) ? attachments : [])
      .filter((attachment) => attachment && typeof attachment === 'object')
      .map((attachment) => ({ ...attachment }));
    if (!normalizedClientMessageId || !safeAttachments.length) return;
    runtime.optimisticAttachmentCacheByClientMessageId.set(normalizedClientMessageId, {
      clientMessageId: normalizedClientMessageId,
      workspaceId: String(workspaceId || '').trim(),
      chatId: normalizeChatId(chatId || ''),
      createdAt: now(),
      attachments: safeAttachments
    });
    pruneOptimisticAttachmentCache();
  }

  function buildMessageAttachmentFallbackKey(workspaceId = '', chatId = '', messageId = '') {
    const ws = String(workspaceId || '').trim();
    const chat = normalizeChatId(chatId || '');
    const id = String(messageId || '').trim();
    if (!ws || !chat || !id) return '';
    return `${ws}\u0001${chat}\u0001${id}`;
  }

  function sanitizePersistableAttachmentFallbackAttachment(attachment = null) {
    if (!attachment || typeof attachment !== 'object') return null;
    const id = String(attachment?.id || attachment?.fileId || '').trim();
    const previewId = String(attachment?.previewId || attachment?.previewFileId || '').trim();
    const name = cleanText(attachment?.name || attachment?.fileName || attachment?.title || '', 180);
    const url = normalizeAssetUrl(attachment?.url || '', 8192);
    const downloadUrl = normalizeAssetUrl(attachment?.downloadUrl || '', 8192);
    const previewUrl = normalizeAssetUrl(attachment?.previewUrl || '', 8192);
    const mediaType = cleanText(attachment?.mediaType || '', 40).toUpperCase();
    const mimeType = cleanText(attachment?.mimeType || '', 140);
    const previewMimeType = cleanText(attachment?.previewMimeType || '', 140);
    const size = Math.max(0, Math.round(Number(attachment?.size || 0) || 0));
    const durationSeconds = Math.max(0, Number(attachment?.durationSeconds || 0) || 0);
    const width = Math.max(0, Math.round(Number(attachment?.width || 0) || 0));
    const height = Math.max(0, Math.round(Number(attachment?.height || 0) || 0));
    const voiceDurationMs = Math.max(0, Math.round(Number(attachment?.voiceDurationMs || 0) || 0));
    const waveform = cleanText(String(attachment?.waveform || ''), 4000);
    const transferId = cleanText(String(attachment?.transferId || ''), 180);
    if (
      !id
      && !previewId
      && !url
      && !downloadUrl
      && !previewUrl
      && !name
      && !mediaType
      && !mimeType
      && attachment?.isVideoNote !== true
      && attachment?.isVoice !== true
      && attachment?.voiceNote !== true
      && attachment?.syntheticPlaceholder !== true
    ) {
      return null;
    }
    return {
      id,
      previewId,
      name,
      url,
      downloadUrl,
      previewUrl,
      size,
      mimeType,
      mediaType,
      previewMimeType,
      isVideoNote: attachment?.isVideoNote === true,
      isVoice: attachment?.isVoice === true,
      voice: attachment?.voice === true,
      voiceNote: attachment?.voiceNote === true,
      waveform,
      voiceDurationMs,
      transferId,
      durationSeconds,
      width,
      height,
      syntheticPlaceholder: attachment?.syntheticPlaceholder === true,
      optimisticFallback: attachment?.optimisticFallback === true
    };
  }

  function ensureMessageAttachmentFallbackStateLoaded() {
    if (runtime.messageAttachmentFallbackLoaded === true) return;
    runtime.messageAttachmentFallbackLoaded = true;
    runtime.messageAttachmentFallbackByMessageKey = new Map();
    try {
      const raw = localStorage.getItem(MESSAGE_ATTACHMENT_FALLBACK_STORAGE_KEY);
      if (!raw) return;
      const parsed = JSON.parse(raw);
      const entries = Array.isArray(parsed?.entries) ? parsed.entries : [];
      entries.forEach((entry) => {
        const key = String(entry?.key || '').trim();
        const createdAt = Math.max(0, Number(entry?.createdAt || 0));
        const attachments = (Array.isArray(entry?.attachments) ? entry.attachments : [])
          .map((attachment) => sanitizePersistableAttachmentFallbackAttachment(attachment))
          .filter(Boolean);
        if (!key || !attachments.length) return;
        runtime.messageAttachmentFallbackByMessageKey.set(key, {
          key,
          createdAt: createdAt || now(),
          attachments
        });
      });
    } catch {
      runtime.messageAttachmentFallbackByMessageKey = new Map();
    }
  }

  function persistMessageAttachmentFallbackState() {
    ensureMessageAttachmentFallbackStateLoaded();
    try {
      const entries = Array.from(runtime.messageAttachmentFallbackByMessageKey.values())
        .filter((entry) => entry && typeof entry === 'object' && String(entry.key || '').trim())
        .sort((left, right) => Number(right?.createdAt || 0) - Number(left?.createdAt || 0))
        .slice(0, MESSAGE_ATTACHMENT_FALLBACK_PERSIST_LIMIT)
        .map((entry) => ({
          key: String(entry.key || '').trim(),
          createdAt: Math.max(0, Number(entry.createdAt || 0)),
          attachments: (Array.isArray(entry.attachments) ? entry.attachments : [])
            .map((attachment) => sanitizePersistableAttachmentFallbackAttachment(attachment))
            .filter(Boolean)
            .slice(0, 12)
        }))
        .filter((entry) => entry.key && entry.attachments.length);
      localStorage.setItem(MESSAGE_ATTACHMENT_FALLBACK_STORAGE_KEY, JSON.stringify({
        updatedAt: now(),
        entries
      }));
    } catch {
      // ignore localStorage persistence failures
    }
  }

  function schedulePersistMessageAttachmentFallbackState(delayMs = 180) {
    ensureMessageAttachmentFallbackStateLoaded();
    if (runtime.messageAttachmentFallbackPersistTimer) return;
    runtime.messageAttachmentFallbackPersistTimer = window.setTimeout(() => {
      runtime.messageAttachmentFallbackPersistTimer = 0;
      persistMessageAttachmentFallbackState();
    }, Math.max(80, Number(delayMs || 0)));
  }

  function rememberMessageAttachmentFallback(message = null, attachments = []) {
    if (!message || typeof message !== 'object') return;
    ensureMessageAttachmentFallbackStateLoaded();
    const key = buildMessageAttachmentFallbackKey(
      message?.workspaceId || '',
      message?.chatId || '',
      message?.id || message?.messageId || ''
    );
    const safeAttachments = (Array.isArray(attachments) ? attachments : [])
      .map((attachment) => sanitizePersistableAttachmentFallbackAttachment(attachment))
      .filter(Boolean);
    if (!key || !safeAttachments.length) return;
    runtime.messageAttachmentFallbackByMessageKey.set(key, {
      key,
      createdAt: now(),
      attachments: safeAttachments
    });
    while (runtime.messageAttachmentFallbackByMessageKey.size > 400) {
      const oldestKey = runtime.messageAttachmentFallbackByMessageKey.keys().next().value;
      if (!oldestKey) break;
      runtime.messageAttachmentFallbackByMessageKey.delete(oldestKey);
    }
    schedulePersistMessageAttachmentFallbackState();
  }

  function getRememberedMessageAttachmentFallback(message = null) {
    if (!message || typeof message !== 'object') return [];
    ensureMessageAttachmentFallbackStateLoaded();
    const key = buildMessageAttachmentFallbackKey(
      message?.workspaceId || '',
      message?.chatId || '',
      message?.id || message?.messageId || ''
    );
    if (!key) return [];
    const record = runtime.messageAttachmentFallbackByMessageKey.get(key) || null;
    return (Array.isArray(record?.attachments) ? record.attachments : [])
      .filter((attachment) => attachment && typeof attachment === 'object')
      .map((attachment) => ({ ...attachment }));
  }

  function getOptimisticAttachmentSnapshotForMessage(message = null) {
    if (!message || typeof message !== 'object') return [];
    const messageWorkspaceId = String(message?.workspaceId || '').trim();
    const messageChatId = normalizeChatId(message?.chatId || '');
    const clientMessageId = getMessageClientMessageId(message);
    let record = clientMessageId
      ? (runtime.optimisticAttachmentCacheByClientMessageId.get(clientMessageId) || null)
      : null;
    if (!record && messageWorkspaceId && messageChatId) {
      const messageTimestamp = Math.max(0, Number(message?.timestamp || 0));
      const candidateRecords = Array.from(runtime.optimisticAttachmentCacheByClientMessageId.values())
        .filter((candidate) => (
          candidate
          && candidate.workspaceId === messageWorkspaceId
          && chatIdsAreEquivalent(candidate.chatId || '', messageChatId)
        ))
        .sort((left, right) => Math.abs(Number(left?.createdAt || 0) - messageTimestamp) - Math.abs(Number(right?.createdAt || 0) - messageTimestamp));
      const timeWindowMs = 2 * 60 * 1000;
      record = candidateRecords.find((candidate) => (
        messageTimestamp <= 0
        || Math.abs(Number(candidate?.createdAt || 0) - messageTimestamp) <= timeWindowMs
      )) || null;
    }
    if (!record) return [];
    if (
      record.workspaceId
      && messageWorkspaceId
      && record.workspaceId !== messageWorkspaceId
    ) {
      return [];
    }
    if (
      record.chatId
      && messageChatId
      && !chatIdsAreEquivalent(record.chatId, messageChatId)
    ) {
      return [];
    }
    pruneOptimisticAttachmentCache();
    return (Array.isArray(record.attachments) ? record.attachments : [])
      .filter((attachment) => attachment && typeof attachment === 'object')
      .map((attachment) => ({ ...attachment }));
  }

  function isBlobUrlRetainedByOptimisticAttachmentCache(value = '') {
    const objectUrl = String(value || '').trim();
    if (!objectUrl || !/^blob:/i.test(objectUrl)) return false;
    for (const record of runtime.optimisticAttachmentCacheByClientMessageId.values()) {
      const matches = collectAttachmentBlobUrls(record?.attachments || []);
      if (matches.includes(objectUrl)) {
        return true;
      }
    }
    return false;
  }

  function releaseOptimisticMessageObjectUrls(message = null) {
    if (!message || message.optimistic !== true) return;
    const attachments = extractMessageAttachments(getMessageRawObject(message) || message);
    const seenUrls = new Set();
    attachments.forEach((attachment) => {
      [
        attachment?.url,
        attachment?.downloadUrl,
        attachment?.previewUrl
      ].forEach((candidate) => {
        const normalized = String(candidate || '').trim();
        if (!normalized || seenUrls.has(normalized)) return;
        seenUrls.add(normalized);
        if (isBlobUrlRetainedByOptimisticAttachmentCache(normalized)) return;
        revokeBlobObjectUrl(normalized);
      });
    });
  }

  function replaceChatMessages(workspaceId = '', chatId = '', items = [], meta = {}) {
    const key = getChatStateKey(workspaceId, chatId);
    if (!key) return [];
    const existing = state.messagesByChatKey?.[key] || {};
    const existingItems = Array.isArray(existing.items) ? existing.items : [];
    const nextItems = sanitizeMessagesList(items);
    const nextHasMore = meta.hasMore === true;
    const nextLoadedCount = Math.max(
      MESSAGE_PAGE_STEP,
      Number(meta.loadedCount) || Number(existing.loadedCount) || MESSAGE_PAGE_STEP
    );
    const itemsChanged = !areMessageRowsEquivalent(existingItems, nextItems);
    const metaChanged = (
      Boolean(existing.hasMore === true) !== Boolean(nextHasMore)
      || Number(existing.loadedCount || 0) !== nextLoadedCount
    );
    if (!itemsChanged && !metaChanged) {
      return existingItems;
    }

    const nextIds = new Set(
      nextItems
        .map((item) => String(item?.id || '').trim())
        .filter(Boolean)
    );
    existingItems.forEach((message) => {
      const messageId = String(message?.id || '').trim();
      if (!messageId || nextIds.has(messageId)) return;
      releaseOptimisticMessageObjectUrls(message);
    });

    state.messagesByChatKey = {
      ...state.messagesByChatKey,
      [key]: {
        ...existing,
        items: nextItems,
        hasMore: nextHasMore,
        loadedCount: nextLoadedCount,
        instantPreviewStub: meta.instantPreviewStub === true,
        updatedAt: now()
      }
    };
    applySharedMemberOverrideCandidates(collectSharedMemberOverrideCandidates(nextItems));
    return nextItems;
  }

  function shouldShowTelegramInSidebar() {
    const settings = normalizeTelegramIntegrationSettings(state.telegramIntegration);
    return settings.enabled === true && settings.showInSidebar !== false;
  }

  function ensureTelegramWorkspace() {
    const showTelegram = shouldShowTelegramInSidebar();
    const workspaceList = Array.isArray(state.workspaces) ? state.workspaces : [];
    const hasTelegramWorkspace = workspaceList.some((workspace) => String(workspace?.workspaceId || '').trim() === 'telegram');
    if (showTelegram && !hasTelegramWorkspace) {
      state.workspaces = [
        ...workspaceList,
        {
          workspaceId: 'telegram',
          title: 'Telegram',
          isTelegram: true,
          synthetic: true
        }
      ];
      runtime.telegramWorkspaceVisible = true;
      runtime.recentsStateVersion += 1;
      invalidateRecentsDerivedCache();
      return true;
    }
    if (!showTelegram && hasTelegramWorkspace) {
      state.workspaces = workspaceList.filter((workspace) => String(workspace?.workspaceId || '').trim() !== 'telegram');
      delete state.recentsByWorkspace.telegram;
      delete state.archivedRecentsByWorkspace.telegram;
      delete state.recentsLoadingByWorkspace.telegram;
      delete state.recentsLoadedAtByWorkspace.telegram;
      if (String(state.activeChatWorkspaceId || '').trim() === 'telegram') {
        state.activeChatWorkspaceId = '';
        state.activeChatId = '';
        state.activeChatTitle = '';
        closeThreadPanel();
      }
      runtime.telegramWorkspaceVisible = false;
      runtime.recentsStateVersion += 1;
      invalidateRecentsDerivedCache();
      return true;
    }
    runtime.telegramWorkspaceVisible = showTelegram;
    return false;
  }

  function normalizeTelegramDialogForSidebar(dialog = null) {
    if (!dialog || typeof dialog !== 'object') return null;
    const chatId = normalizeChatId(dialog.chatId || (dialog.id ? `tg:${dialog.id}` : ''));
    if (!chatId) return null;
    const title = cleanText(dialog.title || dialog.name || 'Telegram', 180) || 'Telegram';
    const telegramType = normalizeTelegramDialogTypeValue(dialog.telegramType || dialog.type || '') || 'chat';
    const peerId = cleanText(
      dialog.peerId
      || dialog.id
      || String(chatId).replace(/^tg:/i, ''),
      160
    );
    const rawDialogNotifySettings = (
      dialog?.notifySettings && typeof dialog.notifySettings === 'object' && !Array.isArray(dialog.notifySettings)
        ? dialog.notifySettings
        : (
          dialog?.notificationSettings && typeof dialog.notificationSettings === 'object' && !Array.isArray(dialog.notificationSettings)
            ? dialog.notificationSettings
            : null
        )
    );
    const dialogNotifySettings = sanitizeNotifySettings(rawDialogNotifySettings || {});
    const isMuted = Object.prototype.hasOwnProperty.call(dialog, 'isMuted')
      ? Boolean(dialog.isMuted)
      : Boolean(dialogNotifySettings.isMuted);
    const notifyOverride = getSidebarNotifyOverride('telegram', chatId);
    const effectiveIsMuted = notifyOverride
      ? notifyOverride.isMuted === true
      : isMuted;
    const pinnedAt = cleanText(dialog.pinnedAt || dialog.pinAt || '', 80)
      || (dialog.pinned === true || dialog.isPinned === true ? TELEGRAM_DIALOG_PINNED_AT : '');
    const directMemberId = telegramType === 'direct'
      ? cleanText(dialog.directMemberId || dialog.memberId || (peerId ? `telegram:${peerId}` : ''), 180)
      : '';
    const rawParticipants = Array.isArray(dialog.participants) ? dialog.participants : [];
    const participantMemberIds = rawParticipants
      .map((participant) => String(participant?.memberId || participant?.id || '').trim())
      .filter(Boolean);
	    const memberIds = Array.from(new Set([
	      directMemberId,
	      ...(Array.isArray(dialog.memberIds) ? dialog.memberIds : []),
	      ...participantMemberIds,
	      ...(telegramType === 'direct' ? [cleanText(dialog.previewAuthorMemberId || '', 160)] : [])
	    ].map((value) => String(value || '').trim()).filter(Boolean)));
	    const sourceMember = telegramType === 'direct'
	      ? normalizeTelegramParticipantForUi({
	        ...(dialog.profile && typeof dialog.profile === 'object' ? dialog.profile : {}),
	        ...(dialog.sourceMember && typeof dialog.sourceMember === 'object' ? dialog.sourceMember : {}),
	        id: directMemberId || dialog.memberId || '',
	        memberId: directMemberId || dialog.memberId || '',
	        peerId,
	        label: title,
	        title,
	        fullName: title,
	        displayName: title,
	        username: dialog.username || dialog.profile?.username || '',
	        phone: dialog.phone || dialog.profile?.phone || '',
	        about: dialog.about || dialog.bio || dialog.profile?.about || dialog.profile?.bio || '',
	        birthday: dialog.birthday || dialog.birthDate || dialog.profile?.birthday || dialog.profile?.birthDate || '',
	        avatarUrl: dialog.avatarUrl || dialog.avatarResourceUrl || dialog.profile?.avatarUrl || ''
	      })
	      : null;
	    const participantSearchText = rawParticipants.map((participant) => cleanText([
	      participant?.label || participant?.title || participant?.fullName || participant?.displayName || '',
	      participant?.username ? `@${participant.username}` : '',
      participant?.phone || '',
      participant?.memberId || participant?.id || ''
    ].filter(Boolean).join(' '), 240)).filter(Boolean).join(' ');
    const telegramTypeText = telegramType === 'direct'
      ? 'личное личка персональный direct personal'
      : (telegramType === 'channel'
        ? 'канал channel'
        : 'группа групповой group chat');
	    const previewTimestamp = Math.max(
	      0,
	      Number(dialog.previewTimestamp || 0),
	      Number(dialog.updatedAt || 0)
	    );
	    const unreadMentionsCount = Math.max(0, Math.trunc(Number(
	      dialog.unreadMentionsCount
	      ?? dialog.unreadMentionCount
	      ?? dialog.unread_mentions_count
	      ?? 0
	    ) || 0));
	    const unreadReactionsCount = Math.max(0, Math.trunc(Number(
	      dialog.unreadReactionsCount
	      ?? dialog.unreadReactionCount
	      ?? dialog.unread_reactions_count
	      ?? 0
	    ) || 0));
	    const previewReactions = sanitizeReactionPreviewList(
	      dialog.previewReactions || dialog.reactions || [],
	      4
	    );
	    if (sourceMember) {
	      cacheKnownProfile(sourceMember);
	    }
	    return sanitizeRecentEntry({
      ...dialog,
      workspaceId: 'telegram',
      workspaceTitle: 'Telegram',
      chatId,
      title,
      searchText: [
        title,
        getReversedNameVariant(title),
	        cleanText(dialog.username || '', 120),
	        cleanText(dialog.phone || '', 80),
	        cleanText(dialog.about || dialog.bio || '', 240),
	        cleanText(dialog.birthday || dialog.birthDate || '', 80),
	        cleanText(dialog.statusText || '', 120),
        cleanText(dialog.previewAuthor || '', 120),
        cleanText(dialog.previewText || '', 220),
        'Телеграм',
        'Telegram',
        telegramTypeText,
        directMemberId,
        peerId,
        participantSearchText
      ].filter(Boolean).join(' '),
      avatarUrl: normalizeAssetUrl(dialog.avatarUrl || dialog.avatarResourceUrl || '', 2097152),
      avatarResourceUrl: normalizeAssetUrl(dialog.avatarResourceUrl || '', 4096),
      unreadCount: Math.max(0, Number(dialog.unreadCount || 0)),
      unreadMentionsCount,
      unreadReactionsCount,
      mentionedMe: dialog.mentionedMe === true || unreadMentionsCount > 0,
      reactionOnMine: dialog.reactionOnMine === true || unreadReactionsCount > 0,
      previewText: cleanText(dialog.previewText || dialog.statusText || '', 220),
      previewAuthor: cleanText(dialog.previewAuthor || '', 120),
      previewAuthorMemberId: cleanText(dialog.previewAuthorMemberId || '', 160),
      previewAuthorAvatarUrl: normalizeAssetUrl(dialog.previewAuthorAvatarUrl || dialog.previewAuthorAvatarResourceUrl || '', 2097152),
      previewAuthorAvatarResourceUrl: normalizeAssetUrl(dialog.previewAuthorAvatarResourceUrl || '', 4096),
      previewMessageId: String(dialog.previewMessageId || '').trim(),
      previewIsMine: dialog.previewIsMine === true,
      previewDeliveryStatus: normalizeDeliveryStatus(dialog.previewDeliveryStatus || dialog.deliveryStatus || ''),
      previewReactions,
      readInboxMaxId: Math.max(0, Math.trunc(Number(dialog.readInboxMaxId || dialog.read_inbox_max_id || 0) || 0)),
      readOutboxMaxId: Math.max(0, Math.trunc(Number(dialog.readOutboxMaxId || dialog.read_outbox_max_id || 0) || 0)),
      previewTimestamp,
      updatedAt: Math.max(0, Number(dialog.updatedAt || 0), previewTimestamp),
      pinnedAt,
      notifySettings: {
        ...dialogNotifySettings,
        isMuted: effectiveIsMuted
      },
      isMuted: effectiveIsMuted,
      directMemberId,
      memberIds,
      rawChat: {
	        ...dialog,
	        type: telegramType,
	        telegramType,
	        participants: rawParticipants,
	        memberIds,
	        unreadMentionsCount,
	        unreadReactionsCount,
	        previewReactions,
	        previewDeliveryStatus: normalizeDeliveryStatus(dialog.previewDeliveryStatus || dialog.deliveryStatus || ''),
	        readInboxMaxId: Math.max(0, Math.trunc(Number(dialog.readInboxMaxId || dialog.read_inbox_max_id || 0) || 0)),
	        readOutboxMaxId: Math.max(0, Math.trunc(Number(dialog.readOutboxMaxId || dialog.read_outbox_max_id || 0) || 0)),
	        sourceMember
	      },
	      sourceMember,
	      isTelegram: true,
      telegramType,
      type: telegramType,
      sourceLabel: 'Телеграм',
	      username: cleanText(dialog.username || '', 120),
	      phone: cleanText(dialog.phone || '', 80),
	      about: cleanText(dialog.about || dialog.bio || '', 2400),
	      bio: cleanText(dialog.bio || dialog.about || '', 2400),
	      birthday: cleanText(dialog.birthday || dialog.birthDate || '', 120),
      statusText: cleanText(dialog.statusText || '', 120),
      statusKind: cleanText(dialog.statusKind || '', 120),
      presence: dialog.presence && typeof dialog.presence === 'object' ? dialog.presence : null,
      isDirect: telegramType === 'direct',
      isArchived: dialog.isArchived === true
    });
  }

  function buildTelegramDialogCollections(dialogs = []) {
    const active = [];
    const archived = [];
    (Array.isArray(dialogs) ? dialogs : []).forEach((dialog) => {
      const entry = normalizeTelegramDialogForSidebar(dialog);
      if (!entry) return;
      if (isTelegramDialogLocallyLeft(entry.chatId)) return;
      if (dialog?.isArchived === true || entry.isArchived === true) {
        archived.push(entry);
      } else {
        active.push(entry);
      }
    });
    return {
      active: sanitizeRecentCollection(active),
      archived: sanitizeRecentCollection(archived)
    };
  }

  function pruneTelegramLeftDialogTombstones() {
    if (!(runtime.telegramLeftDialogTombstonesByChatId instanceof Map)) {
      runtime.telegramLeftDialogTombstonesByChatId = new Map();
      return;
    }
    const expiresBefore = now() - 24 * 60 * 60 * 1000;
    runtime.telegramLeftDialogTombstonesByChatId.forEach((createdAt, chatId) => {
      if (!chatId || Number(createdAt || 0) < expiresBefore) {
        runtime.telegramLeftDialogTombstonesByChatId.delete(chatId);
      }
    });
  }

  function isTelegramDialogLocallyLeft(chatId = '') {
    const normalizedChatId = normalizeChatId(chatId || '');
    if (!normalizedChatId) return false;
    pruneTelegramLeftDialogTombstones();
    if (runtime.telegramLeftDialogTombstonesByChatId.has(normalizedChatId)) {
      return true;
    }
    for (const leftChatId of runtime.telegramLeftDialogTombstonesByChatId.keys()) {
      if (chatIdsAreEquivalent(leftChatId, normalizedChatId)) return true;
    }
    return false;
  }

  function markTelegramDialogLocallyLeft(chatId = '') {
    const normalizedChatId = normalizeChatId(chatId || '');
    if (!normalizedChatId) return false;
    pruneTelegramLeftDialogTombstones();
    runtime.telegramLeftDialogTombstonesByChatId.set(normalizedChatId, now());
    return true;
  }

  function buildTelegramNotificationSnapshot(entry = null) {
    if (!entry || typeof entry !== 'object') return null;
    const chatId = normalizeChatId(entry.chatId || '');
    if (!chatId) return null;
    const previewMessageId = String(entry.previewMessageId || '').trim();
    const previewTimestamp = Math.max(0, Number(entry.previewTimestamp || entry.updatedAt || 0) || 0);
    const previewText = cleanText(entry.previewText || '', 260);
    const previewAuthor = cleanText(entry.previewAuthor || '', 140);
    const previewAuthorMemberId = String(entry.previewAuthorMemberId || '').trim();
    const unreadCount = Math.max(0, resolveEntryUnreadCount(entry));
    const sourceMode = cleanText(entry.sourceMode || entry.rawChat?.sourceMode || '', 40).toLowerCase();
    const key = [
      previewMessageId,
      String(previewTimestamp),
      normalizeText(previewAuthor),
      normalizeText(previewText),
      entry.previewIsMine === true ? 'mine' : 'incoming'
    ].join('\u0001');
    return {
      chatId,
      key,
      previewMessageId,
      previewTimestamp,
      previewText,
      previewAuthor,
      previewAuthorMemberId,
      previewIsMine: entry.previewIsMine === true,
      sourceMode,
      unreadCount
    };
  }

  function pruneTelegramNotificationSnapshots(currentChatIds = []) {
    const keep = new Set(
      (Array.isArray(currentChatIds) ? currentChatIds : [])
        .map((value) => normalizeChatId(value || ''))
        .filter(Boolean)
    );
    runtime.telegramNotificationSnapshotByChatId.forEach((_snapshot, chatId) => {
      if (!keep.has(chatId)) {
        runtime.telegramNotificationSnapshotByChatId.delete(chatId);
      }
    });
    while (runtime.telegramNotificationSnapshotByChatId.size > 260) {
      const oldestKey = runtime.telegramNotificationSnapshotByChatId.keys().next().value;
      if (!oldestKey) break;
      runtime.telegramNotificationSnapshotByChatId.delete(oldestKey);
    }
  }

  function maybeNotifyTelegramDialogUpdates(entries = [], options = {}) {
    const safeEntries = (Array.isArray(entries) ? entries : []).filter(Boolean);
    const snapshotsWerePrimed = runtime.telegramNotificationSnapshotsPrimed === true;
    const notificationsEnabled = normalizeSystemNotificationSettings(state.systemNotifications).telegram !== false;
    const currentChatIds = [];

    safeEntries.forEach((entry) => {
      const snapshot = buildTelegramNotificationSnapshot(entry);
      if (!snapshot) return;
      currentChatIds.push(snapshot.chatId);
      const previous = runtime.telegramNotificationSnapshotByChatId.get(snapshot.chatId) || null;
      runtime.telegramNotificationSnapshotByChatId.set(snapshot.chatId, snapshot);

      if (!snapshotsWerePrimed || !notificationsEnabled || options?.suppressNotifications === true) return;
      if (!previous || previous.key === snapshot.key) return;
      if (snapshot.previewIsMine) return;
      if (!snapshot.previewText) return;
      if (snapshot.unreadCount <= 0 && snapshot.unreadCount <= Math.max(0, Number(previous.unreadCount || 0))) return;
      if (
        snapshot.previewTimestamp > 0
        && previous.previewTimestamp > 0
        && snapshot.previewTimestamp < previous.previewTimestamp
      ) {
        return;
      }
      if (
        snapshot.previewTimestamp > 0
        && previous.previewTimestamp > 0
        && snapshot.previewTimestamp === previous.previewTimestamp
        && snapshot.unreadCount <= Math.max(0, Number(previous.unreadCount || 0))
      ) {
        return;
      }

      const isDirectMessage = isDirectChatEntry(entry);
      const authorName = cleanText(
        snapshot.previewAuthor
        || (isDirectMessage ? getRenderableEntryTitle(entry) || entry.title || '' : '')
        || getRenderableEntryTitle(entry)
        || entry.title
        || 'Telegram',
        140
      );
      const payload = buildAppNotificationPayload({
        workspaceId: 'telegram',
        chatId: snapshot.chatId,
        fallbackTitle: getRenderableEntryTitle(entry) || entry.title || 'Telegram',
        channelTitle: getRenderableEntryTitle(entry) || entry.title || 'Telegram',
        authorName,
        authorMemberId: snapshot.previewAuthorMemberId,
        authorAvatarUrl: normalizeAssetUrl(
          entry.previewAuthorAvatarUrl
          || (isDirectMessage ? entry.avatarUrl || entry.avatarResourceUrl || '' : ''),
          4096
        ),
        body: snapshot.previewText,
        messageId: snapshot.previewMessageId,
        isDirectMessage
      });
      if (!shouldSkipRealtimeNotification(snapshot.chatId, payload.title, payload.body, {
        workspaceId: 'telegram',
        authorMemberId: snapshot.previewAuthorMemberId,
        authorName,
        isOutgoing: false
      })) {
        notifyFromApp(payload);
      }
    });

    runtime.telegramNotificationSnapshotsPrimed = true;
    pruneTelegramNotificationSnapshots(currentChatIds);
  }

  async function refreshTelegramIntegrationState(options = {}) {
    try {
      const response = await ipcRenderer.invoke('yuchat-telegram-state', getTelegramIpcPayload());
      state.telegramStatus = response && typeof response === 'object' ? response : null;
      state.telegramError = response?.ok === false ? cleanText(response?.error || 'Telegram недоступен', 220) : '';
      if (options.render !== false) {
        scheduleRender(resolveInteractiveRenderScopes({
          includeOverlaysIfVisible: true
        }));
      }
      return state.telegramStatus;
    } catch (error) {
      state.telegramError = cleanText(error?.message || 'Telegram недоступен', 220);
      if (options.render !== false) {
        scheduleRender('sidebar');
      }
      return null;
    }
  }

  function getTelegramDialogPreviewRefreshKey(entry = null) {
    if (!entry || typeof entry !== 'object') return '';
    return [
      normalizeChatId(entry.chatId || ''),
      String(entry.previewMessageId || '').trim(),
      cleanText(entry.previewText || '', 240),
      cleanText(entry.previewAttachment || '', 120),
      entry.previewIsMine === true ? 'mine' : 'their',
      entry.previewIsSystem === true ? 'system' : 'regular',
      Math.max(0, Number(entry.previewTimestamp || entry.updatedAt || 0) || 0)
    ].join('\u0001');
  }

  function findTelegramDialogSnapshotByChatId(dialogs = [], chatId = '') {
    const normalizedChatId = normalizeChatId(chatId || '');
    if (!normalizedChatId) return null;
    return (Array.isArray(dialogs) ? dialogs : []).find((entry) => (
      entry
      && typeof entry === 'object'
      && chatIdsAreEquivalent(entry.chatId || '', normalizedChatId)
    )) || null;
  }

  function maybeRefreshActiveTelegramMessagesAfterDialogRefresh(previousDialogs = [], nextDialogs = [], options = {}) {
    const activeWorkspaceId = String(state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
    const activeChatId = normalizeChatId(state.activeChatId || '');
    if (activeWorkspaceId !== 'telegram' || !activeChatId) return false;
    const previousEntry = findTelegramDialogSnapshotByChatId(previousDialogs, activeChatId);
    const nextEntry = findTelegramDialogSnapshotByChatId(nextDialogs, activeChatId);
    if (!nextEntry) return false;
    const previousKey = getTelegramDialogPreviewRefreshKey(previousEntry);
    const nextKey = getTelegramDialogPreviewRefreshKey(nextEntry);
    if (previousKey && previousKey === nextKey && options.forceActiveMessagesRefresh !== true) {
      return false;
    }
    const chatKey = getChatStateKey('telegram', activeChatId);
    const existing = state.messagesByChatKey?.[chatKey] || {};
    const loadedCount = Math.max(
      MESSAGE_PAGE_STEP,
      Math.min(MESSAGE_PAGE_MAX, Number(existing.loadedCount || 0) || MESSAGE_PAGE_STEP)
    );
    window.setTimeout(() => {
      const currentWorkspaceId = String(state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
      const currentChatId = normalizeChatId(state.activeChatId || '');
      if (currentWorkspaceId !== 'telegram' || !chatIdsAreEquivalent(currentChatId, activeChatId)) return;
      void refreshActiveChatMessages({
        force: options.forceActiveMessagesRefresh === true,
        reason: 'telegram_dialog_preview_update',
        suppressLoadingState: true,
        count: loadedCount,
        deltaCount: Math.max(40, MESSAGE_PASSIVE_DELTA_COUNT)
      }).catch(() => {});
    }, Math.max(30, Math.min(900, Number(options.activeRefreshDelayMs || 80) || 80)));
    return true;
  }

  function scheduleTelegramExternalSync(options = {}) {
    const delays = Array.isArray(options.delays) && options.delays.length
      ? options.delays
      : [90, 900, 2600];
    delays.forEach((delay) => {
      window.setTimeout(() => {
        void refreshTelegramDialogs({
          silent: true,
          force: options.force === true,
          forceActiveMessagesRefresh: options.forceActiveMessagesRefresh === true,
          activeRefreshDelayMs: options.activeRefreshDelayMs || 60
        }).catch(() => {});
        const activeWorkspaceId = String(state.activeChatWorkspaceId || getActiveWorkspaceId() || '').trim();
        const activeChatId = normalizeChatId(state.activeChatId || '');
        if (activeWorkspaceId === 'telegram' && activeChatId) {
          void refreshActiveChatMessages({
            force: options.forceActiveMessagesRefresh === true,
            reason: cleanText(options.reason || 'telegram_realtime_update', 80),
            suppressLoadingState: true,
            deltaCount: Math.max(40, MESSAGE_PASSIVE_DELTA_COUNT)
          }).catch(() => {});
        }
      }, Math.max(0, Number(delay || 0) || 0));
    });
  }

  async function refreshTelegramDialogs(options = {}) {
    const settings = normalizeTelegramIntegrationSettings(state.telegramIntegration);
    if (settings.enabled !== true || settings.showInSidebar === false) {
      state.telegramDialogs = [];
      ensureTelegramWorkspace();
      return [];
    }
    if (runtime.telegramDialogsRefreshPromise && options.force !== true) {
      return runtime.telegramDialogsRefreshPromise;
    }
    ensureTelegramWorkspace();
    state.telegramLoading = true;
    state.telegramError = '';
    state.recentsLoadingByWorkspace.telegram = true;
    if (options.silent !== true) {
      scheduleRender(['sidebar']);
    }

    const request = (async () => {
      try {
        const previousTelegramDialogs = Array.isArray(state.telegramDialogs)
          ? state.telegramDialogs.slice()
          : [];
        const response = await ipcRenderer.invoke('yuchat-telegram-list-dialogs', {
          ...getTelegramIpcPayload(),
          limit: Math.max(20, Math.min(200, Number(options.limit || 90) || 90))
        });
        if (!response || typeof response !== 'object' || response.ok === false) {
          state.telegramStatus = response && typeof response === 'object' ? response : state.telegramStatus;
          state.telegramError = cleanText(response?.error || 'Telegram не авторизован или недоступен', 240);
          state.recentsByWorkspace.telegram = [];
          state.archivedRecentsByWorkspace.telegram = [];
          runtime.recentsStateVersion += 1;
          invalidateRecentsDerivedCache();
          return [];
        }
        state.telegramStatus = {
          ...(state.telegramStatus || {}),
          ...response,
          authorized: response.authorized !== false,
          connected: true
        };
        state.telegramError = '';
        const dialogs = Array.isArray(response.dialogs)
          ? response.dialogs
          : (Array.isArray(response.items) ? response.items : []);
        const collections = buildTelegramDialogCollections(dialogs);
        state.telegramDialogs = [...collections.active, ...collections.archived];
        state.recentsByWorkspace.telegram = collections.active;
        state.archivedRecentsByWorkspace.telegram = collections.archived;
        maybeNotifyTelegramDialogUpdates(state.telegramDialogs, options);
        maybeRefreshActiveTelegramMessagesAfterDialogRefresh(previousTelegramDialogs, state.telegramDialogs, options);
        state.recentsLoadedAtByWorkspace.telegram = now();
        state.telegramLastSyncedAt = Number(response.loadedAt || 0) || now();
        runtime.recentsStateVersion += 1;
        invalidateRecentsDerivedCache();
        return state.telegramDialogs;
      } catch (error) {
        state.telegramError = cleanText(error?.message || 'Не удалось загрузить Telegram', 240);
        return [];
      } finally {
        state.telegramLoading = false;
        state.recentsLoadingByWorkspace.telegram = false;
        runtime.telegramDialogsRefreshPromise = null;
        scheduleRender(resolveInteractiveRenderScopes({
          includeOverlaysIfVisible: true
        }));
      }
    })();

    runtime.telegramDialogsRefreshPromise = request;
    return request;
  }

  function maybeAutoRefreshTelegramDialogs() {
    if (!shouldShowTelegramInSidebar()) return false;
    if (runtime.telegramDialogsRefreshPromise || state.telegramLoading === true) return false;
    const currentTs = now();
    const lastSyncedAt = Number(state.telegramLastSyncedAt || 0);
    const lastAttemptAt = Number(runtime.telegramAutoRefreshStartedAt || 0);
    if (lastSyncedAt && currentTs - lastSyncedAt < 120000) return false;
    if (lastAttemptAt && currentTs - lastAttemptAt < 30000) return false;
    runtime.telegramAutoRefreshStartedAt = currentTs;
    void refreshTelegramDialogs({ silent: true }).catch(() => {});
    return true;
  }

  function shouldShowTrueconfInSidebar() {
    return false;
  }

  function ensureTrueconfWorkspace() {
    const showTrueconf = shouldShowTrueconfInSidebar();
    const workspaceList = Array.isArray(state.workspaces) ? state.workspaces : [];
    const hasTrueconfWorkspace = workspaceList.some((workspace) => String(workspace?.workspaceId || '').trim() === 'trueconf');
    if (showTrueconf && !hasTrueconfWorkspace) {
      state.workspaces = [
        ...workspaceList,
        {
          workspaceId: 'trueconf',
          title: 'TrueConf',
          isTrueconf: true,
          synthetic: true
        }
      ];
      runtime.trueconfWorkspaceVisible = true;
      runtime.recentsStateVersion += 1;
      invalidateRecentsDerivedCache();
      return true;
    }
    if (!showTrueconf && hasTrueconfWorkspace) {
      state.workspaces = workspaceList.filter((workspace) => String(workspace?.workspaceId || '').trim() !== 'trueconf');
      delete state.recentsByWorkspace.trueconf;
      delete state.archivedRecentsByWorkspace.trueconf;
      delete state.recentsLoadingByWorkspace.trueconf;
      delete state.recentsLoadedAtByWorkspace.trueconf;
      if (String(state.activeChatWorkspaceId || '').trim() === 'trueconf') {
        state.activeChatWorkspaceId = '';
        state.activeChatId = '';
        state.activeChatTitle = '';
        closeThreadPanel();
      }
      runtime.trueconfWorkspaceVisible = false;
      runtime.recentsStateVersion += 1;
      invalidateRecentsDerivedCache();
      return true;
    }
    runtime.trueconfWorkspaceVisible = showTrueconf;
    return false;
  }

  function normalizeTrueconfDialogForSidebar(dialog = null) {
    if (!dialog || typeof dialog !== 'object') return null;
    const chatId = normalizeChatId(dialog.chatId || dialog.id || '');
    if (!chatId) return null;
    const title = cleanText(dialog.title || dialog.name || 'TrueConf', 180) || 'TrueConf';
    const trueconfType = cleanText(dialog.trueconfType || dialog.type || '', 40).toLowerCase() || 'chat';
    return sanitizeRecentEntry({
      ...dialog,
      workspaceId: 'trueconf',
      workspaceTitle: 'TrueConf',
      chatId,
      title,
      searchText: [
        title,
        cleanText(dialog.previewAuthor || '', 120),
        cleanText(dialog.previewText || '', 220),
        'TrueConf',
        'Труконф',
        trueconfType
      ].filter(Boolean).join(' '),
      avatarUrl: normalizeAssetUrl(dialog.avatarUrl || '', 4096),
      unreadCount: Math.max(0, Number(dialog.unreadCount || dialog.unreadMessages || 0)),
      previewText: cleanText(dialog.previewText || '', 220),
      previewAuthor: cleanText(dialog.previewAuthor || '', 120),
      previewAuthorMemberId: cleanText(dialog.previewAuthorMemberId || '', 180),
      previewMessageId: String(dialog.previewMessageId || '').trim(),
      previewIsMine: dialog.previewIsMine === true,
      previewTimestamp: Math.max(0, Number(dialog.previewTimestamp || dialog.updatedAt || 0) || 0),
      updatedAt: Math.max(0, Number(dialog.updatedAt || dialog.previewTimestamp || 0) || 0),
      memberIds: Array.isArray(dialog.memberIds) ? dialog.memberIds : [],
      directMemberId: cleanText(dialog.directMemberId || '', 180),
      isDirect: dialog.isDirect === true || trueconfType === 'direct',
      isTrueconf: true,
      trueconfType,
      type: trueconfType,
      sourceLabel: 'TrueConf',
      rawChat: {
        ...(dialog.rawChat && typeof dialog.rawChat === 'object' ? dialog.rawChat : dialog),
        source: 'trueconf',
        trueconfType
      }
    });
  }

  async function refreshTrueconfIntegrationState(options = {}) {
    try {
      const response = await ipcRenderer.invoke('yuchat-trueconf-chat-state', getTrueconfIpcPayload({ forceEnabled: true }));
      state.trueconfStatus = response && typeof response === 'object' ? response : null;
      state.trueconfError = response?.ok === false ? cleanText(response?.error || 'TrueConf недоступен', 220) : '';
      if (options.render !== false) {
        scheduleRender(resolveInteractiveRenderScopes({
          includeOverlaysIfVisible: true
        }));
      }
      return state.trueconfStatus;
    } catch (error) {
      state.trueconfError = cleanText(error?.message || 'TrueConf недоступен', 220);
      if (options.render !== false) {
        scheduleRender('sidebar');
      }
      return null;
    }
  }

  async function refreshTrueconfDialogs(options = {}) {
    const settings = normalizeTrueconfIntegrationSettings(state.trueconfIntegration);
    if (settings.enabled !== true || settings.showInSidebar !== true) {
      state.trueconfDialogs = [];
      ensureTrueconfWorkspace();
      return [];
    }
    if (runtime.trueconfDialogsRefreshPromise && options.force !== true) {
      return runtime.trueconfDialogsRefreshPromise;
    }
    ensureTrueconfWorkspace();
    state.trueconfLoading = true;
    state.trueconfError = '';
    state.recentsLoadingByWorkspace.trueconf = true;
    if (options.silent !== true) {
      scheduleRender(['sidebar']);
    }

    const request = (async () => {
      try {
        const response = await ipcRenderer.invoke('yuchat-trueconf-list-chats', {
          ...getTrueconfIpcPayload({ forceEnabled: true }),
          limit: Math.max(20, Math.min(200, Number(options.limit || 90) || 90))
        });
        if (!response || typeof response !== 'object' || response.ok === false) {
          state.trueconfStatus = response && typeof response === 'object' ? response : state.trueconfStatus;
          state.trueconfError = cleanText(response?.error || 'TrueConf не авторизован или недоступен', 240);
          state.recentsByWorkspace.trueconf = [];
          state.archivedRecentsByWorkspace.trueconf = [];
          runtime.recentsStateVersion += 1;
          invalidateRecentsDerivedCache();
          return [];
        }
        state.trueconfStatus = {
          ...(state.trueconfStatus || {}),
          ...response,
          authorized: true,
          connected: true
        };
        state.trueconfError = '';
        const dialogs = Array.isArray(response.dialogs)
          ? response.dialogs
          : (Array.isArray(response.chats) ? response.chats : []);
        const normalizedDialogs = sanitizeRecentCollection(
          dialogs.map((dialog) => normalizeTrueconfDialogForSidebar(dialog)).filter(Boolean)
        );
        state.trueconfDialogs = normalizedDialogs;
        state.recentsByWorkspace.trueconf = normalizedDialogs;
        state.archivedRecentsByWorkspace.trueconf = [];
        state.recentsLoadedAtByWorkspace.trueconf = now();
        state.trueconfLastSyncedAt = Number(response.loadedAt || 0) || now();
        runtime.recentsStateVersion += 1;
        invalidateRecentsDerivedCache();
        return state.trueconfDialogs;
      } catch (error) {
        state.trueconfError = cleanText(error?.message || 'Не удалось загрузить TrueConf', 240);
        return [];
      } finally {
        state.trueconfLoading = false;
        state.recentsLoadingByWorkspace.trueconf = false;
        runtime.trueconfDialogsRefreshPromise = null;
        scheduleRender(resolveInteractiveRenderScopes({
          includeOverlaysIfVisible: true
        }));
      }
    })();

    runtime.trueconfDialogsRefreshPromise = request;
    return request;
  }

  function maybeAutoRefreshTrueconfDialogs() {
    if (!shouldShowTrueconfInSidebar()) return false;
    if (runtime.trueconfDialogsRefreshPromise || state.trueconfLoading === true) return false;
    const currentTs = now();
    const lastSyncedAt = Number(state.trueconfLastSyncedAt || 0);
    const lastAttemptAt = Number(runtime.trueconfAutoRefreshStartedAt || 0);
    if (lastSyncedAt && currentTs - lastSyncedAt < 120000) return false;
    if (lastAttemptAt && currentTs - lastAttemptAt < 30000) return false;
    runtime.trueconfAutoRefreshStartedAt = currentTs;
    void refreshTrueconfDialogs({ silent: true }).catch(() => {});
    return true;
  }

  function shouldShowMaxInSidebar() {
    return false;
  }

  function ensureMaxWorkspace() {
    const workspaceList = Array.isArray(state.workspaces) ? state.workspaces : [];
    const hadMaxWorkspace = workspaceList.some((workspace) => String(workspace?.workspaceId || '').trim() === 'max');
    delete state.recentsByWorkspace.max;
    delete state.archivedRecentsByWorkspace.max;
    delete state.recentsLoadingByWorkspace.max;
    delete state.recentsLoadedAtByWorkspace.max;
    if (!hadMaxWorkspace) return false;
    state.workspaces = workspaceList.filter((workspace) => String(workspace?.workspaceId || '').trim() !== 'max');
    if (String(state.activeChatWorkspaceId || '').trim() === 'max') {
      state.activeChatWorkspaceId = '';
      state.activeChatId = '';
      state.activeChatTitle = '';
      closeThreadPanel();
    }
    runtime.recentsStateVersion += 1;
    invalidateRecentsDerivedCache();
    return true;
  }

  async function refreshMaxDialogs() {
    ensureMaxWorkspace();
    return [];
  }

  function maybeAutoRefreshMaxDialogs() {
    return false;
  }

  function normalizeMaxMemberIdForUi() {
    return '';
  }

  function normalizeMaxDialogForSidebar() {
    return null;
  }


  function rememberRealtimeMessageId(messageId = '') {
    const value = String(messageId || '').trim();
    if (!value) return false;
    if (runtime.seenRealtimeMessageIds.has(value)) {
      return false;
    }
    runtime.seenRealtimeMessageIds.add(value);
    if (runtime.seenRealtimeMessageIds.size > 4000) {
      const oldest = runtime.seenRealtimeMessageIds.values().next().value;
      if (oldest) {
        runtime.seenRealtimeMessageIds.delete(oldest);
      }
    }
    return true;
  }

  function cycleThemeMode() {
    state.themeMode = normalizeThemeChoice(state.themeMode) === 'dark' ? 'light' : 'dark';
    saveUiPreferences();
  }

  function getThemeModeLabel(mode = 'light') {
    const value = normalizeThemeChoice(mode);
    if (value === 'dark') return 'Тёмная';
    if (value === 'light') return 'Светлая';
    return 'Светлая';
  }

  function getMessengerShellModeLabel(mode = WINDOW_MODE_NORMAL) {
    return normalizeWindowMode(mode) === WINDOW_MODE_MESSENGER ? 'Выпадающий' : 'Обычный';
  }

  function normalizeMessengerShellOpacity(value = DEFAULT_MESSENGER_OPACITY) {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) {
      return DEFAULT_MESSENGER_OPACITY;
    }
    return Math.min(
      MAX_MESSENGER_OPACITY,
      Math.max(MIN_MESSENGER_OPACITY, Math.round(numeric * 100) / 100)
    );
  }

  function normalizeMessengerShellAnimationDuration(value = DEFAULT_MESSENGER_ANIMATION_DURATION_MS) {
    const numeric = Math.round(Number(value) || 0);
    if (!Number.isFinite(numeric) || numeric <= 0) {
      return DEFAULT_MESSENGER_ANIMATION_DURATION_MS;
    }
    return Math.min(
      MAX_MESSENGER_ANIMATION_DURATION_MS,
      Math.max(MIN_MESSENGER_ANIMATION_DURATION_MS, numeric)
    );
  }

  function getTransparencyPercentFromOpacity(value = DEFAULT_MESSENGER_OPACITY) {
    const opacity = normalizeMessengerShellOpacity(value);
    const range = MAX_MESSENGER_OPACITY - MIN_MESSENGER_OPACITY;
    if (!(range > 0)) return 0;
    return Math.round(((MAX_MESSENGER_OPACITY - opacity) / range) * 100);
  }

  function formatOpacityPercent(value = DEFAULT_MESSENGER_OPACITY) {
    return `${getTransparencyPercentFromOpacity(value)}%`;
  }

  function formatMessengerAnimationDuration(value = DEFAULT_MESSENGER_ANIMATION_DURATION_MS) {
    return `${normalizeMessengerShellAnimationDuration(value)} мс`;
  }

  function formatShortcutDisplayLabel(shortcut = '') {
    const normalized = normalizeShortcut(shortcut || '');
    if (!normalized) return 'Не задано';
    const labelMap = new Map([
      ['cmd', 'Cmd'],
      ['ctrl', 'Ctrl'],
      ['alt', 'Alt'],
      ['shift', 'Shift'],
      ['space', 'Space'],
      ['esc', 'Esc'],
      ['up', 'Up'],
      ['down', 'Down'],
      ['left', 'Left'],
      ['right', 'Right'],
      ['tab', 'Tab'],
      ['enter', 'Enter']
    ]);
    return normalized
      .split('+')
      .map((part) => {
        const token = String(part || '').trim().toLowerCase();
        if (!token) return '';
        if (labelMap.has(token)) {
          return labelMap.get(token);
        }
        if (token.length === 1) {
          return token.toUpperCase();
        }
        return token.charAt(0).toUpperCase() + token.slice(1);
      })
      .filter(Boolean)
      .join(' + ');
  }

  function isValidCapturedShortcut(shortcut = '') {
    const normalized = normalizeShortcut(shortcut || '');
    if (!normalized) return false;
    const tokens = normalized.split('+').filter(Boolean);
    if (!tokens.length) return false;
    const lastToken = String(tokens[tokens.length - 1] || '').trim().toLowerCase();
    return !['cmd', 'ctrl', 'alt', 'shift', 'meta', 'control', 'option'].includes(lastToken);
  }

  function applyWindowShellStateSnapshot(payload = {}, options = {}) {
    const nextMode = normalizeWindowMode(payload?.mode || state.messengerShellMode || WINDOW_MODE_NORMAL);
    const nextShortcut = normalizeShortcut(
      payload?.shortcut
      || state.messengerShellShortcut
      || DEFAULT_MESSENGER_SHORTCUT
    ) || DEFAULT_MESSENGER_SHORTCUT;
    const nextOpacity = normalizeMessengerShellOpacity(
      payload?.opacity
      ?? state.messengerShellOpacity
      ?? DEFAULT_MESSENGER_OPACITY
    );
    let changed = false;
    if (state.messengerShellMode !== nextMode) {
      state.messengerShellMode = nextMode;
      changed = true;
    }
    if (state.messengerShellShortcut !== nextShortcut) {
      state.messengerShellShortcut = nextShortcut;
      changed = true;
    }
    if (state.messengerShellOpacity !== nextOpacity) {
      state.messengerShellOpacity = nextOpacity;
      changed = true;
    }
    if (changed && options.persist !== false) {
      saveUiPreferences();
    }
    if (refs.root instanceof HTMLElement) {
      applyRootAppearance();
    }
    if (state.appearanceOverlayOpen === true && state.appearanceOverlayMode === 'font') {
      renderAppearanceOverlay();
    }
    if (changed && options.scheduleRender !== false) {
      scheduleRender(['sidebar', 'overlays']);
    }
    return changed;
  }

  async function syncWindowShellStateFromMain(options = {}) {
    if (!ipcRenderer || typeof ipcRenderer.invoke !== 'function') return false;
    try {
      const payload = await ipcRenderer.invoke('yuchat-window-shell-get');
      return applyWindowShellStateSnapshot(payload, options);
    } catch {
      return false;
    }
  }

  async function toggleMessengerShellModeFromUi() {
    if (!ipcRenderer || typeof ipcRenderer.invoke !== 'function') return { ok: false, reason: 'ipc-unavailable' };
    const result = await ipcRenderer.invoke('yuchat-window-shell-toggle-mode');
    if (result?.state) {
      applyWindowShellStateSnapshot(result.state, { persist: true, scheduleRender: true });
    }
    return result && typeof result === 'object'
      ? result
      : { ok: false, reason: 'unknown', state: null };
  }

  async function saveMessengerShellShortcut(nextShortcut = '') {
    if (!ipcRenderer || typeof ipcRenderer.invoke !== 'function') {
      return { ok: false, reason: 'ipc-unavailable' };
    }
    const normalizedShortcut = normalizeShortcut(nextShortcut || '');
    if (!normalizedShortcut) {
      return { ok: false, reason: 'shortcut-empty' };
    }
    const result = await ipcRenderer.invoke('yuchat-window-shell-set-shortcut', {
      shortcut: normalizedShortcut
    });
    if (result?.state) {
      applyWindowShellStateSnapshot(result.state, { persist: true, scheduleRender: true });
    }
    return result && typeof result === 'object'
      ? result
      : { ok: false, reason: 'unknown', state: null };
  }

  async function saveMessengerShellOpacity(nextOpacity = DEFAULT_MESSENGER_OPACITY) {
    if (!ipcRenderer || typeof ipcRenderer.invoke !== 'function') {
      return { ok: false, reason: 'ipc-unavailable' };
    }
    const normalizedOpacity = normalizeMessengerShellOpacity(nextOpacity);
    const result = await ipcRenderer.invoke('yuchat-window-shell-set-opacity', {
      opacity: normalizedOpacity
    });
    if (result?.state) {
      applyWindowShellStateSnapshot(result.state, { persist: true, scheduleRender: true });
    }
    return result && typeof result === 'object'
      ? result
      : { ok: false, reason: 'unknown', state: null };
  }

  async function syncWindowShellStateToMain() {
    if (!ipcRenderer || typeof ipcRenderer.invoke !== 'function') return false;
    const desiredShortcut = normalizeShortcut(state.messengerShellShortcut || DEFAULT_MESSENGER_SHORTCUT) || DEFAULT_MESSENGER_SHORTCUT;
    const desiredOpacity = normalizeMessengerShellOpacity(state.messengerShellOpacity);
    try {
      const remoteState = await ipcRenderer.invoke('yuchat-window-shell-get');
      applyWindowShellStateSnapshot(remoteState, { persist: false, scheduleRender: false });
      if (normalizeShortcut(remoteState?.shortcut || '') !== desiredShortcut) {
        await saveMessengerShellShortcut(desiredShortcut);
      }
      if (normalizeMessengerShellOpacity(remoteState?.opacity ?? DEFAULT_MESSENGER_OPACITY) !== desiredOpacity) {
        await saveMessengerShellOpacity(desiredOpacity);
      }
    } catch {
      return false;
    }
    return true;
  }

  async function hydrateCurrentProfileForSettings() {
    const workspaceId = String(getCurrentProfileWorkspaceId() || '').trim();
    const memberId = String(getCurrentProfileMemberId() || '').trim();
    if (!workspaceId || !memberId) return false;
    if (workspaceId.toLowerCase() === 'telegram' || workspaceId.toLowerCase() === 'max') return false;
    await Promise.allSettled([
      ensureWorkspaceMembers(workspaceId, [memberId], '', {
        requireAvatar: true,
        requireStatus: true
      }),
      ensureProfiles([memberId])
    ]);
    if (state.sidebarMode === 'profile' && !state.profileSettingsDirty) {
      ensureProfileSettingsDraft({ force: true, clearError: false });
      if (runtime.profileSettingsMarkupCacheBySignature instanceof Map) {
        runtime.profileSettingsMarkupCacheBySignature.clear();
      }
    }
    scheduleRender('sidebar');
    return true;
  }

  function requestCurrentProfileHydrationForSettings() {
    if (state.sidebarMode !== 'profile') return;
    const workspaceId = String(getCurrentProfileWorkspaceId() || '').trim();
    const memberId = String(getCurrentProfileMemberId() || '').trim();
    if (!workspaceId || !memberId) return;
    if (workspaceId.toLowerCase() === 'telegram' || workspaceId.toLowerCase() === 'max') return;
    const profile = getKnownProfileByMemberId(memberId) || null;
    const needsHydration = !profile
      || !getProfileDisplayName(profile)
      || !getProfileAvatarUrl(profile);
    if (!needsHydration && state.profileSettingsDraft && typeof state.profileSettingsDraft === 'object') return;
    const requestKey = [
      workspaceId,
      memberId,
      Number(runtime.knownProfileVersion || 0),
      state.profileSettingsDirty ? 'dirty' : 'clean'
    ].join('\u0001');
    if (runtime.profileSettingsHydrationKey === requestKey) return;
    runtime.profileSettingsHydrationKey = requestKey;
    void hydrateCurrentProfileForSettings().catch(() => {});
  }

  function setSidebarMode(mode = 'chats') {
    const nextMode = normalizeSidebarMode(mode);
    const changed = state.sidebarMode !== nextMode;
    if (!changed) return false;

    state.sidebarMode = nextMode;
    if (nextMode === 'meetings') {
      runtime.calendarEventsDay = 'today';
      runtime.calendarEventsSectionCollapsed = null;
    }
    if (nextMode !== 'profile') {
      state.profileLocalStatusEmojiPickerOpen = false;
    }
    if (nextMode !== 'chats') {
      runtime.todoAppletOpen = false;
    }
    if (nextMode === 'contacts') {
      void ensureContactsDirectoryLoaded({ force: false, scheduleRender: false });
    } else if (nextMode === 'profile') {
      ensureProfileSettingsDraft({ force: true });
      void hydrateCurrentProfileForSettings();
    }
    resetDialogsListScrollToTop({
      preserveCurrentContext: true
    });
    saveUiPreferences();
    return true;
  }

  function openProfileSettingsSidebar() {
    const sidebarChanged = setSidebarMode('profile');
    const tabChanged = selectProfileSettingsTab('profile');
    void hydrateCurrentProfileForSettings();
    if (sidebarChanged && !tabChanged) {
      scheduleRender('sidebar');
    }
    return sidebarChanged || tabChanged;
  }

  function openNativeProfileSurface() {
    runtime.nativeSurfaceMode = '';
    document.body?.classList.remove('yc-native-profile-open');
    showTemporaryStatus('Штатный YuChat отключён в этой сборке');
    return false;
  }

  function applyRootAppearance() {
    if (!(refs.root instanceof HTMLElement)) return;
    const resolvedTheme = getResolvedThemeChoice();
    const railVisible = isSidebarRailAvailable();
    const railCollapsed = railVisible && Boolean(state.sidebarRailCollapsed);
    const foldersTopMode = normalizeFoldersPanelPosition(state.foldersPanelPosition) === 'top';
    refs.root.classList.toggle('yc-theme-dark', resolvedTheme === 'dark');
    refs.root.classList.toggle('yc-theme-light', resolvedTheme !== 'dark');
    refs.root.classList.toggle('yc-scene-minimal', state.sceneMode === 'minimal');
    refs.root.classList.toggle('yc-scene-colorful', state.sceneMode !== 'minimal');
    refs.root.classList.toggle('yc-stabilizer-wallpaper-active', state.stabilizerWallpaperEnabled === true);
    refs.root.classList.toggle('yc-density-compact', normalizeDensityChoice(state.densityMode) === 'compact');
    refs.root.classList.toggle('yc-density-comfortable', normalizeDensityChoice(state.densityMode) !== 'compact');
    refs.root.classList.toggle('yc-rail-hidden', !railVisible);
    refs.root.classList.toggle('yc-rail-collapsed', railCollapsed);
    refs.root.classList.toggle('yc-folders-top-mode', foldersTopMode);
    refs.root.classList.remove('yc-max-folder-active', 'yc-max-chat-active');
    refs.root.classList.remove('yc-max-surface-active');
    refs.root.classList.remove('yc-todo-applet-expanded');

    if (refs.dialogsRailToggleButton instanceof HTMLButtonElement) {
      const showInlineToggle = railVisible && Boolean(state.sidebarRailCollapsed);
      refs.dialogsRailToggleButton.hidden = !showInlineToggle;
      refs.dialogsRailToggleButton.classList.toggle('is-hidden', !showInlineToggle);
      refs.dialogsRailToggleButton.classList.toggle('is-active', showInlineToggle);
      refs.dialogsRailToggleButton.title = showInlineToggle ? 'Показать панель' : '';
      refs.dialogsRailToggleButton.setAttribute('aria-label', 'Показать панель');
    }

    if (refs.dialogsThemeButton instanceof HTMLElement) {
      refs.dialogsThemeButton.innerHTML = getHeaderThemeIconMarkup();
      refs.dialogsThemeButton.title = `Тема: ${getThemeModeLabel(state.themeMode)}`;
    }
    if (refs.dialogsWallpaperButton instanceof HTMLButtonElement) {
      const wallpaperEnabled = state.stabilizerWallpaperEnabled === true;
      const title = wallpaperEnabled ? 'Вернуть обычный фон чатов' : 'Включить фон стабилизации';
      refs.dialogsWallpaperButton.classList.toggle('is-active', wallpaperEnabled);
      refs.dialogsWallpaperButton.title = title;
      refs.dialogsWallpaperButton.setAttribute('aria-label', title);
      refs.dialogsWallpaperButton.setAttribute('aria-pressed', wallpaperEnabled ? 'true' : 'false');
    }
    if (refs.dialogsFoldersManageButton instanceof HTMLButtonElement) {
      const foldersManageVisible = isProductivityFoldersFeatureEnabled();
      const foldersManageEnabled = foldersManageVisible && state.sidebarMode === 'chats';
      const foldersManageActive = foldersManageEnabled && state.appearanceOverlayOpen === true && state.appearanceOverlayMode === 'folders';
      refs.dialogsFoldersManageButton.hidden = !foldersManageVisible;
      refs.dialogsFoldersManageButton.disabled = !foldersManageEnabled;
      refs.dialogsFoldersManageButton.classList.toggle('is-hidden', !foldersManageVisible);
      refs.dialogsFoldersManageButton.classList.toggle('is-active', foldersManageActive);
      refs.dialogsFoldersManageButton.title = foldersManageEnabled
        ? (foldersManageActive ? 'Закрыть управление папками' : 'Управление папками')
        : 'Папки доступны в списке чатов';
      refs.dialogsFoldersManageButton.setAttribute('aria-label', refs.dialogsFoldersManageButton.title);
    }
    renderDialogsMaxButtons();
    refs.root.style.setProperty('--yc-sidebar-font-scale', String(normalizeFontScale(state.sidebarFontScale)));
    refs.root.style.setProperty('--yc-chat-font-scale', String(normalizeFontScale(state.chatFontScale)));
    refs.root.style.setProperty('--yc-tag-font-scale', String(normalizeFontScale(state.tagFontScale)));
    refs.root.style.setProperty(
      '--yc-sidebar-rail-width',
      `${getSidebarRailEffectiveWidth(Number(window.innerWidth || 0))}px`
    );
    const splitPaneWidth = normalizeActiveSplitPaneWidth(state.splitPaneWidth);
    const maxWebSplitHorizontalHeight = normalizeMaxWebSplitHorizontalHeight(state.maxWebSplitHorizontalHeight);
    const dialogsPaneWidth = normalizeDialogsPaneWidth(state.dialogsPaneWidth);
    refs.root.style.setProperty('--yc-dialogs-pane-width', `${dialogsPaneWidth}px`);
    refs.root.style.setProperty('--yc-split-pane-width', `${splitPaneWidth}px`);
    refs.root.style.setProperty('--yc-split-pane-width-compact', `${splitPaneWidth}px`);
    refs.root.style.setProperty('--yc-max-split-horizontal-height', `${maxWebSplitHorizontalHeight}px`);
    refs.root.style.setProperty('--yc-chat-info-pane-width', `${normalizeChatInfoPaneWidth(state.chatInfoPaneWidth)}px`);
    if (state.patternDataUrl) {
      refs.root.style.setProperty('--yc-pattern-url', `url("${state.patternDataUrl}")`);
    } else {
      refs.root.style.setProperty('--yc-pattern-url', 'none');
    }
  }

  function buildProfileCardMarkup() {
    requestCurrentProfileHydrationForSettings();
    return buildProfileEditorMarkup({ sidebar: true });
  }

  function buildSidebarSettingsModeMarkup(mode = '') {
    const normalizedMode = normalizeSidebarMode(mode || state.sidebarMode);
    if (normalizedMode === 'calendar') {
      return buildCalendarSidebarMarkup();
    }
    if (normalizedMode === 'meetings') {
      return buildMeetingsSidebarMarkup();
    }
    return buildProfileCardMarkup();
  }

  function buildProfileStatusOptionsMarkup(currentValue = '') {
    const normalizedValue = cleanText(currentValue || '', 180);
    const options = PROFILE_STATUS_PRESETS.slice();
    if (normalizedValue && !options.some((item) => item.value === normalizedValue)) {
      options.push({
        value: normalizedValue,
        label: stripStatusEmojiPrefix(normalizedValue) || normalizedValue,
        kind: 'NOT_SET'
      });
    }
    return options.map((item) => {
      const emoji = resolveStatusDisplayEmoji(item.value || '');
      const label = [emoji, item.label].filter(Boolean).join(' ');
      return `<option value="${escapeHtml(item.value || '')}"${item.value === normalizedValue ? ' selected' : ''}>${escapeHtml(label || item.label || 'Без статуса')}</option>`;
    }).join('');
  }

  function buildProfilePlaceholderMarkup(tab = 'profile') {
    const safeTab = normalizeProfileSettingsTab(tab);
    const titles = {
      notifications: 'Уведомления',
      appearance: 'Настройки интерфейса',
      editor: 'Настройки редактора',
      'audio-video': 'Аудио и Видео',
      calls: 'Звонки'
    };
    const descriptions = {
      notifications: 'Этот раздел переносится в кастомную сборку.',
      appearance: 'Размеры текста и внешний вид уже есть в кастомной сборке.',
      editor: 'Параметры редактора скоро перенесем сюда.',
      'audio-video': 'Параметры камеры, микрофона и устройств скоро появятся здесь.',
      calls: 'Параметры звонков скоро появятся здесь.'
    };
    const primaryAction = safeTab === 'appearance'
      ? { id: 'open-font-settings', label: 'Открыть размер текста' }
      : null;
    return `
      <section class="yc-profile-panel">
        <div class="yc-profile-panel-header">
          <div class="yc-profile-panel-title">${escapeHtml(titles[safeTab] || 'Настройки')}</div>
          <div class="yc-profile-panel-subtitle">${escapeHtml(descriptions[safeTab] || 'Раздел скоро появится в кастомной сборке.')}</div>
        </div>
        <div class="yc-profile-placeholder">
          ${primaryAction
            ? `<button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="${escapeHtml(primaryAction.id)}">${escapeHtml(primaryAction.label)}</button>`
            : '<div class="yc-profile-feature-note">Штатный интерфейс отключён, поэтому этот раздел пока недоступен.</div>'}
        </div>
      </section>
    `;
  }

  function extractProfileSessions(response = null) {
    const directCandidates = [
      response?.sessions,
      response?.items,
      response?.list,
      response?.results,
      response?.data?.sessions,
      response?.data?.items,
      response?.result?.sessions,
      response?.result?.items
    ];
    for (const candidate of directCandidates) {
      if (Array.isArray(candidate)) {
        return candidate.filter((item) => item && typeof item === 'object');
      }
    }
    const fallbackArrays = Object.values(response || {})
      .filter((value) => Array.isArray(value))
      .map((value) => value.filter((item) => item && typeof item === 'object'))
      .filter((value) => value.length > 0);
    return fallbackArrays[0] || [];
  }

  function describeProfileSession(session = null, index = 0) {
    const lastActiveAt = timestampFrom(
      session?.lastActivityAt,
      session?.lastSeenAt,
      session?.updatedAt,
      session?.createdAt,
      session?.lastLoginAt
    );
    const current = Boolean(
      session?.current === true
      || session?.isCurrent === true
      || session?.currentSession === true
      || session?.me === true
    );
    const browser = cleanText(
      [session?.browser, session?.browserVersion].filter(Boolean).join(' '),
      120
    );
    const platform = cleanText(
      [session?.platform, session?.os, session?.osName, session?.deviceKind].filter(Boolean).join(' '),
      140
    );
    const ipAddress = cleanText(session?.ip || session?.ipAddress || session?.remoteAddress || '', 80);
    const title = cleanText(
      session?.deviceName
      || session?.device
      || session?.title
      || browser
      || platform
      || session?.userAgent
      || `Устройство ${index + 1}`,
      180
    ) || `Устройство ${index + 1}`;
    const subtitle = cleanText(
      [browser, platform, ipAddress].filter(Boolean).join(' · '),
      220
    );
    const metaParts = [];
    if (lastActiveAt) {
      metaParts.push(`Активность ${formatExportDateTime(lastActiveAt)}`);
    }
    const location = cleanText(
      [session?.location, session?.city, session?.country].filter(Boolean).join(', '),
      120
    );
    if (location) {
      metaParts.push(location);
    }
    return {
      id: cleanText(session?.sessionId || session?.id || session?.sid || session?.tokenId || `session-${index + 1}`, 180) || `session-${index + 1}`,
      title,
      subtitle,
      meta: metaParts.join(' · '),
      current
    };
  }

  function buildProfileSessionsMarkup() {
    if (state.profileSessionsLoading) {
      return '<div class="yc-profile-placeholder">Загрузка активных устройств…</div>';
    }
    if (state.profileSessionsError) {
      return `
        <div class="yc-profile-placeholder">
          <div class="yc-profile-panel-subtitle">${escapeHtml(state.profileSessionsError)}</div>
          <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="refresh-sessions">Повторить</button>
        </div>
      `;
    }
    const sessions = Array.isArray(state.profileSessions) ? state.profileSessions : [];
    if (!sessions.length) {
      return `
        <div class="yc-profile-placeholder">
          <div class="yc-profile-panel-subtitle">Список устройств пока пуст или недоступен для этой сессии.</div>
          <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="refresh-sessions">Обновить</button>
        </div>
      `;
    }
    return `
      <div class="yc-profile-session-list">
        ${sessions.map((session, index) => {
          const descriptor = describeProfileSession(session, index);
          return `
            <div class="yc-profile-session-card">
              <div class="yc-profile-session-title-row">
                <div class="yc-profile-session-title">${escapeHtml(descriptor.title)}</div>
                ${descriptor.current ? '<span class="yc-chat-info-badge">Текущее</span>' : ''}
              </div>
              ${descriptor.subtitle ? `<div class="yc-profile-session-subtitle">${escapeHtml(descriptor.subtitle)}</div>` : ''}
              ${descriptor.meta ? `<div class="yc-profile-session-meta">${escapeHtml(descriptor.meta)}</div>` : ''}
            </div>
          `;
        }).join('')}
      </div>
    `;
  }

  function buildLocalProfileSettingsMarkup() {
    const chatPreviewEnabled = state.chatPreviewEnabled !== false;
    const telegramSettings = normalizeTelegramIntegrationSettings(state.telegramIntegration);
    const notificationSettings = normalizeSystemNotificationSettings(state.systemNotifications);
    const telegramStatus = state.telegramStatus && typeof state.telegramStatus === 'object' ? state.telegramStatus : {};
    const telegramConnected = telegramStatus.authorized === true || telegramStatus.connected === true || state.telegramLastSyncedAt > 0;
    const telegramCodeRequested = state.telegramAuthCodeRequested === true || telegramStatus.codeSent === true;
    const telegramPasswordRequired = state.telegramPasswordRequired === true || telegramStatus.passwordRequired === true || telegramStatus.code === 'TELEGRAM_PASSWORD_REQUIRED';
    const showTelegramAuthFields = telegramCodeRequested || telegramPasswordRequired;
    const safeDecode = (value = '') => {
      try {
        return decodeURIComponent(String(value || '').replace(/\+/g, '%20'));
      } catch {
        return String(value || '');
      }
    };
    const decodeTelegramFakeTlsDomain = (secret = '') => {
      const normalizedSecret = cleanText(secret || '', 1200).trim().toLowerCase();
      if (!normalizedSecret.startsWith('ee') || normalizedSecret.length <= 34) return '';
      const domainHex = normalizedSecret.slice(34);
      if (!/^[0-9a-f]+$/i.test(domainHex) || domainHex.length % 2 !== 0) return '';
      try {
        const chars = [];
        for (let index = 0; index < domainHex.length; index += 2) {
          const byte = parseInt(domainHex.slice(index, index + 2), 16);
          if (!Number.isFinite(byte) || byte < 32 || byte > 126) return '';
          chars.push(String.fromCharCode(byte));
        }
        return cleanText(chars.join(''), 120);
      } catch {
        return '';
      }
    };
    const describeTelegramProxy = (proxyUrl = '') => {
      const value = normalizeTelegramProxyUrlInput(proxyUrl || '').trim();
      if (!value) {
        return {
          hasProxy: false,
          label: '',
          fakeTls: false
        };
      }
      let server = '';
      let port = '';
      let secret = '';
      try {
        const parsed = new URL(value);
        server = cleanText(parsed.searchParams.get('server') || parsed.hostname || '', 160);
        port = cleanText(parsed.searchParams.get('port') || parsed.port || '', 12);
        secret = cleanText(parsed.searchParams.get('secret') || '', 1200);
      } catch {
        const serverMatch = value.match(/[?&]server=([^&]+)/i);
        const portMatch = value.match(/[?&]port=([^&]+)/i);
        const secretMatch = value.match(/[?&]secret=([^&]+)/i);
        server = cleanText(serverMatch ? safeDecode(serverMatch[1]) : '', 160);
        port = cleanText(portMatch ? safeDecode(portMatch[1]) : '', 12);
        secret = cleanText(secretMatch ? safeDecode(secretMatch[1]) : '', 1200);
      }
      const fakeTls = /^ee/i.test(secret);
      const fakeTlsDomain = fakeTls ? decodeTelegramFakeTlsDomain(secret) : '';
      const endpoint = [server, port].filter(Boolean).join(':') || 'MTProxy';
      const label = fakeTlsDomain ? `${endpoint} (${fakeTlsDomain})` : endpoint;
      return {
        hasProxy: true,
        label: cleanText(label, 180),
        fakeTls
      };
    };
    const proxyDescriptor = describeTelegramProxy(telegramSettings.proxyUrl);
    const telegramProxyLabel = cleanText(telegramStatus.proxyLabel || proxyDescriptor.label || '', 180);
    const telegramSectionSubtitle = (() => {
      if (telegramConnected && telegramProxyLabel) return `Подключено через ${telegramProxyLabel}`;
      if (telegramConnected) return 'Telegram подключён через API.';
      if (telegramCodeRequested && telegramProxyLabel) return `Код отправлен через ${telegramProxyLabel}`;
      if (telegramProxyLabel) return `MTProxy: ${telegramProxyLabel}`;
      return 'Введите телефон и MTProto proxy для подключения.';
    })();
    const telegramDialogCount = Array.isArray(state.telegramDialogs) ? state.telegramDialogs.length : 0;
    const telegramLastSyncText = state.telegramLastSyncedAt ? formatExportDateTime(Number(state.telegramLastSyncedAt || 0)) : '';
    const telegramTransportNote = proxyDescriptor.hasProxy
      ? `${proxyDescriptor.fakeTls ? 'Fake TLS ' : ''}MTProxy включён: Telegram работает через MTProto внутри общего интерфейса YuChat.`
      : 'MTProxy не задан: Telegram подключается напрямую через API.';
    const telegramAuthNotice = (() => {
      if (state.telegramLoading) return 'идёт подключение';
      if (telegramConnected) return 'подключён';
      if (telegramCodeRequested) return 'ожидает кода';
      if (telegramSettings.enabled) return 'ожидает входа';
      return 'отключён';
    })();
    const telegramProxyInputType = state.telegramProxyVisible === true ? 'text' : 'password';
    const telegramProxyToggleLabel = state.telegramProxyVisible === true ? 'Скрыть' : 'Показать';
    const renderToggleRow = (actionId = '', title = '', enabled = false) => `
      <button
        class="yc-profile-feature-toggle-btn${enabled ? ' is-on' : ''}"
        type="button"
        data-profile-panel-action="${escapeHtml(actionId)}"
      >
        <span class="yc-profile-feature-toggle-title">${escapeHtml(title)}</span>
        <span class="yc-profile-feature-toggle-trailing">
          <span class="yc-profile-feature-toggle-state">${enabled ? 'Вкл' : 'Выкл'}</span>
          <span class="yc-profile-feature-toggle-switch" aria-hidden="true">
            <span class="yc-profile-feature-toggle-knob"></span>
          </span>
        </span>
      </button>
    `;
    const renderTelegramButton = (actionId = '', title = '', options = {}) => `
      <button
        class="yc-profile-secondary-btn${options.danger ? ' is-danger' : ''}"
        type="button"
        data-profile-panel-action="${escapeHtml(actionId)}"
        ${options.disabled ? 'disabled' : ''}
      >${escapeHtml(title)}</button>
    `;
    const telegramDetailMarkup = telegramSettings.showInSidebar !== false ? `
          <label class="yc-profile-field is-wide">
            <span class="yc-profile-label">Телефон</span>
            <input class="yc-profile-input" type="tel" value="${escapeHtml(telegramSettings.phoneNumber)}" data-profile-telegram-field="phoneNumber" placeholder="+7..." />
          </label>
          <div class="yc-telegram-proxy-row">
            <label class="yc-profile-field is-wide">
              <span class="yc-profile-label">MTProto proxy</span>
              <input class="yc-profile-input" type="${telegramProxyInputType}" value="${escapeHtml(telegramSettings.proxyUrl)}" data-profile-telegram-field="proxyUrl" placeholder="tg://proxy?server=...&port=...&secret=..." autocomplete="off" />
            </label>
            <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="telegram-toggle-proxy-visibility">${escapeHtml(telegramProxyToggleLabel)}</button>
          </div>
          <div class="yc-profile-feature-note yc-telegram-proxy-note">MTProxy применяется только к Telegram-клиенту. YuChat продолжает работать напрямую.</div>
          ${showTelegramAuthFields ? '' : `
            <div class="yc-telegram-action-stack">
              ${renderTelegramButton('telegram-connect', state.telegramLoading ? 'Подключаю…' : 'Подключить', { disabled: state.telegramLoading })}
            </div>
          `}
          ${showTelegramAuthFields ? `
            <div class="yc-telegram-auth-grid">
              ${telegramPasswordRequired ? '' : `
                <label class="yc-profile-field">
                  <span class="yc-profile-label">Код</span>
                  <input class="yc-profile-input" type="text" inputmode="numeric" autocomplete="one-time-code" data-profile-telegram-auth-field="code" placeholder="12345" />
                </label>
              `}
              <label class="yc-profile-field${telegramPasswordRequired ? ' is-wide' : ''}">
                <span class="yc-profile-label">Пароль 2FA${telegramPasswordRequired ? ' нужен для входа' : ''}</span>
                  <input class="yc-profile-input" type="password" data-profile-telegram-auth-field="password" placeholder="${telegramPasswordRequired ? 'введите пароль' : 'если включен'}" />
                </label>
              </div>
            <div class="yc-telegram-action-stack">
              ${renderTelegramButton('telegram-send-code', state.telegramLoading ? 'Отправляю…' : 'Отправить код повторно', { disabled: state.telegramLoading })}
              ${renderTelegramButton('telegram-sign-in', state.telegramLoading ? 'Вхожу…' : 'Войти', { disabled: state.telegramLoading })}
            </div>
          ` : ''}
          <div class="yc-telegram-action-stack">
            ${renderTelegramButton('telegram-refresh', state.telegramLoading ? 'Обновляю…' : 'Обновить диалоги', { disabled: state.telegramLoading })}
            ${renderTelegramButton('telegram-disconnect', 'Выйти', { danger: true })}
          </div>
          <div class="yc-profile-feature-note yc-telegram-status-note">
            <div>${escapeHtml(telegramTransportNote)}</div>
            <div>Диалогов: ${escapeHtml(String(telegramDialogCount))}${telegramLastSyncText ? ` · ${escapeHtml(telegramLastSyncText)}` : ''}</div>
            <div>${escapeHtml(telegramAuthNotice)}</div>
          </div>
          ${state.telegramError ? `<div class="yc-profile-form-error">${escapeHtml(state.telegramError)}</div>` : ''}
    ` : '';

    return `
      <div class="yc-profile-feature-card">
        <div class="yc-profile-feature-card-head">
          <div class="yc-profile-feature-card-title">Интерфейс</div>
          <div class="yc-profile-feature-card-subtitle">Локальные настройки поведения YuChat.</div>
        </div>
        <div class="yc-profile-feature-group">
          ${renderToggleRow('toggle-chat-preview', 'Предпросмотр чатов', chatPreviewEnabled)}
          <div class="yc-profile-feature-note">Для предпросмотра чата нажмите на счётчик непрочитанных сообщений — они не будут отмечены как прочитанные.</div>
        </div>
      </div>
      <div class="yc-profile-feature-card yc-profile-feature-card--telegram">
        <div class="yc-profile-feature-card-head">
          <div class="yc-profile-feature-card-title">Telegram</div>
          <div class="yc-profile-feature-card-subtitle">${escapeHtml(telegramSectionSubtitle)}</div>
        </div>
        <div class="yc-profile-feature-group yc-telegram-settings-card">
          ${renderToggleRow('toggle-telegram-sidebar', 'Показывать Telegram в сайдбаре', telegramSettings.showInSidebar)}
          ${telegramDetailMarkup}
        </div>
      </div>
      <div class="yc-profile-feature-card">
        <div class="yc-profile-feature-card-head">
          <div class="yc-profile-feature-card-title">Системные уведомления</div>
          <div class="yc-profile-feature-card-subtitle">Отдельные переключатели для YuChat и Telegram.</div>
        </div>
        <div class="yc-profile-feature-group">
          ${renderToggleRow('toggle-notifications-yuchat', 'Системные уведомления YuChat', notificationSettings.yuchat)}
          ${renderToggleRow('toggle-notifications-telegram', 'Системные уведомления Telegram', notificationSettings.telegram)}
        </div>
      </div>
    `;
  }

  function buildProductivityFeatureSettingsMarkup() {
    const filtersEnabled = isProductivityFiltersFeatureEnabled();
    const foldersEnabled = isProductivityFoldersFeatureEnabled();
    const chatTagsEnabled = isProductivityChatTagsFeatureEnabled();
    const visibilityByMode = normalizeProductivityInboxModeVisibilityMap(state.productivityInboxModeVisibilityByMode);
    const renderToggleRow = (actionId = '', title = '', enabled = false) => `
      <button
        class="yc-profile-feature-toggle-btn${enabled ? ' is-on' : ''}"
        type="button"
        data-profile-panel-action="${escapeHtml(actionId)}"
      >
        <span class="yc-profile-feature-toggle-title">${escapeHtml(title)}</span>
        <span class="yc-profile-feature-toggle-trailing">
          <span class="yc-profile-feature-toggle-state">${enabled ? 'Вкл' : 'Выкл'}</span>
          <span class="yc-profile-feature-toggle-switch" aria-hidden="true">
            <span class="yc-profile-feature-toggle-knob"></span>
          </span>
        </span>
      </button>
    `;
    const modeToggles = PRODUCTIVITY_INBOX_MODE_LIST
      .filter((mode) => mode !== PRODUCTIVITY_INBOX_MODE.ALL)
      .map((mode) => {
        const enabled = visibilityByMode[mode] !== false;
        return renderToggleRow(`toggle-filter-mode:${mode}`, getProductivityInboxModeLabel(mode), enabled);
      }).join('');

    return `
      <div class="yc-profile-feature-card">
        <div class="yc-profile-feature-card-head">
          <div class="yc-profile-feature-card-title">Продуктивность</div>
          <div class="yc-profile-feature-card-subtitle">Локальные клиентские функции, без влияния на сервер.</div>
        </div>
        <div class="yc-profile-feature-group">
          ${renderToggleRow('toggle-filters-global', 'Фильтры: глобально', filtersEnabled)}
          ${filtersEnabled ? `
            <div class="yc-profile-panel-actions">
              <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="filters-enable-all">Включить все</button>
              <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="filters-disable-all">Выключить все</button>
            </div>
          ` : ''}
          ${filtersEnabled ? modeToggles : ''}
          ${renderToggleRow('toggle-folders-global', 'Папки', foldersEnabled)}
          ${renderToggleRow('toggle-chat-tags-global', 'Теги', chatTagsEnabled)}
        </div>
      </div>
    `;
  }

  function buildCalendarEventTimingLabel(calendarEvent = null) {
    if (!calendarEvent || typeof calendarEvent !== 'object') return '';
    return formatCalendarSlotLabel(calendarEvent.startAt, calendarEvent.endAt);
  }

  function isCalendarEventsSectionCollapsed(visibleEvents = []) {
    const safeEvents = Array.isArray(visibleEvents) ? visibleEvents : [];
    if (!safeEvents.length) return false;
    if (typeof runtime.calendarEventsSectionCollapsed === 'boolean') {
      return runtime.calendarEventsSectionCollapsed;
    }
    return safeEvents.length > 2;
  }

  function buildCalendarSidebarSnapshot() {
    const settings = normalizeCalendarIntegrationSettings(state.calendarIntegration);
    const calendarStatus = buildCalendarStatusDescriptor();
    const activeEvent = getCalendarActiveEvent();
    const planningParticipants = Array.isArray(state.calendarPlanningParticipants) ? state.calendarPlanningParticipants : [];
    const planningSlots = Array.isArray(state.calendarPlanningSlots) ? state.calendarPlanningSlots : [];
    const selectedDay = normalizeCalendarEventsDay(runtime.calendarEventsDay);
    const normalizedEvents = normalizeCalendarEvents(
      Array.isArray(state.calendarEvents) ? state.calendarEvents : [],
      {
        defaultMeetingDurationMinutes: settings.defaultMeetingDurationMinutes || 30
      }
    );
    const visibleEvents = filterCalendarEventsForDay(normalizedEvents, selectedDay).slice(0, 8);
    const syncLabel = state.calendarSyncBusy
      ? 'Синхронизация календаря…'
      : state.calendarLastSyncedAt > 0
        ? `Обновлено ${formatExportDateTime(state.calendarLastSyncedAt)}`
        : (settings.autoConnectOnStartup !== false
          ? 'OWA подключается автоматически. Если потребуется вход, окно откроется само.'
          : 'Сначала откройте календарь OWA для подключения');
    return {
      settings,
      calendarStatus,
      activeEvent,
      planningParticipants,
      planningSlots,
      visibleEvents,
      selectedDay,
      hasAnyEvents: normalizedEvents.length > 0,
      syncLabel
    };
  }

  function buildCalendarEventsDaySwitchMarkup(selectedDay = 'today') {
    const safeDay = normalizeCalendarEventsDay(selectedDay);
    return `
      <div class="yc-calendar-events-day-switch" role="group" aria-label="Показать встречи на сегодня или завтра">
        <button
          class="yc-calendar-events-day-btn${safeDay === 'today' ? ' is-active' : ''}"
          type="button"
          data-profile-panel-action="calendar-events-day:today"
          aria-pressed="${safeDay === 'today' ? 'true' : 'false'}"
        >Сегодня</button>
        <button
          class="yc-calendar-events-day-btn${safeDay === 'tomorrow' ? ' is-active' : ''}"
          type="button"
          data-profile-panel-action="calendar-events-day:tomorrow"
          aria-pressed="${safeDay === 'tomorrow' ? 'true' : 'false'}"
        >Завтра</button>
      </div>
    `;
  }

  function getCalendarEventsSummaryEvent(events = [], activeEvent = null, selectedDay = 'today', referenceTs = now()) {
    const safeEvents = Array.isArray(events) ? events : [];
    if (!safeEvents.length) return null;
    if (activeEvent?.id) {
      const matchedActiveEvent = safeEvents.find((event) => event?.id === activeEvent.id);
      if (matchedActiveEvent) return matchedActiveEvent;
    }
    if (normalizeCalendarEventsDay(selectedDay) === 'today') {
      const currentTs = Math.max(0, Number(referenceTs || 0) || 0);
      return safeEvents.find((event) => Number(event?.startAt || 0) >= currentTs)
        || safeEvents[safeEvents.length - 1]
        || safeEvents[0]
        || null;
    }
    return safeEvents[0] || null;
  }

  function buildCalendarEventsSectionMarkup(visibleEvents = [], activeEvent = null, options = {}) {
    const safeEvents = Array.isArray(visibleEvents) ? visibleEvents : [];
    const selectedDay = normalizeCalendarEventsDay(options.selectedDay);
    const collapsed = isCalendarEventsSectionCollapsed(safeEvents);
    const nextEvent = getCalendarEventsSummaryEvent(safeEvents, activeEvent, selectedDay);
    const countLabel = `${safeEvents.length} ${pluralize(safeEvents.length, ['встреча', 'встречи', 'встреч'])}`;
    const toggleMeta = nextEvent
      ? `${countLabel} · ${buildCalendarEventTimingLabel(nextEvent)}`
      : countLabel;
    const sectionDayLabel = getCalendarEventsDayLabel(selectedDay, { preposition: true });
    const sectionTitle = `Встречи ${sectionDayLabel}`;
    const emptyStateText = options.hasAnyEvents === true || state.calendarLastSyncedAt > 0
      ? `${sectionDayLabel.charAt(0).toUpperCase()}${sectionDayLabel.slice(1)} встреч нет.`
      : 'События появятся здесь после подключения OWA и первой синхронизации.';
    return `
      <div class="yc-calendar-events-shell${collapsed ? ' is-collapsed' : ''}">
        <div class="yc-calendar-events-head">
          <div class="yc-calendar-events-title">Встречи</div>
          ${buildCalendarEventsDaySwitchMarkup(selectedDay)}
        </div>
        ${safeEvents.length ? `
          <div
            class="yc-calendar-events-toggle${collapsed ? ' is-collapsed' : ''}"
          >
            <span class="yc-calendar-events-toggle-copy">
              <span class="yc-calendar-events-title">${escapeHtml(sectionTitle)}</span>
              <span class="yc-calendar-events-toggle-meta">${escapeHtml(toggleMeta)}</span>
            </span>
            <span class="yc-calendar-events-toggle-side">
              <span class="yc-calendar-events-toggle-count">${escapeHtml(String(safeEvents.length))}</span>
              <button
                class="yc-calendar-events-toggle-btn"
                type="button"
                data-profile-panel-action="calendar-events-toggle"
                aria-expanded="${collapsed ? 'false' : 'true'}"
                aria-label="${collapsed ? `Показать ${sectionTitle.toLowerCase()}` : `Скрыть ${sectionTitle.toLowerCase()}`}"
              >
                <span class="yc-calendar-events-toggle-chevron" aria-hidden="true">
                  <svg viewBox="0 0 20 20" fill="none">
                    <path d="m6.5 8 3.5 4 3.5-4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
                  </svg>
                </span>
              </button>
            </span>
          </div>
        ` : `
          <div class="yc-calendar-events-empty-card">
            <div class="yc-calendar-events-title">${escapeHtml(sectionTitle)}</div>
            <div class="yc-calendar-empty-state">${escapeHtml(emptyStateText)}</div>
          </div>
        `}
        ${safeEvents.length && collapsed ? '' : (safeEvents.length ? `
          <div class="yc-calendar-events-list">
            ${safeEvents.map((calendarEvent) => {
              const isActive = activeEvent?.id && activeEvent.id === calendarEvent.id;
              const participantSummary = buildCalendarParticipantSummary(calendarEvent.participantNames || [], '');
              const joinUrl = resolveCalendarEventJoinUrl(calendarEvent);
              const eventKindLabel = normalizeCalendarEventType(calendarEvent.type || '') === CALENDAR_EVENT_TYPE.FOCUS ? 'Фокус' : 'Встреча';
              return `
                <div class="yc-calendar-event-card${isActive ? ' is-active' : ''}${normalizeCalendarEventType(calendarEvent.type || '') === CALENDAR_EVENT_TYPE.FOCUS ? ' is-focus' : ''}">
                  <div class="yc-calendar-event-copy">
                    <div class="yc-calendar-event-title-row">
                      <div class="yc-calendar-event-title">${escapeHtml(calendarEvent.title || 'Событие')}</div>
                      <span class="yc-calendar-event-kind">${escapeHtml(eventKindLabel)}</span>
                    </div>
                    <div class="yc-calendar-event-meta">${escapeHtml(buildCalendarEventTimingLabel(calendarEvent))}${calendarEvent.location ? ` · ${escapeHtml(calendarEvent.location)}` : ''}</div>
                    ${participantSummary ? `<div class="yc-calendar-event-participants">${escapeHtml(participantSummary)}</div>` : ''}
                  </div>
                  <div class="yc-calendar-event-actions">
                    <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="calendar-event-open:${escapeHtml(calendarEvent.id)}">OWA</button>
                    <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="calendar-event-join:${escapeHtml(calendarEvent.id)}"${joinUrl ? '' : ' disabled'}>Join</button>
                    <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="calendar-event-share:${escapeHtml(calendarEvent.id)}">Экран</button>
                  </div>
                </div>
              `;
            }).join('')}
          </div>
        ` : `
          <div class="yc-calendar-empty-state">События появятся здесь после подключения OWA и первой синхронизации.</div>
        `)}
      </div>
    `;
  }

  function buildCalendarPlannerSectionMarkup(planningParticipants = [], planningSlots = []) {
    const hasPlannerContent = Boolean(state.calendarPlanningError)
      || Boolean(planningParticipants.length)
      || Boolean(planningSlots.length);
    if (!hasPlannerContent) return '';

    return `
      <div class="yc-calendar-planner-shell">
        ${state.calendarPlanningError ? `<div class="yc-profile-form-error">${escapeHtml(state.calendarPlanningError)}</div>` : ''}
        ${planningParticipants.length || planningSlots.length ? `
          <div class="yc-calendar-planner-summary">
            ${escapeHtml(buildCalendarSlotSuggestionText({
              participants: planningParticipants,
              slots: planningSlots
            }))}
          </div>
        ` : ''}
        ${planningSlots.length ? `
          <div class="yc-calendar-slot-list">
            ${planningSlots.map((slot, index) => `
              <div class="yc-calendar-slot-card">
                <div class="yc-calendar-slot-copy">${escapeHtml(formatCalendarSlotLabel(slot.startAt, slot.endAt))}</div>
                <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="calendar-slot-compose:${index}">Создать встречу</button>
              </div>
            `).join('')}
          </div>
        ` : ''}
      </div>
    `;
  }

  function buildCalendarIntegrationSettingsMarkup() {
    const {
      settings,
      syncLabel
    } = buildCalendarSidebarSnapshot();
    return `
      <div class="yc-profile-feature-card yc-calendar-card">
        <div class="yc-profile-feature-card-head">
          <div class="yc-profile-feature-card-title">Почта и календарь</div>
        </div>
        <div class="yc-calendar-settings-grid">
          <label class="yc-calendar-settings-field is-wide">
            <span class="yc-local-settings-label">Ссылка на почту</span>
            <input class="yc-modal-input" type="url" data-calendar-field="mailUrl" value="${escapeHtml(settings.mailUrl || '')}" placeholder="${escapeHtml(DEFAULT_MAIL_INTEGRATION_URL)}" />
            <span class="yc-local-settings-help">Для разных филиалов можно указать свой адрес OWA. Подключение идёт через этот URL.</span>
          </label>
          <label class="yc-calendar-settings-field is-wide">
            <span class="yc-local-settings-label">Ссылка на календарь</span>
            <input class="yc-modal-input" type="url" data-calendar-field="calendarUrl" value="${escapeHtml(settings.calendarUrl || '')}" placeholder="${escapeHtml(deriveCalendarUrlFromMailUrl(settings.mailUrl || DEFAULT_MAIL_INTEGRATION_URL))}" />
            <span class="yc-local-settings-help">Обычно подставляется автоматически, но при необходимости можно заменить вручную.</span>
          </label>
          <label class="yc-calendar-settings-field is-wide">
            <span class="yc-local-settings-label">Ссылка на встречу по умолчанию</span>
            <input class="yc-modal-input" type="url" data-calendar-field="defaultMeetingLocation" value="${escapeHtml(settings.defaultMeetingLocation || '')}" placeholder="Например: https://telemost.yandex.ru/j/..." />
            <span class="yc-local-settings-help">Будет автоматически подставляться в поле места при создании любой встречи из чата и из подбора слотов.</span>
          </label>
          <label class="yc-calendar-settings-field is-wide">
            <span class="yc-local-settings-label">URL TrueConf для списка комнат</span>
            <div class="yc-calendar-settings-trueconf-row">
              <select class="yc-modal-input" data-calendar-field="trueconfBaseUrl" data-calendar-apply-only="1">
                ${buildTrueconfRoomBaseUrlOptionsMarkup(settings.trueconfBaseUrl || '')}
              </select>
              <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="calendar-trueconf-apply">Применить</button>
              <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="calendar-trueconf-auth">Войти в TrueConf</button>
            </div>
            <span class="yc-local-settings-help">Используется в кнопке «Выбрать комнату» при создании встречи из общего слота.</span>
          </label>
          <label class="yc-calendar-settings-field">
            <span class="yc-local-settings-label">Длительность по умолчанию</span>
            <input class="yc-modal-input" type="number" min="15" max="240" step="15" data-calendar-field="defaultMeetingDurationMinutes" value="${escapeHtml(String(settings.defaultMeetingDurationMinutes || 30))}" />
          </label>
          <label class="yc-calendar-settings-field is-wide">
            <span class="yc-local-settings-label">Подключение OWA</span>
            <span class="yc-calendar-check">
              <input type="checkbox" data-calendar-field="autoConnectOnStartup" ${settings.autoConnectOnStartup !== false ? 'checked' : ''} />
              <span>Автоматически подключать OWA при запуске</span>
            </span>
          </label>
        </div>
        <div class="yc-profile-panel-actions yc-profile-panel-actions--calendar">
          <button class="yc-profile-secondary-btn yc-profile-secondary-btn--wide" type="button" data-profile-panel-action="calendar-connect">Подключить OWA</button>
          <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="calendar-open-mail">Открыть почту</button>
          <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="calendar-plan"${state.calendarPlanningBusy ? ' disabled' : ''}>${state.calendarPlanningBusy ? 'Подбор…' : 'Найти слот'}</button>
        </div>
        ${state.calendarSyncError ? `<div class="yc-profile-form-error">${escapeHtml(state.calendarSyncError)}</div>` : ''}
        ${state.calendarTrueconfRoomsError ? `<div class="yc-profile-form-error">${escapeHtml(`TrueConf: ${state.calendarTrueconfRoomsError}`)}</div>` : ''}
        <div class="yc-calendar-sync-hint">${escapeHtml(syncLabel)}</div>
      </div>
    `;
  }

  function buildCalendarSidebarMarkup() {
    return `
      <div class="yc-profile-sidebar-shell">
        <section class="yc-profile-panel yc-profile-panel--sidebar">
          <div class="yc-profile-form-shell">
            ${buildCalendarIntegrationSettingsMarkup()}
          </div>
        </section>
        <div class="yc-profile-sidebar-footer">
          <button class="yc-profile-secondary-btn yc-profile-secondary-btn--wide" type="button" data-profile-action="meetings">Открыть встречи</button>
        </div>
      </div>
    `;
  }

  function buildMeetingsSidebarMarkup() {
    const {
      activeEvent,
      planningParticipants,
      planningSlots,
      visibleEvents,
      selectedDay,
      hasAnyEvents,
      syncLabel
    } = buildCalendarSidebarSnapshot();
    return `
      <div class="yc-profile-sidebar-shell">
        <section class="yc-profile-panel yc-profile-panel--sidebar">
          <div class="yc-profile-form-shell">
            <div class="yc-profile-feature-card yc-calendar-card">
              <div class="yc-profile-feature-card-head">
                <div class="yc-profile-feature-card-title">Встречи</div>
                <div class="yc-profile-feature-card-subtitle">Ближайшие события, быстрый вход в созвон и подбор свободного слота.</div>
              </div>
              <div class="yc-profile-panel-actions yc-profile-panel-actions--calendar">
                <button class="yc-profile-secondary-btn yc-profile-secondary-btn--wide" type="button" data-profile-panel-action="calendar-connect">Подключить OWA</button>
                <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="calendar-open-mail">Почта</button>
                <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="calendar-plan"${state.calendarPlanningBusy ? ' disabled' : ''}>${state.calendarPlanningBusy ? 'Подбор…' : 'Найти слот'}</button>
              </div>
              ${state.calendarSyncError ? `<div class="yc-profile-form-error">${escapeHtml(state.calendarSyncError)}</div>` : ''}
              <div class="yc-calendar-sync-hint">${escapeHtml(activeEvent?.title || syncLabel)}</div>
              ${buildCalendarEventsSectionMarkup(visibleEvents, activeEvent, { selectedDay, hasAnyEvents })}
              ${buildCalendarPlannerSectionMarkup(planningParticipants, planningSlots)}
            </div>
          </div>
        </section>
        <div class="yc-profile-sidebar-footer">
          <button class="yc-profile-secondary-btn yc-profile-secondary-btn--wide" type="button" data-profile-action="calendar">Настройки OWA</button>
        </div>
      </div>
    `;
  }

  function buildProfileEditorMarkup(options = {}) {
    const profile = getCurrentProfile();
    const draft = ensureProfileSettingsDraft({ force: false });
    const isSidebar = options?.sidebar === true;
    const sectionClass = isSidebar
      ? 'yc-profile-panel yc-profile-panel--sidebar yc-profile-panel--settings'
      : 'yc-profile-panel yc-profile-panel--settings';
    const headerMarkup = isSidebar ? '' : `
      <div class="yc-profile-panel-header">
        <div class="yc-profile-panel-title">Профиль</div>
        <div class="yc-profile-panel-subtitle">Данные аккаунта и информация для коллег.</div>
      </div>
    `;
    const localProfileSettingsMarkup = buildLocalProfileSettingsMarkup(profile, draft);
    const productivityFeatureSettingsMarkup = buildProductivityFeatureSettingsMarkup();

    return `
      <div class="${isSidebar ? 'yc-profile-sidebar-shell' : 'yc-profile-panel-shell'}">
        <section class="${sectionClass}">
          ${headerMarkup}
          <div class="yc-profile-form-shell yc-profile-settings-form-shell">
            <div class="yc-profile-settings-section yc-profile-settings-section--identity">
              <div class="yc-profile-settings-heading">Профиль</div>
              <div class="yc-profile-settings-card">
                <div class="yc-profile-hero">
                  <button class="yc-profile-hero-avatar is-editable" type="button" data-profile-panel-action="change-avatar" aria-label="Выбрать фото профиля" title="Выбрать фото профиля"><span class="yc-avatar">${buildAvatarMarkup({
                    title: getProfileDisplayName(profile) || 'Профиль',
                    avatarUrl: getProfileDraftAvatarUrl(draft, profile),
                    chatId: `${isSidebar ? 'profile-sidebar' : 'profile-main'}:${getCurrentWorkspaceMemberId()}`
                  })}</span><span class="yc-profile-hero-avatar-camera" aria-hidden="true">${getContextMenuIconMarkup('camera')}</span></button>
                  <div class="yc-profile-hero-copy">
                    <div class="yc-profile-hero-name">${escapeHtml(draft?.fullName || getProfileDisplayName(profile) || 'Профиль')}</div>
                    ${draft?.email ? `<div class="yc-profile-hero-email">${escapeHtml(draft.email)}</div>` : ''}
                  </div>
                </div>
                <div class="yc-profile-form" data-profile-form="1">
                  <label class="yc-profile-field">
                    <span class="yc-profile-label">Статус</span>
                    <select class="yc-profile-input" data-profile-field="status"${state.profileSaveBusy ? ' disabled' : ''}>
                      ${buildProfileStatusOptionsMarkup(draft?.status || '')}
                    </select>
                  </label>
                  <label class="yc-profile-field">
                    <span class="yc-profile-label">Имя пользователя</span>
                    <input class="yc-profile-input" type="text" value="${escapeHtml(draft?.fullName || '')}" disabled />
                  </label>
                  <label class="yc-profile-field">
                    <span class="yc-profile-label">Должность</span>
                    <input class="yc-profile-input" type="text" value="${escapeHtml(draft?.position || '')}" data-profile-field="position"${state.profileSaveBusy ? ' disabled' : ''} />
                  </label>
                  <label class="yc-profile-field">
                    <span class="yc-profile-label">Департамент</span>
                    <input class="yc-profile-input" type="text" value="${escapeHtml(draft?.department || '')}" data-profile-field="department"${state.profileSaveBusy ? ' disabled' : ''} />
                  </label>
                  <label class="yc-profile-field">
                    <span class="yc-profile-label">Номер телефона</span>
                    <input class="yc-profile-input" type="tel" value="${escapeHtml(draft?.phonenumber || '')}" data-profile-field="phonenumber"${state.profileSaveBusy ? ' disabled' : ''} />
                  </label>
                  <label class="yc-profile-field is-wide">
                    <span class="yc-profile-label">Обо мне</span>
                    <textarea class="yc-profile-textarea" data-profile-field="bio" rows="6"${state.profileSaveBusy ? ' disabled' : ''} placeholder="Любая дополнительная информация для ваших коллег">${escapeHtml(draft?.bio || '')}</textarea>
                  </label>
                </div>
              </div>
            </div>
            ${localProfileSettingsMarkup}
            ${productivityFeatureSettingsMarkup}
            ${state.profileSaveError ? `<div class="yc-profile-form-error">${escapeHtml(state.profileSaveError)}</div>` : ''}
            <div class="yc-profile-panel-actions">
              <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="export-client-config">Экспорт полного бэкапа</button>
              <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="import-client-config">Импорт бэкапа</button>
              <button class="yc-profile-save-btn" type="button" data-profile-panel-action="save-profile"${state.profileSaveBusy ? ' disabled' : ''}>${state.profileSaveBusy ? 'Сохранение…' : 'Сохранить'}</button>
            </div>
          </div>
        </section>
        ${isSidebar ? `
          <div class="yc-profile-sidebar-footer">
            <button class="yc-profile-secondary-btn is-danger" type="button" data-profile-action="logout">Выйти из аккаунта</button>
            <button class="yc-profile-secondary-btn" type="button" data-profile-action="chats">Вернуться к чатам</button>
          </div>
        ` : ''}
      </div>
    `;
  }

  function buildProfileSettingsMarkup() {
    const activeTab = normalizeProfileSettingsTab(state.profileSettingsTab || 'profile');

    if (activeTab === 'sessions') {
      return `
        <section class="yc-profile-panel">
          <div class="yc-profile-panel-header">
            <div class="yc-profile-panel-title">Активные устройства</div>
            <div class="yc-profile-panel-subtitle">Сессии, которые привязаны к текущему аккаунту.</div>
          </div>
          <div class="yc-profile-panel-toolbar">
            <button class="yc-profile-secondary-btn" type="button" data-profile-panel-action="refresh-sessions">Обновить</button>
          </div>
          ${buildProfileSessionsMarkup()}
        </section>
      `;
    }

    if (activeTab !== 'profile') {
      return buildProfilePlaceholderMarkup(activeTab);
    }

    return buildProfileEditorMarkup();
  }

  function buildProfileSettingsRenderSignature() {
    const activeTab = normalizeProfileSettingsTab(state.profileSettingsTab || 'profile');
    const draft = activeTab === 'profile'
      ? ensureProfileSettingsDraft({ force: false })
      : (state.profileSettingsDraft && typeof state.profileSettingsDraft === 'object'
        ? state.profileSettingsDraft
        : {});
    const sessionSignature = activeTab === 'sessions'
      ? (Array.isArray(state.profileSessions) ? state.profileSessions : [])
          .slice(0, 16)
          .map((session) => [
            cleanText(session?.title || session?.deviceTitle || session?.deviceName || '', 120),
            cleanText(session?.subtitle || session?.platform || '', 120),
            cleanText(session?.sessionId || session?.id || '', 120),
            Number(session?.lastSeenAt || session?.updatedAt || session?.createdAt || 0)
          ].join('\u0002'))
          .join('\u0003')
      : '';
    const calendarSettings = normalizeCalendarIntegrationSettings(state.calendarIntegration);
    const telegramSettings = normalizeTelegramIntegrationSettings(state.telegramIntegration);
    const notificationSettings = normalizeSystemNotificationSettings(state.systemNotifications);
    const calendarEventsSignature = (Array.isArray(state.calendarEvents) ? state.calendarEvents : [])
      .slice(0, 12)
      .map((event) => [
        cleanText(event?.id || '', 180),
        cleanText(event?.title || '', 140),
        Number(event?.startAt || 0),
        Number(event?.endAt || 0),
        cleanText(resolveCalendarEventJoinUrl(event) || event?.location || '', 240)
      ].join('\u0002'))
      .join('\u0003');
    const calendarPlanningSignature = (Array.isArray(state.calendarPlanningSlots) ? state.calendarPlanningSlots : [])
      .slice(0, CALENDAR_SLOT_SUGGESTION_LIMIT)
      .map((slot) => [
        Number(slot?.startAt || 0),
        Number(slot?.endAt || 0)
      ].join('\u0002'))
      .join('\u0003');
    return [
      activeTab,
      Number(runtime.knownProfileVersion || 0),
      state.profileSaveBusy ? '1' : '0',
      state.profileSettingsDirty ? '1' : '0',
      state.profileLocalStatusEmojiPickerOpen ? '1' : '0',
      cleanText(state.profileSaveError || '', 180),
      cleanText(draft?.fullName || '', 120),
      cleanText(draft?.email || '', 180),
      cleanText(draft?.status || '', 180),
      cleanText(draft?.position || '', 180),
      cleanText(draft?.department || '', 180),
      cleanText(draft?.phonenumber || '', 120),
      cleanText(draft?.bio || '', 480),
      cleanText(draft?.localDisplayName || '', 180),
      cleanText(draft?.localStatusEmoji || '', 24),
      cleanText(draft?.localStatusText || '', 120),
      normalizeBirthdayInputValue(draft?.localBirthdayDate || ''),
      draft?.avatarDirty === true ? '1' : '0',
      normalizeAssetUrl(draft?.avatarPreviewUrl || '', 2048),
      state.productivityFiltersEnabled !== false ? '1' : '0',
      state.productivityFoldersEnabled !== false ? '1' : '0',
      state.productivityChatTagsEnabled === true ? '1' : '0',
      state.productivityWorkbenchEnabled !== false ? '1' : '0',
      state.chatPreviewEnabled !== false ? '1' : '0',
      telegramSettings.enabled === true ? '1' : '0',
      telegramSettings.showInSidebar !== false ? '1' : '0',
      cleanText(telegramSettings.phoneNumber || '', 64),
      cleanText(telegramSettings.proxyUrl || '', 320),
      state.telegramLoading ? '1' : '0',
      Number(state.telegramLastSyncedAt || 0),
      state.telegramAuthCodeRequested === true ? '1' : '0',
      state.telegramPasswordRequired === true ? '1' : '0',
      state.telegramProxyVisible === true ? '1' : '0',
      cleanText(state.telegramError || '', 180),
      cleanText(state.telegramStatus?.proxyLabel || '', 120),
      notificationSettings.yuchat !== false ? '1' : '0',
      notificationSettings.telegram !== false ? '1' : '0',
      state.profileSessionsLoading ? '1' : '0',
      Number(state.profileSessionsLoadedAt || 0),
      cleanText(state.profileSessionsError || '', 180),
      cleanText(calendarSettings.mailUrl || '', 320),
      cleanText(calendarSettings.calendarUrl || '', 320),
      cleanText(calendarSettings.defaultMeetingLocation || '', 1024),
      cleanText(calendarSettings.trueconfBaseUrl || '', 320),
      calendarSettings.statusSyncEnabled !== false ? '1' : '0',
      calendarSettings.showAvailableStatus !== false ? '1' : '0',
      calendarSettings.autoConnectOnStartup !== false ? '1' : '0',
      calendarSettings.autoOpenCalendarOnCreate === true ? '1' : '0',
      Number(calendarSettings.defaultMeetingDurationMinutes || 30),
      state.calendarSyncBusy ? '1' : '0',
      Number(state.calendarLastSyncedAt || 0),
      cleanText(state.calendarSyncError || '', 180),
      state.calendarPlanningBusy ? '1' : '0',
      cleanText(state.calendarPlanningError || '', 180),
      cleanText(state.calendarPlanningQuery || '', 180),
      calendarEventsSignature,
      calendarPlanningSignature,
      sessionSignature
    ].join('\u0001');
  }

  function getCachedProfileSettingsMarkup(signature = '') {
    const cacheKey = String(signature || '').trim() || buildProfileSettingsRenderSignature();
    const cached = runtime.profileSettingsMarkupCacheBySignature.get(cacheKey) || '';
    if (cached) {
      return cached;
    }
    const markup = buildProfileSettingsMarkup();
    runtime.profileSettingsMarkupCacheBySignature.set(cacheKey, markup);
    if (runtime.profileSettingsMarkupCacheBySignature.size > 10) {
      const oldestKey = runtime.profileSettingsMarkupCacheBySignature.keys().next().value;
      if (oldestKey) {
        runtime.profileSettingsMarkupCacheBySignature.delete(oldestKey);
      }
    }
    return markup;
  }

  function resolveProfileStatusPresenceKind(statusValue = '') {
    const normalizedValue = cleanText(statusValue || '', 180);
    const preset = PROFILE_STATUS_PRESETS.find((item) => item.value === normalizedValue) || null;
    return cleanText(preset?.kind || 'NOT_SET', 32) || 'NOT_SET';
  }

  async function loadProfileSessions(options = {}) {
    if (state.profileSessionsLoading && options.force !== true) return;
    state.profileSessionsLoading = true;
    state.profileSessionsError = '';
    scheduleRender('sidebar');
    try {
      const accountId = await resolveAccountId();
      const response = await callYuChatApi('session.list', { accountId }, { timeoutMs: 16000 });
      state.profileSessions = extractProfileSessions(response);
      state.profileSessionsLoadedAt = now();
      state.profileSessionsError = '';
    } catch (error) {
      state.profileSessionsError = cleanText(error?.message || 'Не удалось загрузить список устройств', 180);
    } finally {
      state.profileSessionsLoading = false;
      scheduleRender('sidebar');
    }
  }

  function selectProfileSettingsTab(tab = 'profile') {
    const nextTab = normalizeProfileSettingsTab(tab);
    if (state.profileSettingsTab === nextTab) {
      if (nextTab === 'sessions' && !state.profileSessionsLoadedAt && !state.profileSessionsLoading) {
        void loadProfileSessions();
      }
      return false;
    }
    state.profileSettingsTab = nextTab;
    if (nextTab === 'profile') {
      ensureProfileSettingsDraft({ force: !state.profileSettingsDirty });
    }
    if (nextTab === 'sessions' && !state.profileSessionsLoadedAt && !state.profileSessionsLoading) {
      void loadProfileSessions();
    }
    scheduleRender('sidebar');
    return true;
  }

  async function saveProfileSettingsDraft() {
    const currentProfile = getCurrentProfile();
    const draft = ensureProfileSettingsDraft({ force: false });
    const accountId = await resolveAccountId();
    const pendingAvatarFile = draft?.avatarDirty === true && draft?.avatarFile instanceof File
      ? draft.avatarFile
      : null;
    const details = {
      position: cleanText(draft?.position || '', 180),
      department: cleanText(draft?.department || '', 240),
      phonenumber: cleanText(draft?.phonenumber || '', 120),
      bio: cleanText(draft?.bio || '', 2400),
      status: cleanText(draft?.status || '', 180)
    };

    state.profileSaveBusy = true;
    state.profileSaveError = '';
    scheduleRender(resolveInteractiveRenderScopes({
      includeOverlaysIfVisible: true
    }));
    try {
      const presenceKind = resolveProfileStatusPresenceKind(details.status);
      await callYuChatApi('session.updateCustomPresenceKind', {
        kind: presenceKind || 'NOT_SET'
      }, { timeoutMs: 12000 }).catch(() => ({}));
      await callYuChatApi('account.updateDetails', {
        accountId,
        details
      }, { timeoutMs: 16000 });

      const baseProfile = getCurrentProfile() || currentProfile;
      const nextDetails = {
        ...getChatInfoProfileDetails(baseProfile),
        ...details
      };
      const nextProfile = {
        ...(baseProfile || {}),
        memberId: String(baseProfile?.memberId || currentProfile?.memberId || getCurrentProfileMemberId() || '').trim(),
        details: {
          ...(baseProfile?.details && typeof baseProfile.details === 'object' ? baseProfile.details : {}),
          ...nextDetails
        },
        profile: {
          ...(baseProfile?.profile && typeof baseProfile.profile === 'object' ? baseProfile.profile : {}),
          details: {
            ...(baseProfile?.profile?.details && typeof baseProfile.profile.details === 'object' ? baseProfile.profile.details : {}),
            ...nextDetails
          }
        }
      };
      cacheKnownProfile(nextProfile);
      const ownMemberId = String(nextProfile?.memberId || getCurrentProfileMemberId() || '').trim();
      if (ownMemberId) {
        syncLocalMemberPresentationToState(ownMemberId);
      }
      invalidateContactsDirectoryCaches({
        resetState: state.sidebarMode === 'contacts'
      });
      if (state.sidebarMode === 'contacts') {
        void ensureContactsDirectoryLoaded({
          force: true
        });
      }

      if (pendingAvatarFile) {
        await updateCurrentProfileAvatarViaApi(pendingAvatarFile);
      }

      const savedProfile = getCurrentProfile() || nextProfile;
      state.profileSettingsDraft = buildProfileSettingsDraft(savedProfile);
      state.profileSettingsDirty = false;
      state.profileSaveError = '';
      showTemporaryStatus('Профиль сохранён');
    } catch (error) {
      state.profileSaveError = cleanText(error?.message || 'Не удалось сохранить профиль', 180);
      throw error;
    } finally {
      state.profileSaveBusy = false;
      scheduleRender(resolveInteractiveRenderScopes({
        includeOverlaysIfVisible: true
      }));
    }
  }

  function syncTelegramIntegrationFieldTarget(target = null) {
    if (state.sidebarMode !== 'profile') return false;
    if (!(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement)) {
      return false;
    }
    const field = cleanText(target.dataset.profileTelegramField || '', 48).toLowerCase();
    if (!field) return false;
    const currentSettings = normalizeTelegramIntegrationSettings(state.telegramIntegration);
    const rawValue = target instanceof HTMLInputElement && target.type === 'checkbox'
      ? target.checked
      : target.value;
    const patch = {};
    if (field === 'phonenumber') {
      patch.phoneNumber = cleanText(rawValue || '', 64);
      if (target instanceof HTMLInputElement && target.value !== patch.phoneNumber) {
        target.value = patch.phoneNumber;
      }
    } else if (field === 'proxyurl') {
      patch.proxyUrl = normalizeTelegramProxyUrlInput(rawValue || '');
      if (target instanceof HTMLInputElement && target.value !== patch.proxyUrl) {
        target.value = patch.proxyUrl;
      }
    } else {
      return false;
    }
    const nextSettings = normalizeTelegramIntegrationSettings({
      ...currentSettings,
      ...patch
    });
    if (JSON.stringify(nextSettings) === JSON.stringify(currentSettings)) return false;
    state.telegramIntegration = nextSettings;
    saveUiPreferences();
    ensureTelegramWorkspace();
    return true;
  }

  function syncTrueconfIntegrationFieldTarget(target = null) {
    if (state.sidebarMode !== 'profile') return false;
    if (!(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement)) {
      return false;
    }
    const field = cleanText(target.dataset.profileTrueconfField || '', 48).toLowerCase();
    if (!field) return false;
    const currentSettings = normalizeTrueconfIntegrationSettings(state.trueconfIntegration);
    const rawValue = target instanceof HTMLInputElement && target.type === 'checkbox'
      ? target.checked
      : target.value;
    const patch = {};
    if (field === 'baseurl') {
      patch.baseUrl = cleanText(rawValue || '', 4096).trim();
      if (!patch.baseUrl) return false;
    } else if (field === 'username') {
      patch.username = cleanText(rawValue || '', 180);
      if (target instanceof HTMLInputElement && target.value !== patch.username) {
        target.value = patch.username;
      }
    } else if (field === 'password') {
      patch.password = cleanText(rawValue || '', 1200);
      if (target instanceof HTMLInputElement && target.value !== patch.password) {
        target.value = patch.password;
      }
    } else {
      return false;
    }
    const nextSettings = normalizeTrueconfIntegrationSettings({
      ...currentSettings,
      ...patch
    });
    if (JSON.stringify(nextSettings) === JSON.stringify(currentSettings)) return false;
    state.trueconfIntegration = nextSettings;
    if (field === 'baseurl' || field === 'username') {
      state.trueconfStatus = null;
      state.trueconfDialogs = [];
      state.trueconfLastSyncedAt = 0;
      state.recentsByWorkspace.trueconf = [];
      state.archivedRecentsByWorkspace.trueconf = [];
      state.trueconfError = '';
      runtime.recentsStateVersion += 1;
      invalidateRecentsDerivedCache();
    }
    saveUiPreferences();
    ensureTrueconfWorkspace();
    return true;
  }

  function syncProfileDraftFieldTarget(target = null) {
    if (state.sidebarMode !== 'profile') return false;
    if (!(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement)) {
      return false;
    }
    if (target.dataset.profileTelegramField) {
      return syncTelegramIntegrationFieldTarget(target);
    }
    const field = cleanText(target.dataset.profileField || '', 40).toLowerCase();
    const localField = LOCAL_PROFILE_CUSTOMIZATION_ENABLED
      ? cleanText(target.dataset.profileLocalField || '', 40).toLowerCase()
      : '';
    if (!field && !localField) return false;
    let nextValue = target.value;
    if (localField === 'statusemoji') {
      nextValue = cleanText(resolveStatusDisplayEmoji(target.value || '') || cleanText(target.value || '', 24), 24);
      if (target instanceof HTMLInputElement && target.value !== nextValue) {
        target.value = nextValue;
      }
    } else if (localField === 'statustext') {
      nextValue = cleanText(stripStatusEmojiToken(target.value || ''), 120);
      if (target instanceof HTMLInputElement && target.value !== nextValue) {
        target.value = nextValue;
      }
    } else if (localField === 'birthdaydate') {
      nextValue = normalizeBirthdayInputValue(target.value || '');
      if (target instanceof HTMLInputElement && target.value !== nextValue) {
        target.value = nextValue;
      }
    }
    const localDraftFieldMap = {
      displayname: 'localDisplayName',
      statusemoji: 'localStatusEmoji',
      statustext: 'localStatusText',
      birthdaydate: 'localBirthdayDate'
    };
    state.profileSettingsDraft = {
      ...ensureProfileSettingsDraft({ force: false }),
      ...(field ? { [field]: nextValue } : {}),
      ...(localField && localDraftFieldMap[localField] ? { [localDraftFieldMap[localField]]: nextValue } : {})
    };
    state.profileSettingsDirty = true;
    state.profileSaveError = '';
    return true;
  }

  function syncCalendarIntegrationFieldTarget(target = null, options = {}) {
    if (!isSidebarCalendarMode()) return false;
    if (!(target instanceof HTMLInputElement || target instanceof HTMLSelectElement || target instanceof HTMLTextAreaElement)) {
      return false;
    }
    const field = cleanText(target.dataset.calendarField || '', 48).toLowerCase();
    if (!field) return false;
    const requiresManualApply = target.dataset.calendarApplyOnly === '1';
    if (field === 'trueconfbaseurl' && requiresManualApply && options.forceApply !== true) {
      return false;
    }
    const currentSettings = normalizeCalendarIntegrationSettings(state.calendarIntegration);
    const rawValue = target instanceof HTMLInputElement && target.type === 'checkbox'
      ? target.checked
      : target.value;
    const patch = {};
    if (field === 'mailurl') {
      const nextMailUrl = normalizeCalendarUrl(rawValue || '', currentSettings.mailUrl)
        || DEFAULT_MAIL_INTEGRATION_URL;
      patch.mailUrl = nextMailUrl;
      const currentCalendarUrl = normalizeCalendarUrl(currentSettings.calendarUrl || '', deriveCalendarUrlFromMailUrl(currentSettings.mailUrl));
      const derivedCurrentUrl = deriveCalendarUrlFromMailUrl(currentSettings.mailUrl);
      if (!currentCalendarUrl || currentCalendarUrl === derivedCurrentUrl) {
        patch.calendarUrl = deriveCalendarUrlFromMailUrl(nextMailUrl);
      }
    } else if (field === 'calendarurl') {
      patch.calendarUrl = normalizeCalendarUrl(rawValue || '', deriveCalendarUrlFromMailUrl(currentSettings.mailUrl));
    } else if (field === 'defaultmeetinglocation') {
      patch.defaultMeetingLocation = cleanText(rawValue || '', 1024);
      if (target instanceof HTMLInputElement) {
        target.value = patch.defaultMeetingLocation;
      }
    } else if (field === 'trueconfbaseurl') {
      patch.trueconfBaseUrl = normalizeTrueconfBaseUrl(rawValue || '', '');
      if (!patch.trueconfBaseUrl) {
        return false;
      }
    } else if (field === 'statussyncenabled') {
      patch.statusSyncEnabled = rawValue === true;
    } else if (field === 'showavailablestatus') {
      patch.showAvailableStatus = rawValue === true;
    } else if (field === 'autoconnectonstartup') {
      patch.autoConnectOnStartup = rawValue === true;
    } else if (field === 'autoopencalendaroncreate') {
      patch.autoOpenCalendarOnCreate = rawValue === true;
    } else if (field === 'defaultmeetingdurationminutes') {
      patch.defaultMeetingDurationMinutes = Math.max(15, Math.min(240, Math.round(Number(rawValue || 0) || 30)));
      if (target instanceof HTMLInputElement) {
        target.value = String(patch.defaultMeetingDurationMinutes);
      }
    } else {
      return false;
    }
    const nextSettings = normalizeCalendarIntegrationSettings({
      ...currentSettings,
      ...patch
    });
    const didChange = JSON.stringify(nextSettings) !== JSON.stringify(currentSettings);
    if (!didChange) return false;
    state.calendarIntegration = nextSettings;
    if (field === 'trueconfbaseurl') {
      clearTrueconfRoomsRuntimeState({
        clearRooms: true,
        clearCache: true
      });
    }
    saveUiPreferences();
    if (field === 'statussyncenabled' || field === 'showavailablestatus') {
      void maybeBroadcastCalendarStatusChange({
        force: true,
        silent: true
      });
      scheduleCalendarStatusBoundaryTimer();
      scheduleRender('status');
    }
    if (field === 'autoconnectonstartup' && nextSettings.autoConnectOnStartup !== false && state.ready === true) {
      maybeAutoConnectCalendarOnStartup();
    }
    if (
      field === 'trueconfbaseurl'
      && state.modalOpen
      && state.modalMode === 'calendar-planner'
    ) {
      void ensureTrueconfRoomsLoaded({
        force: true,
        silent: true,
        render: true
      });
    }
    scheduleRender(resolveInteractiveRenderScopes({
      includeOverlaysIfVisible: true
    }));
    return true;
  }

  function handleProfileLocalDraftActionTarget(target = null) {
    if (!LOCAL_PROFILE_CUSTOMIZATION_ENABLED) return false;
    if (state.sidebarMode !== 'profile') return false;
    if (!(target instanceof HTMLElement)) return false;
    const statusEmojiOptionButton = target.closest('[data-profile-local-status-emoji-option]');
    if (statusEmojiOptionButton instanceof HTMLElement) {
      const emoji = cleanText(statusEmojiOptionButton.dataset.profileLocalStatusEmojiOption || '', 24);
      if (!emoji) return true;
      state.profileSettingsDraft = {
        ...ensureProfileSettingsDraft({ force: false }),
        localStatusEmoji: emoji
      };
      state.profileSettingsDirty = true;
      state.profileLocalStatusEmojiPickerOpen = false;
      state.profileSaveError = '';
      scheduleRender('sidebar');
      return true;
    }
    const statusEmojiClearButton = target.closest('[data-profile-local-status-emoji-clear]');
    if (statusEmojiClearButton instanceof HTMLElement) {
      state.profileSettingsDraft = {
        ...ensureProfileSettingsDraft({ force: false }),
        localStatusEmoji: ''
      };
      state.profileSettingsDirty = true;
      state.profileLocalStatusEmojiPickerOpen = false;
      state.profileSaveError = '';
      scheduleRender(resolveInteractiveRenderScopes({
        includeOverlaysIfVisible: true
      }));
      return true;
    }
    const statusEmojiPickerTrigger = target.closest('[data-profile-local-status-emoji-toggle]');
    if (statusEmojiPickerTrigger instanceof HTMLElement) {
      state.profileLocalStatusEmojiPickerOpen = !state.profileLocalStatusEmojiPickerOpen;
      state.profileSaveError = '';
      scheduleRender('sidebar');
      return true;
    }
    const presetButton = target.closest('[data-profile-local-status-text-preset]');
    if (!(presetButton instanceof HTMLElement)) return false;
    const preset = cleanText(stripStatusEmojiToken(presetButton.dataset.profileLocalStatusTextPreset || ''), 120);
    state.profileSettingsDraft = {
      ...ensureProfileSettingsDraft({ force: false }),
      localStatusText: preset
    };
    state.profileSettingsDirty = true;
    state.profileLocalStatusEmojiPickerOpen = false;
    state.profileSaveError = '';
    scheduleRender(resolveInteractiveRenderScopes({
      includeOverlaysIfVisible: true
    }));
    return true;
  }

  function setAllProductivityFilterModesEnabled(enabled = true, options = {}) {
    const nextEnabled = enabled === true;
    const visibility = normalizeProductivityInboxModeVisibilityMap(state.productivityInboxModeVisibilityByMode);
    let changed = false;
    PRODUCTIVITY_INBOX_MODE_LIST.forEach((mode) => {
      if (mode === PRODUCTIVITY_INBOX_MODE.ALL) return;
      if (visibility[mode] !== nextEnabled) {
        visibility[mode] = nextEnabled;
        changed = true;
      }
    });
    if (!changed) {
      if (options.showStatus !== false) {
        showTemporaryStatus(`Все фильтры уже ${nextEnabled ? 'включены' : 'выключены'}`);
      }
      return true;
    }
    state.productivityInboxModeVisibilityByMode = visibility;
    syncProductivityInboxModesWithFeatureSettings();
    saveUiPreferences();
    if (options.showStatus !== false) {
      showTemporaryStatus(nextEnabled ? 'Все фильтры включены' : 'Все фильтры выключены');
    }
    scheduleRender('sidebar');
    return true;
  }

  function readProfileTelegramAuthField(field = '') {
    const safeField = cleanText(field || '', 40);
    if (!safeField) return '';
    const selector = `[data-profile-telegram-auth-field="${safeField}"]`;
    const sourceRoot = refs.root instanceof HTMLElement ? refs.root : document;
    const node = sourceRoot.querySelector(selector);
    if (node instanceof HTMLInputElement || node instanceof HTMLTextAreaElement) {
      return cleanText(node.value || '', field === 'password' ? 240 : 80);
    }
    return '';
  }

  function setTelegramEnabled(enabled = true, options = {}) {
    state.telegramIntegration = normalizeTelegramIntegrationSettings({
      ...state.telegramIntegration,
      enabled: enabled === true
    });
    ensureTelegramWorkspace();
    saveUiPreferences();
    if (enabled === true && options.refresh !== false) {
      void refreshTelegramDialogs({ force: true, silent: true }).catch(() => {});
    }
  }

  function setTrueconfEnabled(enabled = true, options = {}) {
    const currentSettings = normalizeTrueconfIntegrationSettings(state.trueconfIntegration);
    const nextEnabled = enabled === true;
    state.trueconfIntegration = normalizeTrueconfIntegrationSettings({
      ...currentSettings,
      enabled: nextEnabled,
      showInSidebar: options.showInSidebar === true ? true : currentSettings.showInSidebar === true
    });
    ensureTrueconfWorkspace();
    saveUiPreferences();
    if (nextEnabled && shouldShowTrueconfInSidebar() && options.refresh !== false) {
      void refreshTrueconfDialogs({ force: true, silent: true }).catch(() => {});
    }
  }

  function checkTrueconfFromProfile(options = {}) {
    const settings = normalizeTrueconfIntegrationSettings(state.trueconfIntegration);
    if (!settings.baseUrl) {
      showTemporaryStatus('Выберите сервер TrueConf');
      return true;
    }
    if (!settings.username) {
      showTemporaryStatus('Введите логин TrueConf');
      return true;
    }
    state.trueconfIntegration = normalizeTrueconfIntegrationSettings({
      ...settings,
      enabled: true,
      showInSidebar: true
    });
    ensureTrueconfWorkspace();
    saveUiPreferences();
    state.trueconfLoading = true;
    state.trueconfError = '';
    scheduleRender('sidebar');
    void ipcRenderer.invoke('yuchat-trueconf-chat-state', {
      ...getTrueconfIpcPayload({ forceEnabled: true }),
      forceAuth: options.forceAuth === true
    }).then((response) => {
      state.trueconfStatus = response && typeof response === 'object' ? response : null;
      state.trueconfError = response?.ok === false ? cleanText(response?.error || 'Не удалось подключиться к TrueConf', 240) : '';
      if (response?.ok === false) {
        setError(`Не удалось подключиться к TrueConf (${state.trueconfError})`);
        return;
      }
      showTemporaryStatus('TrueConf доступен, обновляю чаты');
      if (options.refreshDialogs !== false) {
        void refreshTrueconfDialogs({ force: true, silent: true }).catch(() => {});
      }
    }).catch((error) => {
      state.trueconfError = cleanText(error?.message || 'Не удалось подключиться к TrueConf', 240);
      setError(`Не удалось подключиться к TrueConf (${state.trueconfError})`);
    }).finally(() => {
      state.trueconfLoading = false;
      scheduleRender(resolveInteractiveRenderScopes({
        includeOverlaysIfVisible: true
      }));
    });
    return true;
  }

  function applyTelegramCodeRequestResponse(response = null) {
    state.telegramStatus = {
      ...(state.telegramStatus || {}),
      ...(response && typeof response === 'object' ? response : {})
    };
    state.telegramError = response?.ok === false ? cleanText(response?.error || 'Не удалось отправить код Telegram', 220) : '';
    state.telegramAuthCodeRequested = response?.ok !== false;
    state.telegramPasswordRequired = response?.passwordRequired === true || response?.code === 'TELEGRAM_PASSWORD_REQUIRED';
    if (response?.ok === false) {
      setError(`Не удалось отправить код Telegram (${state.telegramError})`);
      return false;
    }
    showTemporaryStatus(response?.isCodeViaApp ? 'Код отправлен в Telegram' : 'Код Telegram отправлен');
    return true;
  }

  function connectTelegramFromProfile() {
    setTelegramEnabled(true, { refresh: false });
    const settings = normalizeTelegramIntegrationSettings(state.telegramIntegration);
    if (!settings.phoneNumber) {
      showTemporaryStatus('Введите номер телефона Telegram');
      return true;
    }
    state.telegramLoading = true;
    state.telegramError = '';
    state.telegramPasswordRequired = false;
    scheduleRender('sidebar');
    void ipcRenderer.invoke('yuchat-telegram-connect', getTelegramIpcPayload({ forceEnabled: true })).then((response) => {
      state.telegramStatus = response && typeof response === 'object' ? response : null;
      state.telegramError = response?.ok === false ? cleanText(response?.error || 'Не удалось подключиться к Telegram', 220) : '';
      if (response?.ok === false) {
        state.telegramAuthCodeRequested = false;
        state.telegramPasswordRequired = false;
        setError(`Не удалось подключиться к Telegram (${state.telegramError})`);
        return null;
      }
      if (response?.authorized === true) {
        state.telegramAuthCodeRequested = false;
        state.telegramPasswordRequired = false;
        showTemporaryStatus('Telegram уже авторизован, обновляю диалоги');
        void refreshTelegramDialogs({ force: true, silent: true }).catch(() => {});
        return null;
      }
      state.telegramAuthCodeRequested = true;
      scheduleRender('sidebar');
      return ipcRenderer.invoke('yuchat-telegram-send-code', getTelegramIpcPayload({ forceEnabled: true })).then((codeResponse) => {
        applyTelegramCodeRequestResponse(codeResponse);
        return codeResponse;
      });
    }).catch((error) => {
      state.telegramAuthCodeRequested = false;
      state.telegramPasswordRequired = false;
      state.telegramError = cleanText(error?.message || 'Не удалось подключиться к Telegram', 220);
      setError(`Не удалось подключиться к Telegram (${state.telegramError})`);
    }).finally(() => {
      state.telegramLoading = false;
      scheduleRender(resolveInteractiveRenderScopes({
        includeOverlaysIfVisible: true
      }));
    });
    return true;
  }

  function requestTelegramCodeFromProfile(options = {}) {
    setTelegramEnabled(true, { refresh: false });
    const settings = normalizeTelegramIntegrationSettings(state.telegramIntegration);
    if (!settings.phoneNumber) {
      showTemporaryStatus('Введите номер телефона Telegram');
      return true;
    }
    state.telegramLoading = true;
    state.telegramError = '';
    state.telegramPasswordRequired = false;
    if (options.showAuthFields === true) {
      state.telegramAuthCodeRequested = true;
    }
    scheduleRender('sidebar');
    const payload = getTelegramIpcPayload({ forceEnabled: true });
    if (options.forceSMS === true) {
      payload.forceSMS = true;
    }
    void ipcRenderer.invoke('yuchat-telegram-send-code', payload).then((response) => {
      applyTelegramCodeRequestResponse(response);
    }).catch((error) => {
      state.telegramAuthCodeRequested = false;
      state.telegramPasswordRequired = false;
      state.telegramError = cleanText(error?.message || 'Не удалось отправить код Telegram', 220);
      setError(`Не удалось отправить код Telegram (${state.telegramError})`);
    }).finally(() => {
      state.telegramLoading = false;
      scheduleRender(resolveInteractiveRenderScopes({
        includeOverlaysIfVisible: true
      }));
    });
    return true;
  }

  function handleProfilePanelAction(action = '') {
    const normalizedAction = String(action || '').trim();
    if (!normalizedAction) return false;

    const actionsAllowedDuringProfileSave = new Set([
      'refresh-profile'
    ]);
    const actionAllowedDuringProfileSave = (
      actionsAllowedDuringProfileSave.has(normalizedAction)
      || normalizedAction.startsWith('calendar-')
      || normalizedAction.startsWith('telegram-')
      || normalizedAction.startsWith('max-')
    );
    if (state.profileSaveBusy && !actionAllowedDuringProfileSave) {
      return true;
    }
    if (!LOCAL_PROFILE_CUSTOMIZATION_ENABLED && (normalizedAction === 'save-local-profile' || normalizedAction === 'reset-local-profile')) {
      showTemporaryStatus('Локальные настройки отключены');
      return true;
    }

    if (normalizedAction === 'change-avatar') {
      void pickAvatarFileFromUser().then((file) => {
        if (!(file instanceof File)) return false;
        return queueProfileAvatarDraft(file);
      }).catch((error) => {
        setError(`Не удалось сменить аватар (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction === 'refresh-profile') {
      state.profileLocalStatusEmojiPickerOpen = false;
      ensureProfileSettingsDraft({ force: true });
      scheduleRender('sidebar');
      return true;
    }
    if (normalizedAction === 'export-client-config') {
      void exportClientConfigToFile().catch((error) => {
        setError(`Не удалось экспортировать конфиг (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction === 'import-client-config') {
      void importClientConfigFromFile().catch((error) => {
        setError(`Не удалось импортировать конфиг (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction === 'save-profile') {
      void saveProfileSettingsDraft().catch((error) => {
        setError(`Не удалось сохранить профиль (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction === 'calendar-connect' || normalizedAction === 'calendar-open-calendar') {
      void openCalendarIntegrationWindow({ view: 'calendar' }).then(() => {
        showTemporaryStatus('Календарь OWA открыт');
        scheduleCalendarRefresh(12 * 1000, {
          silent: true,
          reason: 'calendar-connect'
        });
      }).catch((error) => {
        setError(`Не удалось открыть календарь (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction === 'calendar-open-mail') {
      void openCalendarIntegrationWindow({ view: 'mail' }).catch((error) => {
        setError(`Не удалось открыть почту (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction === 'calendar-trueconf-apply') {
      const trueconfFieldNode = refs.dialogsList instanceof HTMLElement
        ? refs.dialogsList.querySelector('[data-calendar-field="trueconfBaseUrl"]')
        : null;
      if (!(trueconfFieldNode instanceof HTMLSelectElement || trueconfFieldNode instanceof HTMLInputElement)) {
        showTemporaryStatus('Не удалось найти список URL TrueConf');
        return true;
      }
      const selectedBaseUrl = normalizeTrueconfBaseUrl(trueconfFieldNode.value || '', '');
      if (!selectedBaseUrl) {
        showTemporaryStatus('Выберите URL TrueConf из списка');
        return true;
      }
      const currentBaseUrl = normalizeTrueconfBaseUrl(state.calendarIntegration?.trueconfBaseUrl || '', '');
      syncCalendarIntegrationFieldTarget(trueconfFieldNode, { forceApply: true });
      showTemporaryStatus(currentBaseUrl === selectedBaseUrl ? 'URL TrueConf уже применён' : 'URL TrueConf применён');
      scheduleRender('sidebar');
      return true;
    }
    if (normalizedAction === 'calendar-trueconf-auth') {
      const trueconfFieldNode = refs.dialogsList instanceof HTMLElement
        ? refs.dialogsList.querySelector('[data-calendar-field="trueconfBaseUrl"]')
        : null;
      if (trueconfFieldNode instanceof HTMLSelectElement || trueconfFieldNode instanceof HTMLInputElement) {
        syncCalendarIntegrationFieldTarget(trueconfFieldNode, { forceApply: true });
      }
      void openTrueconfAuthorizationWindow({ force: true }).then((result) => {
        if (result?.ok) {
          showTemporaryStatus(result?.reused === true
            ? 'Окно авторизации TrueConf уже открыто'
            : 'Открыл окно авторизации TrueConf');
          if (state.modalOpen && state.modalMode === 'calendar-planner') {
            void ensureTrueconfRoomsLoaded({
              force: true,
              silent: true,
              render: true
            });
          }
          return;
        }
        setError(`Не удалось открыть TrueConf (${cleanText(result?.error || '', 140) || 'ошибка авторизации'})`);
      }).catch((error) => {
        setError(`Не удалось открыть TrueConf (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction === 'calendar-refresh') {
      void refreshCalendarIntegrationState({
        force: true,
        silent: false,
        reason: 'manual-refresh'
      }).catch(() => {});
      return true;
    }
    if (normalizedAction === 'calendar-plan') {
      void findCalendarSlots({
        prompt: true,
        insertIntoComposer: false
      }).catch(() => {});
      return true;
    }
    if (normalizedAction.startsWith('calendar-events-day:')) {
      const nextDay = normalizeCalendarEventsDay(normalizedAction.slice('calendar-events-day:'.length));
      if (runtime.calendarEventsDay !== nextDay) {
        runtime.calendarEventsDay = nextDay;
        runtime.calendarEventsSectionCollapsed = null;
        scheduleRender('sidebar');
      }
      return true;
    }
    if (normalizedAction === 'calendar-events-toggle') {
      const { visibleEvents } = buildCalendarSidebarSnapshot();
      runtime.calendarEventsSectionCollapsed = !isCalendarEventsSectionCollapsed(visibleEvents);
      scheduleRender('sidebar');
      return true;
    }
    if (normalizedAction.startsWith('calendar-event-open:')) {
      void openCalendarIntegrationWindow({ view: 'calendar' }).catch((error) => {
        setError(`Не удалось открыть календарное событие (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction.startsWith('calendar-event-join:')) {
      const eventId = cleanText(normalizedAction.slice('calendar-event-join:'.length), 180);
      const calendarEvent = (Array.isArray(state.calendarEvents) ? state.calendarEvents : []).find((event) => cleanText(event?.id || '', 180) === eventId) || null;
      const joinUrl = resolveCalendarEventJoinUrl(calendarEvent);
      if (!joinUrl) {
        showTemporaryStatus('Для этого события не найден адрес подключения');
        return true;
      }
      ipcRenderer.send('open-external-url', joinUrl);
      showTemporaryStatus('Ссылка на подключение открыта');
      return true;
    }
    if (normalizedAction.startsWith('calendar-event-share:')) {
      void startScreenSharePreview().catch((error) => {
        setError(`Не удалось запустить показ экрана (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction.startsWith('calendar-slot-compose:')) {
      const slotIndex = Math.max(0, Number(normalizedAction.slice('calendar-slot-compose:'.length)) || 0);
      const slot = Array.isArray(state.calendarPlanningSlots) ? state.calendarPlanningSlots[slotIndex] : null;
      if (!slot) {
        showTemporaryStatus('Слот уже недоступен, обновите подбор');
        return true;
      }
      void createCalendarMeetingFromChat({
        participantResolution: {
          resolved: Array.isArray(state.calendarPlanningParticipants) ? state.calendarPlanningParticipants : []
        },
        startAt: Number(slot.startAt || 0),
        endAt: Number(slot.endAt || 0),
        prependBody: buildCalendarSlotSuggestionText({
          participants: state.calendarPlanningParticipants,
          slots: [slot]
        })
      }).catch((error) => {
        setError(`Не удалось открыть черновик встречи (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction === 'toggle-filters-global') {
      state.productivityFiltersEnabled = !isProductivityFiltersFeatureEnabled();
      if (!state.productivityFiltersEnabled) {
        state.inboxModesExpanded = false;
      }
      syncProductivityInboxModesWithFeatureSettings();
      saveUiPreferences();
      showTemporaryStatus(state.productivityFiltersEnabled ? 'Фильтры включены' : 'Фильтры выключены');
      scheduleRender(resolveChatMutationRenderScopes());
      return true;
    }
    if (normalizedAction === 'filters-enable-all') {
      if (!isProductivityFiltersFeatureEnabled()) {
        showTemporaryStatus('Сначала включите фильтры глобально');
        return true;
      }
      return setAllProductivityFilterModesEnabled(true);
    }
    if (normalizedAction === 'filters-disable-all') {
      if (!isProductivityFiltersFeatureEnabled()) {
        showTemporaryStatus('Сначала включите фильтры глобально');
        return true;
      }
      return setAllProductivityFilterModesEnabled(false);
    }
    if (normalizedAction === 'toggle-chat-preview') {
      state.chatPreviewEnabled = state.chatPreviewEnabled === false;
      saveUiPreferences();
      showTemporaryStatus(state.chatPreviewEnabled !== false ? 'Предпросмотр чатов включён' : 'Предпросмотр чатов выключен');
      scheduleRender('sidebar');
      return true;
    }
    if (normalizedAction === 'toggle-telegram-enabled') {
      setTelegramEnabled(normalizeTelegramIntegrationSettings(state.telegramIntegration).enabled !== true);
      showTemporaryStatus(normalizeTelegramIntegrationSettings(state.telegramIntegration).enabled ? 'Telegram интеграция включена' : 'Telegram интеграция выключена');
      scheduleRender(resolveChatMutationRenderScopes());
      return true;
    }
    if (normalizedAction === 'toggle-telegram-sidebar') {
      const currentSettings = normalizeTelegramIntegrationSettings(state.telegramIntegration);
      state.telegramIntegration = normalizeTelegramIntegrationSettings({
        ...currentSettings,
        showInSidebar: currentSettings.showInSidebar === false
      });
      ensureTelegramWorkspace();
      ensureActiveFolderSelection();
      saveUiPreferences();
      if (shouldShowTelegramInSidebar()) {
        void refreshTelegramDialogs({ force: true, silent: true }).catch(() => {});
      }
      showTemporaryStatus(state.telegramIntegration.showInSidebar !== false ? 'Telegram чаты показываются в сайдбаре' : 'Telegram чаты скрыты из сайдбара');
      scheduleRender(resolveChatMutationRenderScopes());
      return true;
    }
    if (normalizedAction === 'toggle-notifications-yuchat' || normalizedAction === 'toggle-notifications-telegram') {
      const source = normalizedAction.endsWith('telegram') ? 'telegram' : 'yuchat';
      state.systemNotifications = normalizeSystemNotificationSettings({
        ...state.systemNotifications,
        [source]: normalizeSystemNotificationSettings(state.systemNotifications)[source] === false
      });
      saveUiPreferences();
      sendSystemNotificationPreferences();
      showTemporaryStatus(`${source === 'telegram' ? 'Telegram' : 'YuChat'} уведомления ${state.systemNotifications[source] !== false ? 'включены' : 'выключены'}`);
      scheduleRender('sidebar');
      return true;
    }
    if (normalizedAction === 'telegram-toggle-proxy-visibility') {
      state.telegramProxyVisible = state.telegramProxyVisible !== true;
      scheduleRender('sidebar');
      return true;
    }
    if (normalizedAction === 'telegram-connect') {
      return requestTelegramCodeFromProfile({ showAuthFields: true });
    }
    if (normalizedAction === 'telegram-send-code') {
      return requestTelegramCodeFromProfile({ showAuthFields: true, forceSMS: true });
    }
    if (normalizedAction === 'telegram-sign-in') {
      const code = readProfileTelegramAuthField('code').replace(/\s+/g, '');
      const password = readProfileTelegramAuthField('password');
      if (!code && !password) {
        showTemporaryStatus('Введите код Telegram или пароль 2FA');
        return true;
      }
      setTelegramEnabled(true, { refresh: false });
      state.telegramLoading = true;
      state.telegramError = '';
      scheduleRender('sidebar');
      void ipcRenderer.invoke('yuchat-telegram-sign-in', {
        ...getTelegramIpcPayload({ forceEnabled: true }),
        code,
        password
      }).then((response) => {
        state.telegramStatus = response && typeof response === 'object' ? response : null;
        state.telegramError = response?.ok === false ? cleanText(response?.error || 'Не удалось войти в Telegram', 220) : '';
        state.telegramPasswordRequired = response?.passwordRequired === true || response?.code === 'TELEGRAM_PASSWORD_REQUIRED';
        state.telegramAuthCodeRequested = state.telegramPasswordRequired || response?.ok === false;
        if (response?.ok === false) {
          setError(`Не удалось войти в Telegram (${state.telegramError})`);
          return;
        }
        state.telegramAuthCodeRequested = false;
        state.telegramPasswordRequired = false;
        showTemporaryStatus('Вход в Telegram выполнен');
        void refreshTelegramDialogs({ force: true, silent: true }).catch(() => {});
      }).catch((error) => {
        state.telegramError = cleanText(error?.message || 'Не удалось войти в Telegram', 220);
        setError(`Не удалось войти в Telegram (${state.telegramError})`);
      }).finally(() => {
        state.telegramLoading = false;
        scheduleRender(resolveInteractiveRenderScopes({
          includeOverlaysIfVisible: true
        }));
      });
      return true;
    }
    if (normalizedAction === 'telegram-refresh') {
      setTelegramEnabled(true, { refresh: false });
      void refreshTelegramDialogs({ force: true, silent: false }).catch((error) => {
        setError(`Не удалось обновить Telegram (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction === 'telegram-disconnect') {
      void ipcRenderer.invoke('yuchat-telegram-logout').catch(() => {});
      state.telegramIntegration = normalizeTelegramIntegrationSettings({
        ...state.telegramIntegration,
        enabled: false
      });
      state.telegramStatus = null;
      state.telegramDialogs = [];
      state.telegramLastSyncedAt = 0;
      state.telegramAuthCodeRequested = false;
      state.telegramPasswordRequired = false;
      state.telegramError = '';
      state.recentsByWorkspace.telegram = [];
      state.archivedRecentsByWorkspace.telegram = [];
      ensureTelegramWorkspace();
      saveUiPreferences();
      runtime.recentsStateVersion += 1;
      invalidateRecentsDerivedCache();
      showTemporaryStatus('Telegram отключён');
      scheduleRender(resolveChatMutationRenderScopes());
      return true;
    }
    if (normalizedAction.startsWith('toggle-filter-mode:')) {
      if (!isProductivityFiltersFeatureEnabled()) {
        showTemporaryStatus('Сначала включите фильтры глобально');
        return true;
      }
      const mode = cleanText(normalizedAction.slice('toggle-filter-mode:'.length), 120).toLowerCase();
      if (!mode || mode === PRODUCTIVITY_INBOX_MODE.ALL || !PRODUCTIVITY_INBOX_MODE_LIST.includes(mode)) {
        return true;
      }
      const visibility = normalizeProductivityInboxModeVisibilityMap(state.productivityInboxModeVisibilityByMode);
      visibility[mode] = visibility[mode] === false;
      state.productivityInboxModeVisibilityByMode = visibility;
      syncProductivityInboxModesWithFeatureSettings();
      saveUiPreferences();
      showTemporaryStatus(`Фильтр «${getProductivityInboxModeLabel(mode)}» ${visibility[mode] ? 'включён' : 'выключен'}`);
      scheduleRender('sidebar');
      return true;
    }
    if (normalizedAction === 'toggle-folders-global') {
      state.productivityFoldersEnabled = !isProductivityFoldersFeatureEnabled();
      if (
        !state.productivityFoldersEnabled
        && !isProductivityChatTagsFeatureEnabled()
        && !isSmartFolderId(state.activeFolderId || '')
      ) {
        state.activeFolderId = '';
      }
      saveUiPreferences();
      showTemporaryStatus(state.productivityFoldersEnabled ? 'Папки включены' : 'Папки выключены');
      scheduleRender(resolveChatMutationRenderScopes());
      return true;
    }
    if (normalizedAction === 'toggle-chat-tags-global') {
      const nextEnabled = !isProductivityChatTagsFeatureEnabled();
      state.productivityChatTagsEnabled = nextEnabled;
      if (!nextEnabled) {
        runtime.dialogSearchTagPickerOpen = false;
        runtime.chatSearchTagPickerOpen = false;
        if (state.appearanceOverlayOpen && state.appearanceOverlayMode === 'tags') {
          state.appearanceOverlayOpen = false;
        }
      }
      if (!nextEnabled && !isProductivityFoldersFeatureEnabled() && !isSmartFolderId(state.activeFolderId || '')) {
        state.activeFolderId = '';
      }
      saveUiPreferences();
      showTemporaryStatus(nextEnabled ? 'Теги включены' : 'Теги выключены');
      scheduleRender(resolveChatMutationRenderScopes());
      return true;
    }
    if (normalizedAction === 'open-chat-tags-manager') {
      void openChatTagsManager().catch((error) => {
        setError(`Не удалось открыть теги (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction === 'create-chat-tag') {
      const workspaceId = String(
        getFolderWorkspaceId()
        || state.workspaces?.find((workspace) => String(workspace?.workspaceId || '').trim())?.workspaceId
        || Object.keys(state.customFoldersByWorkspace || {}).find((workspace) => String(workspace || '').trim())
        || ''
      ).trim();
      if (!workspaceId) {
        showTemporaryStatus('Не найдено пространство для нового тега');
        return true;
      }
      void promptCreateFolder(workspaceId, '', {
        showStatus: false,
        activate: false,
        dialogTitle: 'Новый тег',
        description: 'Короткое название тега, которое будет видно рядом с чатом.',
        inputPlaceholder: 'Например: Важное',
        confirmLabel: 'Создать тег'
      }).then((createdFolder) => {
        if (!createdFolder) return;
        if (!isProductivityChatTagsFeatureEnabled()) {
          state.productivityChatTagsEnabled = true;
          saveUiPreferences();
        }
        showTemporaryStatus(`Тег «${cleanText(createdFolder.title || 'Без названия', 120)}» создан`);
        scheduleRender(['sidebar', 'overlays']);
      }).catch((error) => {
        setError(`Не удалось создать тег (${cleanText(error?.message || '', 140)})`);
      });
      return true;
    }
    if (normalizedAction === 'refresh-sessions') {
      void loadProfileSessions({ force: true });
      return true;
    }
    if (normalizedAction === 'open-font-settings') {
      openFontSettingsOverlayInstant({ anchorNode: refs.dialogsAppearanceButton });
      return true;
    }
    if (normalizedAction === 'open-native-profile') {
      openNativeProfileSurface();
      return true;
    }

    return false;
  }

  async function logoutCurrentAccountViaApi() {
    const confirmed = await requestConfirmModal({
      title: 'Выйти из аккаунта?',
      description: 'Текущая сессия будет завершена.',
      confirmLabel: 'Выйти',
      cancelLabel: 'Отмена',
      danger: true
    });
    if (!confirmed) return false;
    const accountId = await resolveAccountId();
    await callYuChatApi('session.logout', { accountId }, { timeoutMs: 16000 });
    purgeAuthStorageForLoginRequired();
    await clearPersistedAuthStorageSnapshot();
    window.location.reload();
    return true;
  }

