      list: '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="6.2" cy="7.2" r="1.2" fill="currentColor"/><circle cx="6.2" cy="12" r="1.2" fill="currentColor"/><circle cx="6.2" cy="16.8" r="1.2" fill="currentColor"/><path d="M10 7.2h8M10 12h8M10 16.8h8" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>',
