    refs.transferProgressHud = transferProgressHud;
    refs.transferProgressHudLabel = transferProgressHud.querySelector('.yc-transfer-progress-label');
    refs.transferProgressHudMeta = transferProgressHud.querySelector('.yc-transfer-progress-meta');
    refs.transferProgressHudPercent = transferProgressHud.querySelector('.yc-transfer-progress-percent');
    refs.transferProgressHudBarFill = transferProgressHud.querySelector('.yc-transfer-progress-bar-fill');
    refs.transferProgressHudAction = transferProgressHud.querySelector('[data-role="transfer-progress-action"]');
    transferProgressHud.addEventListener('click', (event) => {
      const target = event.target instanceof HTMLElement
        ? event.target.closest('[data-role="transfer-progress-action"]')
        : null;
      if (!(target instanceof HTMLElement)) return;
      event.preventDefault();
      event.stopPropagation();
      const transferId = cleanText(transferProgressHud.dataset.transferId || '', 180);
      const isCancelable = transferProgressHud.dataset.cancelable === '1';
      if (!transferId) {
        transferProgressHud.classList.remove('is-visible');
        return;
      }
      if (!isCancelable) {
        dropTransferProgressUiEntry(transferId);
        return;
      }
      target.setAttribute('disabled', 'disabled');
      const localAbortResult = abortLocalTransferOperation(transferId, 'canceled');
      if (localAbortResult?.ok === true || localAbortResult?.active === true) {
        handleTransferProgressEvent({
          transferId,
          stage: 'canceled',
          done: true,
          ok: false,
          error: 'Операция отменена'
        });
        showTemporaryStatus('Останавливаю загрузку…', 1800);
        target.removeAttribute('disabled');
        return;
      }
      void ipcRenderer.invoke('abort-transfer-operation', {
        transferId,
        reason: 'canceled'
      }).then((result) => {
        if (result?.ok === true || result?.active === true) {
          handleTransferProgressEvent({
            transferId,
            stage: 'canceled',
            done: true,
            ok: false,
            error: 'Операция отменена'
          });
          showTemporaryStatus('Останавливаю загрузку…', 1800);
          return;
        }
        showTemporaryStatus(cleanText(result?.error || 'Не удалось остановить загрузку', 180) || 'Не удалось остановить загрузку');
      }).catch(() => {
        showTemporaryStatus('Не удалось остановить загрузку');
      }).finally(() => {
        target.removeAttribute('disabled');
      });
    });
    upcomingCalendarHud.addEventListener('click', (event) => {
      const dismissTarget = event.target instanceof HTMLElement
        ? event.target.closest('[data-upcoming-calendar-dismiss]')
        : null;
      if (dismissTarget instanceof HTMLElement) {
        event.preventDefault();
        event.stopPropagation();
        runtime.upcomingCalendarHudDismissedKey = cleanText(dismissTarget.dataset.upcomingCalendarDismiss || '', 220);
        scheduleRender('status');
        return;
      }
      const openTarget = event.target instanceof HTMLElement
        ? event.target.closest('[data-upcoming-calendar-open]')
        : null;
      if (!(openTarget instanceof HTMLButtonElement)) return;
      event.preventDefault();
      event.stopPropagation();
      const eventKey = cleanText(openTarget.dataset.upcomingCalendarOpen || '', 220);
      const calendarEvent = getCalendarUpcomingEvent();
      if (!calendarEvent || buildCalendarUpcomingEventDismissKey(calendarEvent) !== eventKey) {
        showTemporaryStatus('Ближайшее событие уже обновилось');
        scheduleRender('status');
        return;
      }
      openTarget.disabled = true;
      void openCalendarUpcomingEvent(calendarEvent)
        .catch((error) => {
          setError(`Не удалось открыть ближайшее событие (${cleanText(error?.message || '', 140)})`);
        })
        .finally(() => {
          openTarget.disabled = false;
        });
    });
    birthdayReminderHud.addEventListener('click', (event) => {
      const dismissTarget = event.target instanceof HTMLElement
        ? event.target.closest('[data-birthday-reminder-dismiss]')
        : null;
      if (dismissTarget instanceof HTMLElement) {
        event.preventDefault();
        event.stopPropagation();
        const memberId = String(dismissTarget.dataset.birthdayReminderDismiss || '').trim();
        if (!memberId) return;
        dismissBirthdayReminder(memberId);
        return;
      }
      const memberTarget = event.target instanceof HTMLElement
        ? event.target.closest('[data-birthday-reminder-member]')
        : null;
      if (memberTarget instanceof HTMLButtonElement) {
        event.preventDefault();
        event.stopPropagation();
        const memberId = String(memberTarget.dataset.birthdayReminderMember || '').trim();
        if (!memberId) return;
        openBirthdayReminderMemberInfo(memberId, {
          resetHistory: true,
          pushHistory: false
        });
        return;
      }
      const messageTarget = event.target instanceof HTMLElement
        ? event.target.closest('[data-birthday-reminder-message]')
        : null;
      if (!(messageTarget instanceof HTMLButtonElement)) return;
      event.preventDefault();
      event.stopPropagation();
      const memberId = String(messageTarget.dataset.birthdayReminderMessage || '').trim();
      if (!memberId) return;
      messageTarget.disabled = true;
      void openDirectChatByMemberId(memberId)
        .catch(() => null)
        .finally(() => {
          messageTarget.disabled = false;
        });
    });
