    refs.dialogsBottomDock?.addEventListener('click', (event) => {
      const button = event.target instanceof Element
        ? event.target.closest('[data-sidebar-mode]')
        : null;
      if (!(button instanceof HTMLElement)) return;
      if (!button.dataset?.sidebarMode) return;
      const nextMode = normalizeSidebarMode(button.dataset.sidebarMode || 'chats');
      runtime.nativeSurfaceMode = '';
      document.body?.classList.remove('yc-native-profile-open');
      if (nextMode === 'chats' && state.recentsSearch) {
        state.recentsSearch = '';
      }
      if (nextMode === 'chats') {
        runtime.sidebarBackStack = [];
        setSidebarMode(nextMode);
      } else {
        openSidebarSurface(nextMode);
      }
      scheduleRender(resolveChatMutationRenderScopes());
    });

    refs.dialogsBottomDock?.addEventListener('contextmenu', (event) => {
      openChatsDockContextMenuFromEvent(event);
    });

    refs.chatThreadToggleButton?.addEventListener('click', () => {
      const activeEntry = getCurrentChatEntry() || (
        state.threadPanelSourceWorkspaceId && state.threadPanelSourceChatId
          ? {
              workspaceId: state.threadPanelSourceWorkspaceId,
              chatId: state.threadPanelSourceChatId,
              title: state.threadPanelSourceTitle || 'Чат'
            }
          : null
      );
      if (!activeEntry) return;
      const key = getChatStateKey(activeEntry.workspaceId, activeEntry.chatId);
      const threads = Array.isArray(state.threadListByWorkspaceChat?.[key]) ? state.threadListByWorkspaceChat[key] : [];
      if (!threads.length) {
        showTemporaryStatus('В этом чате нет веток');
        return;
      }

      if (state.threadPanelOpen) {
        closeThreadPanel();
      } else {
        state.threadPanelOpen = true;
        state.activeThreadChatId = '';
        state.activeThreadTitle = '';
        state.activeThreadMessages = [];
        state.threadPanelSourceWorkspaceId = activeEntry.workspaceId || '';
        state.threadPanelSourceChatId = activeEntry.chatId || '';
        state.threadPanelSourceTitle = activeEntry.title || state.activeChatTitle || '';
      }
      scheduleRender(resolveChatMutationRenderScopes({
        includeSidebar: false,
        forceThread: true
      }));
    });

    refs.chatBackButton?.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (state.favoritesCollectionViewOpen) {
        closeFavoritesCollectionView();
        return;
      }
      if (state.scheduledMessagesViewOpen) {
        closeScheduledMessagesView();
        return;
      }
      if (getForwardSourceNavigationReturnForActiveChat()) {
        void returnToForwardSourceNavigationOrigin();
        return;
      }
      returnToParentChatFromThread({ keepThreadPanel: state.threadPanelOpen === true });
    });

    refs.chatCallButton?.addEventListener('click', async (event) => {
      event.preventDefault();
      event.stopPropagation();
      const entry = getCurrentChatEntry();
      if (!entry) return;
      try {
        if (!isDirectChatEntry(entry)) {
          throw new Error('Звонки доступны только в личных чатах');
        }
        showTemporaryStatus('Запускаю звонок…', 1800);
        const callInfo = await startDirectChatCall(entry);
        presentStartedCall(entry, callInfo);
      } catch (error) {
        setError(cleanText(getCallStartErrorMessage(error), 140));
      }
    });

    const handleChatHeaderInfoOpen = (event) => {
      const target = event?.target instanceof Element ? event.target : null;
      if (state.favoritesCollectionViewOpen) {
        return;
      }
      if (state.scheduledMessagesViewOpen) {
        return;
      }
      if (
        target?.closest('[data-role="chat-back"]')
        || target?.closest('[data-role="chat-call"]')
        || target?.closest('[data-role="chat-search"]')
        || target?.closest('[data-role="chat-thread-toggle"]')
        || target?.closest('[data-role="chat-attention-mention"]')
        || target?.closest('[data-role="chat-attention-reaction"]')
      ) {
        return;
      }
      openChatInfoOverlay();
    };

