    refs.chatHeaderAvatar?.addEventListener('click', handleChatHeaderInfoOpen);
    refs.chatTitle?.addEventListener('click', handleChatHeaderInfoOpen);
    refs.chatSubtitle?.addEventListener('click', handleChatHeaderInfoOpen);
    refs.chatHeader?.addEventListener('click', handleChatHeaderInfoOpen);

