    refs.chatMessageSelectionToolbar?.addEventListener('click', (event) => {
      const actionNode = event.target instanceof Element ? event.target.closest('[data-message-selection-action]') : null;
      if (!(actionNode instanceof HTMLElement)) return;
      const action = String(actionNode.dataset.messageSelectionAction || '').trim();
      const selectedMessages = getSelectedMessagesForCurrentChat();
      if (action === 'cancel') {
        clearMessageSelection();
        scheduleRender('chat');
        refs.chatComposerInput?.focus({ preventScroll: true });
        return;
      }
      if (action === 'reply') {
        void startReplyFromSelection();
        return;
      }
      if (action === 'forward') {
        void forwardSelectedMessages();
        return;
      }
      if (action === 'delete') {
        void deleteSelectedMessages();
        return;
      }
      if (action === 'copy-email') {
        void copyMessagesAsEmailReady(selectedMessages, {
          title: buildProductivityExportTitle('Selection email')
        });
        return;
      }
      if (action === 'export-markdown') {
        void exportMessagesByType(PRODUCTIVITY_EXPORT_TYPE.MARKDOWN, selectedMessages, {
          scopeLabel: 'Selection Markdown'
        });
        return;
      }
      if (action === 'export-html') {
        void exportMessagesByType(PRODUCTIVITY_EXPORT_TYPE.HTML, selectedMessages, {
          scopeLabel: 'Selection HTML'
        });
        return;
      }
      if (action === 'export-pdf') {
        void exportMessagesByType(PRODUCTIVITY_EXPORT_TYPE.PDF, selectedMessages, {
          scopeLabel: 'Selection PDF'
        });
        return;
      }
      if (action === 'copy-brief') {
        const brief = buildExportDocument(PRODUCTIVITY_EXPORT_TYPE.BRIEF, {
          title: buildProductivityExportTitle('Selection brief'),
          messages: selectedMessages,
          context: buildExportContext(state.activeChatWorkspaceId, state.activeChatId),
          options: {
            includeAuthors: true,
            includeTimestamps: true,
            includeAttachments: true,
            includeQuotes: true,
            includeLinks: true,
            locale: 'ru-RU'
          }
        });
        void copyTextToClipboard(String(brief?.content || '')).then((copied) => {
          showTemporaryStatus(copied ? 'Brief скопирован' : 'Не удалось скопировать brief');
        });
      }
    });

    refs.chatSearchResults?.addEventListener('click', (event) => {
      const target = event.target instanceof HTMLElement ? event.target : null;
      if (!target) return;
      const removeNode = target.closest('[data-message-search-tag-remove-key]');
      if (removeNode instanceof HTMLElement) {
        event.preventDefault();
        event.stopPropagation();
        const tagKey = cleanText(removeNode.dataset.messageSearchTagRemoveKey || '', 120);
        state.chatSearchQuery = removeMessageSearchTag(state.chatSearchQuery, tagKey);
        state.chatSearchActiveId = '';
        runtime.lastChatSearchTarget = '';
        runtime.chatSearchTagPickerOpen = true;
        scheduleRender('chat');
        focusChatSearchInput();
        return;
      }
      const clearDateNode = target.closest('[data-chat-search-date-clear]');
      if (clearDateNode instanceof HTMLElement) {
        event.preventDefault();
        event.stopPropagation();
        state.chatSearchDateValue = '';
        if (refs.chatSearchDateInput instanceof HTMLInputElement) {
          refs.chatSearchDateInput.value = '';
        }
        state.chatSearchActiveId = '';
        runtime.lastChatSearchTarget = '';
        scheduleRender('chat');
        focusChatSearchInput();
        return;
      }
      const suggestionNode = target.closest('[data-message-search-tag-suggestion]');
      if (suggestionNode instanceof HTMLElement) {
        event.preventDefault();
        event.stopPropagation();
        const tagValue = cleanSearchInputValue(suggestionNode.dataset.messageSearchTagSuggestion || '', 120);
        if (!tagValue) return;
        state.chatSearchQuery = appendMessageSearchTag(state.chatSearchQuery, tagValue);
        state.chatSearchActiveId = '';
        runtime.lastChatSearchTarget = '';
        runtime.chatSearchTagPickerOpen = true;
        scheduleRender('chat');
        focusChatSearchInput();
        return;
      }
      const resultNode = event.target instanceof HTMLElement ? event.target.closest('[data-search-result-id]') : null;
      if (!(resultNode instanceof HTMLElement)) return;
      const searchResultId = String(resultNode.dataset.searchResultId || '').trim();
      if (!searchResultId) return;
      const threadTarget = parseThreadSearchResultId(searchResultId);
      if (threadTarget) {
        const activeState = getCurrentChatState();
        if (activeState?.workspaceId && activeState?.chatId) {
          void openThreadSearchResult(activeState.workspaceId, activeState.chatId, threadTarget);
        }
        return;
      }
      state.chatSearchActiveId = searchResultId;
      runtime.lastChatSearchTarget = '';
      const activeState = state.favoritesCollectionViewOpen === true
        ? {
            key: getFavoritesChannelKey(),
            workspaceId: FAVORITES_CHANNEL_WORKSPACE_ID,
            chatId: FAVORITES_CHANNEL_CHAT_ID
          }
        : getCurrentChatState();
      const searchTargetMessageId = getSearchResultMessageId(searchResultId);
      if (activeState?.key && searchTargetMessageId) {
        const targetRow = findRenderedChatMessageRow(searchTargetMessageId);
        if (targetRow instanceof HTMLElement) {
          suppressChatHistoryLoad(420);
          targetRow.scrollIntoView({ block: 'center', inline: 'nearest' });
          runtime.lastChatSearchTarget = `${activeState.key}:${searchTargetMessageId}`;
        }
      }
      scheduleRender('chat');
    });

    document.addEventListener('click', (event) => {
      if (!runtime.chatSearchTagPickerOpen) return;
      const target = event.target instanceof HTMLElement ? event.target : null;
      if (!target) return;
      if (refs.chatSearchBar instanceof HTMLElement && refs.chatSearchBar.contains(target)) return;
      runtime.chatSearchTagPickerOpen = false;
      scheduleRender('chat');
    });

