        clearComposerPendingFiles(composerTarget.workspaceId, composerTarget.chatId);
        clearSendAssist();
        state.sendAssistApprovedSignature = '';
        scheduleRender('chat');
        refs.chatComposerInput?.focus({ preventScroll: true });
